struct UniqueSocket {
  SOCKET value = INVALID_SOCKET;

  UniqueSocket() = default;
  explicit UniqueSocket(SOCKET socket) : value(socket) {}
  ~UniqueSocket() { reset(); }

  UniqueSocket(const UniqueSocket&) = delete;
  UniqueSocket& operator=(const UniqueSocket&) = delete;

  UniqueSocket(UniqueSocket&& other) noexcept : value(other.value) {
    other.value = INVALID_SOCKET;
  }

  UniqueSocket& operator=(UniqueSocket&& other) noexcept {
    if (this != &other) {
      reset();
      value = other.value;
      other.value = INVALID_SOCKET;
    }
    return *this;
  }

  void reset(SOCKET socket = INVALID_SOCKET) {
    if (value != INVALID_SOCKET) {
      closesocket(value);
    }
    value = socket;
  }

  SOCKET get() const { return value; }
  explicit operator bool() const { return value != INVALID_SOCKET; }
};

struct WinsockSession {
  WinsockSession() {
    WSADATA data{};
    const int result = WSAStartup(MAKEWORD(2, 2), &data);
    if (result != 0) {
      throw std::runtime_error("WSAStartup failed");
    }
  }

  ~WinsockSession() { WSACleanup(); }

  WinsockSession(const WinsockSession&) = delete;
  WinsockSession& operator=(const WinsockSession&) = delete;
};

