void ListServers() {
  for (const auto& server : hgbridge::kHgServers) {
    wprintf(L"%ls  %ls\n", std::wstring(server.id).c_str(), std::wstring(server.address).c_str());
  }
}

Options ParseArgs(int argc, wchar_t** argv) {
  Options options;
  for (int i = 1; i < argc; ++i) {
    const std::wstring arg = argv[i];
    if (arg == L"--help" || arg == L"-h") {
      PrintUsage();
      ExitProcess(0);
    } else if (arg == L"--list-servers") {
      options.list_servers = true;
    } else if (arg == L"--dry-run") {
      options.dry_run = true;
    } else if (arg == L"--allow-remote-clients") {
      options.allow_remote_clients = true;
    } else if (arg == L"--packet-dump") {
      options.packet_dump = true;
    } else if (arg == L"--ee-crypto" || arg == L"--enable-ee-crypto" || arg == L"--stock-ee") {
      options.enable_ee_crypto = true;
    } else if (arg == L"--ee-crypto-self-test") {
      options.enable_ee_crypto = true;
      options.ee_crypto_self_test = true;
    } else if (arg == L"--no-startup-m-gate") {
      options.startup_m_gate = false;
    } else if (arg == L"--quarantine-ee-control-collisions") {
      options.quarantine_ee_control_collisions = true;
    } else if (arg == L"--no-quarantine-ee-control-collisions") {
      options.quarantine_ee_control_collisions = false;
    } else if (arg == L"--no-consume-device-properties" ||
        arg == L"--no-consume-client-device-properties") {
      options.consume_client_device_properties = false;
    } else if (arg == L"--rewrite-client-gui-inventory-self-id" ||
        arg == L"--rewrite-client-gui-inventory-self-ids") {
      options.rewrite_client_gui_inventory_self_id = true;
    } else if (arg == L"--no-rewrite-client-gui-inventory-self-id" ||
        arg == L"--no-rewrite-client-gui-inventory-self-ids") {
      options.rewrite_client_gui_inventory_self_id = false;
    } else if (arg == L"--rewrite-client-input-self-object-id" ||
        arg == L"--rewrite-client-input-self-object-ids") {
      options.rewrite_client_input_self_object_ids = true;
    } else if (arg == L"--no-rewrite-client-input-self-object-id" ||
        arg == L"--no-rewrite-client-input-self-object-ids") {
      options.rewrite_client_input_self_object_ids = false;
    } else if (arg == L"--rewrite-bncs-private-build") {
      options.rewrite_bncs_private_build = true;
    } else if (arg == L"--no-rewrite-bncs-private-build") {
      options.rewrite_bncs_private_build = false;
    } else if (arg == L"--rewrite-module-hak-list" || arg == L"--rewrite-direct-module-hak-list") {
      options.rewrite_module_hak_list = true;
    } else if (arg == L"--nwsync" || arg == L"--enable-nwsync") {
      options.rewrite_module_hak_list = true;
      options.enable_nwsync_advertisement = true;
    } else if (arg == L"--rewrite-quickbar-simple" || arg == L"--rewrite-simple-quickbar") {
      options.rewrite_quickbar_simple = true;
    } else if (arg == L"--rewrite-live-object-updates" || arg == L"--rewrite-live-updates") {
      options.rewrite_live_object_updates = true;
    } else if (arg == L"--rewrite-live-object-visual-transform-masks" ||
        arg == L"--rewrite-live-object-visual-transforms" ||
        arg == L"--rewrite-live-visual-transform-masks") {
      options.rewrite_live_object_visual_transform_masks = true;
    } else if (arg == L"--rewrite-live-object-material-shader-params" ||
        arg == L"--rewrite-live-material-shader-params") {
      options.rewrite_live_object_material_shader_params = true;
    } else if (arg == L"--rewrite-live-object-item-appearances" ||
        arg == L"--rewrite-live-item-appearances" ||
        arg == L"--rewrite-live-items") {
      options.rewrite_live_object_item_appearances = true;
    } else if (arg == L"--rewrite-live-object-item-appearance-word-parts" ||
        arg == L"--rewrite-live-item-word-parts") {
      options.rewrite_live_object_item_appearances = true;
      options.rewrite_live_object_item_appearance_word_parts = true;
    } else if (arg == L"--rewrite-live-object-item-appearance-visual-transforms" ||
        arg == L"--rewrite-live-object-item-visual-transforms" ||
        arg == L"--rewrite-live-item-visual-transforms") {
      options.rewrite_live_object_item_appearances = true;
      options.rewrite_live_object_item_appearance_visual_transforms = true;
    } else if (arg == L"--rewrite-live-object-inventory-feature23-categories" ||
        arg == L"--rewrite-live-inventory-feature23-categories" ||
        arg == L"--rewrite-live-object-inventory-categories") {
      options.rewrite_live_object_inventory_feature23_categories = true;
    } else if (arg == L"--rewrite-live-object-add-records" ||
        arg == L"--rewrite-live-add-records" ||
        arg == L"--rewrite-live-object-add-bools" ||
        arg == L"--rewrite-live-add-bools") {
      options.rewrite_live_object_add_records = true;
    } else if (arg == L"--rewrite-live-object-add-visual-transforms" ||
        arg == L"--rewrite-live-add-visual-transforms" ||
        arg == L"--rewrite-live-creature-add-visual-transforms") {
      options.rewrite_live_object_add_visual_transforms = true;
    } else if (arg == L"--rewrite-player-list" ||
        arg == L"--rewrite-playerlist" ||
        arg == L"--rewrite-party-player-list") {
      options.rewrite_player_list = true;
    } else if (arg == L"--rewrite-area-client-area" ||
        arg == L"--rewrite-client-area" ||
        arg == L"--rewrite-area-name") {
      options.rewrite_area_client_area = true;
    } else if (arg == L"--synthetic-area-loaded" ||
        arg == L"--synthesize-area-loaded") {
      options.synthesize_area_loaded = true;
    } else if (arg == L"--no-synthetic-area-loadbar" ||
        arg == L"--no-synthesize-area-loadbar") {
      options.synthesize_area_loadbar = false;
    } else if ((arg == L"--listen" || arg == L"--server" || arg == L"--log" ||
        arg == L"--ee-nwmain" ||
        arg == L"--diamond-cdkey" || arg == L"--baseitems" ||
        arg == L"--genericdoors" ||
        arg == L"--nwsync-root" || arg == L"--nwsync-url" ||
        arg == L"--nwsync-hash" || arg == L"--nwsync-repository-hash" ||
        arg == L"--nwsync-manifest" || arg == L"--nwsync-http" ||
        arg == L"--bncs-private-build" ||
        arg == L"--rewrite-bncs-field" || arg == L"--session-timeout-ms") && i + 1 < argc) {
      const std::wstring value = argv[++i];
      if (arg == L"--listen") {
        if (!ParseListenEndpoint(value, &options.listen_host, &options.listen_port)) {
          fwprintf(stderr, L"Invalid --listen endpoint: %ls\n", value.c_str());
          ExitProcess(2);
        }
      } else if (arg == L"--server") {
        if (value.find(L':') != std::wstring::npos) {
          options.server_id.clear();
          if (!ParseEndpoint(value, &options.server_host, &options.server_port)) {
            fwprintf(stderr, L"Invalid --server endpoint: %ls\n", value.c_str());
            ExitProcess(2);
          }
        } else {
          options.server_id = value;
          options.server_host.clear();
          options.server_port = 0;
        }
      } else if (arg == L"--log") {
        options.log_path = value;
      } else if (arg == L"--ee-nwmain") {
        options.enable_ee_crypto = true;
        options.ee_nwmain_path = value;
      } else if (arg == L"--diamond-cdkey") {
        options.diamond_cdkey_path = value;
      } else if (arg == L"--baseitems") {
        options.baseitems_path = value;
      } else if (arg == L"--genericdoors") {
        options.genericdoors_path = value;
      } else if (arg == L"--nwsync-root") {
        options.nwsync_root_path = value;
        options.enable_nwsync_advertisement = true;
        options.enable_nwsync_http = true;
        options.rewrite_module_hak_list = true;
      } else if (arg == L"--nwsync-url") {
        options.nwsync_url = WideToUtf8(value);
        options.enable_nwsync_advertisement = true;
        options.rewrite_module_hak_list = true;
      } else if (arg == L"--nwsync-hash" || arg == L"--nwsync-repository-hash") {
        std::string normalized;
        if (!NormalizeSha1Hex(WideToUtf8(value), &normalized)) {
          fwprintf(stderr, L"Invalid NWSync SHA1 hash: %ls\n", value.c_str());
          ExitProcess(2);
        }
        options.nwsync_repository_hash = std::move(normalized);
        options.enable_nwsync_advertisement = true;
        options.rewrite_module_hak_list = true;
      } else if (arg == L"--nwsync-manifest") {
        NwsyncManifestAdvert manifest;
        if (!ParseNwsyncManifestSpec(value, &manifest)) {
          fwprintf(stderr, L"Invalid --nwsync-manifest value: %ls\n", value.c_str());
          ExitProcess(2);
        }
        options.nwsync_manifests.push_back(std::move(manifest));
        options.enable_nwsync_advertisement = true;
        options.rewrite_module_hak_list = true;
      } else if (arg == L"--nwsync-http") {
        if (!ParseListenEndpoint(value, &options.nwsync_http_host, &options.nwsync_http_port)) {
          fwprintf(stderr, L"Invalid --nwsync-http endpoint: %ls\n", value.c_str());
          ExitProcess(2);
        }
        options.enable_nwsync_http = true;
      } else if (arg == L"--bncs-private-build") {
        uint32_t private_build = 0;
        if (!ParseUnsigned32Flexible(value, &private_build)) {
          fwprintf(stderr, L"Invalid --bncs-private-build value: %ls\n", value.c_str());
          ExitProcess(2);
        }
        options.rewrite_bncs_private_build = true;
        options.bncs_private_build = private_build;
      } else if (arg == L"--rewrite-bncs-field") {
        unsigned short field = 0;
        if (!ParseUnsigned16Flexible(value, &field)) {
          fwprintf(stderr, L"Invalid --rewrite-bncs-field value: %ls\n", value.c_str());
          ExitProcess(2);
        }
        options.rewrite_bncs_field = true;
        options.bncs_build_field = field;
      } else if (arg == L"--session-timeout-ms") {
        uint32_t timeout = 0;
        if (!ParseUnsigned32(value, &timeout)) {
          fwprintf(stderr, L"Invalid --session-timeout-ms value: %ls\n", value.c_str());
          ExitProcess(2);
        }
        options.session_timeout_ms = timeout;
      }
    } else {
      fwprintf(stderr, L"Unknown or incomplete argument: %ls\n", arg.c_str());
      PrintUsage();
      ExitProcess(2);
    }
  }

  if (options.server_host.empty()) {
    const hgbridge::HgServer* server = hgbridge::FindServerById(options.server_id);
    if (server == nullptr) {
      fwprintf(stderr, L"Unknown HG server id: %ls\n", options.server_id.c_str());
      fwprintf(stderr, L"Use --list-servers to see known shortcuts.\n");
      ExitProcess(2);
    }
    options.server_host = std::wstring(server->ip);
    options.server_port = server->port;
  }
  if (options.diamond_cdkey_path.empty()) {
    options.diamond_cdkey_path = GetEnvironmentString(L"HG_BRIDGE_DIAMOND_CDKEY_PATH");
  }
  if (options.baseitems_path.empty()) {
    options.baseitems_path = GetEnvironmentString(L"HG_BRIDGE_BASEITEMS_PATH");
  }
  options.server_address = FormatEndpoint(options.server_host, options.server_port);
  return options;
}

bool ResolveUdpPeer(const std::wstring& host, unsigned short port, PeerAddress* peer) {
  if (peer == nullptr) {
    return false;
  }

  ADDRINFOW hints{};
  hints.ai_family = AF_INET;
  hints.ai_socktype = SOCK_DGRAM;
  hints.ai_protocol = IPPROTO_UDP;

  ADDRINFOW* result = nullptr;
  const std::wstring port_text = std::to_wstring(port);
  const int status = GetAddrInfoW(host.c_str(), port_text.c_str(), &hints, &result);
  if (status != 0 || result == nullptr) {
    LogFormat(L"resolve failed: %s:%hu status=%d", host.c_str(), port, status);
    return false;
  }

  peer->length = static_cast<int>(result->ai_addrlen);
  std::memcpy(&peer->storage, result->ai_addr, result->ai_addrlen);
  FreeAddrInfoW(result);
  return true;
}

bool MakeBindAddress(const std::wstring& host, unsigned short port, sockaddr_in* out) {
  if (out == nullptr) {
    return false;
  }
  *out = {};
  out->sin_family = AF_INET;
  out->sin_port = htons(port);

  if (host.empty() || host == L"*" || host == L"0.0.0.0") {
    out->sin_addr.s_addr = htonl(INADDR_ANY);
    return true;
  }

  if (InetPtonW(AF_INET, host.c_str(), &out->sin_addr) == 1) {
    return true;
  }

  PeerAddress resolved{};
  if (!ResolveUdpPeer(host, port, &resolved) || resolved.storage.ss_family != AF_INET) {
    return false;
  }
  const auto* ipv4 = reinterpret_cast<const sockaddr_in*>(&resolved.storage);
  out->sin_addr = ipv4->sin_addr;
  return true;
}

std::wstring FormatSockaddr(const sockaddr* address, int length) {
  if (address == nullptr || length < static_cast<int>(sizeof(sockaddr))) {
    return L"<null>";
  }
  if (address->sa_family == AF_INET && length >= static_cast<int>(sizeof(sockaddr_in))) {
    const auto* ipv4 = reinterpret_cast<const sockaddr_in*>(address);
    wchar_t host[64]{};
    InetNtopW(AF_INET, const_cast<IN_ADDR*>(&ipv4->sin_addr), host, static_cast<DWORD>(_countof(host)));
    return std::wstring(host) + L":" + std::to_wstring(ntohs(ipv4->sin_port));
  }
  return L"family=" + std::to_wstring(address->sa_family) + L" len=" + std::to_wstring(length);
}

std::wstring FormatPeer(const PeerAddress& peer) {
  return FormatSockaddr(reinterpret_cast<const sockaddr*>(&peer.storage), peer.length);
}

PeerAddress MakePeerAddress(const sockaddr* address, int length) {
  PeerAddress peer{};
  if (address != nullptr && length > 0 && static_cast<size_t>(length) <= sizeof(peer.storage)) {
    peer.length = length;
    std::memcpy(&peer.storage, address, static_cast<size_t>(length));
  }
  return peer;
}

bool SameSockaddr(const PeerAddress& left, const sockaddr* right, int right_length) {
  if (right == nullptr || left.length != right_length || left.storage.ss_family != right->sa_family) {
    return false;
  }
  if (right->sa_family == AF_INET) {
    const auto* left_ipv4 = reinterpret_cast<const sockaddr_in*>(&left.storage);
    const auto* right_ipv4 = reinterpret_cast<const sockaddr_in*>(right);
    return left_ipv4->sin_port == right_ipv4->sin_port &&
        left_ipv4->sin_addr.s_addr == right_ipv4->sin_addr.s_addr;
  }
  return std::memcmp(&left.storage, right, static_cast<size_t>(right_length)) == 0;
}

std::wstring SocketLocalEndpoint(SOCKET socket) {
  sockaddr_storage storage{};
  int length = sizeof(storage);
  if (getsockname(socket, reinterpret_cast<sockaddr*>(&storage), &length) == SOCKET_ERROR) {
    return L"<getsockname failed " + std::to_wstring(WSAGetLastError()) + L">";
  }
  return FormatSockaddr(reinterpret_cast<const sockaddr*>(&storage), length);
}

bool IsLoopbackClient(const sockaddr* address, int length) {
  if (address == nullptr || address->sa_family != AF_INET || length < static_cast<int>(sizeof(sockaddr_in))) {
    return false;
  }
  const auto* ipv4 = reinterpret_cast<const sockaddr_in*>(address);
  const uint32_t host_order = ntohl(ipv4->sin_addr.s_addr);
  return (host_order & 0xFF000000u) == 0x7F000000u;
}

std::wstring FormatLimitedBytes(const unsigned char* bytes, size_t length, size_t limit = 64) {
  if (bytes == nullptr || length == 0) {
    return L"<empty>";
  }

  const size_t count = std::min(length, limit);
  std::wstring result;
  result.reserve(count * 3 + 8);
  wchar_t cell[8]{};
  for (size_t index = 0; index < count; ++index) {
    if (index != 0) {
      result.push_back(L' ');
    }
    swprintf_s(cell, L"%02X", static_cast<unsigned int>(bytes[index]));
    result.append(cell);
  }
  if (length > count) {
    result.append(L" ...");
  }
  return result;
}

std::wstring PacketPrefix(const unsigned char* bytes, size_t length) {
  if (bytes == nullptr || length == 0) {
    return L"<empty>";
  }

  wchar_t text[192]{};
  const size_t prefix_count = std::min<size_t>(length, 4);
  wchar_t ascii[8]{};
  for (size_t i = 0; i < prefix_count; ++i) {
    const unsigned char ch = bytes[i];
    ascii[i] = ch >= 0x20 && ch <= 0x7E ? static_cast<wchar_t>(ch) : L'.';
  }
  ascii[prefix_count] = L'\0';
  swprintf_s(
      text,
      L"'%s' len=%zu bytes=[%s]",
      ascii,
      length,
      FormatLimitedBytes(bytes, length, 32).c_str());
  return text;
}

bool StartsWith(const unsigned char* bytes, size_t length, const char* prefix) {
  if (bytes == nullptr || prefix == nullptr) {
    return false;
  }
  const size_t prefix_length = std::strlen(prefix);
  return length >= prefix_length && std::memcmp(bytes, prefix, prefix_length) == 0;
}

bool LooksLikeBnControlPacket(const unsigned char* bytes, size_t length) {
  return bytes != nullptr && length >= 4 && bytes[0] == 'B' && bytes[1] == 'N';
}

std::wstring PacketTag(const unsigned char* bytes, size_t length) {
  if (bytes == nullptr || length < 4) {
    return L"<short>";
  }
  wchar_t tag[5]{};
  for (size_t index = 0; index < 4; ++index) {
    const unsigned char ch = bytes[index];
    tag[index] = ch >= 0x20 && ch <= 0x7E ? static_cast<wchar_t>(ch) : L'.';
  }
  return tag;
}

const wchar_t* KnownBnControlDescription(const unsigned char* bytes, size_t length) {
  if (!LooksLikeBnControlPacket(bytes, length)) {
    return L"not BN control";
  }
  if (StartsWith(bytes, length, "BNCS")) return L"legacy connect start";
  if (StartsWith(bytes, length, "BNCR")) return L"legacy verifier challenge";
  if (StartsWith(bytes, length, "BNVS")) return L"legacy verifier response";
  if (StartsWith(bytes, length, "BNVR")) return L"legacy verifier result";
  if (StartsWith(bytes, length, "BNK0")) return L"EE key exchange reset";
  if (StartsWith(bytes, length, "BNK1")) return L"EE key exchange packet 1";
  if (StartsWith(bytes, length, "BNK2")) return L"EE key exchange packet 2";
  if (StartsWith(bytes, length, "BNK3")) return L"EE key exchange packet 3";
  if (StartsWith(bytes, length, "BNK4")) return L"EE key exchange identity";
  if (StartsWith(bytes, length, "BNDM")) return L"EE direct message";
  if (StartsWith(bytes, length, "BNDP")) return L"EE direct-packet control";
  if (StartsWith(bytes, length, "BNDR")) return L"EE direct response";
  if (StartsWith(bytes, length, "BNDS")) return L"EE disconnect";
  if (StartsWith(bytes, length, "BNER")) return L"EE error response";
  if (StartsWith(bytes, length, "BNES")) return L"EE server discovery";
  if (StartsWith(bytes, length, "BNLM")) return L"EE list message";
  if (StartsWith(bytes, length, "BNLR")) return L"EE list response";
  if (StartsWith(bytes, length, "BNXI")) return L"EE extended info";
  if (StartsWith(bytes, length, "BNXR")) return L"EE extended response";
  return L"unknown BN control";
}

bool IsEeBnkPacket(const unsigned char* bytes, size_t length) {
  return StartsWith(bytes, length, "BNK0") ||
      StartsWith(bytes, length, "BNK1") ||
      StartsWith(bytes, length, "BNK2") ||
      StartsWith(bytes, length, "BNK3") ||
      StartsWith(bytes, length, "BNK4");
}

const wchar_t* ExpectedBnkSizeText(const unsigned char* bytes, size_t length) {
  if (StartsWith(bytes, length, "BNK0")) return L">= 4";
  if (StartsWith(bytes, length, "BNK1")) return L"36";
  if (StartsWith(bytes, length, "BNK2")) return L"84";
  if (StartsWith(bytes, length, "BNK3")) return L"52";
  if (StartsWith(bytes, length, "BNK4")) return L"8";
  return L"<unknown>";
}

bool BnkSizeMatches(const unsigned char* bytes, size_t length) {
  if (StartsWith(bytes, length, "BNK0")) return length >= 4;
  if (StartsWith(bytes, length, "BNK1")) return length == 36;
  if (StartsWith(bytes, length, "BNK2")) return length == 84;
  if (StartsWith(bytes, length, "BNK3")) return length == 52;
  if (StartsWith(bytes, length, "BNK4")) return length == 8;
  return false;
}

bool IsEeDirectControlCollision(const unsigned char* bytes, size_t length) {
  return StartsWith(bytes, length, "BNDM") ||
      StartsWith(bytes, length, "BNDP") ||
      StartsWith(bytes, length, "BNDR") ||
      StartsWith(bytes, length, "BNDS");
}

bool PacketRequiresEeEncryption(const unsigned char* bytes, size_t length) {
  if (bytes == nullptr || length < 4) {
    return true;
  }
  if (bytes[0] == 'B' && bytes[1] == 'N' && bytes[2] != 'C' && bytes[2] != 'V') {
    return false;
  }
  return true;
}

bool IsEeIdentityEncryptedPacket(const std::vector<unsigned char>& packet) {
  return packet.size() >= kEeEncryptedIdentityHeaderBytes + kNwnHydroSecretboxHeaderBytes &&
      packet[0] == 'I';
}

uint32_t GenerateEeCryptoIdentity() {
  uint32_t identity = 0;
  if (g_ee_crypto.Ready()) {
    for (int attempt = 0; attempt < 16; ++attempt) {
      identity = g_ee_crypto.RandomU32();
      if (identity != 0 && identity != 0xFFFFFFFFu) {
        return identity;
      }
    }
  }
  identity = static_cast<uint32_t>(GetTickCount64());
  if (identity == 0 || identity == 0xFFFFFFFFu) {
    identity = 1;
  }
  return identity;
}

uint16_t ReadU16Le(const unsigned char* bytes) {
  return static_cast<uint16_t>(bytes[0] | (static_cast<uint16_t>(bytes[1]) << 8));
}

uint16_t ReadU16Be(const unsigned char* bytes) {
  return static_cast<uint16_t>((static_cast<uint16_t>(bytes[0]) << 8) | bytes[1]);
}

uint32_t ReadU32Le(const unsigned char* bytes) {
  return static_cast<uint32_t>(bytes[0]) |
      (static_cast<uint32_t>(bytes[1]) << 8) |
      (static_cast<uint32_t>(bytes[2]) << 16) |
      (static_cast<uint32_t>(bytes[3]) << 24);
}

bool TryReadWindowPacketizedPayloadLength(
    const unsigned char* packet,
    size_t length,
    bool extended_length,
    uint32_t* payload_length) {
  if (packet == nullptr || payload_length == nullptr || length < kLegacyGameplayPayloadOffset) {
    return false;
  }

  if (extended_length) {
    if (length < kLegacyGameplayPayloadOffset + 2) {
      return false;
    }
    *payload_length =
        (static_cast<uint32_t>(packet[12]) << 24) |
        (static_cast<uint32_t>(packet[13]) << 16) |
        (static_cast<uint32_t>(packet[10]) << 8) |
        static_cast<uint32_t>(packet[11]);
    return true;
  }

  *payload_length = ReadU16Be(packet + 10);
  return true;
}

void WriteU16Le(unsigned char* bytes, uint16_t value) {
  bytes[0] = static_cast<unsigned char>(value & 0xFFu);
  bytes[1] = static_cast<unsigned char>((value >> 8) & 0xFFu);
}

void WriteU16Be(unsigned char* bytes, uint16_t value) {
  bytes[0] = static_cast<unsigned char>((value >> 8) & 0xFFu);
  bytes[1] = static_cast<unsigned char>(value & 0xFFu);
}

void WriteU32Le(unsigned char* bytes, uint32_t value) {
  bytes[0] = static_cast<unsigned char>(value & 0xFFu);
  bytes[1] = static_cast<unsigned char>((value >> 8) & 0xFFu);
  bytes[2] = static_cast<unsigned char>((value >> 16) & 0xFFu);
  bytes[3] = static_cast<unsigned char>((value >> 24) & 0xFFu);
}

const std::array<uint32_t, 256>& NetLayerCrcTable() {
  static const std::array<uint32_t, 256> table = [] {
    std::array<uint32_t, 256> values{};
    for (uint32_t index = 0; index < values.size(); ++index) {
      uint32_t value = index;
      for (int bit = 0; bit < 8; ++bit) {
        value = (value & 1u) != 0 ? ((value >> 1) ^ 0xEDB88320u) : (value >> 1);
      }
      values[index] = value;
    }
    return values;
  }();
  return table;
}

uint16_t CalculateNetLayerFrameCrc(const unsigned char* packet, size_t length) {
  if (packet == nullptr || length < kLegacyGameplayPayloadOffset) {
    return 0;
  }

  uint32_t crc = 0;
  const auto& table = NetLayerCrcTable();
  for (size_t index = 3; index < length; ++index) {
    crc = (crc >> 8) ^ table[(crc ^ packet[index]) & 0xFFu];
  }
  return static_cast<uint16_t>(crc & 0xFFFFu);
}

bool EncodeNetLayerFrameCrc(std::vector<unsigned char>* packet) {
  if (packet == nullptr || packet->size() < kLegacyGameplayPayloadOffset || packet->front() != 'M') {
    return false;
  }
  WriteU16Be(packet->data() + 1, CalculateNetLayerFrameCrc(packet->data(), packet->size()));
  return true;
}

bool UpdateWindowPacketizedPayloadLength(std::vector<unsigned char>* packet, uint32_t payload_length) {
  if (packet == nullptr || packet->size() < kLegacyGameplayPayloadOffset || packet->front() != 'M') {
    return false;
  }

  const unsigned char flags = (*packet)[7];
  if ((flags & 0x80u) != 0) {
    if (packet->size() < kLegacyGameplayPayloadOffset + 2) {
      return false;
    }
    (*packet)[12] = static_cast<unsigned char>((payload_length >> 24) & 0xFFu);
    (*packet)[13] = static_cast<unsigned char>((payload_length >> 16) & 0xFFu);
    (*packet)[10] = static_cast<unsigned char>((payload_length >> 8) & 0xFFu);
    (*packet)[11] = static_cast<unsigned char>(payload_length & 0xFFu);
    return true;
  }

  if (payload_length > 0xFFFFu) {
    return false;
  }
  WriteU16Be(packet->data() + 10, static_cast<uint16_t>(payload_length));
  return true;
}

bool IsLegacyStartupGamePacket(const unsigned char* message, size_t length) {
  return message != nullptr &&
      length == 15 &&
      message[0] == 'M' &&
      message[3] == 0x00 &&
      message[5] == 0xFF &&
      message[6] == 0xFF &&
      message[8] == 0x00 &&
      message[9] == 0x01 &&
      message[10] == 0x00 &&
      message[11] == 0x03 &&
      message[12] == 0x70;
}

bool ReadLegacyLengthSegment(const unsigned char* message, size_t length, size_t* cursor, std::string* value) {
  if (message == nullptr || cursor == nullptr || value == nullptr || *cursor >= length) {
    return false;
  }
  const size_t segment_length = message[*cursor];
  ++(*cursor);
  if (segment_length > length - *cursor) {
    return false;
  }
  value->assign(reinterpret_cast<const char*>(message + *cursor), segment_length);
  *cursor += segment_length;
  return true;
}

std::string TrimAscii(std::string_view value) {
  size_t first = 0;
  while (first < value.size() && (value[first] == ' ' || value[first] == '\t' || value[first] == '\r' || value[first] == '\n')) {
    ++first;
  }
  size_t last = value.size();
  while (last > first && (value[last - 1] == ' ' || value[last - 1] == '\t' || value[last - 1] == '\r' || value[last - 1] == '\n')) {
    --last;
  }
  return std::string(value.substr(first, last - first));
}

std::vector<std::string> SplitAsciiWhitespace(std::string_view value) {
  std::vector<std::string> result;
  size_t cursor = 0;
  while (cursor < value.size()) {
    while (cursor < value.size() &&
        (value[cursor] == ' ' || value[cursor] == '\t' ||
         value[cursor] == '\r' || value[cursor] == '\n')) {
      ++cursor;
    }
    if (cursor >= value.size()) {
      break;
    }
    const size_t start = cursor;
    while (cursor < value.size() &&
        value[cursor] != ' ' && value[cursor] != '\t' &&
        value[cursor] != '\r' && value[cursor] != '\n') {
      ++cursor;
    }
    result.emplace_back(value.substr(start, cursor - start));
  }
  return result;
}

bool ParseUnsigned32Ascii(std::string_view value, uint32_t* out) {
  if (out != nullptr) {
    *out = 0;
  }
  if (out == nullptr || value.empty()) {
    return false;
  }
  uint64_t parsed = 0;
  for (char ch : value) {
    if (ch < '0' || ch > '9') {
      return false;
    }
    parsed = parsed * 10 + static_cast<uint64_t>(ch - '0');
    if (parsed > 0xFFFFFFFFull) {
      return false;
    }
  }
  *out = static_cast<uint32_t>(parsed);
  return true;
}

bool ParseUnsigned64Ascii(std::string_view value, uint64_t* out) {
  if (out != nullptr) {
    *out = 0;
  }
  if (out == nullptr || value.empty()) {
    return false;
  }
  uint64_t parsed = 0;
  for (char ch : value) {
    if (ch < '0' || ch > '9') {
      return false;
    }
    const uint64_t digit = static_cast<uint64_t>(ch - '0');
    if (parsed > (UINT64_MAX - digit) / 10ull) {
      return false;
    }
    parsed = parsed * 10ull + digit;
  }
  *out = parsed;
  return true;
}

bool ParseSigned32Ascii(std::string_view value, int32_t* out) {
  if (out != nullptr) {
    *out = 0;
  }
  if (out == nullptr || value.empty()) {
    return false;
  }
  bool negative = false;
  if (value.front() == '-') {
    negative = true;
    value.remove_prefix(1);
  }
  uint32_t unsigned_value = 0;
  if (!ParseUnsigned32Ascii(value, &unsigned_value)) {
    return false;
  }
  if ((!negative && unsigned_value > 0x7FFFFFFFu) ||
      (negative && unsigned_value > 0x80000000u)) {
    return false;
  }
  *out = negative
      ? -static_cast<int32_t>(unsigned_value)
      : static_cast<int32_t>(unsigned_value);
  return true;
}

bool ReadSmallTextFile(const std::wstring& path, std::string* contents) {
  if (contents == nullptr || path.empty()) {
    return false;
  }
  contents->clear();

  HANDLE file = CreateFileW(path.c_str(), GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE, nullptr, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
  if (file == INVALID_HANDLE_VALUE) {
    return false;
  }

  LARGE_INTEGER size{};
  if (!GetFileSizeEx(file, &size) || size.QuadPart < 0 || size.QuadPart > 1024 * 1024) {
    CloseHandle(file);
    return false;
  }

  std::string data(static_cast<size_t>(size.QuadPart), '\0');
  DWORD read = 0;
  const BOOL ok = data.empty()
      ? TRUE
      : ReadFile(file, data.data(), static_cast<DWORD>(data.size()), &read, nullptr);
  CloseHandle(file);
  if (!ok || read != data.size()) {
    return false;
  }
  *contents = std::move(data);
  return true;
}

bool ReadBinaryFileRange(
    const std::wstring& path,
    uint64_t offset,
    uint32_t size,
    size_t max_size,
    std::vector<unsigned char>* data) {
  if (data == nullptr || path.empty() || size > max_size) {
    return false;
  }
  data->clear();

  std::error_code ec;
  const uintmax_t file_size = std::filesystem::file_size(std::filesystem::path(path), ec);
  if (ec || offset > file_size || static_cast<uint64_t>(size) > file_size - offset) {
    return false;
  }

  std::ifstream file(std::filesystem::path(path), std::ios::binary);
  if (!file) {
    return false;
  }
  file.seekg(static_cast<std::streamoff>(offset), std::ios::beg);
  if (!file) {
    return false;
  }

  data->resize(size);
  if (!data->empty()) {
    file.read(reinterpret_cast<char*>(data->data()), static_cast<std::streamsize>(data->size()));
    if (file.gcount() != static_cast<std::streamsize>(data->size())) {
      data->clear();
      return false;
    }
  }
  return true;
}

std::wstring LowerWide(std::wstring value) {
  for (wchar_t& ch : value) {
    ch = static_cast<wchar_t>(towlower(ch));
  }
  return value;
}

bool LooksLikeErfContainerPath(const std::wstring& path) {
  const std::wstring ext = LowerWide(std::filesystem::path(path).extension().wstring());
  return ext == L".hak" || ext == L".erf" || ext == L".mod" || ext == L".nwm";
}

bool ReadErfTextResource(
    const std::wstring& path,
    std::string_view wanted_resref,
    std::string* contents) {
  if (contents == nullptr || path.empty() || wanted_resref.empty() || wanted_resref.size() > 16) {
    return false;
  }
  contents->clear();

  std::vector<unsigned char> header;
  if (!ReadBinaryFileRange(path, 0, 32, 32, &header) || header.size() < 32) {
    return false;
  }
  if (memcmp(header.data(), "HAK ", 4) != 0 &&
      memcmp(header.data(), "ERF ", 4) != 0 &&
      memcmp(header.data(), "MOD ", 4) != 0) {
    return false;
  }
  if (memcmp(header.data() + 4, "V1.0", 4) != 0) {
    return false;
  }

  const uint32_t entry_count = ReadU32Le(header.data() + 16);
  const uint32_t key_list_offset = ReadU32Le(header.data() + 24);
  const uint32_t resource_list_offset = ReadU32Le(header.data() + 28);
  constexpr uint32_t kMaxReasonableErfResources = 200000;
  if (entry_count == 0 || entry_count > kMaxReasonableErfResources) {
    return false;
  }

  std::vector<unsigned char> keys;
  if (entry_count > UINT32_MAX / 24 ||
      !ReadBinaryFileRange(
          path,
          key_list_offset,
          entry_count * 24u,
          static_cast<size_t>(kMaxReasonableErfResources) * 24u,
          &keys)) {
    return false;
  }

  uint32_t resource_index = UINT32_MAX;
  uint16_t resource_type = 0;
  for (uint32_t index = 0; index < entry_count; ++index) {
    const unsigned char* key = keys.data() + static_cast<size_t>(index) * 24u;
    size_t length = 0;
    while (length < 16 && key[length] != 0) {
      ++length;
    }
    const std::string resref(reinterpret_cast<const char*>(key), length);
    if (_stricmp(resref.c_str(), std::string(wanted_resref).c_str()) != 0) {
      continue;
    }
    resource_index = ReadU32Le(key + 16);
    resource_type = ReadU16Le(key + 20);
    break;
  }
  if (resource_index == UINT32_MAX || resource_index >= entry_count) {
    return false;
  }

  std::vector<unsigned char> resource_entry;
  if (!ReadBinaryFileRange(
          path,
          static_cast<uint64_t>(resource_list_offset) + static_cast<uint64_t>(resource_index) * 8u,
          8,
          8,
          &resource_entry) ||
      resource_entry.size() < 8) {
    return false;
  }

  constexpr uint16_t kResType2da = 2017;
  constexpr size_t kMaxReasonable2daBytes = 2 * 1024 * 1024;
  const uint32_t resource_offset = ReadU32Le(resource_entry.data());
  const uint32_t resource_size = ReadU32Le(resource_entry.data() + 4);
  if (resource_type != kResType2da || resource_size == 0 || resource_size > kMaxReasonable2daBytes) {
    return false;
  }

  std::vector<unsigned char> bytes;
  if (!ReadBinaryFileRange(path, resource_offset, resource_size, kMaxReasonable2daBytes, &bytes)) {
    return false;
  }
  contents->assign(reinterpret_cast<const char*>(bytes.data()), bytes.size());
  return true;
}

std::string NormalizeCdKeyValue(std::string_view value) {
  std::string result = TrimAscii(value);
  if (result.size() >= 2 && ((result.front() == '"' && result.back() == '"') || (result.front() == '\'' && result.back() == '\''))) {
    result = result.substr(1, result.size() - 2);
  }
  for (char& ch : result) {
    if (ch >= 'a' && ch <= 'z') {
      ch = static_cast<char>(ch - 'a' + 'A');
    }
  }
  return result;
}

std::vector<std::string> ParseCdKeyIniValues(std::string_view contents) {
  std::vector<std::string> keys;
  size_t cursor = 0;
  while (cursor < contents.size()) {
    size_t end = contents.find('\n', cursor);
    if (end == std::string_view::npos) {
      end = contents.size();
    }
    std::string line = TrimAscii(contents.substr(cursor, end - cursor));
    cursor = end + 1;
    if (line.empty() || line[0] == ';' || line[0] == '#') {
      continue;
    }
    const size_t equals = line.find('=');
    if (equals == std::string::npos) {
      continue;
    }
    std::string key = NormalizeCdKeyValue(std::string_view(line).substr(equals + 1));
    if (key.size() == 41) {
      keys.push_back(std::move(key));
    }
  }
  return keys;
}

bool UnscrambleCdKeyPublicPart(std::string_view key, std::string* public_part) {
  if (public_part != nullptr) {
    public_part->clear();
  }
  if (public_part == nullptr || key.size() != 41) {
    return false;
  }

  std::string public_key;
  std::string private_part;
  std::string checksum_part;
  int state = 0;

  for (size_t index = 0; index < key.size();) {
    const char ch = key[index];
    bool reprocess = false;
    if (ch != '-') {
      if (state == 0) {
        state = 1;
        if (private_part.size() < 20) {
          private_part.push_back(ch);
        }
      } else if (state == 1) {
        state = 2;
        if (private_part.size() <= 12) {
          state = 0;
          if (public_key.size() < 8) {
            public_key.push_back(ch);
          } else if (private_part.size() < 20 || checksum_part.size() < 7) {
            reprocess = true;
          }
        } else if (checksum_part.size() < 7) {
          checksum_part.push_back(ch);
        }
      } else {
        state = 0;
        if (public_key.size() < 8) {
          public_key.push_back(ch);
        } else if (private_part.size() < 20 || checksum_part.size() < 7) {
          reprocess = true;
        }
      }
    }

    if (!reprocess) {
      ++index;
    }
  }

  if (public_key.size() != 8) {
    return false;
  }
  *public_part = std::move(public_key);
  return true;
}

bool Md5HexLower(std::string_view input, std::string* output) {
  if (output == nullptr || input.size() > 0xFFFFFFFFull) {
    return false;
  }
  output->clear();

  HCRYPTPROV provider = 0;
  HCRYPTHASH hash = 0;
  if (!CryptAcquireContextW(&provider, nullptr, nullptr, PROV_RSA_FULL, CRYPT_VERIFYCONTEXT)) {
    return false;
  }

  bool ok = false;
  if (CryptCreateHash(provider, CALG_MD5, 0, 0, &hash) &&
      CryptHashData(hash, reinterpret_cast<const BYTE*>(input.data()), static_cast<DWORD>(input.size()), 0)) {
    BYTE digest[16]{};
    DWORD digest_size = sizeof(digest);
    if (CryptGetHashParam(hash, HP_HASHVAL, digest, &digest_size, 0) && digest_size == sizeof(digest)) {
      static constexpr char kHex[] = "0123456789abcdef";
      std::string text;
      text.resize(sizeof(digest) * 2);
      for (size_t index = 0; index < sizeof(digest); ++index) {
        text[index * 2] = kHex[(digest[index] >> 4) & 0x0F];
        text[index * 2 + 1] = kHex[digest[index] & 0x0F];
      }
      *output = std::move(text);
      ok = true;
    }
  }

  if (hash != 0) {
    CryptDestroyHash(hash);
  }
  CryptReleaseContext(provider, 0);
  return ok;
}

bool BuildLegacyCdKeyVerifier(const std::string& raw_key, const std::string& public_key, const std::string& challenge, std::string* verifier) {
  if (verifier == nullptr) {
    return false;
  }
  verifier->clear();
  if (raw_key.empty() || public_key.size() != 8 || challenge.empty()) {
    return false;
  }

  std::string digest;
  if (!Md5HexLower(raw_key + challenge, &digest) || digest.size() != 32) {
    return false;
  }
  *verifier = public_key + digest;
  return verifier->size() == 40;
}

void AppendLegacyLengthSegment(std::vector<unsigned char>* packet, const std::string& value) {
  if (packet == nullptr || value.size() > 255) {
    return;
  }
  packet->push_back(static_cast<unsigned char>(value.size()));
  packet->insert(packet->end(), value.begin(), value.end());
}

void LoadDiamondCdKeys(BridgeRuntime* runtime) {
  if (runtime == nullptr || runtime->options.diamond_cdkey_path.empty()) {
    return;
  }

  const std::wstring path = FullPath(runtime->options.diamond_cdkey_path);
  std::string contents;
  if (!ReadSmallTextFile(path, &contents)) {
    LogFormat(L"Diamond CD key source unreadable: path=%s", path.c_str());
    return;
  }

  std::vector<std::string> keys = ParseCdKeyIniValues(contents);
  std::vector<std::string> public_keys;
  public_keys.reserve(keys.size());
  for (const std::string& key : keys) {
    std::string public_key;
    if (UnscrambleCdKeyPublicPart(key, &public_key)) {
      public_keys.push_back(std::move(public_key));
    }
  }

  runtime->diamond_cd_keys = std::move(keys);
  runtime->diamond_public_cd_keys = std::move(public_keys);
  LogFormat(
      L"Diamond CD key source loaded: raw_count=%zu public_count=%zu primary_public='%s' path=%s",
      runtime->diamond_cd_keys.size(),
      runtime->diamond_public_cd_keys.size(),
      runtime->diamond_public_cd_keys.empty()
          ? L"<none>"
          : AsciiPreviewToWide(runtime->diamond_public_cd_keys.front(), 16).c_str(),
      path.c_str());
}

