struct LegacyLiveInventoryFeature25Shape {
  uint32_t first_count = 0;
  uint32_t second_count = 0;
  size_t first_objects_offset = 0;
  size_t second_count_offset = 0;
  size_t second_objects_offset = 0;
  size_t block_end = 0;
  bool missing_second_count = false;
};

struct LegacyLiveInventory2A00Shape {
  LegacyLiveInventoryFeature25Shape feature25;
  size_t feature25_bit_offset = 0;
  size_t total_bit_count = 0;
  bool inventory0800_true_tail = false;
};

bool TryParseLegacyLiveInventoryFeature25ShapeAt(
    const std::vector<unsigned char>& bytes,
    size_t cursor,
    size_t record_end,
    LegacyLiveInventoryFeature25Shape* shape);

bool LooksLikeLegacyLiveInventoryFeature25ObjectList(
    const std::vector<unsigned char>& bytes,
    size_t offset,
    size_t count,
    size_t record_end) {
  constexpr size_t kMaxReasonableInventoryFeature25Objects = 128;
  if (count > kMaxReasonableInventoryFeature25Objects ||
      offset > record_end ||
      record_end > bytes.size() ||
      count > (record_end - offset) / 4) {
    return false;
  }
  for (size_t index = 0; index < count; ++index) {
    uint32_t object_id = 0;
    if (!TryReadU32LeFromBytes(bytes, offset + index * 4, &object_id) ||
        !LooksLikeLegacyLiveObjectIdValue(object_id)) {
      return false;
    }
  }
  return true;
}

bool TryParseLegacyLiveInventoryFeature25Shape(
    const std::vector<unsigned char>& bytes,
    size_t record_offset,
    size_t record_end,
    LegacyLiveInventoryFeature25Shape* shape) {
  if (shape != nullptr) {
    *shape = LegacyLiveInventoryFeature25Shape{};
  }
  if (record_offset > bytes.size() ||
      record_end > bytes.size() ||
      record_end <= record_offset ||
      record_end - record_offset < 11 ||
      bytes[record_offset] != 'I') {
    return false;
  }

  uint32_t object_id = 0;
  uint16_t mask = 0;
  if (!TryReadU32LeFromBytes(bytes, record_offset + 1, &object_id) ||
      !TryReadU16LeFromBytes(bytes, record_offset + 5, &mask) ||
      !LooksLikeLegacyLiveObjectIdValue(object_id) ||
      mask != 0x2000u) {
    return false;
  }

  LegacyLiveInventoryFeature25Shape local;
  if (!TryParseLegacyLiveInventoryFeature25ShapeAt(
          bytes,
          record_offset + 7,
          record_end,
          &local) ||
      local.block_end != record_end) {
    return false;
  }
  if (shape != nullptr) {
    *shape = local;
  }
  return true;
}

bool TryParseLegacyLiveInventoryFeature25ShapeAt(
    const std::vector<unsigned char>& bytes,
    size_t cursor,
    size_t record_end,
    LegacyLiveInventoryFeature25Shape* shape) {
  if (shape != nullptr) {
    *shape = LegacyLiveInventoryFeature25Shape{};
  }
  if (cursor > bytes.size() ||
      record_end > bytes.size() ||
      cursor > record_end ||
      record_end - cursor < 4) {
    return false;
  }
  uint32_t first_count = 0;
  if (!TryReadU32LeFromBytes(bytes, cursor, &first_count)) {
    return false;
  }
  const size_t first_objects = cursor + 4;
  const size_t first_end =
      first_objects + static_cast<size_t>(first_count) * 4;
  if (first_end < first_objects || first_end > record_end ||
      !LooksLikeLegacyLiveInventoryFeature25ObjectList(
          bytes,
          first_objects,
          first_count,
          first_end)) {
    return false;
  }

  LegacyLiveInventoryFeature25Shape local;
  local.first_count = first_count;
  local.first_objects_offset = first_objects;
  local.second_count_offset = first_end;
  local.second_objects_offset = first_end + 4;

  if (first_end == record_end) {
    // 1.69 emits removal-only packets as one DWORD count followed by object ids.
    // EE 8193.37 always reads a second DWORD count after that list.
    local.missing_second_count = true;
    local.block_end = record_end;
    if (shape != nullptr) {
      *shape = local;
    }
    return true;
  }

  if (record_end - first_end < 4) {
    return false;
  }

  uint32_t second_count = 0;
  if (!TryReadU32LeFromBytes(bytes, first_end, &second_count)) {
    return false;
  }
  const size_t second_objects = first_end + 4;
  const size_t second_end =
      second_objects + static_cast<size_t>(second_count) * 4;
  if (second_end < second_objects || second_end > record_end ||
      !LooksLikeLegacyLiveInventoryFeature25ObjectList(
          bytes,
          second_objects,
          second_count,
          second_end)) {
    return false;
  }

  local.second_count = second_count;
  local.second_objects_offset = second_objects;
  local.block_end = second_end;
  if (shape != nullptr) {
    *shape = local;
  }
  return true;
}

bool TryParseLegacyLiveInventory2A00Shape(
    const std::vector<unsigned char>& bytes,
    size_t record_offset,
    size_t record_end,
    LegacyLiveInventory2A00Shape* shape) {
  if (shape != nullptr) {
    *shape = LegacyLiveInventory2A00Shape{};
  }
  if (record_offset > bytes.size() ||
      record_end > bytes.size() ||
      record_end <= record_offset ||
      record_end - record_offset < 7 ||
      bytes[record_offset] != 'I') {
    return false;
  }

  uint32_t object_id = 0;
  uint16_t mask = 0;
  if (!TryReadU32LeFromBytes(bytes, record_offset + 1, &object_id) ||
      !TryReadU16LeFromBytes(bytes, record_offset + 5, &mask) ||
      !LooksLikeLegacyLiveObjectIdValue(object_id) ||
      mask != 0x2A00u) {
    return false;
  }

  size_t cursor = record_offset + 7;
  if (record_end - cursor < 4) {
    return false;
  }
  uint32_t inventory0200_count = 0;
  if (!TryReadU32LeFromBytes(bytes, cursor, &inventory0200_count) ||
      inventory0200_count != 0) {
    // The nonzero 0x0200 branches have different per-entry fragment BOOL
    // shapes. Keep them evidence-driven instead of guessing the bit cursor.
    return false;
  }
  cursor += 4;

  LegacyLiveInventoryFeature25Shape feature25;
  if (!TryParseLegacyLiveInventoryFeature25ShapeAt(
          bytes,
          cursor,
          record_end,
          &feature25) ||
      feature25.missing_second_count ||
      feature25.block_end > record_end) {
    return false;
  }

  bool inventory0800_true_tail = false;
  if (feature25.block_end == record_end) {
    inventory0800_true_tail = false;
  } else if (record_end - feature25.block_end == 12) {
    inventory0800_true_tail = true;
  } else {
    return false;
  }

  LegacyLiveInventory2A00Shape local;
  local.feature25 = feature25;
  local.feature25_bit_offset = 2;
  local.total_bit_count =
      local.feature25_bit_offset +
      static_cast<size_t>(feature25.second_count) * 3u +
      1u;
  local.inventory0800_true_tail = inventory0800_true_tail;
  if (shape != nullptr) {
    *shape = local;
  }
  return true;
}

bool TryGetLegacyLiveInventoryFragmentBitCount(
    const std::vector<unsigned char>& bytes,
    size_t record_offset,
    size_t record_end,
    size_t* bit_count,
    bool trace_failures) {
  if (bit_count != nullptr) {
    *bit_count = 0;
  }
  if (record_offset > bytes.size() ||
      record_end > bytes.size() ||
      record_end <= record_offset ||
      record_end - record_offset < 7 ||
      bytes[record_offset] != 'I') {
    return false;
  }

  uint32_t object_id = 0;
  uint16_t mask = 0;
  if (!TryReadU32LeFromBytes(bytes, record_offset + 1, &object_id) ||
      !TryReadU16LeFromBytes(bytes, record_offset + 5, &mask) ||
      (object_id != 0xFFFFFFFDu && !LooksLikeLegacyLiveObjectIdValue(object_id))) {
    return false;
  }

  auto try_parse_inventory_0400 =
      [&](size_t cursor, size_t* parsed_set_count) -> bool {
    if (parsed_set_count != nullptr) {
      *parsed_set_count = 0;
    }
    if (cursor >= record_end) {
      return false;
    }
    const uint8_t clear_count = bytes[cursor++];
    if (clear_count > record_end - cursor) {
      return false;
    }
    cursor += clear_count;

    if (cursor >= record_end) {
      return false;
    }
    const uint8_t set_count = bytes[cursor++];
    if (set_count > record_end - cursor) {
      return false;
    }
    cursor += set_count;
    if (cursor != record_end) {
      return false;
    }

    if (parsed_set_count != nullptr) {
      *parsed_set_count = set_count;
    }
    return true;
  };

  if (mask == 0x2A00u) {
    LegacyLiveInventory2A00Shape inventory2a00;
    if (!TryParseLegacyLiveInventory2A00Shape(
            bytes,
            record_offset,
            record_end,
            &inventory2a00)) {
      return false;
    }
    if (bit_count != nullptr) {
      *bit_count = inventory2a00.total_bit_count;
    }
    return true;
  }

  if (mask == 0x2000u) {
    LegacyLiveInventoryFeature25Shape feature25;
    if (!TryParseLegacyLiveInventoryFeature25Shape(
            bytes,
            record_offset,
            record_end,
            &feature25)) {
      return false;
    }
    if (bit_count != nullptr) {
      *bit_count = feature25.second_count * 3u;
    }
    return true;
  }

  if (mask == 0x0401u) {
    // 0x0001 consumes one BOOL before the 0x0400 equipment delta. The
    // BOOL conditionally reads one WORD, so accept either read-buffer
    // shape when counting fragment bits for later object records.
    size_t set_count = 0;
    const size_t base_cursor = record_offset + 7 + 10;
    if (base_cursor <= record_end &&
        (try_parse_inventory_0400(base_cursor, &set_count) ||
         (record_end - base_cursor >= 2 &&
          try_parse_inventory_0400(base_cursor + 2, &set_count)))) {
      if (bit_count != nullptr) {
        *bit_count = 1 + set_count;
      }
      return true;
    }
    return false;
  }

  constexpr uint16_t kLegacyLiveInventoryGenericParseMask =
      0x0001u | 0x0002u | kLegacyLiveInventoryLegacyIconListMask |
      0x0008u | kLegacyLiveInventorySimpleCategoryMask |
      kLegacyLiveInventoryRichCategoryMask | 0x0040u | 0x0080u |
      0x0100u | 0x0400u | 0x1000u | 0x2000u | 0x4000u |
      0x8000u;

  if ((mask & ~kLegacyLiveInventoryGenericParseMask) == 0 &&
      (mask & (0x0200u | 0x0800u)) == 0) {
    size_t cursor = record_offset + 7;
    size_t parsed_bits = 0;
    bool ok = true;
    const bool trace_d5ff_self_inventory =
        object_id == 0xFFFFFFFDu && mask == 0xD5FFu;
    const wchar_t* stage = L"start";

    auto fail = [&](const wchar_t* reason) -> bool {
      if (trace_failures && trace_d5ff_self_inventory) {
        LogFormat(
            L"server->client live inventory generic parse failed: "
            L"reason=%s stage=%s offset=%zu cursor=%zu rel=%zu end=%zu "
            L"remaining=%zu bits=%zu prefix=[%s] around=[%s]",
            reason != nullptr ? reason : L"<unknown>",
            stage != nullptr ? stage : L"<unknown>",
            record_offset,
            cursor,
            cursor >= record_offset ? cursor - record_offset : 0,
            record_end,
            cursor <= record_end ? record_end - cursor : 0,
            parsed_bits,
            FormatLimitedBytes(
                bytes.data() + record_offset,
                record_end - record_offset,
                96)
                .c_str(),
            cursor <= record_end
                ? FormatLimitedBytes(bytes.data() + cursor, record_end - cursor, 96)
                      .c_str()
                : L"<past-end>");
      }
      return false;
    };

    auto remaining = [&]() -> size_t {
      return cursor <= record_end ? record_end - cursor : 0;
    };
    auto advance = [&](size_t count) -> bool {
      if (!ok || cursor > record_end || count > remaining()) {
        ok = false;
        return false;
      }
      cursor += count;
      return true;
    };
    auto read_u8 = [&](uint8_t* value) -> bool {
      if (!advance(1)) {
        return false;
      }
      if (value != nullptr) {
        *value = bytes[cursor - 1];
      }
      return true;
    };
    auto read_u16 = [&](uint16_t* value) -> bool {
      if (!ok || cursor > record_end || remaining() < 2) {
        ok = false;
        return false;
      }
      if (value != nullptr) {
        *value = ReadU16Le(bytes.data() + cursor);
      }
      cursor += 2;
      return true;
    };
    auto read_u32 = [&](uint32_t* value) -> bool {
      if (!ok || cursor > record_end || remaining() < 4) {
        ok = false;
        return false;
      }
      if (value != nullptr) {
        *value = ReadU32Le(bytes.data() + cursor);
      }
      cursor += 4;
      return true;
    };

    if ((mask & 0x0001u) != 0) {
      stage = L"0x0001";
      // HG's large self-inventory packet takes the legacy FALSE branch:
      // SHORT, DWORD, INT, one fragment BOOL, then the next mask bit.
      // The TRUE branch has variable strings and remains intentionally
      // unmodeled until a packet validates it.
      if (!advance(2 + 4 + 4)) {
        return fail(L"short-dword-int");
      }
      parsed_bits += 1;
    }

    if ((mask & 0x0002u) != 0) {
      stage = L"0x0002";
      if (!advance(4)) {
        return fail(L"dword");
      }
    }

    if ((mask & 0x0008u) != 0) {
      stage = L"0x0008";
      if (!advance(4)) {
        return fail(L"dword");
      }
    }

    if ((mask & 0x8000u) != 0) {
      stage = L"0x8000";
      if (!advance(12)) {
        return fail(L"three-ints");
      }
    }

    if ((mask & 0x0080u) != 0) {
      stage = L"0x0080";
      size_t group_end = 0;
      if (!TryAdvanceLegacyLiveInventoryTenBitValueGroups(
              bytes,
              cursor,
              record_end,
              &group_end,
              nullptr,
              nullptr)) {
        return fail(L"ten-bit-groups");
      }
      cursor = group_end;
    }

    if ((mask & kLegacyLiveInventorySimpleCategoryMask) != 0) {
      stage = L"0x0010";
      size_t simple_end = 0;
      if (!TryAdvanceLegacyLiveInventorySimpleCategoryBlock(
              bytes,
              cursor,
              record_end,
              kLegacyLiveInventoryCategoryCount,
              &simple_end,
              nullptr,
              nullptr)) {
        return fail(L"simple-category");
      }
      cursor = simple_end;
    }

    if ((mask & kLegacyLiveInventoryRichCategoryMask) != 0) {
      stage = L"0x0020";
      size_t rich_end = 0;
      uint32_t first_entries = 0;
      uint32_t second_entries = 0;
      if (!TryAdvanceLegacyLiveInventoryCategoryBlock(
              bytes,
              cursor,
              record_end,
              kLegacyLiveInventoryCategoryCount,
              &rich_end,
              &first_entries,
              &second_entries)) {
        return fail(L"rich-category");
      }
      cursor = rich_end;
      parsed_bits += static_cast<size_t>(second_entries) * 2u;
    }

    if ((mask & 0x0040u) != 0) {
      stage = L"0x0040";
      size_t group_end = 0;
      if (!TryAdvanceLegacyLiveInventoryTenBitValueGroups(
              bytes,
              cursor,
              record_end,
              &group_end,
              nullptr,
              nullptr)) {
        return fail(L"ten-bit-groups");
      }
      cursor = group_end;
    }

    if ((mask & 0x0400u) != 0) {
      stage = L"0x0400";
      uint8_t first_count = 0;
      if (!read_u8(&first_count) ||
          first_count > remaining() ||
          !advance(first_count)) {
        return fail(L"first-byte-list");
      }
      uint8_t second_count = 0;
      if (!read_u8(&second_count) ||
          second_count > remaining() ||
          !advance(second_count)) {
        return fail(L"second-byte-list");
      }
      parsed_bits += second_count;
    }

    if ((mask & kLegacyLiveInventoryLegacyIconListMask) != 0) {
      stage = L"0x0004";
      size_t legacy_icon_end = 0;
      uint32_t legacy_icon_bits = 0;
      if (!TryAdvanceLegacyLiveInventoryLegacyIconListBlock(
              bytes,
              cursor,
              record_end,
              &legacy_icon_end,
              nullptr,
              nullptr,
              &legacy_icon_bits)) {
        return fail(L"legacy-icon-list");
      }
      cursor = legacy_icon_end;
      parsed_bits += legacy_icon_bits;
    }

    if ((mask & 0x0100u) != 0) {
      stage = L"0x0100";
      uint8_t entry_count = 0;
      if (!read_u8(&entry_count)) {
        return fail(L"entry-count");
      }
      for (uint8_t entry = 0; entry < entry_count; ++entry) {
        uint8_t opcode = 0;
        if (!read_u8(&opcode)) {
          return fail(L"entry-opcode");
        }
        if (opcode == 'D') {
          if (!advance(2 + 2)) {
            return fail(L"D-entry");
          }
        } else if (opcode == 'S' || opcode == 'U') {
          if (!advance(2 + 2 + 4)) {
            return fail(L"S/U-entry");
          }
        } else if (opcode == 'A') {
          uint16_t item_type = 0;
          if (!read_u16(&item_type) || !advance(2)) {
            return fail(L"A-header");
          }
          if (item_type != 0 && item_type != 2 && !advance(4)) {
            return fail(L"A-object-id");
          }
          if (item_type == 0 || item_type == 2 || item_type == 4 ||
              item_type == 12 || item_type == 19) {
            if (!advance(12)) {
              return fail(L"A-vector");
            }
          }
          if ((item_type == 4 || item_type == 19) && !advance(4)) {
            return fail(L"A-extra-dword");
          }
        }
      }
    }

    if ((mask & 0x2000u) != 0) {
      stage = L"0x2000";
      LegacyLiveInventoryFeature25Shape feature25;
      if (!TryParseLegacyLiveInventoryFeature25ShapeAt(
              bytes,
              cursor,
              record_end,
              &feature25) ||
          feature25.missing_second_count ||
          feature25.block_end > record_end) {
        return fail(L"feature25");
      }
      cursor = feature25.block_end;
      parsed_bits += static_cast<size_t>(feature25.second_count) * 3u;
    }

    if ((mask & 0x4000u) != 0) {
      stage = L"0x4000";
      uint16_t entry_count = 0;
      if (!read_u16(&entry_count) ||
          entry_count > kMaxReasonableLiveInventoryCategoryEntries) {
        return fail(L"entry-count");
      }
      for (uint16_t entry = 0; entry < entry_count; ++entry) {
        uint8_t opcode = 0;
        if (!read_u8(&opcode)) {
          return fail(L"entry-opcode");
        }
        if (opcode == 'S') {
          if (!advance(2)) {
            return fail(L"S-entry");
          }
        } else if (opcode == 'U') {
          if (!advance(2)) {
            return fail(L"U-word");
          }
          parsed_bits += 1;
          if (!advance(1 + 2)) {
            return fail(L"U-tail");
          }
        }
      }
    }

    if (ok && cursor == record_end) {
      if (bit_count != nullptr) {
        *bit_count = parsed_bits;
      }
      return true;
    }
    return fail(L"cursor-not-at-record-end");
  }

  if ((mask & ~(kLegacyLiveInventorySimpleCategoryMask |
                kLegacyLiveInventoryRichCategoryMask |
                kLegacyLiveInventoryLegacyIconListMask)) == 0 &&
      (mask & (kLegacyLiveInventorySimpleCategoryMask |
               kLegacyLiveInventoryRichCategoryMask)) != 0) {
    size_t cursor = record_offset + 7;
    size_t category_fragment_bits = 0;

    if ((mask & kLegacyLiveInventorySimpleCategoryMask) != 0) {
      size_t simple_end = 0;
      if (!TryAdvanceLegacyLiveInventorySimpleCategoryBlock(
              bytes,
              cursor,
              record_end,
              kLegacyLiveInventoryCategoryCount,
              &simple_end,
              nullptr,
              nullptr)) {
        return false;
      }
      cursor = simple_end;
    }

    if ((mask & kLegacyLiveInventoryRichCategoryMask) != 0) {
      size_t rich_end = 0;
      uint32_t first_entries = 0;
      uint32_t second_entries = 0;
      if (!TryAdvanceLegacyLiveInventoryCategoryBlock(
              bytes,
              cursor,
              record_end,
              kLegacyLiveInventoryCategoryCount,
              &rich_end,
              &first_entries,
              &second_entries)) {
        return false;
      }
      cursor = rich_end;
      // The rich category second-list entries carry two BOOLs in both 1.69
      // and EE. First-list entries are read-buffer-only.
      category_fragment_bits += static_cast<size_t>(second_entries) * 2;
    }

    if ((mask & kLegacyLiveInventoryLegacyIconListMask) != 0) {
      size_t legacy_icon_end = 0;
      uint32_t legacy_icon_bits = 0;
      if (!TryAdvanceLegacyLiveInventoryLegacyIconListBlock(
              bytes,
              cursor,
              record_end,
              &legacy_icon_end,
              nullptr,
              nullptr,
              &legacy_icon_bits)) {
        return false;
      }
      cursor = legacy_icon_end;
      category_fragment_bits += legacy_icon_bits;
    }

    if (cursor != record_end) {
      return false;
    }
    if (bit_count != nullptr) {
      *bit_count = category_fragment_bits;
    }
    return true;
  }

  // The Diamond 0x0400 inventory/equipment block reads:
  //   BYTE clear_count, clear_count BYTEs,
  //   BYTE set_count, then set_count pairs of BYTE + fragment BOOL.
  // EE consumes the same BOOLs, so later object records must advance past
  // them before their door/placeable/trigger bit rewrites are applied.
  if ((mask & 0x0400u) == 0 || (mask & ~0x1400u) != 0) {
    return false;
  }

  size_t set_count = 0;
  if (!try_parse_inventory_0400(record_offset + 7, &set_count)) {
    return false;
  }

  if (bit_count != nullptr) {
    *bit_count = set_count;
  }
  return true;
}

bool TryFormatLegacyLiveObjectPacketSummary(
    const unsigned char* packet,
    size_t packet_size,
    std::wstring* summary,
    bool* transition_related) {
  if (summary != nullptr) {
    summary->clear();
  }
  if (transition_related != nullptr) {
    *transition_related = false;
  }
  if (packet == nullptr || packet_size <= 7 || !IsHighLevelGameplayEnvelope(packet[0]) ||
      packet[1] != 5 || packet[2] != 1 ||
      packet_size > kMaxReasonableReassembledGameplayPayload) {
    return false;
  }

  const uint32_t wire_declared = ReadU32Le(packet + 3);
  size_t live_end = packet_size;
  if (wire_declared != 0) {
    if (wire_declared < 7 || wire_declared > packet_size ||
        wire_declared > kMaxReasonableReassembledGameplayPayload) {
      return false;
    }
    live_end = wire_declared;
  }

  std::vector<unsigned char> bytes(packet + 7, packet + live_end);
  if (bytes.size() < 6) {
    return false;
  }

  uint32_t boundary_count = 0;
  uint32_t door_count = 0;
  uint32_t trigger_count = 0;
  uint32_t placeable_count = 0;
  uint32_t creature_count = 0;
  uint32_t item_count = 0;
  uint32_t named_count = 0;
  bool local_transition_related = false;
  std::wstring entries;
  uint32_t logged_entry_count = 0;
  constexpr uint32_t kMaxEntries = 32;

  for (size_t offset = 0; offset + 1 < bytes.size();) {
    if (!LooksLikeLegacyLiveObjectSubMessageBoundaryBytes(bytes, offset)) {
      ++offset;
      continue;
    }

    size_t record_end = FindNextLegacyLiveObjectSubMessageBoundaryAfter(bytes, offset);
    if (record_end > bytes.size()) {
      record_end = bytes.size();
    }
    ++boundary_count;
    const unsigned char opcode = bytes[offset];
    const unsigned char object_type = bytes[offset + 1];
    if (opcode == 'I') {
      ++item_count;
      if (logged_entry_count < kMaxEntries && offset + 7 <= bytes.size()) {
        uint32_t object_id = 0;
        uint16_t mask = 0;
        TryReadU32LeFromBytes(bytes, offset + 1, &object_id);
        TryReadU16LeFromBytes(bytes, offset + 5, &mask);
        size_t fragment_bits = 0;
        const bool fragment_bits_known =
            TryGetLegacyLiveInventoryFragmentBitCount(bytes, offset, record_end, &fragment_bits);
        wchar_t entry[768]{};
        swprintf_s(
            entry,
            L"%s+%zu I id=0x%08X mask=0x%04X fragment-bits=%s%zu",
            entries.empty() ? L"" : L"; ",
            offset,
            object_id,
            static_cast<unsigned int>(mask),
            fragment_bits_known ? L"" : L"?",
            fragment_bits);
        entries += entry;
        entries += FormatLegacyLiveRecordDiagnosticSuffix(bytes, offset, record_end);
        ++logged_entry_count;
      }
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }
    if (offset + 6 > bytes.size()) {
      ++offset;
      continue;
    }

    uint32_t object_id = 0;
    TryReadU32LeFromBytes(bytes, offset + 2, &object_id);
    uint32_t first_dword = 0;
    const bool first_known =
        offset + 10 <= bytes.size() && TryReadU32LeFromBytes(bytes, offset + 6, &first_dword);

    if (object_type == 10) {
      ++door_count;
      local_transition_related = true;
    } else if (object_type == 7) {
      ++trigger_count;
      local_transition_related = true;
    } else if (object_type == 9) {
      ++placeable_count;
    } else if (object_type == 5) {
      ++creature_count;
    } else if (object_type == 6) {
      ++item_count;
    }

    std::string inline_name;
    uint32_t inline_name_length = 0;
    size_t inline_name_end = 0;
    bool inline_name_known = false;
    bool short_locstring_known = false;
    uint32_t strref = 0;
    size_t name_offset = 0;
    if (object_type == 10 && first_known) {
      name_offset = first_dword == 0 ? 12 : 8;
    } else if (object_type == 9 || object_type == 5) {
      name_offset = 4;
    }

    const size_t object_start = offset + 2;
    const size_t name_start = name_offset != 0 ? object_start + name_offset : bytes.size();
    if (name_start < bytes.size()) {
      inline_name_known =
          LooksLikeInlineCExoStringAt(bytes, name_start, &inline_name_length, &inline_name_end, &inline_name);
      if (!inline_name_known &&
          (object_type == 9 || object_type == 10) &&
          LooksLikeLegacyLiveShortAddLocStringRecordBytes(bytes, object_type, name_start, nullptr)) {
        short_locstring_known = TryReadU32LeFromBytes(bytes, name_start, &strref);
      }
    }

    const bool name_transition_related =
        inline_name_known && LegacyLiveObjectNameLooksTransitionRelated(inline_name);
    if (inline_name_known) {
      ++named_count;
      if (name_transition_related) {
        local_transition_related = true;
      }
    } else if (short_locstring_known && (object_type == 9 || object_type == 10)) {
      local_transition_related = true;
    }

    const bool raw_interesting =
        object_type == 5 ||
        object_type == 7 ||
        object_type == 10 ||
        name_transition_related ||
        (short_locstring_known && object_type == 10);
    const bool entry_interesting =
        raw_interesting ||
        inline_name_known ||
        short_locstring_known ||
        object_type == 5 ||
        object_type == 9;
    if (entry_interesting && logged_entry_count < kMaxEntries) {
      ++logged_entry_count;
      wchar_t entry[1024]{};
      const wchar_t printable_opcode = opcode >= 0x20 && opcode <= 0x7E ? static_cast<wchar_t>(opcode) : L'.';
      if (inline_name_known) {
        swprintf_s(
            entry,
            L"%s+%zu %c type=%u/%s id=0x%08X first=0x%08X name='%s'",
            entries.empty() ? L"" : L"; ",
            offset,
            printable_opcode,
            static_cast<unsigned int>(object_type),
            LegacyLiveObjectTypeName(object_type),
            object_id,
            first_dword,
            AsciiPreviewToWide(inline_name, 80).c_str());
      } else if (short_locstring_known) {
        swprintf_s(
            entry,
            L"%s+%zu %c type=%u/%s id=0x%08X first=0x%08X strref=0x%08X/%u",
            entries.empty() ? L"" : L"; ",
            offset,
            printable_opcode,
            static_cast<unsigned int>(object_type),
            LegacyLiveObjectTypeName(object_type),
            object_id,
            first_dword,
            strref,
            strref);
      } else {
        swprintf_s(
            entry,
            L"%s+%zu %c type=%u/%s id=0x%08X first=0x%08X",
            entries.empty() ? L"" : L"; ",
            offset,
            printable_opcode,
            static_cast<unsigned int>(object_type),
            LegacyLiveObjectTypeName(object_type),
            object_id,
            first_dword);
      }
      entries += entry;
      if (object_type == 5 && first_known) {
        entries += FormatLegacyCreatureUpdateMaskHints(first_dword);
      }
      if (raw_interesting) {
        entries += FormatLegacyLiveRecordDiagnosticSuffix(bytes, offset, record_end);
      }
    }

    offset = record_end > offset ? record_end : offset + 1;
  }

  if (boundary_count == 0) {
    return false;
  }

  if (summary != nullptr) {
    wchar_t header[320]{};
    swprintf_s(
        header,
        L"boundaries=%u doors=%u triggers=%u placeables=%u creatures=%u items=%u named=%u transition-related=%d",
        boundary_count,
        door_count,
        trigger_count,
        placeable_count,
        creature_count,
        item_count,
        named_count,
        local_transition_related ? 1 : 0);
    *summary = header;
    if (!entries.empty()) {
      *summary += L" entries=[";
      *summary += entries;
      *summary += L"]";
    }
  }
  if (transition_related != nullptr) {
    *transition_related = local_transition_related;
  }
  return true;
}

uint32_t TranslateLegacyLiveObjectUpdateMask(
    unsigned char object_type,
    uint32_t raw_mask,
    const wchar_t** reason) {
  if (reason != nullptr) {
    *reason = L"";
  }

  if (object_type == 9) {
    constexpr uint32_t kLegacyPlaceableUpdateBits =
        kLegacyLiveObjectUpdatePositionMask |  // generic position
        kLegacyLiveObjectUpdateStateMask |  // placeable state/action flags
        kLegacyLiveObjectUpdateNameMask;    // placeable name payload
    if (reason != nullptr) {
      *reason = L"placeable-position-state-name";
    }
    return raw_mask & kLegacyPlaceableUpdateBits;
  }

  if (object_type == 10) {
    constexpr uint32_t kLegacyDoorUpdateBits =
        kLegacyLiveObjectUpdatePositionMask |  // generic position
        kLegacyLiveObjectUpdateStateMask |  // door state/action flags
        kLegacyLiveObjectUpdateNameMask;    // door name payload
    if (reason != nullptr) {
      *reason = L"door-position-state-name";
    }
    return raw_mask & kLegacyDoorUpdateBits;
  }

  if (object_type == 7) {
    constexpr uint32_t kLegacyTriggerUpdateBits =
        kLegacyLiveObjectUpdatePositionMask;
    if (reason != nullptr) {
      *reason = L"trigger-position-only";
    }
    return raw_mask & kLegacyTriggerUpdateBits;
  }

  return raw_mask;
}

bool LooksLikeLegacyLiveScalarTail6(
    const std::vector<unsigned char>& bytes,
    size_t offset) {
  float scale = 0.0f;
  uint16_t state = 0;
  return TryReadFloatLeFromBytes(bytes, offset, &scale) &&
      TryReadU16LeFromBytes(bytes, offset + 4, &state) &&
      IsPlausibleLegacyObjectScale(scale);
}

bool LooksLikeLegacyLiveNamedUpdateTail9(
    const std::vector<unsigned char>& bytes,
    size_t offset) {
  uint16_t facing = 0;
  float scale = 0.0f;
  uint16_t state = 0;
  return TryReadU16LeFromBytes(bytes, offset, &facing) &&
      offset <= bytes.size() &&
      bytes.size() - offset >= 9 &&
      bytes[offset + 2] <= 10 &&
      TryReadFloatLeFromBytes(bytes, offset + 3, &scale) &&
      TryReadU16LeFromBytes(bytes, offset + 7, &state) &&
      IsPlausibleLegacyObjectScale(scale);
}

bool IsLegacyDoorModelTokenByte(unsigned char value) {
  return (value >= '0' && value <= '9') ||
      (value >= 'A' && value <= 'Z') ||
      (value >= 'a' && value <= 'z') ||
      value == '_' ||
      value == '-';
}

bool FindInlineLiveObjectNameEndingNear(
    const std::vector<unsigned char>& bytes,
    size_t record_start,
    size_t record_end,
    size_t* name_offset,
    size_t* name_end) {
  if (name_offset != nullptr) {
    *name_offset = SIZE_MAX;
  }
  if (name_end != nullptr) {
    *name_end = SIZE_MAX;
  }
  if (record_start > bytes.size() || record_end > bytes.size() ||
      record_end <= record_start || record_end - record_start < 14) {
    return false;
  }

  const size_t search_start = record_start + 10;
  for (size_t offset = search_start; offset + 4 <= record_end; ++offset) {
    uint32_t length = 0;
    size_t end = 0;
    if (!LooksLikeInlineCExoStringAt(bytes, offset, &length, &end, nullptr) ||
        end > record_end) {
      continue;
    }
    const size_t post_bytes = record_end - end;
    if (post_bytes > 4) {
      continue;
    }
    if (name_offset != nullptr) {
      *name_offset = offset;
    }
    if (name_end != nullptr) {
      *name_end = end;
    }
    return true;
  }
  return false;
}

void AppendLiveObjectRewriteDetail(
    LiveObjectUpdateRewriteResult* result,
    size_t record_offset,
    unsigned char object_type,
    uint32_t object_id,
    uint32_t raw_mask,
    uint32_t translated_mask,
    uint32_t removed_bytes,
    uint32_t inserted_bits,
    uint32_t flattened_names,
    const wchar_t* reason) {
  if (result == nullptr) {
    return;
  }
  if (result->details.size() > 1800) {
    return;
  }

  wchar_t text[384]{};
  swprintf_s(
      text,
      L"%s+%zu type=%u/%s id=0x%08X mask=0x%08X->0x%08X removed=%u bits=%u names=%u reason=%s",
      result->details.empty() ? L"" : L"; ",
      record_offset,
      static_cast<unsigned int>(object_type),
      LegacyLiveObjectTypeName(object_type),
      object_id,
      raw_mask,
      translated_mask,
      removed_bytes,
      inserted_bits,
      flattened_names,
      reason != nullptr ? reason : L"");
  result->details += text;
}

std::wstring FormatCnwBitSlice(
    const std::vector<unsigned char>& bits,
    size_t start,
    size_t count);

void AppendLiveUpdateRecordRewriteDiagnostic(
    LiveObjectUpdateRewriteResult* result,
    const std::vector<unsigned char>& bytes,
    size_t record_offset,
    size_t record_end,
    size_t old_record_length,
    unsigned char object_type,
    uint32_t object_id,
    uint32_t raw_mask,
    uint32_t translated_mask,
    size_t bit_cursor_before,
    size_t bit_cursor_after,
    uint32_t inserted_bits,
    uint32_t removed_bytes,
    uint32_t flattened_names,
    const std::vector<unsigned char>& before_bits,
    const std::vector<unsigned char>& after_bits,
    const wchar_t* reason) {
  if (result == nullptr || result->diagnostics.size() > 5200) {
    return;
  }

  const size_t safe_record_end = std::min(record_end, bytes.size());
  const size_t raw_length = safe_record_end > record_offset
      ? safe_record_end - record_offset
      : 0;
  const bool has_position =
      (translated_mask & kLegacyLiveObjectUpdatePositionMask) != 0;
  const bool has_state =
      (translated_mask & kLegacyLiveObjectUpdateStateMask) != 0;
  const bool has_name =
      (translated_mask & kLegacyLiveObjectUpdateNameMask) != 0;
  const size_t expected_name_offset =
      record_offset + 10 +
      (has_position ? kLegacyLiveObjectUpdatePositionReadBytes : 0);

  std::string name_preview;
  uint32_t name_length = 0;
  bool name_ready = false;
  if (has_name && expected_name_offset < safe_record_end) {
    size_t name_end = expected_name_offset;
    name_ready = LooksLikeInlineCExoStringAt(
        bytes,
        expected_name_offset,
        &name_length,
        &name_end,
        &name_preview) &&
        name_end <= safe_record_end;
  }

  uint16_t fixed_x = 0;
  uint16_t fixed_y = 0;
  uint16_t fixed_z = 0;
  if (has_position && record_offset + 16 <= bytes.size()) {
    (void)TryReadU16LeFromBytes(bytes, record_offset + 10, &fixed_x);
    (void)TryReadU16LeFromBytes(bytes, record_offset + 12, &fixed_y);
    (void)TryReadU16LeFromBytes(bytes, record_offset + 14, &fixed_z);
  }

  const size_t bit_slice_start = bit_cursor_before >= 6 ? bit_cursor_before - 6 : 0;
  const size_t bit_slice_count = 36;
  const std::wstring before_slice =
      FormatCnwBitSlice(before_bits, bit_slice_start, bit_slice_count);
  const std::wstring after_slice =
      FormatCnwBitSlice(after_bits, bit_slice_start, bit_slice_count);

  wchar_t text[1700]{};
  swprintf_s(
      text,
      L"%s+%zu U %s id=0x%08X mask=0x%08X->0x%08X len=%zu->%zu bits[cursor=%zu->%zu inserted=%u before=%s after=%s] flags[pos=%d state=%d name=%d] fixed=[0x%04X,0x%04X,0x%04X] name_off=%zu name_ready=%d name_len=%u name='%s' removed=%u flattened=%u reason=%s raw=[%s]",
      result->diagnostics.empty() ? L"" : L"; ",
      record_offset,
      LegacyLiveObjectTypeName(object_type),
      object_id,
      raw_mask,
      translated_mask,
      old_record_length,
      raw_length,
      bit_cursor_before,
      bit_cursor_after,
      inserted_bits,
      before_slice.c_str(),
      after_slice.c_str(),
      has_position ? 1 : 0,
      has_state ? 1 : 0,
      has_name ? 1 : 0,
      static_cast<unsigned int>(fixed_x),
      static_cast<unsigned int>(fixed_y),
      static_cast<unsigned int>(fixed_z),
      expected_name_offset,
      name_ready ? 1 : 0,
      name_length,
      AsciiPreviewToWide(name_preview, 96).c_str(),
      removed_bytes,
      flattened_names,
      reason != nullptr ? reason : L"",
      raw_length != 0
          ? FormatLimitedBytes(bytes.data() + record_offset, raw_length, 120).c_str()
          : L"");
  result->diagnostics += text;
}

