bool FindLegacyLiveUpdateShortNameEndingNear(
    const std::vector<unsigned char>& bytes,
    size_t record_start,
    size_t record_end,
    size_t* name_offset,
    size_t* name_end) {
  if (name_offset != nullptr) {
    *name_offset = SIZE_MAX;
  }
  if (name_end != nullptr) {
    *name_end = SIZE_MAX;
  }
  if (record_start > bytes.size() || record_end > bytes.size() ||
      record_end <= record_start || record_end - record_start < 23) {
    return false;
  }

  if (bytes.size() - record_start >= 10 &&
      IsDoorPlaceableUpdateRecord(bytes[record_start], bytes[record_start + 1])) {
    uint32_t raw_mask = 0;
    if (!TryReadU32LeFromBytes(bytes, record_start + 6, &raw_mask)) {
      return false;
    }
    const size_t cursor = DoorPlaceableUpdateNameCursor(record_start, raw_mask);
    if (cursor > record_end || record_end - cursor < 13 ||
        LooksLikeInlineCExoStringAt(bytes, cursor, nullptr, nullptr, nullptr)) {
      return false;
    }
    if (LooksLikeLegacyLiveObjectSubMessageBoundaryBytes(bytes, cursor + 4)) {
      return false;
    }

    const size_t anchored_name_offset = cursor + 9;
    if (!LooksLikeLegacyLiveNamedUpdateTail9(bytes, cursor) ||
        LooksLikeInlineCExoStringAt(
            bytes,
            anchored_name_offset,
            nullptr,
            nullptr,
            nullptr)) {
      return false;
    }
    const size_t post_bytes = record_end - (anchored_name_offset + 4);
    if (post_bytes > 4) {
      return false;
    }
    if (name_offset != nullptr) {
      *name_offset = anchored_name_offset;
    }
    if (name_end != nullptr) {
      *name_end = anchored_name_offset + 4;
    }
    return true;
  }

  const size_t search_start = record_start + 10;
  for (size_t offset = search_start; offset + 4 <= record_end; ++offset) {
    if (LooksLikeInlineCExoStringAt(bytes, offset, nullptr, nullptr, nullptr) ||
        offset < record_start + 19 ||
        !LooksLikeLegacyLiveNamedUpdateTail9(bytes, offset - 9)) {
      continue;
    }
    const size_t post_bytes = record_end - (offset + 4);
    if (post_bytes > 4) {
      continue;
    }
    if (name_offset != nullptr) {
      *name_offset = offset;
    }
    if (name_end != nullptr) {
      *name_end = offset + 4;
    }
    return true;
  }
  return false;
}

