bool RewriteLegacyCreaturePFeatureGateRecord(
    const BridgeRuntime& runtime,
    const std::vector<unsigned char>& bytes,
    size_t record_offset,
    size_t declared_live_end,
    std::vector<unsigned char>* fragment_bits,
    size_t* bit_cursor,
    std::vector<unsigned char>* rewritten_record,
    size_t* old_record_end,
    uint32_t* promoted_bytes,
    uint32_t* inserted_bytes,
    uint32_t* removed_bytes,
    uint32_t* equipment_items_seen,
    uint32_t* equipment_item_appearances_seen,
    uint32_t* active_property_bits_inserted,
    uint32_t* name_mode_bits_rewritten,
    std::wstring* detail) {
  if (rewritten_record != nullptr) {
    rewritten_record->clear();
  }
  if (old_record_end != nullptr) {
    *old_record_end = record_offset;
  }
  if (promoted_bytes != nullptr) {
    *promoted_bytes = 0;
  }
  if (inserted_bytes != nullptr) {
    *inserted_bytes = 0;
  }
  if (removed_bytes != nullptr) {
    *removed_bytes = 0;
  }
  if (equipment_items_seen != nullptr) {
    *equipment_items_seen = 0;
  }
  if (equipment_item_appearances_seen != nullptr) {
    *equipment_item_appearances_seen = 0;
  }
  if (active_property_bits_inserted != nullptr) {
    *active_property_bits_inserted = 0;
  }
  if (name_mode_bits_rewritten != nullptr) {
    *name_mode_bits_rewritten = 0;
  }
  if (detail != nullptr) {
    detail->clear();
  }
  if (rewritten_record == nullptr ||
      record_offset > bytes.size() ||
      bytes.size() - record_offset < 10 ||
      bytes[record_offset] != 'P' ||
      bytes[record_offset + 1] != 5 ||
      !LooksLikeLegacyLiveObjectIdAt(bytes, record_offset + 2)) {
    return false;
  }

  uint32_t object_id = 0;
  uint16_t flags = 0;
  if (!TryReadU32LeFromBytes(bytes, record_offset + 2, &object_id) ||
      !TryReadU16LeFromBytes(bytes, record_offset + 6, &flags)) {
    return false;
  }

  size_t cursor = record_offset + 8;
  uint32_t local_inserted = 0;
  uint32_t local_removed = 0;
  uint32_t local_equipment_items = 0;
  uint32_t local_equipment_appearances = 0;
  uint32_t local_active_property_bits_inserted = 0;
  bool equipment_count_synthesized_zero = false;
  bool equipment_tail_copied_raw = false;
  bool promoted_equipment_copied = false;
  uint32_t promoted_active_properties_synthesized = 0;
  uint32_t promoted_active_properties_compact_bytes_dropped = 0;
  uint32_t active_properties_synthesized = 0;
  uint32_t active_properties_synthetic_bytes = 0;
  uint32_t active_properties_synthetic_skipped_bytes = 0;
  bool skipped_feature0e_field = false;
  uint32_t local_promoted = 0;
  uint32_t local_promoted_bits_erased = 0;
  uint32_t local_equipment_appearance_bytes_inserted = 0;
  uint32_t local_name_mode_bits_rewritten = 0;
  size_t equipment_failure_offset = SIZE_MAX;
  unsigned char equipment_failure_opcode = 0;
  bool equipment_failure_has_opcode = false;
  std::wstring partial_reason;
  std::string name_preview;
  std::string second_name_preview;
  uint32_t name_length = 0;
  uint32_t second_name_length = 0;
  bool used_double_inline_name = false;
  bool used_single_inline_name = false;
  bool used_missing_second_name_length = false;
  bool repaired_outer_name_mode_to_double = false;
  bool repaired_outer_name_mode_to_single = false;
  std::vector<unsigned char> working_fragment_bits;
  std::vector<unsigned char>* record_fragment_bits = nullptr;
  size_t working_bit_cursor = 0;
  bool record_bit_cursor_reliable = false;
  if (fragment_bits != nullptr && bit_cursor != nullptr) {
    working_fragment_bits = *fragment_bits;
    record_fragment_bits = &working_fragment_bits;
    working_bit_cursor = *bit_cursor;
    record_bit_cursor_reliable = true;
  }
  const size_t initial_bit_cursor = working_bit_cursor;
  const size_t initial_fragment_bit_count =
      record_fragment_bits != nullptr ? record_fragment_bits->size() : 0;
  const bool should_log_detailed_creature_p =
      runtime.options.packet_dump || object_id == 0xFFFFFFFDu;
  std::wstring equipment_diagnostics;

  const auto append_equipment_diagnostic = [&](
      unsigned int index,
      size_t entry_offset,
      unsigned char opcode,
      uint32_t equipment_object_id,
      uint32_t equipment_field,
      uint32_t base_item_id,
      int model_type,
      size_t legacy_size,
      size_t active_start,
      size_t active_end,
      uint32_t active_bits,
      std::string_view active_name_preview,
      std::wstring_view note) {
    if (!should_log_detailed_creature_p || equipment_diagnostics.size() > 2400) {
      return;
    }
    if (!equipment_diagnostics.empty()) {
      equipment_diagnostics += L"; ";
    }
    const wchar_t opcode_text =
        opcode >= 0x20 && opcode <= 0x7Eu ? static_cast<wchar_t>(opcode) : L'.';
    wchar_t text[384]{};
    const size_t rel =
        entry_offset >= record_offset ? entry_offset - record_offset : 0;
    const size_t active_rel =
        active_start >= record_offset ? active_start - record_offset : 0;
    const size_t active_end_rel =
        active_end >= record_offset ? active_end - record_offset : 0;
    swprintf_s(
        text,
        L"#%u +%zu op='%c'/0x%02X oid=0x%08X field=0x%08X base=%u model=%d legacy=%zu active=%zu..%zu bits=%u",
        index,
        rel,
        opcode_text,
        static_cast<unsigned int>(opcode),
        equipment_object_id,
        equipment_field,
        base_item_id,
        model_type,
        legacy_size,
        active_rel,
        active_end_rel,
        active_bits);
    equipment_diagnostics += text;
    if (!active_name_preview.empty()) {
      equipment_diagnostics += L" active_name='";
      equipment_diagnostics += AsciiPreviewToWide(active_name_preview, 48);
      equipment_diagnostics += L"'";
    }
    if (!note.empty()) {
      equipment_diagnostics += L" ";
      equipment_diagnostics += note;
    }
  };

  // We present HG as a Diamond/1.69 server. Stock EE's creature reader then
  // takes the ServerSatisfiesBuild-false branches for these optional fields.
  constexpr bool kEeCreatureFeature23Fields = false;
  constexpr bool kEeCreatureFeature0eFields = false;

  rewritten_record->reserve(160);
  rewritten_record->insert(
      rewritten_record->end(),
      bytes.begin() + static_cast<std::ptrdiff_t>(record_offset),
      bytes.begin() + static_cast<std::ptrdiff_t>(cursor));

  const auto read_promoted_byte_from_fragment = [&](unsigned char* value) -> bool {
    if (value != nullptr) {
      *value = 0;
    }
    if (!record_bit_cursor_reliable ||
        record_fragment_bits == nullptr ||
        value == nullptr) {
      return false;
    }
    uint64_t raw = 0;
    if (!ReadLegacyLiveFragmentUnsignedAt(
            *record_fragment_bits,
            working_bit_cursor,
            8,
            &raw) ||
        !EraseCnwMsbBits(record_fragment_bits, working_bit_cursor, 8)) {
      return false;
    }
    *value = static_cast<unsigned char>(raw & 0xFFu);
    ++local_promoted;
    local_promoted_bits_erased += 8;
    return true;
  };

  const auto read_legacy_byte = [&](unsigned char* value) -> bool {
    if (value != nullptr) {
      *value = 0;
    }
    if (value == nullptr) {
      return false;
    }
    if (cursor < declared_live_end) {
      if (cursor >= bytes.size()) {
        return false;
      }
      *value = bytes[cursor++];
      return true;
    }

    if (!read_promoted_byte_from_fragment(value)) {
      return false;
    }
    ++cursor;
    return true;
  };

  const auto peek_legacy_bytes = [&](
      size_t source_cursor,
      size_t count,
      std::vector<unsigned char>* values) -> bool {
    if (values != nullptr) {
      values->clear();
    }
    if (values == nullptr ||
        source_cursor < cursor ||
        count > kMaxReasonableReassembledGameplayPayload) {
      return false;
    }

    size_t temp_cursor = source_cursor;
    size_t temp_bit_cursor = working_bit_cursor;
    if (source_cursor > cursor) {
      size_t promoted_bytes_between = 0;
      if (cursor < declared_live_end) {
        if (source_cursor > declared_live_end) {
          promoted_bytes_between = source_cursor - declared_live_end;
        }
      } else {
        promoted_bytes_between = source_cursor - cursor;
      }
      if (promoted_bytes_between >
          (kMaxReasonableReassembledGameplayPayload * 8ull) / 8ull) {
        return false;
      }
      temp_bit_cursor += promoted_bytes_between * 8;
    }

    values->reserve(count);
    for (size_t index = 0; index < count; ++index) {
      if (temp_cursor < declared_live_end) {
        if (temp_cursor >= bytes.size()) {
          return false;
        }
        values->push_back(bytes[temp_cursor++]);
        continue;
      }

      if (!record_bit_cursor_reliable || record_fragment_bits == nullptr) {
        return false;
      }
      uint64_t raw = 0;
      if (!ReadLegacyLiveFragmentUnsignedAt(
              *record_fragment_bits,
              temp_bit_cursor,
              8,
              &raw)) {
        return false;
      }
      values->push_back(static_cast<unsigned char>(raw & 0xFFu));
      temp_bit_cursor += 8;
      ++temp_cursor;
    }
    return true;
  };

  const auto peek_legacy_byte = [&](size_t source_cursor, unsigned char* value) -> bool {
    std::vector<unsigned char> values;
    if (!peek_legacy_bytes(source_cursor, 1, &values) || values.empty()) {
      return false;
    }
    if (value != nullptr) {
      *value = values[0];
    }
    return true;
  };

  const auto read_legacy_bytes = [&](
      size_t count,
      std::vector<unsigned char>* values) -> bool {
    if (values != nullptr) {
      values->clear();
      values->reserve(count);
    }
    for (size_t index = 0; index < count; ++index) {
      unsigned char value = 0;
      if (!read_legacy_byte(&value)) {
        return false;
      }
      if (values != nullptr) {
        values->push_back(value);
      }
    }
    return true;
  };

  const auto copy_bytes = [&](size_t count) -> bool {
    std::vector<unsigned char> values;
    if (!read_legacy_bytes(count, &values)) {
      return false;
    }
    rewritten_record->insert(
        rewritten_record->end(),
        values.begin(),
        values.end());
    return true;
  };

  const auto copy_legacy_byte_as_ee_word = [&]() -> bool {
    unsigned char value = 0;
    if (!read_legacy_byte(&value)) {
      return false;
    }
    rewritten_record->push_back(value);
    rewritten_record->push_back(0);
    ++local_inserted;
    return true;
  };

  const auto fail = [&](const wchar_t* reason) -> bool {
    if (runtime.options.packet_dump) {
      const size_t available = record_offset < bytes.size() ? bytes.size() - record_offset : 0;
      const size_t cursor_relative = cursor >= record_offset ? cursor - record_offset : 0;
      const unsigned int cursor_byte =
          cursor < bytes.size() ? static_cast<unsigned int>(bytes[cursor]) : 0x100u;
      wchar_t cursor_byte_text[16]{};
      if (cursor_byte <= 0xFFu) {
        swprintf_s(cursor_byte_text, L"0x%02X", cursor_byte);
      } else {
        wcscpy_s(cursor_byte_text, L"<eof>");
      }
      LogFormat(
          L"server->client live creature-P feature parse skipped: rec=%zu id=0x%08X flags=0x%04X cursor=%zu rel=%zu byte=%s declared_live_end=%zu reason=%s prefix=[%s]",
          record_offset,
          object_id,
          flags,
          cursor,
          cursor_relative,
          cursor_byte_text,
          declared_live_end,
          reason != nullptr ? reason : L"<unknown>",
          available != 0
              ? FormatLimitedBytes(
                    bytes.data() + record_offset,
                    available,
                    std::min<size_t>(available, 256)).c_str()
              : L"<none>");
    }
    return false;
  };

  const auto looks_like_equipment_list_at = [&](size_t list_offset) -> bool {
    if ((flags & 0x0200u) == 0) {
      return true;
    }
    std::vector<unsigned char> probe;
    if (!peek_legacy_bytes(list_offset, 1, &probe) || probe.empty()) {
      return false;
    }
    const unsigned char equipment_count = probe[0];
    if (equipment_count > 32) {
      return false;
    }
    size_t equipment_cursor = list_offset + 1;
    const unsigned char entries_to_probe =
        std::min<unsigned char>(equipment_count, 4);
    for (unsigned char index = 0; index < entries_to_probe; ++index) {
      if (!peek_legacy_bytes(equipment_cursor, 9, &probe) || probe.size() != 9) {
        return false;
      }
      const unsigned char equipment_opcode = probe[0];
      if (equipment_opcode != 'A' &&
          equipment_opcode != 'D' &&
          equipment_opcode != 'U') {
        return false;
      }
      const uint32_t equipment_object_id = ReadU32Le(probe.data() + 1);
      const uint32_t equipment_high_byte = equipment_object_id & 0xFF000000u;
      if (!LooksLikeLegacyLiveObjectIdValue(equipment_object_id) &&
          equipment_high_byte != 0x7F000000u) {
        return false;
      }
      const uint32_t equipment_field = ReadU32Le(probe.data() + 5);
      if (equipment_field >= 0x00010000u) {
        return false;
      }
      equipment_cursor += 9;
      if (equipment_opcode == 'U') {
        if (!peek_legacy_bytes(equipment_cursor, 1, &probe)) {
          return false;
        }
        ++equipment_cursor;
      } else if (equipment_opcode == 'A') {
        // For part-table boundary detection it is enough to prove the first
        // add-entry header reaches an apparent base item id. The real equipment
        // parser below validates and copies the full item appearance payload.
        if (!peek_legacy_bytes(equipment_cursor, 4, &probe)) {
          return false;
        }
        break;
      }
    }
    return true;
  };

  const auto append_u32_to_rewritten = [&](uint32_t value) -> bool {
    const size_t offset = rewritten_record->size();
    rewritten_record->resize(offset + 4);
    WriteU32Le(rewritten_record->data() + offset, value);
    return true;
  };

  const auto looks_like_creature_p_scalar_and_tail_at =
      [&](size_t scalar_offset) -> bool {
    size_t probe_cursor = scalar_offset;
    std::vector<unsigned char> probe;
    const auto probe_bytes = [&](size_t count) -> bool {
      if (count == 0) {
        return true;
      }
      if (count > SIZE_MAX - probe_cursor ||
          !peek_legacy_bytes(probe_cursor, count, &probe) ||
          probe.size() != count) {
        return false;
      }
      probe_cursor += count;
      return true;
    };

    if ((flags & 0x0001u) != 0 && !probe_bytes(2)) {
      return false;
    }
    if ((flags & 0x0002u) != 0 && !probe_bytes(1)) {
      return false;
    }
    if ((flags & 0x0004u) != 0 && !probe_bytes(1)) {
      return false;
    }
    if ((flags & 0x0080u) != 0 && !probe_bytes(1)) {
      return false;
    }
    if ((flags & 0x0800u) != 0 && !probe_bytes(4)) {
      return false;
    }
    if ((flags & 0x1000u) != 0 && !probe_bytes(4)) {
      return false;
    }
    if ((flags & 0x0008u) != 0 && !probe_bytes(1)) {
      return false;
    }
    if ((flags & 0x0010u) != 0 && !probe_bytes(1)) {
      return false;
    }
    if ((flags & 0x0020u) != 0 && !probe_bytes(1)) {
      return false;
    }
    if ((flags & 0x0040u) != 0 && !probe_bytes(1)) {
      return false;
    }

    const auto tail_after_parts_valid = [&](size_t part_end) -> bool {
      size_t tail_cursor = part_end;
      if ((flags & 0x2000u) != 0) {
        if (tail_cursor > SIZE_MAX - 6 ||
            !peek_legacy_bytes(tail_cursor, 6, &probe) ||
            probe.size() != 6) {
          return false;
        }
        tail_cursor += 6;
      }
      return looks_like_equipment_list_at(tail_cursor);
    };

    if ((flags & 0x0100u) == 0) {
      return tail_after_parts_valid(probe_cursor);
    }

    if (peek_legacy_bytes(probe_cursor, 24, &probe) &&
        probe.size() == 24 &&
        probe[4] == 0x13 &&
        tail_after_parts_valid(probe_cursor + 24)) {
      return true;
    }

    if (peek_legacy_bytes(probe_cursor, 28, &probe) &&
        probe.size() == 28 &&
        probe[0] == 0 &&
        probe[1] == 0 &&
        probe[2] == 0 &&
        probe[3] == 0 &&
        probe[8] == 0x13 &&
        tail_after_parts_valid(probe_cursor + 28)) {
      return true;
    }

    if (peek_legacy_bytes(probe_cursor, 20, &probe) &&
        probe.size() == 20 &&
        probe[0] == 0x13 &&
        tail_after_parts_valid(probe_cursor + 20)) {
      return true;
    }

    if (!peek_legacy_bytes(probe_cursor, 1, &probe) || probe.empty()) {
      return false;
    }
    const unsigned char part_count = probe[0];
    if (part_count > 19) {
      return false;
    }
    const size_t part_size =
        part_count < 10 ? 1u + static_cast<size_t>(part_count) * 2u : 20u;
    if (!peek_legacy_bytes(probe_cursor, part_size, &probe) ||
        probe.size() != part_size) {
      return false;
    }
    return tail_after_parts_valid(probe_cursor + part_size);
  };

  const auto creature_p_part_count_byte_after_scalars =
      [&](size_t scalar_offset, unsigned char* part_count_byte) -> bool {
    if (part_count_byte != nullptr) {
      *part_count_byte = 0;
    }
    size_t probe_cursor = scalar_offset;
    std::vector<unsigned char> probe;
    const auto probe_bytes = [&](size_t count) -> bool {
      if (count == 0) {
        return true;
      }
      if (count > SIZE_MAX - probe_cursor ||
          !peek_legacy_bytes(probe_cursor, count, &probe) ||
          probe.size() != count) {
        return false;
      }
      probe_cursor += count;
      return true;
    };

    if ((flags & 0x0001u) != 0 && !probe_bytes(2)) {
      return false;
    }
    if ((flags & 0x0002u) != 0 && !probe_bytes(1)) {
      return false;
    }
    if ((flags & 0x0004u) != 0 && !probe_bytes(1)) {
      return false;
    }
    if ((flags & 0x0080u) != 0 && !probe_bytes(1)) {
      return false;
    }
    if ((flags & 0x0800u) != 0 && !probe_bytes(4)) {
      return false;
    }
    if ((flags & 0x1000u) != 0 && !probe_bytes(4)) {
      return false;
    }
    if ((flags & 0x0008u) != 0 && !probe_bytes(1)) {
      return false;
    }
    if ((flags & 0x0010u) != 0 && !probe_bytes(1)) {
      return false;
    }
    if ((flags & 0x0020u) != 0 && !probe_bytes(1)) {
      return false;
    }
    if ((flags & 0x0040u) != 0 && !probe_bytes(1)) {
      return false;
    }
    return peek_legacy_byte(probe_cursor, part_count_byte);
  };

  const auto find_missing_second_inline_name_length = [&](
      size_t text_offset,
      uint32_t* length,
      size_t* text_end,
      std::string* preview) -> bool {
    if (length != nullptr) {
      *length = 0;
    }
    if (text_end != nullptr) {
      *text_end = text_offset;
    }
    if (preview != nullptr) {
      preview->clear();
    }

    const auto score_creature_p_scalar_tail_at = [&](
        size_t scalar_offset,
        uint32_t candidate_length,
        uint32_t* score) -> bool {
      if (score != nullptr) {
        *score = 0;
      }
      size_t probe_cursor = scalar_offset;
      std::vector<unsigned char> probe;
      const auto probe_bytes = [&](size_t count) -> bool {
        if (count == 0) {
          return true;
        }
        if (count > SIZE_MAX - probe_cursor ||
            !peek_legacy_bytes(probe_cursor, count, &probe) ||
            probe.size() != count) {
          return false;
        }
        probe_cursor += count;
        return true;
      };

      if ((flags & 0x0001u) != 0 && !probe_bytes(2)) {
        return false;
      }
      if ((flags & 0x0002u) != 0 && !probe_bytes(1)) {
        return false;
      }
      if ((flags & 0x0004u) != 0 && !probe_bytes(1)) {
        return false;
      }
      if ((flags & 0x0080u) != 0 && !probe_bytes(1)) {
        return false;
      }
      if ((flags & 0x0800u) != 0 && !probe_bytes(4)) {
        return false;
      }
      if ((flags & 0x1000u) != 0 && !probe_bytes(4)) {
        return false;
      }
      if ((flags & 0x0008u) != 0 && !probe_bytes(1)) {
        return false;
      }
      if ((flags & 0x0010u) != 0 && !probe_bytes(1)) {
        return false;
      }
      if ((flags & 0x0020u) != 0 && !probe_bytes(1)) {
        return false;
      }
      if ((flags & 0x0040u) != 0 && !probe_bytes(1)) {
        return false;
      }

      const auto finish_after_part_end =
          [&](size_t part_end, uint32_t part_score) -> bool {
        uint32_t local_score = candidate_length * 4u + part_score;
        size_t tail_cursor = part_end;
        if ((flags & 0x2000u) != 0) {
          if (tail_cursor > SIZE_MAX - 6 ||
              !peek_legacy_bytes(tail_cursor, 6, &probe) ||
              probe.size() != 6) {
            return false;
          }
          tail_cursor += 6;
          local_score += 80;
        }
        if ((flags & 0x0200u) != 0) {
          if (!peek_legacy_bytes(tail_cursor, 1, &probe) || probe.empty()) {
            return false;
          }
          const uint32_t equipment_count = probe[0];
          if (equipment_count > 64 || !looks_like_equipment_list_at(tail_cursor)) {
            return false;
          }
          local_score += equipment_count != 0
              ? 1000u + std::min<uint32_t>(equipment_count, 16u) * 20u
              : 1u;
        } else {
          local_score += 50;
        }
        if (score != nullptr) {
          *score = local_score;
        }
        return true;
      };

      if ((flags & 0x0100u) == 0) {
        return finish_after_part_end(probe_cursor, 10);
      }

      if (peek_legacy_bytes(probe_cursor, 24, &probe) &&
          probe.size() == 24 &&
          probe[4] == 0x13 &&
          finish_after_part_end(probe_cursor + 24, 5000)) {
        return true;
      }

      if (peek_legacy_bytes(probe_cursor, 28, &probe) &&
          probe.size() == 28 &&
          probe[0] == 0 &&
          probe[1] == 0 &&
          probe[2] == 0 &&
          probe[3] == 0 &&
          probe[8] == 0x13 &&
          finish_after_part_end(probe_cursor + 28, 4900)) {
        return true;
      }

      if (peek_legacy_bytes(probe_cursor, 20, &probe) &&
          probe.size() == 20 &&
          probe[0] == 0x13 &&
          finish_after_part_end(probe_cursor + 20, 4800)) {
        return true;
      }

      if (!peek_legacy_bytes(probe_cursor, 1, &probe) || probe.empty()) {
        return false;
      }
      const unsigned char part_count = probe[0];
      if (part_count > 19) {
        return false;
      }
      const size_t part_size =
          part_count < 10 ? 1u + static_cast<size_t>(part_count) * 2u : 20u;
      if (!peek_legacy_bytes(probe_cursor, part_size, &probe) ||
          probe.size() != part_size) {
        return false;
      }
      return finish_after_part_end(
          probe_cursor + part_size,
          part_count >= 10 ? 2000u : 200u + static_cast<uint32_t>(part_count));
    };

    constexpr uint32_t kMaxMissingSecondNameBytes = 64;
    bool found = false;
    uint32_t best_length = 0;
    uint32_t best_score = 0;
    size_t best_end = text_offset;
    std::string best_preview;
    std::vector<unsigned char> text_probe;
    for (uint32_t candidate_length = 1;
         candidate_length <= kMaxMissingSecondNameBytes;
         ++candidate_length) {
      if (!peek_legacy_bytes(text_offset, candidate_length, &text_probe) ||
          text_probe.size() != static_cast<size_t>(candidate_length)) {
        break;
      }

      bool printable = true;
      for (unsigned char value : text_probe) {
        if (value < 0x20 || value > 0x7E || value == 0x7F) {
          printable = false;
          break;
        }
      }
      if (!printable) {
        break;
      }

      const size_t candidate_end = text_offset + candidate_length;
      uint32_t candidate_score = 0;
      if (score_creature_p_scalar_tail_at(
              candidate_end,
              candidate_length,
              &candidate_score)) {
        if (!found ||
            candidate_score > best_score ||
            (candidate_score == best_score && candidate_length > best_length)) {
          found = true;
          best_length = candidate_length;
          best_score = candidate_score;
          best_end = candidate_end;
          best_preview.assign(text_probe.begin(), text_probe.end());
        }
      }
    }
    if (!found) {
      return false;
    }
    if (length != nullptr) {
      *length = best_length;
    }
    if (text_end != nullptr) {
      *text_end = best_end;
    }
    if (preview != nullptr) {
      *preview = best_preview;
    }
    return true;
  };

  if ((flags & 0x0400u) != 0) {
    size_t name_end = 0;
    if (!LooksLikeLegacyCreatureInlineCExoStringAt(
            bytes,
            cursor,
            &name_length,
            &name_end,
            &name_preview) ||
        name_end < cursor) {
      return fail(L"name-cstring");
    }
    if (!record_bit_cursor_reliable || record_fragment_bits == nullptr) {
      return fail(L"name-fragment-context");
    }

    size_t second_name_end = 0;
    const bool has_second_inline_name =
        LooksLikeLegacyCreatureInlineCExoStringAt(
            bytes,
            name_end,
            &second_name_length,
            &second_name_end,
            &second_name_preview) &&
        second_name_end > name_end;
    if (working_bit_cursor >= record_fragment_bits->size()) {
      return fail(L"name-outer-bool-short");
    }
    bool legacy_outer_locstring =
        (*record_fragment_bits)[working_bit_cursor] != 0;

    uint32_t missing_second_name_length = 0;
    size_t missing_second_name_end = 0;
    std::string missing_second_name_preview;
    const bool missing_second_inline_name_valid =
        !has_second_inline_name &&
        name_length == 0 &&
        find_missing_second_inline_name_length(
            name_end,
            &missing_second_name_length,
            &missing_second_name_end,
            &missing_second_name_preview);
    const bool single_tail_valid =
        looks_like_creature_p_scalar_and_tail_at(name_end);
    const bool explicit_double_tail_valid =
        has_second_inline_name &&
        looks_like_creature_p_scalar_and_tail_at(second_name_end);
    const bool double_tail_valid =
        explicit_double_tail_valid || missing_second_inline_name_valid;
    const size_t double_scalar_offset =
        has_second_inline_name ? second_name_end : missing_second_name_end;
    unsigned char single_part_count_byte = 0;
    unsigned char double_part_count_byte = 0;
    const bool have_single_part_count =
        creature_p_part_count_byte_after_scalars(
            name_end,
            &single_part_count_byte);
    const bool have_double_part_count =
        double_tail_valid &&
        creature_p_part_count_byte_after_scalars(
            double_scalar_offset,
            &double_part_count_byte);
    const bool double_has_direct_part_table =
        have_double_part_count && double_part_count_byte <= 19;
    const bool single_requires_legacy_part_prefix =
        have_single_part_count && single_part_count_byte > 19;

    if (!legacy_outer_locstring &&
        double_tail_valid &&
        double_has_direct_part_table &&
        (!single_tail_valid || single_requires_legacy_part_prefix)) {
      bool outer_changed = false;
      if (!SetCnwMsbBit(
              record_fragment_bits,
              working_bit_cursor,
              true,
              &outer_changed)) {
        return fail(L"name-outer-bool-repair-double");
      }
      legacy_outer_locstring = true;
      repaired_outer_name_mode_to_double = true;
      local_name_mode_bits_rewritten +=
          static_cast<uint32_t>(outer_changed ? 1 : 0);
    } else if (legacy_outer_locstring &&
               !double_tail_valid &&
               single_tail_valid) {
      bool outer_changed = false;
      if (!SetCnwMsbBit(
              record_fragment_bits,
              working_bit_cursor,
              false,
              &outer_changed)) {
        return fail(L"name-outer-bool-repair-single");
      }
      legacy_outer_locstring = false;
      repaired_outer_name_mode_to_single = true;
      local_name_mode_bits_rewritten +=
          static_cast<uint32_t>(outer_changed ? 1 : 0);
    }

    if (legacy_outer_locstring) {
      if (!has_second_inline_name) {
        if (name_length != 0 || !missing_second_inline_name_valid) {
          return fail(L"name-double-cstring-missing");
        }
        second_name_length = missing_second_name_length;
        second_name_end = missing_second_name_end;
        second_name_preview = missing_second_name_preview;
        used_missing_second_name_length = true;
      }
      // EE routes two-part creature names through two CExoLocString readers.
      // Diamond's HG stream carries inline CExoString bytes for both names, so
      // keep the legacy outer bit and force each locstring reader's inner
      // TLK/string flag to the inline-string branch.
      bool first_inner_changed = false;
      bool second_inner_changed = false;
      if (!SetCnwMsbBit(
              record_fragment_bits,
              working_bit_cursor + 1,
              false,
              &first_inner_changed) ||
          !SetCnwMsbBit(
              record_fragment_bits,
              working_bit_cursor + 2,
              false,
              &second_inner_changed) ||
          !AdvanceLegacyLiveFragmentBits(
              *record_fragment_bits,
              &working_bit_cursor,
              3)) {
        return fail(L"name-double-cstring");
      }
      if (used_missing_second_name_length) {
        // Some HG Diamond packets carry the first name as an empty CExoString
        // and then place the printable second name directly in the read buffer.
        // Reinsert the missing 32-bit length so EE's second locstring helper
        // consumes the same bytes Diamond displayed.
        if (!copy_bytes(name_end - cursor) ||
            !append_u32_to_rewritten(second_name_length) ||
            !copy_bytes(second_name_length)) {
          return fail(L"name-double-cstring-missing-length");
        }
        local_inserted += 4;
      } else if (!copy_bytes(second_name_end - cursor)) {
        return fail(L"name-double-cstring");
      }
      local_name_mode_bits_rewritten +=
          static_cast<uint32_t>(first_inner_changed ? 1 : 0) +
          static_cast<uint32_t>(second_inner_changed ? 1 : 0);
      used_double_inline_name = true;
      if (!second_name_preview.empty()) {
        name_preview += " ";
        name_preview += second_name_preview;
        name_length += second_name_length;
      }
    } else {
      // Diamond already writes the same outer name-mode BOOL that EE reads.
      // Preserve and consume it for the single inline CExoString branch.
      if (!AdvanceLegacyLiveFragmentBits(
              *record_fragment_bits,
              &working_bit_cursor,
              1) ||
          !copy_bytes(name_end - cursor)) {
        return fail(L"name-single-cstring");
      }
      used_single_inline_name = true;
    }
  }

  if ((flags & 0x0001u) != 0 && !copy_bytes(2)) {
    return fail(L"field-0001-word");
  }
  if ((flags & 0x0002u) != 0 && !copy_bytes(1)) {
    return fail(L"field-0002-byte");
  }
  if ((flags & 0x0004u) != 0 && !copy_bytes(1)) {
    return fail(L"field-0004-byte");
  }
  if ((flags & 0x0080u) != 0) {
    // Feature 0x23 is false for the HG/Diamond stream, so EE reads this as the
    // compact legacy byte rather than a newer WORD.
    if (!(kEeCreatureFeature23Fields
              ? copy_legacy_byte_as_ee_word()
              : copy_bytes(1))) {
      return fail(L"field-0080-feature23-byte");
    }
  }
  if ((flags & 0x0800u) != 0 && !copy_bytes(4)) {
    return fail(L"field-0800-dword");
  }
  if ((flags & 0x1000u) != 0 && !copy_bytes(4)) {
    return fail(L"field-1000-dword");
  }
  if ((flags & 0x0008u) != 0 && !copy_bytes(1)) {
    return fail(L"field-0008-byte");
  }
  if ((flags & 0x0010u) != 0 && !copy_bytes(1)) {
    return fail(L"field-0010-byte");
  }
  if ((flags & 0x0020u) != 0 && !copy_bytes(1)) {
    return fail(L"field-0020-byte");
  }
  if ((flags & 0x0040u) != 0 && !copy_bytes(1)) {
    return fail(L"field-0040-byte");
  }

  bool used_alternate_2000_before_parts_order = false;
  bool used_prefixed_full_part_table = false;
  bool used_zero_prefixed_full_part_table = false;
  bool used_aligned_short_zero_prefixed_full_part_table = false;
  bool promoted_byte_stream_aligned = false;
  const auto copy_2000_field = [&]() -> bool {
    if ((flags & 0x2000u) == 0) {
      return true;
    }
    return copy_bytes(6);
  };
  const auto align_promoted_byte_stream = [&]() -> bool {
    if (promoted_byte_stream_aligned) {
      return true;
    }
    if (!record_bit_cursor_reliable || record_fragment_bits == nullptr) {
      return false;
    }
    const size_t padding_bits = (8u - (working_bit_cursor % 8u)) % 8u;
    if (padding_bits != 0) {
      if (!EraseCnwMsbBits(record_fragment_bits, working_bit_cursor, padding_bits)) {
        return false;
      }
      local_promoted_bits_erased += static_cast<uint32_t>(padding_bits);
    }
    promoted_byte_stream_aligned = true;
    return true;
  };
  const auto read_aligned_promoted_byte_from_fragment =
      [&](unsigned char* value) -> bool {
    if (!align_promoted_byte_stream()) {
      return false;
    }
    return read_promoted_byte_from_fragment(value);
  };
  const auto peek_legacy_bytes_aligned_promoted = [&](
      size_t source_cursor,
      size_t count,
      std::vector<unsigned char>* values) -> bool {
    if (values != nullptr) {
      values->clear();
    }
    if (values == nullptr ||
        source_cursor < cursor ||
        count > kMaxReasonableReassembledGameplayPayload) {
      return false;
    }

    size_t temp_cursor = source_cursor;
    size_t temp_bit_cursor = working_bit_cursor;
    bool temp_aligned = promoted_byte_stream_aligned;
    if (source_cursor > cursor) {
      if (cursor < declared_live_end) {
        if (source_cursor > declared_live_end) {
          temp_cursor = declared_live_end;
          if (!temp_aligned) {
            temp_bit_cursor += (8u - (temp_bit_cursor % 8u)) % 8u;
            temp_aligned = true;
          }
          temp_bit_cursor += (source_cursor - declared_live_end) * 8u;
          temp_cursor = source_cursor;
        }
      } else {
        if (!temp_aligned) {
          temp_bit_cursor += (8u - (temp_bit_cursor % 8u)) % 8u;
          temp_aligned = true;
        }
        temp_bit_cursor += (source_cursor - cursor) * 8u;
        temp_cursor = source_cursor;
      }
    }

    values->reserve(count);
    for (size_t index = 0; index < count; ++index) {
      if (temp_cursor < declared_live_end) {
        if (temp_cursor >= bytes.size()) {
          return false;
        }
        values->push_back(bytes[temp_cursor++]);
        continue;
      }

      if (!record_bit_cursor_reliable || record_fragment_bits == nullptr) {
        return false;
      }
      if (!temp_aligned) {
        temp_bit_cursor += (8u - (temp_bit_cursor % 8u)) % 8u;
        temp_aligned = true;
      }
      uint64_t raw = 0;
      if (!ReadLegacyLiveFragmentUnsignedAt(
              *record_fragment_bits,
              temp_bit_cursor,
              8,
              &raw)) {
        return false;
      }
      values->push_back(static_cast<unsigned char>(raw & 0xFFu));
      temp_bit_cursor += 8;
      ++temp_cursor;
    }
    return true;
  };
  const auto read_legacy_bytes_aligned_promoted = [&](
      size_t count,
      std::vector<unsigned char>* values) -> bool {
    if (values != nullptr) {
      values->clear();
      values->reserve(count);
    }
    for (size_t index = 0; index < count; ++index) {
      unsigned char value = 0;
      if (cursor < declared_live_end) {
        if (!read_legacy_byte(&value)) {
          return false;
        }
      } else if (!read_aligned_promoted_byte_from_fragment(&value)) {
        return false;
      } else {
        ++cursor;
      }
      if (values != nullptr) {
        values->push_back(value);
      }
    }
    return true;
  };
  const auto parse_part_table = [&]() -> bool {
    if ((flags & 0x0100u) == 0) {
      return true;
    }
    unsigned char first_part_byte = 0;
    if (!peek_legacy_byte(cursor, &first_part_byte)) {
      return fail(L"part-count-short");
    }
    // Several HG full-creature P records carry four legacy bytes immediately
    // before the 19-part body table. Diamond consumes that legacy prefix before
    // the table; stock EE goes straight to the body table. Detect the shape by
    // requiring the following 0x2000/equipment boundary to be sane, then emit
    // the EE table shape for the negotiated feature branch and drop the prefix.
    const size_t legacy_prefixed_part_block_size = 24;
    const size_t prefixed_full_count_offset = cursor + 4;
    const size_t prefixed_full_values_offset = cursor + 5;
    const size_t prefixed_full_end = cursor + legacy_prefixed_part_block_size;
    size_t after_prefixed_full = prefixed_full_end;
    if ((flags & 0x2000u) != 0) {
      after_prefixed_full += 6;
    }
    std::vector<unsigned char> part_probe;
    if (peek_legacy_bytes(cursor, legacy_prefixed_part_block_size, &part_probe) &&
        part_probe.size() == legacy_prefixed_part_block_size &&
        part_probe[prefixed_full_count_offset - cursor] == 0x13 &&
        (looks_like_equipment_list_at(after_prefixed_full) ||
         (object_id >= 0xFFFFFF00u && prefixed_full_end > declared_live_end))) {
      const size_t legacy_part_start = cursor;
      std::vector<unsigned char> legacy_part_block;
      if (!read_legacy_bytes(legacy_prefixed_part_block_size, &legacy_part_block) ||
          legacy_part_block.size() != legacy_prefixed_part_block_size) {
        return fail(L"part-prefixed-full19-short");
      }
      rewritten_record->push_back(0x13);
      if (kEeCreatureFeature23Fields) {
        for (size_t index = 0; index < 19; ++index) {
          AppendU16Le(
              rewritten_record,
              static_cast<uint16_t>(
                  legacy_part_block[prefixed_full_values_offset - legacy_part_start + index]));
        }
        local_inserted += 15;
      } else {
        rewritten_record->insert(
            rewritten_record->end(),
            legacy_part_block.begin() +
                static_cast<std::ptrdiff_t>(prefixed_full_values_offset - legacy_part_start),
            legacy_part_block.begin() +
                static_cast<std::ptrdiff_t>(
                    prefixed_full_values_offset - legacy_part_start + 19));
        local_removed += 4;
      }
      used_prefixed_full_part_table = true;
      return true;
    }

    const size_t legacy_zero_prefixed_part_block_size =
        legacy_prefixed_part_block_size + 4;
    const size_t zero_prefixed_full_count_offset = cursor + 8;
    const size_t zero_prefixed_full_values_offset = cursor + 9;
    const size_t zero_prefixed_full_end =
        cursor + legacy_zero_prefixed_part_block_size;
    size_t after_zero_prefixed_full = zero_prefixed_full_end;
    if ((flags & 0x2000u) != 0) {
      after_zero_prefixed_full += 6;
    }
    if (peek_legacy_bytes(
            cursor,
            legacy_zero_prefixed_part_block_size,
            &part_probe) &&
        part_probe.size() == legacy_zero_prefixed_part_block_size &&
        part_probe[0] == 0 &&
        part_probe[1] == 0 &&
        part_probe[2] == 0 &&
        part_probe[3] == 0 &&
        part_probe[zero_prefixed_full_count_offset - cursor] == 0x13 &&
        (looks_like_equipment_list_at(after_zero_prefixed_full) ||
         (object_id >= 0xFFFFFF00u && zero_prefixed_full_end > declared_live_end))) {
      const size_t legacy_part_start = cursor;
      std::vector<unsigned char> legacy_part_block;
      if (!read_legacy_bytes(
              legacy_zero_prefixed_part_block_size,
              &legacy_part_block) ||
          legacy_part_block.size() != legacy_zero_prefixed_part_block_size) {
        return fail(L"part-zero-prefixed-full19-short");
      }
      rewritten_record->push_back(0x13);
      if (kEeCreatureFeature23Fields) {
        for (size_t index = 0; index < 19; ++index) {
          AppendU16Le(
              rewritten_record,
              static_cast<uint16_t>(
                  legacy_part_block[
                      zero_prefixed_full_values_offset - legacy_part_start + index]));
        }
        local_inserted += 11;
      } else {
        rewritten_record->insert(
            rewritten_record->end(),
            legacy_part_block.begin() +
                static_cast<std::ptrdiff_t>(
                    zero_prefixed_full_values_offset - legacy_part_start),
            legacy_part_block.begin() +
                static_cast<std::ptrdiff_t>(
                    zero_prefixed_full_values_offset - legacy_part_start + 19));
        local_removed += 8;
      }
      used_zero_prefixed_full_part_table = true;
      return true;
    }

    // In short self/controlled-creature updates the declared CNW read buffer
    // can end after the first legacy prefix byte. The remaining byte-oriented
    // body table is stored in the fragment area after the fragment header and
    // any pending BOOL bits, so decode it from the next byte boundary instead
    // of treating packed fragment bytes as raw read-buffer bytes.
    const size_t aligned_short_zero_prefixed_part_block_size = 23;
    const size_t aligned_short_zero_count_offset = cursor + 3;
    const size_t aligned_short_zero_values_offset = cursor + 4;
    const size_t aligned_short_zero_end =
        cursor + aligned_short_zero_prefixed_part_block_size;
    if (object_id >= 0xFFFFFF00u &&
        cursor < declared_live_end &&
        aligned_short_zero_end > declared_live_end &&
        peek_legacy_bytes_aligned_promoted(
            cursor,
            aligned_short_zero_prefixed_part_block_size,
            &part_probe) &&
        part_probe.size() == aligned_short_zero_prefixed_part_block_size &&
        part_probe[0] == 0 &&
        part_probe[1] == 0 &&
        part_probe[2] == 0 &&
        part_probe[aligned_short_zero_count_offset - cursor] == 0x13) {
      const size_t legacy_part_start = cursor;
      std::vector<unsigned char> legacy_part_block;
      if (!read_legacy_bytes_aligned_promoted(
              aligned_short_zero_prefixed_part_block_size,
              &legacy_part_block) ||
          legacy_part_block.size() != aligned_short_zero_prefixed_part_block_size) {
        return fail(L"part-aligned-short-zero-prefixed-full19-short");
      }
      rewritten_record->push_back(0x13);
      if (kEeCreatureFeature23Fields) {
        for (size_t index = 0; index < 19; ++index) {
          AppendU16Le(
              rewritten_record,
              static_cast<uint16_t>(
                  legacy_part_block[
                      aligned_short_zero_values_offset - legacy_part_start + index]));
        }
        local_inserted += 16;
      } else {
        rewritten_record->insert(
            rewritten_record->end(),
            legacy_part_block.begin() +
                static_cast<std::ptrdiff_t>(
                    aligned_short_zero_values_offset - legacy_part_start),
            legacy_part_block.begin() +
                static_cast<std::ptrdiff_t>(
                    aligned_short_zero_values_offset - legacy_part_start + 19));
        local_removed += 3;
      }
      used_aligned_short_zero_prefixed_full_part_table = true;
      return true;
    }

    unsigned char part_count = 0;
    if (!read_legacy_byte(&part_count)) {
      return fail(L"part-count-short");
    }
    if (part_count > 19) {
      return fail(L"part-count-unreasonable");
    }
    rewritten_record->push_back(part_count);
    if (part_count < 10) {
      for (unsigned char index = 0; index < part_count; ++index) {
        if (!copy_bytes(1) ||
            !(kEeCreatureFeature23Fields
                  ? copy_legacy_byte_as_ee_word()
                  : copy_bytes(1))) {
          return fail(L"part-index-value-short");
        }
      }
    } else {
      if (kEeCreatureFeature23Fields) {
        for (unsigned char index = 0; index < 19; ++index) {
          if (!copy_legacy_byte_as_ee_word()) {
            return fail(L"part-table-short");
          }
        }
      } else if (!copy_bytes(19)) {
        return fail(L"part-table-short");
      }
    }
    return true;
  };

  unsigned char alternate_first_byte = 0;
  unsigned char alternate_after_2000_byte = 0;
  const bool alternate_2000_probe =
      peek_legacy_byte(cursor, &alternate_first_byte) &&
      peek_legacy_byte(cursor + 6, &alternate_after_2000_byte);
  if ((flags & 0x0100u) != 0 &&
      (flags & 0x2000u) != 0 &&
      alternate_2000_probe &&
      alternate_first_byte > 19 &&
      alternate_after_2000_byte <= 19 &&
      (object_id >= 0xFFFFFF00u || cursor >= declared_live_end)) {
    used_alternate_2000_before_parts_order = true;
    if (!copy_2000_field() || !parse_part_table()) {
      return fail(L"field-2000-before-parts-short");
    }
  } else {
    if (!parse_part_table()) {
      return false;
    }
    if (!copy_2000_field()) {
      return fail(L"field-2000-word-int");
    }
  }
  if ((flags & 0x4000u) != 0) {
    if (kEeCreatureFeature0eFields) {
      rewritten_record->push_back(0);
      ++local_inserted;
    } else {
      skipped_feature0e_field = true;
    }
  }

  if ((flags & 0x0200u) != 0) {
    const bool count_is_promoted =
        cursor >= declared_live_end &&
        (object_id >= 0xFFFFFF00u || declared_live_end - record_offset < 128);
    const auto synthesize_empty_equipment_count = [&](const wchar_t* reason) -> bool {
      if (!count_is_promoted) {
        return fail(reason);
      }
      rewritten_record->push_back(0);
      ++local_inserted;
      equipment_count_synthesized_zero = true;
      partial_reason = reason != nullptr ? reason : L"equipment-count-synthesized";
      return true;
    };
    const auto copy_legacy_dword_string_from_reader = [&](
        std::vector<unsigned char>* output,
        std::string* preview,
        std::wstring* failure_reason) -> bool {
      if (preview != nullptr) {
        preview->clear();
      }
      if (output == nullptr) {
        if (failure_reason != nullptr) {
          *failure_reason = L"active-properties-string-output-missing";
        }
        return false;
      }

      std::vector<unsigned char> length_bytes;
      if (!read_legacy_bytes(4, &length_bytes) || length_bytes.size() != 4) {
        if (failure_reason != nullptr) {
          *failure_reason = L"active-properties-string-length-short";
        }
        return false;
      }
      const uint32_t length = ReadU32Le(length_bytes.data());
      constexpr uint32_t kMaxLegacyLivePromotedItemNameBytes = 1024;
      if (length > kMaxLegacyLivePromotedItemNameBytes) {
        if (failure_reason != nullptr) {
          wchar_t text[96]{};
          swprintf_s(
              text,
              L"active-properties-string-length-unreasonable=%u",
              static_cast<unsigned int>(length));
          *failure_reason = text;
        }
        return false;
      }

      std::vector<unsigned char> text_bytes;
      if (!read_legacy_bytes(length, &text_bytes) ||
          text_bytes.size() != static_cast<size_t>(length)) {
        if (failure_reason != nullptr) {
          *failure_reason = L"active-properties-string-text-short";
        }
        return false;
      }

      output->insert(output->end(), length_bytes.begin(), length_bytes.end());
      output->insert(output->end(), text_bytes.begin(), text_bytes.end());
      if (preview != nullptr && length != 0) {
        preview->assign(
            reinterpret_cast<const char*>(text_bytes.data()),
            reinterpret_cast<const char*>(text_bytes.data() + text_bytes.size()));
      }
      return true;
    };
    const auto copy_legacy_bytes_from_reader = [&](
        size_t count,
        std::vector<unsigned char>* output,
        std::wstring* failure_reason,
        const wchar_t* reason) -> bool {
      if (output == nullptr) {
        if (failure_reason != nullptr) {
          *failure_reason = L"legacy-byte-output-missing";
        }
        return false;
      }
      std::vector<unsigned char> values;
      if (!read_legacy_bytes(count, &values) || values.size() != count) {
        if (failure_reason != nullptr) {
          *failure_reason = reason != nullptr ? reason : L"legacy-byte-reader-short";
        }
        return false;
      }
      output->insert(output->end(), values.begin(), values.end());
      return true;
    };
    const auto copy_promoted_active_properties_for_ee = [&](
        uint32_t base_item_id,
        std::vector<unsigned char>* equipment_bytes,
        uint32_t* inserted_bits,
        std::string* active_name_preview,
        std::wstring* failure_reason) -> bool {
      if (inserted_bits != nullptr) {
        *inserted_bits = 0;
      }
      if (active_name_preview != nullptr) {
        active_name_preview->clear();
      }
      if (!record_bit_cursor_reliable ||
          record_fragment_bits == nullptr ||
          equipment_bytes == nullptr) {
        if (failure_reason != nullptr) {
          *failure_reason = L"promoted-active-properties-fragment-context-missing";
        }
        return false;
      }

      if (base_item_id == 0x10u &&
          !copy_legacy_bytes_from_reader(
              2,
              equipment_bytes,
              failure_reason,
              L"promoted-active-properties-armor-word-short")) {
        return false;
      }

      bool name_is_locstring = false;
      if (!ReadLegacyLiveFragmentBool(
              *record_fragment_bits,
              &working_bit_cursor,
              &name_is_locstring)) {
        if (failure_reason != nullptr) {
          *failure_reason = L"promoted-active-properties-name-kind-bit-missing";
        }
        return false;
      }

      if (name_is_locstring) {
        const size_t inner_locstring_bit = working_bit_cursor;
        bool custom_tlk = false;
        if (!ReadLegacyLiveFragmentBool(
                *record_fragment_bits,
                &working_bit_cursor,
                &custom_tlk)) {
          if (failure_reason != nullptr) {
            *failure_reason = L"promoted-active-properties-locstring-kind-bit-missing";
          }
          return false;
        }
        if (custom_tlk) {
          if (!AdvanceLegacyLiveFragmentBits(
                  *record_fragment_bits,
                  &working_bit_cursor,
                  1)) {
            if (failure_reason != nullptr) {
              *failure_reason = L"promoted-active-properties-locstring-custom-bit-short";
            }
            return false;
          }
          std::vector<unsigned char> strref_bytes;
          if (!read_legacy_bytes(4, &strref_bytes) || strref_bytes.size() != 4) {
            if (failure_reason != nullptr) {
              *failure_reason = L"promoted-active-properties-locstring-custom-short";
            }
            return false;
          }
          equipment_bytes->insert(
              equipment_bytes->end(),
              strref_bytes.begin(),
              strref_bytes.end());
          if (active_name_preview != nullptr) {
            char text[96]{};
            sprintf_s(text, "strref:%u", ReadU32Le(strref_bytes.data()));
            *active_name_preview = text;
          }
        } else {
          const size_t text_cursor = cursor;
          const size_t text_equipment_size = equipment_bytes->size();
          std::wstring text_failure;
          if (!copy_legacy_dword_string_from_reader(
                  equipment_bytes,
                  active_name_preview,
                  &text_failure)) {
            cursor = text_cursor;
            equipment_bytes->resize(text_equipment_size);
            if (!SetCnwMsbBit(record_fragment_bits, inner_locstring_bit, true, nullptr) ||
                !AdvanceLegacyLiveFragmentBits(
                    *record_fragment_bits,
                    &working_bit_cursor,
                    1)) {
              if (failure_reason != nullptr) {
                *failure_reason = text_failure.empty()
                    ? L"promoted-active-properties-locstring-text-short"
                    : text_failure;
              }
              return false;
            }
            std::vector<unsigned char> strref_bytes;
            if (!read_legacy_bytes(4, &strref_bytes) || strref_bytes.size() != 4) {
              if (failure_reason != nullptr) {
                *failure_reason = L"promoted-active-properties-locstring-strref-short";
              }
              return false;
            }
            equipment_bytes->insert(
                equipment_bytes->end(),
                strref_bytes.begin(),
                strref_bytes.end());
            if (active_name_preview != nullptr) {
              char text[96]{};
              sprintf_s(text, "strref:%u", ReadU32Le(strref_bytes.data()));
              *active_name_preview = text;
            }
          }
        }
      } else if (!copy_legacy_dword_string_from_reader(
                     equipment_bytes,
                     active_name_preview,
                     failure_reason)) {
        if (failure_reason != nullptr && failure_reason->empty()) {
          *failure_reason = L"promoted-active-properties-name-string-short";
        }
        return false;
      }

      if (!AdvanceLegacyLiveFragmentBits(
              *record_fragment_bits,
              &working_bit_cursor,
              1) ||
          !copy_legacy_bytes_from_reader(
              8,
              equipment_bytes,
              failure_reason,
              L"promoted-active-properties-cost-stack-short")) {
        if (failure_reason != nullptr && failure_reason->empty()) {
          *failure_reason = L"promoted-active-properties-cost-stack-short";
        }
        return false;
      }

      if (!AdvanceLegacyLiveFragmentBits(
              *record_fragment_bits,
              &working_bit_cursor,
              3)) {
        if (failure_reason != nullptr) {
          *failure_reason = L"promoted-active-properties-post-name-bits-short";
        }
        return false;
      }

      if (!InsertCnwMsbBit(record_fragment_bits, working_bit_cursor, false)) {
        if (failure_reason != nullptr) {
          *failure_reason = L"promoted-active-properties-ee-extra-bit-insert-failed";
        }
        return false;
      }
      ++working_bit_cursor;
      if (inserted_bits != nullptr) {
        ++(*inserted_bits);
      }

      unsigned char property_count = 0;
      if (!read_legacy_byte(&property_count)) {
        if (failure_reason != nullptr) {
          *failure_reason = L"promoted-active-properties-count-short";
        }
        return false;
      }
      constexpr uint8_t kMaxReasonablePromotedLiveItemProperties = 128;
      if (property_count > kMaxReasonablePromotedLiveItemProperties) {
        if (failure_reason != nullptr) {
          wchar_t text[96]{};
          swprintf_s(
              text,
              L"promoted-active-properties-count-unreasonable=%u",
              static_cast<unsigned int>(property_count));
          *failure_reason = text;
        }
        return false;
      }
      equipment_bytes->push_back(property_count);

      const size_t property_bytes = static_cast<size_t>(property_count) * 7u;
      if (!copy_legacy_bytes_from_reader(
              property_bytes,
              equipment_bytes,
              failure_reason,
              L"promoted-active-properties-table-short")) {
        return false;
      }

      unsigned char state_mask = 0;
      unsigned char value_mask = 0;
      if (!read_legacy_byte(&state_mask) ||
          !read_legacy_byte(&value_mask)) {
        if (failure_reason != nullptr) {
          *failure_reason = L"promoted-active-properties-state-value-mask-short";
        }
        return false;
      }
      equipment_bytes->push_back(state_mask);
      equipment_bytes->push_back(value_mask);

      const size_t value_bytes = CountByteSetBits(value_mask);
      if (!copy_legacy_bytes_from_reader(
              value_bytes,
              equipment_bytes,
              failure_reason,
              L"promoted-active-properties-value-mask-short")) {
        return false;
      }
      return true;
    };
    const auto looks_like_promoted_equipment_header_probe =
        [&](const std::vector<unsigned char>& probe) -> bool {
      if (probe.size() < 9) {
        return false;
      }
      const unsigned char equipment_opcode = probe[0];
      if (equipment_opcode != 'A' &&
          equipment_opcode != 'D' &&
          equipment_opcode != 'U') {
        return false;
      }
      const uint32_t equipment_object_id = ReadU32Le(probe.data() + 1);
      const uint32_t equipment_high_byte = equipment_object_id & 0xFF000000u;
      if (!LooksLikeLegacyLiveObjectIdValue(equipment_object_id) &&
          equipment_high_byte != 0x7F000000u) {
        return false;
      }
      return ReadU32Le(probe.data() + 5) < 0x00010000u;
    };
    const auto looks_like_promoted_equipment_header_here = [&]() -> bool {
      std::vector<unsigned char> probe;
      return peek_legacy_bytes(cursor, 9, &probe) &&
          looks_like_promoted_equipment_header_probe(probe);
    };
    const auto find_promoted_equipment_header_lookahead = [&](
        size_t max_skip,
        size_t* skip_bytes,
        std::vector<unsigned char>* header_probe) -> bool {
      if (skip_bytes != nullptr) {
        *skip_bytes = 0;
      }
      if (header_probe != nullptr) {
        header_probe->clear();
      }
      for (size_t skip = 0; skip <= max_skip; ++skip) {
        std::vector<unsigned char> probe;
        if (!peek_legacy_bytes(cursor + skip, 9, &probe)) {
          continue;
        }
        if (!looks_like_promoted_equipment_header_probe(probe)) {
          continue;
        }
        if (skip_bytes != nullptr) {
          *skip_bytes = skip;
        }
        if (header_probe != nullptr) {
          *header_probe = std::move(probe);
        }
        return true;
      }
      return false;
    };
    const auto synthesize_promoted_empty_active_properties_for_ee = [&](
        uint32_t base_item_id,
        std::vector<unsigned char>* equipment_bytes,
        uint32_t* inserted_bits,
        uint32_t* inserted_bytes,
        std::wstring* failure_reason) -> bool {
      if (inserted_bits != nullptr) {
        *inserted_bits = 0;
      }
      if (inserted_bytes != nullptr) {
        *inserted_bytes = 0;
      }
      if (!record_bit_cursor_reliable ||
          record_fragment_bits == nullptr ||
          equipment_bytes == nullptr) {
        if (failure_reason != nullptr) {
          *failure_reason = L"promoted-active-properties-synth-context-missing";
        }
        return false;
      }
      const auto append_zero_bytes = [&](size_t count) {
        equipment_bytes->insert(equipment_bytes->end(), count, 0);
        if (inserted_bytes != nullptr) {
          *inserted_bytes += static_cast<uint32_t>(count);
        }
      };
      const auto insert_false_bit = [&]() -> bool {
        if (!InsertCnwMsbBit(record_fragment_bits, working_bit_cursor, false)) {
          return false;
        }
        ++working_bit_cursor;
        if (inserted_bits != nullptr) {
          ++(*inserted_bits);
        }
        return true;
      };

      if (base_item_id == 0x10u) {
        append_zero_bytes(2);
      }
      if (!insert_false_bit()) {
        if (failure_reason != nullptr) {
          *failure_reason = L"promoted-active-properties-synth-name-bit-failed";
        }
        return false;
      }
      append_zero_bytes(4);
      if (!insert_false_bit()) {
        if (failure_reason != nullptr) {
          *failure_reason = L"promoted-active-properties-synth-cost-bit-failed";
        }
        return false;
      }
      append_zero_bytes(8);
      for (size_t bit_index = 0; bit_index < 4; ++bit_index) {
        if (!insert_false_bit()) {
          if (failure_reason != nullptr) {
            *failure_reason =
                L"promoted-active-properties-synth-post-name-bit-failed";
          }
          return false;
        }
      }
      append_zero_bytes(3);
      return true;
    };

    if (count_is_promoted) {
      const size_t equipment_cursor_snapshot = cursor;
      const uint32_t promoted_before_equipment = local_promoted;
      const uint32_t promoted_bits_before_equipment = local_promoted_bits_erased;
      const uint32_t inserted_before_equipment = local_inserted;
      const uint32_t equipment_app_inserted_before =
          local_equipment_appearance_bytes_inserted;
      const uint32_t active_bits_inserted_before =
          local_active_property_bits_inserted;
      const bool had_equipment_fragment_snapshot =
          record_bit_cursor_reliable && record_fragment_bits != nullptr;
      std::vector<unsigned char> equipment_fragment_bits_snapshot;
      size_t equipment_bit_cursor_snapshot = working_bit_cursor;
      if (had_equipment_fragment_snapshot) {
        equipment_fragment_bits_snapshot = *record_fragment_bits;
      }
      const auto restore_promoted_equipment_snapshot = [&]() {
        cursor = equipment_cursor_snapshot;
        local_promoted = promoted_before_equipment;
        local_promoted_bits_erased = promoted_bits_before_equipment;
        local_inserted = inserted_before_equipment;
        local_equipment_appearance_bytes_inserted = equipment_app_inserted_before;
        local_active_property_bits_inserted = active_bits_inserted_before;
        if (had_equipment_fragment_snapshot && record_fragment_bits != nullptr) {
          *record_fragment_bits = equipment_fragment_bits_snapshot;
          working_bit_cursor = equipment_bit_cursor_snapshot;
        }
      };

      unsigned char legacy_equipment_count = 0;
      if (!read_legacy_byte(&legacy_equipment_count)) {
        return fail(L"equipment-count-promoted-tail");
      }

      std::vector<unsigned char> equipment_bytes;
      uint32_t parsed_equipment_items = 0;
      uint32_t parsed_equipment_appearances = 0;
      std::wstring promoted_equipment_failure;
      const bool promoted_count_reasonable = legacy_equipment_count <= 64;
      bool promoted_parse_ok = promoted_count_reasonable;
      if (promoted_parse_ok) {
        equipment_bytes.reserve(
            static_cast<size_t>(legacy_equipment_count) * 64u + 1u);
        equipment_bytes.push_back(legacy_equipment_count);
        for (unsigned char index = 0; index < legacy_equipment_count; ++index) {
          std::vector<unsigned char> header;
          if (!read_legacy_bytes(9, &header) || header.size() != 9) {
            promoted_equipment_failure = L"promoted-equipment-entry-short";
            equipment_failure_offset = cursor;
            promoted_parse_ok = false;
            break;
          }

          const size_t equipment_entry_offset = cursor >= 9 ? cursor - 9 : cursor;
          const unsigned char equipment_opcode = header[0];
          const uint32_t equipment_object_id = ReadU32Le(header.data() + 1);
          const uint32_t equipment_high_byte = equipment_object_id & 0xFF000000u;
          const uint32_t equipment_field = ReadU32Le(header.data() + 5);
          if ((equipment_opcode != 'A' &&
               equipment_opcode != 'D' &&
               equipment_opcode != 'U') ||
              (!LooksLikeLegacyLiveObjectIdValue(equipment_object_id) &&
               equipment_high_byte != 0x7F000000u) ||
              equipment_field >= 0x00010000u) {
            promoted_equipment_failure =
                equipment_opcode == 'A' ||
                equipment_opcode == 'D' ||
                equipment_opcode == 'U'
                    ? L"promoted-equipment-header-invalid"
                    : L"promoted-equipment-opcode-unsupported";
            equipment_failure_offset = equipment_entry_offset;
            equipment_failure_opcode = equipment_opcode;
            equipment_failure_has_opcode = true;
            promoted_parse_ok = false;
            break;
          }

          equipment_bytes.insert(
              equipment_bytes.end(),
              header.begin(),
              header.end());
          ++parsed_equipment_items;

          if (equipment_opcode == 'D') {
            append_equipment_diagnostic(
                index,
                equipment_entry_offset,
                equipment_opcode,
                equipment_object_id,
                equipment_field,
                0,
                -1,
                0,
                cursor,
                cursor,
                0,
                {},
                L"promoted delete");
            continue;
          }
          if (equipment_opcode == 'U') {
            unsigned char state = 0;
            if (!read_legacy_byte(&state)) {
              promoted_equipment_failure = L"promoted-equipment-U-state-short";
              equipment_failure_offset = cursor;
              promoted_parse_ok = false;
              break;
            }
            equipment_bytes.push_back(state);
            append_equipment_diagnostic(
                index,
                equipment_entry_offset,
                equipment_opcode,
                equipment_object_id,
                equipment_field,
                0,
                -1,
                0,
                cursor >= 1 ? cursor - 1 : cursor,
                cursor,
                0,
                {},
                L"promoted update");
            continue;
          }

          std::vector<unsigned char> base_item_bytes;
          if (!read_legacy_bytes(4, &base_item_bytes) ||
              base_item_bytes.size() != 4) {
            promoted_equipment_failure =
                L"promoted-equipment-appearance-base-short";
            equipment_failure_offset = cursor;
            promoted_parse_ok = false;
            break;
          }
          const uint32_t base_item_id = ReadU32Le(base_item_bytes.data());
          const int model_type = GetBaseItemModelType(runtime, base_item_id);
          const size_t legacy_size = LegacyItemAppearanceReadSize(model_type);
          if (legacy_size < 4) {
            promoted_equipment_failure =
                L"promoted-equipment-appearance-model-unknown";
            equipment_failure_offset = cursor;
            promoted_parse_ok = false;
            break;
          }

          std::vector<unsigned char> legacy_appearance = base_item_bytes;
          std::vector<unsigned char> appearance_tail;
          if (!read_legacy_bytes(legacy_size - 4, &appearance_tail) ||
              appearance_tail.size() != legacy_size - 4) {
            promoted_equipment_failure =
                L"promoted-equipment-appearance-short";
            equipment_failure_offset = cursor;
            promoted_parse_ok = false;
            break;
          }
          legacy_appearance.insert(
              legacy_appearance.end(),
              appearance_tail.begin(),
              appearance_tail.end());

          const bool append_empty_visual_transform_map =
              runtime.options.rewrite_live_object_item_appearance_visual_transforms;
          const bool expand_word_parts =
              runtime.options.rewrite_live_object_item_appearance_word_parts;
          if (model_type == 3 ||
              expand_word_parts ||
              append_empty_visual_transform_map) {
            if (expand_word_parts || append_empty_visual_transform_map) {
              std::vector<unsigned char> ee_appearance;
              if (!BuildEeItemAppearanceReadBufferBytes(
                      legacy_appearance,
                      0,
                      model_type,
                      expand_word_parts,
                      append_empty_visual_transform_map,
                      &ee_appearance)) {
                promoted_equipment_failure =
                    L"promoted-equipment-appearance-build-failed";
                equipment_failure_offset = cursor;
                promoted_parse_ok = false;
                break;
              }
              if (ee_appearance.size() > legacy_size) {
                const uint32_t delta =
                    static_cast<uint32_t>(ee_appearance.size() - legacy_size);
                local_inserted += delta;
                local_equipment_appearance_bytes_inserted += delta;
              }
              equipment_bytes.insert(
                  equipment_bytes.end(),
                  ee_appearance.begin(),
                  ee_appearance.end());
            } else {
              equipment_bytes.insert(
                  equipment_bytes.end(),
                  legacy_appearance.begin(),
                  legacy_appearance.end());
              equipment_bytes.insert(
                  equipment_bytes.end(),
                  kEeLiveExtendedArmorTableBytes,
                  0);
              local_inserted +=
                  static_cast<uint32_t>(kEeLiveExtendedArmorTableBytes);
              local_equipment_appearance_bytes_inserted +=
                  static_cast<uint32_t>(kEeLiveExtendedArmorTableBytes);
            }
          } else {
            equipment_bytes.insert(
                equipment_bytes.end(),
                legacy_appearance.begin(),
                legacy_appearance.end());
          }

          uint32_t active_property_bits = 0;
          std::string active_name_preview;
          std::wstring active_failure;
          const size_t active_cursor_snapshot = cursor;
          const uint32_t active_promoted_snapshot = local_promoted;
          const uint32_t active_promoted_bits_snapshot =
              local_promoted_bits_erased;
          const size_t active_equipment_size_snapshot = equipment_bytes.size();
          const bool had_active_fragment_snapshot =
              record_bit_cursor_reliable && record_fragment_bits != nullptr;
          std::vector<unsigned char> active_fragment_bits_snapshot;
          size_t active_bit_cursor_snapshot = working_bit_cursor;
          if (had_active_fragment_snapshot) {
            active_fragment_bits_snapshot = *record_fragment_bits;
          }
          const auto restore_active_property_snapshot = [&]() {
            cursor = active_cursor_snapshot;
            local_promoted = active_promoted_snapshot;
            local_promoted_bits_erased = active_promoted_bits_snapshot;
            equipment_bytes.resize(active_equipment_size_snapshot);
            if (had_active_fragment_snapshot && record_fragment_bits != nullptr) {
              *record_fragment_bits = active_fragment_bits_snapshot;
              working_bit_cursor = active_bit_cursor_snapshot;
            }
          };
          if (!copy_promoted_active_properties_for_ee(
                  base_item_id,
                  &equipment_bytes,
                  &active_property_bits,
                  &active_name_preview,
                  &active_failure)) {
            const size_t failed_active_cursor = cursor;
            restore_active_property_snapshot();

            uint32_t synthetic_active_bits = 0;
            uint32_t synthetic_active_bytes = 0;
            std::wstring synthetic_failure;
            bool can_synthesize_compact_active =
                synthesize_promoted_empty_active_properties_for_ee(
                    base_item_id,
                    &equipment_bytes,
                    &synthetic_active_bits,
                    &synthetic_active_bytes,
                    &synthetic_failure);
            if (can_synthesize_compact_active &&
                index + 1 < legacy_equipment_count &&
                !looks_like_promoted_equipment_header_here()) {
              size_t compact_tail_skip = 0;
              std::vector<unsigned char> header_probe;
              if (find_promoted_equipment_header_lookahead(
                      32,
                      &compact_tail_skip,
                      &header_probe) &&
                  compact_tail_skip != 0) {
                std::vector<unsigned char> discarded_compact_tail;
                if (read_legacy_bytes(
                        compact_tail_skip,
                        &discarded_compact_tail) &&
                    discarded_compact_tail.size() == compact_tail_skip &&
                    looks_like_promoted_equipment_header_here()) {
                  promoted_active_properties_compact_bytes_dropped +=
                      static_cast<uint32_t>(compact_tail_skip);
                } else {
                  can_synthesize_compact_active = false;
                  synthetic_failure =
                      L"promoted-active-properties-compact-tail-drop-failed";
                }
              } else {
                can_synthesize_compact_active = false;
                synthetic_failure =
                    L"promoted-active-properties-next-header-mismatch";
              }
            }
            if (!can_synthesize_compact_active) {
              restore_active_property_snapshot();
              promoted_equipment_failure = active_failure.empty()
                  ? L"promoted-equipment-active-properties-parse-failed"
                  : active_failure;
              if (!synthetic_failure.empty()) {
                promoted_equipment_failure += L";synth=";
                promoted_equipment_failure += synthetic_failure;
              }
              equipment_failure_offset = failed_active_cursor;
              promoted_parse_ok = false;
              break;
            }
            active_property_bits = synthetic_active_bits;
            local_inserted += synthetic_active_bytes;
            ++promoted_active_properties_synthesized;
            wchar_t note[160]{};
            swprintf_s(
                note,
                L"promoted active=synth bytes=%u",
                synthetic_active_bytes);
            append_equipment_diagnostic(
                index,
                equipment_entry_offset,
                equipment_opcode,
                equipment_object_id,
                equipment_field,
                base_item_id,
                model_type,
                legacy_size,
                active_cursor_snapshot,
                cursor,
                active_property_bits,
                active_name_preview,
                note);
          } else {
            append_equipment_diagnostic(
                index,
                equipment_entry_offset,
                equipment_opcode,
                equipment_object_id,
                equipment_field,
                base_item_id,
                model_type,
                legacy_size,
                active_cursor_snapshot,
                cursor,
                active_property_bits,
                active_name_preview,
                L"promoted active=parsed");
          }
          local_active_property_bits_inserted += active_property_bits;
          ++parsed_equipment_appearances;
        }
      } else {
        wchar_t text[96]{};
        swprintf_s(
            text,
            L"promoted-equipment-count-unreasonable=%u",
            static_cast<unsigned int>(legacy_equipment_count));
        promoted_equipment_failure = text;
        equipment_failure_offset = cursor;
      }

      if (promoted_parse_ok) {
        rewritten_record->insert(
            rewritten_record->end(),
            equipment_bytes.begin(),
            equipment_bytes.end());
        local_equipment_items += parsed_equipment_items;
        local_equipment_appearances += parsed_equipment_appearances;
        if (legacy_equipment_count != 0) {
          promoted_equipment_copied = true;
        }
      } else {
        restore_promoted_equipment_snapshot();
        if (!read_legacy_byte(&legacy_equipment_count)) {
          return fail(L"equipment-count-promoted-tail");
        }
        rewritten_record->push_back(0);
        if (legacy_equipment_count != 0) {
          equipment_count_synthesized_zero = true;
          partial_reason = promoted_equipment_failure.empty()
              ? L"equipment-count-promoted-nonzero-zeroed"
              : promoted_equipment_failure;
        }
      }
    } else if (cursor >= declared_live_end || cursor >= bytes.size()) {
      if (!synthesize_empty_equipment_count(L"equipment-count-missing")) {
        return false;
      }
    } else {
      const unsigned char equipment_count = bytes[cursor];
      std::vector<unsigned char> equipment_bytes;
      size_t equipment_cursor = cursor + 1;
      uint32_t parsed_equipment_items = 0;
      uint32_t parsed_equipment_appearances = 0;
      const wchar_t* equipment_parse_failure = nullptr;
      std::wstring equipment_parse_failure_storage;
      const uint32_t inserted_before_equipment = local_inserted;
      const uint32_t equipment_app_inserted_before =
          local_equipment_appearance_bytes_inserted;
      const uint32_t active_bits_inserted_before =
          local_active_property_bits_inserted;
      const bool had_equipment_fragment_snapshot =
          record_bit_cursor_reliable && record_fragment_bits != nullptr;
      std::vector<unsigned char> equipment_fragment_bits_snapshot;
      size_t equipment_bit_cursor_snapshot = working_bit_cursor;
      if (had_equipment_fragment_snapshot) {
        equipment_fragment_bits_snapshot = *record_fragment_bits;
      }

      if (equipment_count > 64) {
        equipment_parse_failure = L"equipment-count-unreasonable";
        equipment_failure_offset = cursor;
      } else {
        equipment_bytes.reserve(static_cast<size_t>(equipment_count) * 16 + 1);
        equipment_bytes.push_back(equipment_count);
        for (unsigned char index = 0; index < equipment_count; ++index) {
          if (equipment_cursor > declared_live_end ||
              declared_live_end - equipment_cursor < 9) {
            equipment_parse_failure = L"equipment-entry-short";
            equipment_failure_offset = equipment_cursor;
            break;
          }
          const size_t equipment_entry_offset = equipment_cursor;
          const unsigned char equipment_opcode = bytes[equipment_cursor];
          const uint32_t equipment_object_id =
              ReadU32Le(bytes.data() + equipment_cursor + 1);
          const uint32_t equipment_field =
              ReadU32Le(bytes.data() + equipment_cursor + 5);
          equipment_bytes.insert(
              equipment_bytes.end(),
              bytes.begin() + static_cast<std::ptrdiff_t>(equipment_cursor),
              bytes.begin() + static_cast<std::ptrdiff_t>(equipment_cursor + 9));
          equipment_cursor += 9;
          ++parsed_equipment_items;

          if (equipment_opcode == 'A') {
            if (equipment_cursor > declared_live_end ||
                declared_live_end - equipment_cursor < 4) {
              equipment_parse_failure = L"equipment-appearance-base-short";
              equipment_failure_offset = equipment_cursor;
              break;
            }
            const uint32_t base_item_id = ReadU32Le(bytes.data() + equipment_cursor);
            const int model_type = GetBaseItemModelType(runtime, base_item_id);
            const size_t legacy_size = LegacyItemAppearanceReadSize(model_type);
            if (legacy_size == 0 ||
                equipment_cursor > declared_live_end ||
                declared_live_end - equipment_cursor < legacy_size) {
              equipment_parse_failure = L"equipment-appearance-short";
              equipment_failure_offset = equipment_cursor;
              break;
            }
            const bool append_empty_visual_transform_map =
                runtime.options.rewrite_live_object_item_appearance_visual_transforms;
            const bool expand_word_parts =
                runtime.options.rewrite_live_object_item_appearance_word_parts;
            if (model_type == 3 ||
                expand_word_parts ||
                append_empty_visual_transform_map) {
              if (expand_word_parts || append_empty_visual_transform_map) {
                std::vector<unsigned char> ee_appearance;
                if (!BuildEeItemAppearanceReadBufferBytes(
                        bytes,
                        equipment_cursor,
                        model_type,
                        expand_word_parts,
                        append_empty_visual_transform_map,
                        &ee_appearance)) {
                  equipment_parse_failure = L"equipment-appearance-build-failed";
                  equipment_failure_offset = equipment_cursor;
                  break;
                }
                if (ee_appearance.size() > legacy_size) {
                  const uint32_t delta =
                      static_cast<uint32_t>(ee_appearance.size() - legacy_size);
                  local_inserted += delta;
                  local_equipment_appearance_bytes_inserted += delta;
                }
                equipment_bytes.insert(
                    equipment_bytes.end(),
                    ee_appearance.begin(),
                    ee_appearance.end());
              } else {
                equipment_bytes.insert(
                    equipment_bytes.end(),
                    bytes.begin() + static_cast<std::ptrdiff_t>(equipment_cursor),
                    bytes.begin() + static_cast<std::ptrdiff_t>(equipment_cursor + legacy_size));
                equipment_bytes.insert(
                    equipment_bytes.end(),
                    kEeLiveExtendedArmorTableBytes,
                    0);
                local_inserted += static_cast<uint32_t>(kEeLiveExtendedArmorTableBytes);
                local_equipment_appearance_bytes_inserted +=
                    static_cast<uint32_t>(kEeLiveExtendedArmorTableBytes);
              }
            } else {
              equipment_bytes.insert(
                  equipment_bytes.end(),
                  bytes.begin() + static_cast<std::ptrdiff_t>(equipment_cursor),
                  bytes.begin() + static_cast<std::ptrdiff_t>(equipment_cursor + legacy_size));
            }
            equipment_cursor += legacy_size;
            if (!record_bit_cursor_reliable || record_fragment_bits == nullptr) {
              equipment_parse_failure = L"equipment-active-properties-bit-cursor-unreliable";
              equipment_failure_offset = equipment_cursor;
              break;
            }

            size_t active_properties_end = equipment_cursor;
            uint32_t active_property_bits = 0;
            std::string active_name_preview;
            std::wstring active_failure;
            const size_t active_cursor_snapshot = equipment_cursor;
            const size_t active_equipment_size_snapshot = equipment_bytes.size();
            const uint32_t active_inserted_snapshot = local_inserted;
            const uint32_t active_equipment_app_inserted_snapshot =
                local_equipment_appearance_bytes_inserted;
            const uint32_t active_bits_inserted_snapshot =
                local_active_property_bits_inserted;
            const bool had_active_fragment_snapshot =
                record_bit_cursor_reliable && record_fragment_bits != nullptr;
            std::vector<unsigned char> active_fragment_bits_snapshot;
            size_t active_bit_cursor_snapshot = working_bit_cursor;
            if (had_active_fragment_snapshot) {
              active_fragment_bits_snapshot = *record_fragment_bits;
            }
            const auto restore_nonpromoted_active_snapshot = [&]() {
              equipment_cursor = active_cursor_snapshot;
              equipment_bytes.resize(active_equipment_size_snapshot);
              local_inserted = active_inserted_snapshot;
              local_equipment_appearance_bytes_inserted =
                  active_equipment_app_inserted_snapshot;
              local_active_property_bits_inserted =
                  active_bits_inserted_snapshot;
              if (had_active_fragment_snapshot && record_fragment_bits != nullptr) {
                *record_fragment_bits = active_fragment_bits_snapshot;
                working_bit_cursor = active_bit_cursor_snapshot;
              }
            };
            if (!CopyLegacyLiveCreaturePActiveItemPropertiesForEe(
                    bytes,
                    equipment_cursor,
                    declared_live_end,
                    base_item_id,
                    record_fragment_bits,
                    &working_bit_cursor,
                    &equipment_bytes,
                    &active_properties_end,
                    &active_property_bits,
                    &active_name_preview,
                    &active_failure)) {
              restore_nonpromoted_active_snapshot();

              uint32_t synthetic_active_bits = 0;
              uint32_t synthetic_active_bytes = 0;
              std::wstring synthetic_failure;
              bool synthesized_active_properties =
                  synthesize_promoted_empty_active_properties_for_ee(
                      base_item_id,
                      &equipment_bytes,
                      &synthetic_active_bits,
                      &synthetic_active_bytes,
                      &synthetic_failure);
              size_t resume_cursor = active_cursor_snapshot;
              if (synthesized_active_properties) {
                if (index + 1 < equipment_count) {
                  bool found_next_equipment_header = false;
                  constexpr size_t kMaxActivePropertyRecoveryLookahead = 96;
                  const size_t scan_limit = std::min(
                      declared_live_end,
                      active_cursor_snapshot + kMaxActivePropertyRecoveryLookahead);
                  for (size_t scan = active_cursor_snapshot;
                       scan + 9 <= scan_limit;
                       ++scan) {
                    std::vector<unsigned char> probe(
                        bytes.begin() + static_cast<std::ptrdiff_t>(scan),
                        bytes.begin() + static_cast<std::ptrdiff_t>(scan + 9));
                    if (!looks_like_promoted_equipment_header_probe(probe)) {
                      continue;
                    }
                    resume_cursor = scan;
                    found_next_equipment_header = true;
                    break;
                  }
                  if (!found_next_equipment_header) {
                    synthesized_active_properties = false;
                    synthetic_failure =
                        L"active-properties-synth-next-header-missing";
                  }
                } else {
                  resume_cursor = std::min(
                      FindNextLegacyLiveObjectSubMessageBoundaryAfter(bytes, record_offset),
                      declared_live_end);
                  if (resume_cursor < active_cursor_snapshot) {
                    synthesized_active_properties = false;
                    synthetic_failure =
                        L"active-properties-synth-record-end-before-active";
                  }
                }
              }

              if (!synthesized_active_properties) {
                restore_nonpromoted_active_snapshot();
                if (!active_failure.empty()) {
                  equipment_parse_failure_storage = active_failure;
                }
                equipment_parse_failure = equipment_parse_failure_storage.empty()
                    ? L"equipment-active-properties-parse-failed"
                    : equipment_parse_failure_storage.c_str();
                if (!synthetic_failure.empty()) {
                  equipment_parse_failure_storage =
                      equipment_parse_failure != nullptr
                          ? std::wstring(equipment_parse_failure)
                          : L"equipment-active-properties-parse-failed";
                  equipment_parse_failure_storage += L";synth=";
                  equipment_parse_failure_storage += synthetic_failure;
                  equipment_parse_failure = equipment_parse_failure_storage.c_str();
                }
                equipment_failure_offset = active_cursor_snapshot;
                break;
              }

              const size_t skipped_active_bytes =
                  resume_cursor > active_cursor_snapshot
                      ? resume_cursor - active_cursor_snapshot
                      : 0;
              equipment_cursor = resume_cursor;
              local_inserted += synthetic_active_bytes;
              local_active_property_bits_inserted += synthetic_active_bits;
              ++active_properties_synthesized;
              active_properties_synthetic_bytes += synthetic_active_bytes;
              active_properties_synthetic_skipped_bytes +=
                  static_cast<uint32_t>(
                      std::min<size_t>(skipped_active_bytes, UINT32_MAX));
              ++parsed_equipment_appearances;
              wchar_t note_prefix[160]{};
              swprintf_s(
                  note_prefix,
                  L"active=synth bytes=%u skipped=%u",
                  synthetic_active_bytes,
                  static_cast<unsigned int>(
                      std::min<size_t>(skipped_active_bytes, UINT32_MAX)));
              std::wstring note(note_prefix);
              if (!active_failure.empty()) {
                note += L" reason=";
                note += active_failure;
              }
              append_equipment_diagnostic(
                  index,
                  equipment_entry_offset,
                  equipment_opcode,
                  equipment_object_id,
                  equipment_field,
                  base_item_id,
                  model_type,
                  legacy_size,
                  active_cursor_snapshot,
                  equipment_cursor,
                  synthetic_active_bits,
                  active_name_preview,
                  note);
              continue;
            }
            equipment_cursor = active_properties_end;
            local_active_property_bits_inserted += active_property_bits;
            ++parsed_equipment_appearances;
            append_equipment_diagnostic(
                index,
                equipment_entry_offset,
                equipment_opcode,
                equipment_object_id,
                equipment_field,
                base_item_id,
                model_type,
                legacy_size,
                active_cursor_snapshot,
                equipment_cursor,
                active_property_bits,
                active_name_preview,
                L"active=parsed");
          } else if (equipment_opcode == 'D') {
            append_equipment_diagnostic(
                index,
                equipment_entry_offset,
                equipment_opcode,
                equipment_object_id,
                equipment_field,
                0,
                -1,
                0,
                equipment_cursor,
                equipment_cursor,
                0,
                {},
                L"delete");
            continue;
          } else if (equipment_opcode == 'U') {
            if (equipment_cursor >= declared_live_end) {
              equipment_parse_failure = L"equipment-U-state-short";
              equipment_failure_offset = equipment_cursor;
              break;
            }
            equipment_bytes.push_back(bytes[equipment_cursor++]);
            append_equipment_diagnostic(
                index,
                equipment_entry_offset,
                equipment_opcode,
                equipment_object_id,
                equipment_field,
                0,
                -1,
                0,
                equipment_cursor >= 1 ? equipment_cursor - 1 : equipment_cursor,
                equipment_cursor,
                0,
                {},
                L"update");
            continue;
          } else {
            // Equipment update subrecords can carry a feature-gated visual
            // transform map in EE. If this lives beyond the legacy declared
            // read buffer, keep the cursor aligned by saying "no equipment"
            // for now and leave the original bytes in the CNW fragment tail.
            equipment_parse_failure = L"equipment-opcode-unsupported";
            equipment_failure_offset = equipment_entry_offset;
            equipment_failure_opcode = equipment_opcode;
            equipment_failure_has_opcode = true;
            break;
          }
        }
      }

      if (equipment_parse_failure != nullptr) {
        local_inserted = inserted_before_equipment;
        local_equipment_appearance_bytes_inserted = equipment_app_inserted_before;
        local_active_property_bits_inserted = active_bits_inserted_before;
        if (had_equipment_fragment_snapshot && record_fragment_bits != nullptr) {
          *record_fragment_bits = std::move(equipment_fragment_bits_snapshot);
          working_bit_cursor = equipment_bit_cursor_snapshot;
        }
        if (equipment_failure_offset == SIZE_MAX) {
          equipment_failure_offset = std::min(equipment_cursor, bytes.size());
        }
      }
      if (equipment_parse_failure == nullptr) {
        rewritten_record->insert(
            rewritten_record->end(),
            equipment_bytes.begin(),
            equipment_bytes.end());
        cursor = equipment_cursor;
        local_equipment_items += parsed_equipment_items;
        local_equipment_appearances += parsed_equipment_appearances;
      } else if (!synthesize_empty_equipment_count(equipment_parse_failure)) {
        const size_t fallback_end =
            std::min(
                FindNextLegacyLiveObjectSubMessageBoundaryAfter(bytes, record_offset),
                declared_live_end);
        if (fallback_end <= cursor || fallback_end > bytes.size()) {
          return false;
        }
        rewritten_record->insert(
            rewritten_record->end(),
            bytes.begin() + static_cast<std::ptrdiff_t>(cursor),
            bytes.begin() + static_cast<std::ptrdiff_t>(fallback_end));
        cursor = fallback_end;
        equipment_tail_copied_raw = true;
        partial_reason = equipment_parse_failure;
      }
    }
  }

  const size_t logical_old_end = cursor;
  const size_t old_end = std::min(cursor, declared_live_end);
  if (local_inserted == 0 &&
      local_promoted == 0 &&
      local_removed == 0 &&
      local_active_property_bits_inserted == 0 &&
      local_name_mode_bits_rewritten == 0) {
    return fail(L"no-insertion-or-promotion");
  }

  if (old_record_end != nullptr) {
    *old_record_end = old_end;
  }
  if (promoted_bytes != nullptr) {
    *promoted_bytes = local_promoted;
  }
  if (inserted_bytes != nullptr) {
    *inserted_bytes = local_inserted;
  }
  if (removed_bytes != nullptr) {
    *removed_bytes = local_removed;
  }
  if (equipment_items_seen != nullptr) {
    *equipment_items_seen = local_equipment_items;
  }
  if (equipment_item_appearances_seen != nullptr) {
    *equipment_item_appearances_seen = local_equipment_appearances;
  }
  if (active_property_bits_inserted != nullptr) {
    *active_property_bits_inserted = local_active_property_bits_inserted;
  }
  if (name_mode_bits_rewritten != nullptr) {
    *name_mode_bits_rewritten = local_name_mode_bits_rewritten;
  }
  if (fragment_bits != nullptr && bit_cursor != nullptr && record_fragment_bits != nullptr) {
    *fragment_bits = std::move(working_fragment_bits);
    *bit_cursor = working_bit_cursor;
  }
  if (detail != nullptr) {
    wchar_t text[512]{};
    swprintf_s(
        text,
        L"P+%zu id=0x%08X flags=0x%04X name_len=%u legacy_end=%zu promoted=%u inserted=%u removed=%u equip=%u equip_appear=%u active_bits=%u name_bits=%u name='%s'",
        record_offset,
        object_id,
        flags,
        name_length,
        logical_old_end,
        local_promoted,
        local_inserted,
        local_removed,
        local_equipment_items,
        local_equipment_appearances,
        local_active_property_bits_inserted,
        local_name_mode_bits_rewritten,
        AsciiPreviewToWide(name_preview, 80).c_str());
    *detail = text;
    if (used_double_inline_name) {
      wchar_t name_text[64]{};
      swprintf_s(
          name_text,
          used_missing_second_name_length
              ? L" name_branch=double-inline-missing-length name2_len=%u"
              : L" name_branch=double-inline name2_len=%u",
          second_name_length);
      *detail += name_text;
    } else if (used_single_inline_name) {
      *detail += L" name_branch=single-inline";
    }
    if (repaired_outer_name_mode_to_double) {
      *detail += L" name_outer=repaired-double";
    } else if (repaired_outer_name_mode_to_single) {
      *detail += L" name_outer=repaired-single";
    }
    if (logical_old_end != old_end) {
      wchar_t logical_text[96]{};
      swprintf_s(
          logical_text,
          L" readbuf_end=%zu promoted_bits_erased=%u",
          old_end,
          local_promoted_bits_erased);
      *detail += logical_text;
    }
    if (local_equipment_appearance_bytes_inserted != 0) {
      wchar_t appearance_text[64]{};
      swprintf_s(
          appearance_text,
          L" equip_app_inserted=%u",
          local_equipment_appearance_bytes_inserted);
      *detail += appearance_text;
    }
    if (equipment_count_synthesized_zero) {
      *detail += L" partial=";
      *detail += partial_reason.empty() ? L"equipment-count-synthesized" : partial_reason;
    }
    if (promoted_equipment_copied) {
      *detail += L" promoted_equipment=copied";
    }
    if (promoted_active_properties_synthesized != 0) {
      wchar_t synth_text[64]{};
      swprintf_s(
          synth_text,
          L" promoted_active_synth=%u",
          promoted_active_properties_synthesized);
      *detail += synth_text;
    }
    if (promoted_active_properties_compact_bytes_dropped != 0) {
      wchar_t drop_text[80]{};
      swprintf_s(
          drop_text,
          L" promoted_active_drop=%u",
          promoted_active_properties_compact_bytes_dropped);
      *detail += drop_text;
    }
    if (active_properties_synthesized != 0) {
      wchar_t synth_text[128]{};
      swprintf_s(
          synth_text,
          L" active_synth=%u active_synth_bytes=%u active_synth_skipped=%u",
          active_properties_synthesized,
          active_properties_synthetic_bytes,
          active_properties_synthetic_skipped_bytes);
      *detail += synth_text;
    }
    if (equipment_tail_copied_raw) {
      *detail += L" raw_equipment_tail=";
      *detail += partial_reason.empty() ? L"preserved" : partial_reason;
    }
    if (equipment_failure_offset != SIZE_MAX) {
      wchar_t failure_text[96]{};
      const size_t failure_rel =
          equipment_failure_offset >= record_offset
              ? equipment_failure_offset - record_offset
              : 0;
      if (equipment_failure_has_opcode) {
        swprintf_s(
            failure_text,
            L" equip_fail_rel=%zu op=0x%02X",
            failure_rel,
            static_cast<unsigned int>(equipment_failure_opcode));
      } else {
        swprintf_s(failure_text, L" equip_fail_rel=%zu", failure_rel);
      }
      *detail += failure_text;
    }
    if (used_alternate_2000_before_parts_order) {
      *detail += L" order=2000-before-parts";
    }
    if (used_prefixed_full_part_table) {
      *detail += L" parts=prefixed-full19";
    }
    if (used_zero_prefixed_full_part_table) {
      *detail += L" parts=zero-prefixed-full19";
    }
    if (used_aligned_short_zero_prefixed_full_part_table) {
      *detail += L" parts=aligned-short-zero-prefixed-full19";
    }
    if (skipped_feature0e_field) {
      *detail += L" feature0e=legacy-skip";
    }
  }
  if (should_log_detailed_creature_p) {
    const size_t raw_readbuffer_end = std::min(old_end, bytes.size());
    const size_t raw_readbuffer_len =
        raw_readbuffer_end > record_offset ? raw_readbuffer_end - record_offset : 0;
    const size_t next_boundary =
        std::min(FindNextLegacyLiveObjectSubMessageBoundaryAfter(bytes, record_offset), bytes.size());
    const size_t apparent_record_len =
        next_boundary > record_offset ? next_boundary - record_offset : raw_readbuffer_len;
    LogFormat(
        L"server->client live creature-P detailed rewrite: rec=%zu id=0x%08X flags=0x%04X declared_live_end=%zu old_end=%zu logical_old_end=%zu apparent_len=%zu rewritten_len=%zu bit_cursor=%zu->%zu fragment_bits=%zu->%zu inserted=%u removed=%u promoted=%u promoted_bits_erased=%u name_bits=%u equip=%u equip_appear=%u equip_diag=[%s] raw_readbuf=[%s] raw_apparent=[%s] rewritten=[%s]",
        record_offset,
        object_id,
        flags,
        declared_live_end,
        old_end,
        logical_old_end,
        apparent_record_len,
        rewritten_record->size(),
        initial_bit_cursor,
        working_bit_cursor,
        initial_fragment_bit_count,
        record_fragment_bits != nullptr ? record_fragment_bits->size() : 0,
        local_inserted,
        local_removed,
        local_promoted,
        local_promoted_bits_erased,
        local_name_mode_bits_rewritten,
        local_equipment_items,
        local_equipment_appearances,
        equipment_diagnostics.empty() ? L"<none>" : equipment_diagnostics.c_str(),
        raw_readbuffer_len != 0
            ? FormatLimitedBytes(
                  bytes.data() + record_offset,
                  raw_readbuffer_len,
                  std::min<size_t>(raw_readbuffer_len, 768)).c_str()
            : L"<empty>",
        apparent_record_len != 0
            ? FormatLimitedBytes(
                  bytes.data() + record_offset,
                  apparent_record_len,
                  std::min<size_t>(apparent_record_len, 768)).c_str()
            : L"<empty>",
        rewritten_record->empty()
            ? L"<empty>"
            : FormatLimitedBytes(
                  rewritten_record->data(),
                  rewritten_record->size(),
                  std::min<size_t>(rewritten_record->size(), 768)).c_str());
  }
  return true;
}

bool LooksLikeLegacyInlineLocStringTextAt(
    const std::vector<unsigned char>& bytes,
    size_t offset,
    size_t record_end) {
  if (offset > bytes.size() || record_end > bytes.size() ||
      offset + 6 > record_end || bytes[offset] > 5 || bytes[offset + 1] > 5) {
    return false;
  }

  const uint32_t length = ReadU32Le(bytes.data() + offset + 2);
  if (length == 0 || length > 512 || offset + 6 + length > record_end) {
    return false;
  }

  uint32_t printable = 0;
  const size_t text_start = offset + 6;
  const size_t text_end = text_start + length;
  for (size_t index = text_start; index < text_end; ++index) {
    const unsigned char value = bytes[index];
    if ((value >= 0x20 && value <= 0x7E) || value == '\t') {
      ++printable;
    }
  }
  return printable * 4 >= length * 3;
}

bool LooksLikeLegacyPostItemAppearanceContinuation(
    const std::vector<unsigned char>& bytes,
    size_t offset,
    size_t record_end) {
  if (offset > record_end || record_end > bytes.size()) {
    return false;
  }
  if (offset == record_end) {
    return true;
  }
  if (LooksLikeLegacyLiveObjectSubMessageBoundaryBytes(bytes, offset)) {
    return true;
  }
  if (LooksLikeInlineCExoStringAt(bytes, offset, nullptr, nullptr, nullptr)) {
    return true;
  }
  if (LooksLikeLegacyInlineLocStringTextAt(bytes, offset, record_end)) {
    return true;
  }

  // Several item-bearing records continue with compact counters/flags rather
  // than a named field. Keep this narrow so random small DWORDs are not treated
  // as armor appearances.
  return record_end - offset >= 8 &&
      bytes[offset] <= 5 &&
      bytes[offset + 1] <= 5 &&
      bytes[offset + 2] <= 0x40 &&
      bytes[offset + 3] == 0;
}

bool LooksLikeExistingEeExtendedArmorPadding(
    const std::vector<unsigned char>& bytes,
    size_t offset,
    size_t record_end) {
  if (offset > record_end || record_end > bytes.size() ||
      record_end - offset < kEeLiveExtendedArmorTableBytes) {
    return false;
  }
  for (size_t index = 0; index < kEeLiveExtendedArmorTableBytes; ++index) {
    if (bytes[offset + index] != 0) {
      return false;
    }
  }
  return LooksLikeLegacyPostItemAppearanceContinuation(
      bytes,
      offset + kEeLiveExtendedArmorTableBytes,
      record_end);
}

bool HasEeExtendedArmorPaddingBytesAt(
    const std::vector<unsigned char>& bytes,
    size_t offset,
    size_t record_end) {
  if (offset > record_end || record_end > bytes.size() ||
      record_end - offset < kEeLiveExtendedArmorTableBytes) {
    return false;
  }
  for (size_t index = 0; index < kEeLiveExtendedArmorTableBytes; ++index) {
    if (bytes[offset + index] != 0) {
      return false;
    }
  }
  return true;
}

bool HasEeIdentityVisualTransformMapBytesAt(
    const std::vector<unsigned char>& bytes,
    size_t offset,
    size_t record_end) {
  if (offset > record_end || record_end > bytes.size() ||
      record_end - offset < kEeLiveVisualTransformEmptyMapBytes) {
    return false;
  }
  for (size_t index = 0; index < kEeLiveVisualTransformEmptyMapBytes; ++index) {
    if (bytes[offset + index] != kEeLiveVisualTransformIdentityMapBytes[index]) {
      return false;
    }
  }
  return true;
}

bool LooksLikeExistingEeIdentityVisualTransformMap(
    const std::vector<unsigned char>& bytes,
    size_t offset,
    size_t record_end) {
  if (!HasEeIdentityVisualTransformMapBytesAt(bytes, offset, record_end)) {
    return false;
  }
  return LooksLikeLegacyPostItemAppearanceContinuation(
      bytes,
      offset + kEeLiveVisualTransformEmptyMapBytes,
      record_end);
}

bool TrySkipExistingEeItemAppearanceExtension(
    const std::vector<unsigned char>& bytes,
    size_t continuation,
    size_t record_end,
    int model_type,
    bool append_empty_visual_transform_map,
    size_t* skip_to) {
  if (skip_to != nullptr) {
    *skip_to = continuation;
  }

  size_t cursor = continuation;
  if (model_type == 3) {
    if (!HasEeExtendedArmorPaddingBytesAt(bytes, cursor, record_end)) {
      return false;
    }
    cursor += kEeLiveExtendedArmorTableBytes;
  }

  if (append_empty_visual_transform_map) {
    if (!HasEeIdentityVisualTransformMapBytesAt(bytes, cursor, record_end)) {
      return false;
    }
    cursor += kEeLiveVisualTransformEmptyMapBytes;
  }

  if (cursor == continuation ||
      !LooksLikeLegacyPostItemAppearanceContinuation(bytes, cursor, record_end)) {
    return false;
  }
  if (skip_to != nullptr) {
    *skip_to = cursor;
  }
  return true;
}

void AppendLiveItemAppearanceRewriteDetail(
    LiveItemAppearanceRewriteResult* result,
    size_t record_offset,
    size_t appearance_offset,
    uint32_t base_item_id,
    int model_type,
    uint32_t visual_transform_maps_inserted,
    uint32_t feature25_zero_counts_inserted,
    uint32_t bytes_inserted,
    const wchar_t* context = nullptr) {
  if (result == nullptr || result->details.size() > 1800) {
    return;
  }

  wchar_t text[384]{};
  swprintf_s(
      text,
      L"%s%srec+%zu item+%zu base=%u model=%d inserted=%u",
      result->details.empty() ? L"" : L"; ",
      context != nullptr ? context : L"",
      record_offset,
      appearance_offset - record_offset,
      base_item_id,
      model_type,
      bytes_inserted);
  result->details += text;
  if (visual_transform_maps_inserted != 0) {
    wchar_t visual_text[64]{};
    swprintf_s(visual_text, L" visual_maps=%u", visual_transform_maps_inserted);
    result->details += visual_text;
  }
  if (feature25_zero_counts_inserted != 0) {
    wchar_t feature_text[64]{};
    swprintf_s(feature_text, L" feature25_zero_counts=%u", feature25_zero_counts_inserted);
    result->details += feature_text;
  }
}

bool LooksLikeLegacyCreatureEquipmentAppearanceHeaderAt(
    const std::vector<unsigned char>& bytes,
    size_t record_offset,
    size_t record_end,
    size_t header_offset) {
  if (record_offset > bytes.size() ||
      record_end > bytes.size() ||
      header_offset < record_offset + 10 ||
      header_offset > record_end ||
      record_end - header_offset < 13 ||
      bytes[header_offset] != 'A') {
    return false;
  }

  uint32_t equipment_object_id = 0;
  if (!TryReadU32LeFromBytes(bytes, header_offset + 1, &equipment_object_id)) {
    return false;
  }
  const uint32_t equipment_high_byte = equipment_object_id & 0xFF000000u;
  if (!LooksLikeLegacyLiveObjectIdValue(equipment_object_id) &&
      equipment_high_byte != 0x7F000000u) {
    return false;
  }

  const uint32_t equipment_field = ReadU32Le(bytes.data() + header_offset + 5);
  // This field is the compact equipment slot/state value seen immediately
  // before AddItemAppearanceToMessage in the 1.69 creature P reader. Keep the
  // range broad, but reject obviously shifted string/float payloads.
  return equipment_field < 0x00010000u;
}

bool RewriteLegacyCreaturePEmbeddedItemAppearances(
    BridgeRuntime* runtime,
    std::vector<unsigned char>* live_bytes,
    size_t record_offset,
    size_t* record_end,
    LiveItemAppearanceRewriteResult* result) {
  if (runtime == nullptr || live_bytes == nullptr || record_end == nullptr ||
      record_offset > live_bytes->size() ||
      *record_end > live_bytes->size() ||
      *record_end <= record_offset ||
      *record_end - record_offset < 10 ||
      (*live_bytes)[record_offset] != 'P' ||
      (*live_bytes)[record_offset + 1] != 5 ||
      !LooksLikeLegacyLiveObjectIdAt(*live_bytes, record_offset + 2)) {
    return false;
  }

  uint16_t legacy_flags = 0;
  if (!TryReadU16LeFromBytes(*live_bytes, record_offset + 6, &legacy_flags) ||
      (legacy_flags & 0x0200u) == 0) {
    return false;
  }

  const bool append_empty_visual_transform_map =
      runtime->options.rewrite_live_object_item_appearance_visual_transforms;
  const bool expand_word_parts =
      runtime->options.rewrite_live_object_item_appearance_word_parts;

  bool rewritten = false;
  for (size_t header = record_offset + 10; header + 13 <= *record_end;) {
    if (!LooksLikeLegacyCreatureEquipmentAppearanceHeaderAt(
            *live_bytes,
            record_offset,
            *record_end,
            header)) {
      ++header;
      continue;
    }

    const size_t appearance_offset = header + 9;
    const uint32_t base_item_id = ReadU32Le(live_bytes->data() + appearance_offset);
    const int model_type = GetBaseItemModelType(*runtime, base_item_id);
    const size_t legacy_size = LegacyItemAppearanceReadSize(model_type);
    if (legacy_size == 0 || appearance_offset > *record_end ||
        *record_end - appearance_offset < legacy_size) {
      ++header;
      continue;
    }

    const size_t continuation = appearance_offset + legacy_size;
    if (!LooksLikeLegacyPostItemAppearanceContinuation(
            *live_bytes,
            continuation,
            *record_end)) {
      ++header;
      continue;
    }

    if (result != nullptr) {
      ++result->candidates;
    }
    ++runtime->live_object_item_appearance_candidate_count;

    if (model_type != 3 && !expand_word_parts && !append_empty_visual_transform_map) {
      header = continuation;
      continue;
    }
    size_t existing_extension_end = continuation;
    if (!expand_word_parts &&
        TrySkipExistingEeItemAppearanceExtension(
            *live_bytes,
            continuation,
            *record_end,
            model_type,
            append_empty_visual_transform_map,
            &existing_extension_end)) {
      header = existing_extension_end;
      continue;
    }

    uint32_t inserted_bytes = static_cast<uint32_t>(kEeLiveExtendedArmorTableBytes);
    if (expand_word_parts || append_empty_visual_transform_map) {
      std::vector<unsigned char> ee_appearance;
      if (!BuildEeItemAppearanceReadBufferBytes(
              *live_bytes,
              appearance_offset,
              model_type,
              expand_word_parts,
              append_empty_visual_transform_map,
              &ee_appearance)) {
        ++header;
        continue;
      }
      if (ee_appearance.size() <= legacy_size) {
        ++header;
        continue;
      }
      inserted_bytes = static_cast<uint32_t>(ee_appearance.size() - legacy_size);
      live_bytes->erase(
          live_bytes->begin() + static_cast<std::ptrdiff_t>(appearance_offset),
          live_bytes->begin() + static_cast<std::ptrdiff_t>(continuation));
      live_bytes->insert(
          live_bytes->begin() + static_cast<std::ptrdiff_t>(appearance_offset),
          ee_appearance.begin(),
          ee_appearance.end());
    } else {
      live_bytes->insert(
          live_bytes->begin() + static_cast<std::ptrdiff_t>(continuation),
          kEeLiveExtendedArmorTableBytes,
          0);
    }
    *record_end += inserted_bytes;
    rewritten = true;

    if (result != nullptr) {
      ++result->rewritten;
      if (model_type == 3) {
        ++result->extended_armor_tables_inserted;
      }
      if (expand_word_parts) {
        ++result->word_part_appearances_expanded;
      }
      if (append_empty_visual_transform_map) {
        ++result->visual_transform_maps_inserted;
      }
      result->bytes_inserted += inserted_bytes;
      AppendLiveItemAppearanceRewriteDetail(
          result,
          record_offset,
          appearance_offset,
          base_item_id,
          model_type,
          append_empty_visual_transform_map ? 1u : 0u,
          0,
          inserted_bytes,
          L"creature-P ");
    }

    header = appearance_offset + legacy_size + inserted_bytes;
  }

  return rewritten;
}

bool LegacyLiveItemRecordRequestsFeature25ZeroCount(
    const std::vector<unsigned char>& bytes,
    size_t record_offset,
    size_t record_end) {
  if (record_offset > bytes.size() || record_end > bytes.size() ||
      record_end - record_offset < 7 ||
      bytes[record_offset] != 'I') {
    return false;
  }

  if (bytes[record_offset + 1] == 0xFD &&
      bytes[record_offset + 2] == 0xFF &&
      bytes[record_offset + 3] == 0xFF &&
      bytes[record_offset + 4] == 0xFF) {
    const uint16_t legacy_flags = ReadU16Le(bytes.data() + record_offset + 5);
    return (legacy_flags & 0x2000u) != 0;
  }

  return false;
}

bool LooksLikeExistingFeature25ZeroCount(
    const std::vector<unsigned char>& bytes,
    size_t offset,
    size_t record_end) {
  if (offset > record_end || record_end > bytes.size() ||
      record_end - offset < 4 ||
      ReadU32Le(bytes.data() + offset) != 0) {
    return false;
  }
  return LooksLikeLegacyPostItemAppearanceContinuation(bytes, offset + 4, record_end);
}

bool TryGetLegacyLiveItemAppearanceScanWindow(
    const std::vector<unsigned char>& bytes,
    size_t offset,
    size_t record_end,
    size_t* scan_start,
    size_t* scan_end) {
  if (scan_start != nullptr) {
    *scan_start = 0;
  }
  if (scan_end != nullptr) {
    *scan_end = 0;
  }
  if (offset > bytes.size() || record_end > bytes.size() ||
      record_end <= offset || record_end - offset < 2) {
    return false;
  }

  const unsigned char opcode = bytes[offset];
  const unsigned char marker = bytes[offset + 1];
  size_t appearance_offset = SIZE_MAX;
  if (opcode == 'A' && marker == 6 && LooksLikeLegacyLiveObjectIdAt(bytes, offset + 2)) {
    // EE's CreateNewLastUpdateObject writes item add records as:
    // 'A', object type 6, object id, then AddItemAppearanceToMessage.
    appearance_offset = offset + 6;
  } else if (opcode == 'I' &&
      record_end - offset >= 7 &&
      marker == 0xFD &&
      bytes[offset + 2] == 0xFF &&
      bytes[offset + 3] == 0xFF &&
      bytes[offset + 4] == 0xFF) {
    // Legacy inventory/equipment item records seen from HG carry a
    // four-byte -3 sentinel followed by two compact flags before the
    // AddItemAppearanceToMessage payload.
    const uint16_t legacy_flags = ReadU16Le(bytes.data() + offset + 5);
    if (legacy_flags == 0x2000u ||
        (legacy_flags & (0x0200u | 0x0800u)) != 0) {
      // Self-inventory state masks that carry the 0x0200, 0x0800, or exact
      // 0x2000 branches are not item appearances. Treating their branch data
      // as a base item id corrupts EE's inventory reader and fragment cursor.
      return false;
    }
    appearance_offset = offset + 7;
  } else if (opcode == 'I' && LooksLikeLegacyLiveObjectIdAt(bytes, offset + 1)) {
    appearance_offset = offset + 5;
  } else {
    return false;
  }

  if (appearance_offset > record_end || record_end - appearance_offset < 4) {
    return false;
  }
  if (scan_start != nullptr) {
    *scan_start = appearance_offset;
  }
  if (scan_end != nullptr) {
    // Only the decompile-backed start of the item appearance is eligible.
    // Scanning whole door/placeable/creature records produced false
    // base-item matches and corrupted live-object alignment.
    *scan_end = appearance_offset + 4;
  }
  return true;
}

bool RewriteLegacyLiveItemAppearanceRecords(
    BridgeRuntime* runtime,
    std::vector<unsigned char>* live_bytes,
    LiveItemAppearanceRewriteResult* result) {
  if (result != nullptr) {
    result->records_examined = 0;
    result->candidates = 0;
    result->rewritten = 0;
    result->extended_armor_tables_inserted = 0;
    result->word_part_appearances_expanded = 0;
    result->visual_transform_maps_inserted = 0;
    result->feature25_zero_counts_inserted = 0;
    result->bytes_inserted = 0;
    result->details.clear();
  }
  if (runtime == nullptr || live_bytes == nullptr ||
      live_bytes->size() < 10 || runtime->base_item_model_types.empty()) {
    return false;
  }

  bool rewritten = false;
  for (size_t offset = 0; offset + 10 <= live_bytes->size();) {
    if (!LooksLikeLegacyLiveObjectSubMessageBoundaryBytes(*live_bytes, offset)) {
      ++offset;
      continue;
    }

    if (result != nullptr) {
      ++result->records_examined;
    }

    size_t record_end = FindNextLegacyLiveObjectSubMessageBoundaryAfter(*live_bytes, offset);
    if (record_end > live_bytes->size()) {
      record_end = live_bytes->size();
    }

    if ((*live_bytes)[offset] == 'P' && (*live_bytes)[offset + 1] == 5) {
      // Creature P equipment is parsed and rewritten by the creature-P feature
      // pass. A generic byte scan inside the same record can find already
      // expanded equipment appearances and duplicate the EE padding.
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }

    size_t scan_start = 0;
    size_t scan_end = 0;
    if (!TryGetLegacyLiveItemAppearanceScanWindow(
            *live_bytes,
            offset,
            record_end,
            &scan_start,
            &scan_end)) {
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }

    for (size_t cursor = scan_start; cursor + 4 <= scan_end;) {
      const uint32_t base_item_id = ReadU32Le(live_bytes->data() + cursor);
      const int model_type = GetBaseItemModelType(*runtime, base_item_id);
      const size_t legacy_size = LegacyItemAppearanceReadSize(model_type);
      if (legacy_size == 0 || cursor + legacy_size > record_end) {
        ++cursor;
        continue;
      }

      const size_t continuation = cursor + legacy_size;
      if (!LooksLikeLegacyPostItemAppearanceContinuation(*live_bytes, continuation, record_end)) {
        ++cursor;
        continue;
      }

      uint16_t legacy_item_feature_flags = 0;
      const bool legacy_item_sentinel =
          offset + 7 <= record_end &&
          offset + 7 <= live_bytes->size() &&
          (*live_bytes)[offset] == 'I' &&
          (*live_bytes)[offset + 1] == 0xFD &&
          (*live_bytes)[offset + 2] == 0xFF &&
          (*live_bytes)[offset + 3] == 0xFF &&
          (*live_bytes)[offset + 4] == 0xFF;
      if (legacy_item_sentinel) {
        legacy_item_feature_flags = ReadU16Le(live_bytes->data() + offset + 5);
      }
      const bool needs_feature25_zero_count =
          legacy_item_sentinel &&
          ((legacy_item_feature_flags & 0x2000u) != 0 ||
           (legacy_item_feature_flags & 0x0020u) != 0);

      if (result != nullptr) {
        ++result->candidates;
      }
      ++runtime->live_object_item_appearance_candidate_count;

      const bool append_empty_visual_transform_map =
          runtime->options.rewrite_live_object_item_appearance_visual_transforms;
      const bool expand_word_parts =
          runtime->options.rewrite_live_object_item_appearance_word_parts;

      if (model_type != 3 && !expand_word_parts && !append_empty_visual_transform_map) {
        cursor = continuation;
        continue;
      }
      size_t existing_extension_end = continuation;
      if (!expand_word_parts &&
          TrySkipExistingEeItemAppearanceExtension(
              *live_bytes,
              continuation,
              record_end,
              model_type,
              append_empty_visual_transform_map,
              &existing_extension_end)) {
        cursor = existing_extension_end;
        continue;
      }

      uint32_t inserted_bytes = static_cast<uint32_t>(kEeLiveExtendedArmorTableBytes);
      if (expand_word_parts || append_empty_visual_transform_map) {
        std::vector<unsigned char> ee_appearance;
        if (!BuildEeItemAppearanceReadBufferBytes(
                *live_bytes,
                cursor,
                model_type,
                expand_word_parts,
                append_empty_visual_transform_map,
                &ee_appearance)) {
          ++cursor;
          continue;
        }
        if (ee_appearance.size() <= legacy_size) {
          ++cursor;
          continue;
        }
        inserted_bytes = static_cast<uint32_t>(ee_appearance.size() - legacy_size);
        live_bytes->erase(
            live_bytes->begin() + static_cast<std::ptrdiff_t>(cursor),
            live_bytes->begin() + static_cast<std::ptrdiff_t>(continuation));
        live_bytes->insert(
            live_bytes->begin() + static_cast<std::ptrdiff_t>(cursor),
            ee_appearance.begin(),
            ee_appearance.end());
      } else {
        live_bytes->insert(
            live_bytes->begin() + static_cast<std::ptrdiff_t>(continuation),
            kEeLiveExtendedArmorTableBytes,
            0);
      }
      record_end += inserted_bytes;

      uint32_t feature25_zero_counts_inserted = 0;
      const size_t ee_continuation = continuation + inserted_bytes;
      if (needs_feature25_zero_count && ee_continuation <= record_end) {
        live_bytes->insert(
            live_bytes->begin() + static_cast<std::ptrdiff_t>(ee_continuation),
            4,
            0);
        record_end += 4;
        inserted_bytes += 4;
        feature25_zero_counts_inserted = 1;
      }
      rewritten = true;

      if (result != nullptr) {
        ++result->rewritten;
        if (model_type == 3) {
          ++result->extended_armor_tables_inserted;
        }
        if (expand_word_parts) {
          ++result->word_part_appearances_expanded;
        }
        if (append_empty_visual_transform_map) {
          ++result->visual_transform_maps_inserted;
        }
        result->feature25_zero_counts_inserted += feature25_zero_counts_inserted;
        result->bytes_inserted += inserted_bytes;
        AppendLiveItemAppearanceRewriteDetail(
            result,
            offset,
            cursor,
            base_item_id,
            model_type,
            append_empty_visual_transform_map ? 1u : 0u,
            feature25_zero_counts_inserted,
            inserted_bytes);
      }

      cursor = continuation + inserted_bytes;
    }

    offset = record_end > offset ? record_end : offset + 1;
  }

  return rewritten;
}

bool TryAdvanceLegacyLiveInventoryCategoryBlock(
    const std::vector<unsigned char>& bytes,
    size_t cursor,
    size_t record_end,
    size_t category_count,
    size_t* block_end,
    uint32_t* total_first_entries,
    uint32_t* total_second_entries) {
  if (block_end != nullptr) {
    *block_end = cursor;
  }
  if (total_first_entries != nullptr) {
    *total_first_entries = 0;
  }
  if (total_second_entries != nullptr) {
    *total_second_entries = 0;
  }
  if (record_end > bytes.size() || cursor > record_end) {
    return false;
  }

  uint32_t first_total = 0;
  uint32_t second_total = 0;
  for (size_t category = 0; category < category_count; ++category) {
    if (record_end - cursor < 2) {
      return false;
    }
    const uint16_t first_count = ReadU16Le(bytes.data() + cursor);
    cursor += 2;
    if (first_count > kMaxReasonableLiveInventoryCategoryEntries) {
      return false;
    }
    const size_t first_bytes = static_cast<size_t>(first_count) * 2;
    if (first_bytes > record_end - cursor) {
      return false;
    }
    cursor += first_bytes;
    first_total += first_count;

    if (record_end - cursor < 2) {
      return false;
    }
    const uint16_t second_count = ReadU16Le(bytes.data() + cursor);
    cursor += 2;
    if (second_count > kMaxReasonableLiveInventoryCategoryEntries) {
      return false;
    }
    const size_t second_bytes = static_cast<size_t>(second_count) * 7;
    if (second_bytes > record_end - cursor) {
      return false;
    }
    cursor += second_bytes;
    second_total += second_count;
  }

  if (block_end != nullptr) {
    *block_end = cursor;
  }
  if (total_first_entries != nullptr) {
    *total_first_entries = first_total;
  }
  if (total_second_entries != nullptr) {
    *total_second_entries = second_total;
  }
  return true;
}

bool TryAdvanceLegacyLiveInventoryLegacyIconListBlock(
    const std::vector<unsigned char>& bytes,
    size_t cursor,
    size_t record_end,
    size_t* block_end,
    uint32_t* first_entries,
    uint32_t* second_entries,
    uint32_t* fragment_bits) {
  if (block_end != nullptr) {
    *block_end = cursor;
  }
  if (first_entries != nullptr) {
    *first_entries = 0;
  }
  if (second_entries != nullptr) {
    *second_entries = 0;
  }
  if (fragment_bits != nullptr) {
    *fragment_bits = 0;
  }
  if (record_end > bytes.size() || cursor > record_end ||
      record_end - cursor < 2) {
    return false;
  }

  const uint16_t first_count = ReadU16Le(bytes.data() + cursor);
  cursor += 2;
  if (first_count > kMaxReasonableLiveInventoryCategoryEntries) {
    return false;
  }

  // Diamond and EE both use the read buffer for width-8 CHAR/BYTE reads here.
  // The old Diamond overflow helper after each tuple does not consume bits.
  const size_t first_bytes = static_cast<size_t>(first_count) * 3;
  if (first_bytes > record_end - cursor) {
    return false;
  }
  cursor += first_bytes;

  if (record_end - cursor < 2) {
    return false;
  }
  const uint16_t second_count = ReadU16Le(bytes.data() + cursor);
  cursor += 2;
  if (second_count > kMaxReasonableLiveInventoryCategoryEntries) {
    return false;
  }

  // The second legacy list uses read-buffer WORD + BYTE tuples.
  const size_t second_bytes = static_cast<size_t>(second_count) * 3;
  if (second_bytes > record_end - cursor) {
    return false;
  }
  cursor += second_bytes;

  if (block_end != nullptr) {
    *block_end = cursor;
  }
  if (first_entries != nullptr) {
    *first_entries = first_count;
  }
  if (second_entries != nullptr) {
    *second_entries = second_count;
  }
  if (fragment_bits != nullptr) {
    *fragment_bits = 0;
  }
  return true;
}

bool TryAdvanceLegacyLiveInventorySimpleCategoryBlock(
    const std::vector<unsigned char>& bytes,
    size_t cursor,
    size_t record_end,
    size_t category_count,
    size_t* block_end,
    uint32_t* total_first_entries,
    uint32_t* total_second_entries) {
  if (block_end != nullptr) {
    *block_end = cursor;
  }
  if (total_first_entries != nullptr) {
    *total_first_entries = 0;
  }
  if (total_second_entries != nullptr) {
    *total_second_entries = 0;
  }
  if (record_end > bytes.size() || cursor > record_end) {
    return false;
  }

  uint32_t first_total = 0;
  uint32_t second_total = 0;
  for (size_t category = 0; category < category_count; ++category) {
    if (record_end - cursor < 2) {
      return false;
    }
    const uint16_t first_count = ReadU16Le(bytes.data() + cursor);
    cursor += 2;
    if (first_count > kMaxReasonableLiveInventoryCategoryEntries) {
      return false;
    }
    const size_t first_bytes = static_cast<size_t>(first_count) * 4;
    if (first_bytes > record_end - cursor) {
      return false;
    }
    cursor += first_bytes;
    first_total += first_count;

    if (record_end - cursor < 2) {
      return false;
    }
    const uint16_t second_count = ReadU16Le(bytes.data() + cursor);
    cursor += 2;
    if (second_count > kMaxReasonableLiveInventoryCategoryEntries) {
      return false;
    }
    const size_t second_bytes = static_cast<size_t>(second_count) * 4;
    if (second_bytes > record_end - cursor) {
      return false;
    }
    cursor += second_bytes;
    second_total += second_count;
  }

  if (block_end != nullptr) {
    *block_end = cursor;
  }
  if (total_first_entries != nullptr) {
    *total_first_entries = first_total;
  }
  if (total_second_entries != nullptr) {
    *total_second_entries = second_total;
  }
  return true;
}

struct LegacyLiveInventoryCategoryScanResult {
  size_t simple_start = SIZE_MAX;
  size_t simple_end = SIZE_MAX;
  size_t rich_start = SIZE_MAX;
  size_t rich_end = SIZE_MAX;
  uint32_t simple_first_entries = 0;
  uint32_t simple_second_entries = 0;
  uint32_t rich_first_entries = 0;
  uint32_t rich_second_entries = 0;
  uint32_t followup_groups = 0;
  uint32_t followup_values = 0;
};

uint32_t CountLowTenBits(uint16_t value) {
  value &= 0x03FFu;
  uint32_t count = 0;
  while (value != 0) {
    count += value & 1u;
    value >>= 1;
  }
  return count;
}

bool TryAdvanceLegacyLiveInventoryTenBitValueGroups(
    const std::vector<unsigned char>& bytes,
    size_t cursor,
    size_t record_end,
    size_t* block_end,
    uint32_t* total_groups,
    uint32_t* total_values) {
  if (block_end != nullptr) {
    *block_end = cursor;
  }
  if (total_groups != nullptr) {
    *total_groups = 0;
  }
  if (total_values != nullptr) {
    *total_values = 0;
  }
  if (record_end > bytes.size() || cursor >= record_end) {
    return false;
  }

  const uint8_t group_count = bytes[cursor++];
  if (group_count > kMaxReasonableLiveInventoryValueGroups) {
    return false;
  }

  uint32_t value_count = 0;
  for (uint8_t group = 0; group < group_count; ++group) {
    if (record_end - cursor < 3) {
      return false;
    }
    ++cursor;
    const uint16_t mask = ReadU16Le(bytes.data() + cursor);
    cursor += 2;
    if ((mask & ~0x03FFu) != 0) {
      return false;
    }
    const uint32_t set_bits = CountLowTenBits(mask);
    if (set_bits > record_end - cursor) {
      return false;
    }
    cursor += set_bits;
    value_count += set_bits;
  }

  if (block_end != nullptr) {
    *block_end = cursor;
  }
  if (total_groups != nullptr) {
    *total_groups = group_count;
  }
  if (total_values != nullptr) {
    *total_values = value_count;
  }
  return true;
}

int ScoreLegacyLiveInventoryCategoryScanMatch(
    const LegacyLiveInventoryCategoryScanResult& match) {
  const uint32_t simple_total =
      match.simple_first_entries + match.simple_second_entries;
  const uint32_t rich_total =
      match.rich_first_entries + match.rich_second_entries;
  const uint32_t total = simple_total + rich_total;

  int score = 0;
  if (rich_total != 0) {
    score += 8;
  }
  if (total >= 32) {
    score += 4;
  }
  if (simple_total == 0 && rich_total != 0) {
    score += 3;
  }
  if (match.followup_groups != 0 || match.followup_values != 0) {
    score += 6;
  }
  return score;
}

bool TryFindLegacyLiveInventoryCategoryBlocksByScan(
    const std::vector<unsigned char>& bytes,
    size_t search_start,
    size_t record_end,
    uint16_t mask,
    LegacyLiveInventoryCategoryScanResult* scan_result,
    bool* ambiguous) {
  if (scan_result != nullptr) {
    *scan_result = LegacyLiveInventoryCategoryScanResult{};
  }
  if (ambiguous != nullptr) {
    *ambiguous = false;
  }
  if (record_end > bytes.size() ||
      search_start >= record_end ||
      (mask & (kLegacyLiveInventorySimpleCategoryMask |
               kLegacyLiveInventoryRichCategoryMask)) !=
          (kLegacyLiveInventorySimpleCategoryMask |
           kLegacyLiveInventoryRichCategoryMask)) {
    return false;
  }

  bool found = false;
  int best_score = INT_MIN;
  LegacyLiveInventoryCategoryScanResult best;
  const size_t search_end = std::min(
      record_end,
      search_start + kLegacyLiveInventoryCategoryScanWindowBytes);

  for (size_t candidate = search_start; candidate < search_end; ++candidate) {
    size_t simple_end = 0;
    uint32_t simple_first = 0;
    uint32_t simple_second = 0;
    if (!TryAdvanceLegacyLiveInventorySimpleCategoryBlock(
            bytes,
            candidate,
            record_end,
            kLegacyLiveInventoryCategoryCount,
            &simple_end,
            &simple_first,
            &simple_second)) {
      continue;
    }

    size_t rich_end = 0;
    uint32_t rich_first = 0;
    uint32_t rich_second = 0;
    if (!TryAdvanceLegacyLiveInventoryCategoryBlock(
            bytes,
            simple_end,
            record_end,
            kLegacyLiveInventoryCategoryCount,
            &rich_end,
            &rich_first,
            &rich_second)) {
      continue;
    }

    const uint32_t total_entries =
        simple_first + simple_second + rich_first + rich_second;
    if (total_entries == 0) {
      continue;
    }

    uint32_t followup_groups = 0;
    uint32_t followup_values = 0;
    if ((mask & 0x0040u) != 0) {
      size_t followup_end = 0;
      if (!TryAdvanceLegacyLiveInventoryTenBitValueGroups(
              bytes,
              rich_end,
              record_end,
              &followup_end,
              &followup_groups,
              &followup_values)) {
        continue;
      }
    }

    LegacyLiveInventoryCategoryScanResult candidate_result;
    candidate_result.simple_start = candidate;
    candidate_result.simple_end = simple_end;
    candidate_result.rich_start = simple_end;
    candidate_result.rich_end = rich_end;
    candidate_result.simple_first_entries = simple_first;
    candidate_result.simple_second_entries = simple_second;
    candidate_result.rich_first_entries = rich_first;
    candidate_result.rich_second_entries = rich_second;
    candidate_result.followup_groups = followup_groups;
    candidate_result.followup_values = followup_values;

    const int score =
        ScoreLegacyLiveInventoryCategoryScanMatch(candidate_result);
    if (!found || score > best_score) {
      found = true;
      best_score = score;
      best = candidate_result;
      if (ambiguous != nullptr) {
        *ambiguous = false;
      }
    } else if (score == best_score) {
      if (ambiguous != nullptr) {
        *ambiguous = true;
      }
    }
  }

  if (!found || (ambiguous != nullptr && *ambiguous)) {
    return false;
  }
  if (scan_result != nullptr) {
    *scan_result = best;
  }
  return true;
}

bool IsLegacyLiveInventoryObjectId(uint32_t object_id) {
  return object_id == 0xFFFFFFFDu || LooksLikeLegacyLiveObjectIdValue(object_id);
}

void AppendLiveInventoryFeature23RewriteDetail(
    LiveInventoryFeature23RewriteResult* result,
    const wchar_t* block_name,
    size_t record_offset,
    uint32_t object_id,
    uint16_t mask,
    uint32_t first_entries,
    uint32_t second_entries,
    uint32_t bytes_inserted) {
  if (result == nullptr || result->details.size() > 1800) {
    return;
  }

  wchar_t text[320]{};
  swprintf_s(
      text,
      L"%s+%zu I/%s id=0x%08X mask=0x%04X first=%u second=%u inserted=%u",
      result->details.empty() ? L"" : L"; ",
      record_offset,
      block_name == nullptr ? L"?" : block_name,
      object_id,
      mask,
      first_entries,
      second_entries,
      bytes_inserted);
  result->details += text;
}

