bool RewriteLegacyLiveInventoryFeature23CategoryBlocks(
    std::vector<unsigned char>* live_bytes,
    std::vector<unsigned char>* fragment_bytes,
    LiveInventoryFeature23RewriteResult* result) {
  if (result != nullptr) {
    result->records_examined = 0;
    result->records_candidate = 0;
    result->records_rewritten = 0;
    result->records_skipped_unsupported = 0;
    result->records_skipped_parse = 0;
    result->category_padding_inserted = 0;
    result->bytes_inserted = 0;
    result->legacy_icon_blocks_removed = 0;
    result->legacy_icon_entries_removed = 0;
    result->legacy_icon_bytes_removed = 0;
    result->legacy_icon_fragment_bits_removed = 0;
    result->legacy_icon_blocks_preserved = 0;
    result->legacy_icon_entries_preserved = 0;
    result->legacy_icon_bytes_preserved = 0;
    result->details.clear();
  }
  if (live_bytes == nullptr || live_bytes->size() < 7) {
    return false;
  }

  std::vector<unsigned char> fragment_bits;
  bool fragment_bits_changed = false;
  bool bit_cursor_reliable = false;
  size_t bit_cursor = 3;
  if (fragment_bytes != nullptr &&
      DecodeCnwFragmentBits(*fragment_bytes, &fragment_bits)) {
    bit_cursor_reliable = true;
  }

  bool rewritten = false;
  for (size_t offset = 0; offset + 7 <= live_bytes->size();) {
    if (!LooksLikeLegacyLiveObjectSubMessageBoundaryBytes(*live_bytes, offset)) {
      ++offset;
      continue;
    }

    if (result != nullptr) {
      ++result->records_examined;
    }

    size_t record_end = FindNextLegacyLiveObjectSubMessageBoundaryAfter(*live_bytes, offset);
    if (record_end > live_bytes->size()) {
      record_end = live_bytes->size();
    }

    if ((*live_bytes)[offset] != 'I' || record_end - offset < 7) {
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }

    const uint32_t object_id = ReadU32Le(live_bytes->data() + offset + 1);
    if (!IsLegacyLiveInventoryObjectId(object_id)) {
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }

    uint16_t mask = ReadU16Le(live_bytes->data() + offset + 5);
    if ((mask & (kLegacyLiveInventorySimpleCategoryMask |
                 kLegacyLiveInventoryRichCategoryMask)) == 0) {
      if (bit_cursor_reliable) {
        size_t inventory_bits = 0;
        if (TryGetLegacyLiveInventoryFragmentBitCount(
                *live_bytes,
                offset,
                record_end,
                &inventory_bits) &&
            inventory_bits <= fragment_bits.size() &&
            bit_cursor <= fragment_bits.size() - inventory_bits) {
          bit_cursor += inventory_bits;
        } else {
          bit_cursor_reliable = false;
        }
      }
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }

    if (result != nullptr) {
      ++result->records_candidate;
    }

    bool record_rewritten = false;
    size_t validated_inventory_bits = 0;
    if (!TryGetLegacyLiveInventoryFragmentBitCount(
            *live_bytes,
            offset,
            record_end,
            &validated_inventory_bits,
            false)) {
      if (result != nullptr) {
        ++result->records_skipped_parse;
        AppendLiveInventoryFeature23SkipDetail(
            result,
            L"inventory-parse",
            offset,
            object_id,
            mask);
      }
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }

    if ((mask & kLegacyLiveInventoryUnsupportedBeforeKnownCategoryMask) != 0) {
      LegacyLiveInventoryCategoryScanResult scan;
      bool scan_ambiguous = false;
      if (!TryFindLegacyLiveInventoryCategoryBlocksByScan(
              *live_bytes,
              offset + 7,
              record_end,
              mask,
              &scan,
              &scan_ambiguous)) {
        if (result != nullptr) {
          ++result->records_skipped_unsupported;
          AppendLiveInventoryFeature23SkipDetail(
              result,
              scan_ambiguous ? L"pre-category-scan-ambiguous"
                             : L"pre-category-scan",
              offset,
              object_id,
              mask);
        }
        offset = record_end > offset ? record_end : offset + 1;
        continue;
      }

      if (live_bytes->size() >
          kMaxReasonableReassembledGameplayPayload -
              (kEeLiveInventoryFeature23EmptyCategoryBytes * 2)) {
        offset = record_end > offset ? record_end : offset + 1;
        continue;
      }

      live_bytes->insert(
          live_bytes->begin() + static_cast<std::ptrdiff_t>(scan.rich_end),
          kEeLiveInventoryFeature23EmptyCategoryBytes,
          0);
      live_bytes->insert(
          live_bytes->begin() + static_cast<std::ptrdiff_t>(scan.simple_end),
          kEeLiveInventoryFeature23EmptyCategoryBytes,
          0);
      record_end += kEeLiveInventoryFeature23EmptyCategoryBytes * 2;
      rewritten = true;
      record_rewritten = true;

      if (result != nullptr) {
        result->category_padding_inserted += static_cast<uint32_t>(
            (kEeLiveInventoryFeature23CategoryCount -
             kLegacyLiveInventoryCategoryCount) *
            2);
        result->bytes_inserted += static_cast<uint32_t>(
            kEeLiveInventoryFeature23EmptyCategoryBytes * 2);
        AppendLiveInventoryFeature23RewriteDetail(
            result,
            L"scan-simple",
            offset,
            object_id,
            mask,
            scan.simple_first_entries,
            scan.simple_second_entries,
            static_cast<uint32_t>(kEeLiveInventoryFeature23EmptyCategoryBytes));
        AppendLiveInventoryFeature23RewriteDetail(
            result,
            L"scan-rich",
            offset,
            object_id,
            mask,
            scan.rich_first_entries,
            scan.rich_second_entries,
            static_cast<uint32_t>(kEeLiveInventoryFeature23EmptyCategoryBytes));
      }

      if (result != nullptr && record_rewritten) {
        ++result->records_rewritten;
      }
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }

    size_t cursor = offset + 7;
    size_t category_fragment_bits = 0;
    if ((mask & kLegacyLiveInventorySimpleCategoryMask) != 0) {
      size_t insert_offset = 0;
      uint32_t first_entries = 0;
      uint32_t second_entries = 0;
      if (!TryAdvanceLegacyLiveInventorySimpleCategoryBlock(
              *live_bytes,
              cursor,
              record_end,
              kLegacyLiveInventoryCategoryCount,
              &insert_offset,
              &first_entries,
              &second_entries)) {
        if (result != nullptr) {
          ++result->records_skipped_parse;
          AppendLiveInventoryFeature23SkipDetail(
              result,
              L"simple-parse",
              offset,
              object_id,
              mask);
        }
        offset = record_end > offset ? record_end : offset + 1;
        continue;
      }

      if (live_bytes->size() >
          kMaxReasonableReassembledGameplayPayload -
              kEeLiveInventoryFeature23EmptyCategoryBytes) {
        offset = record_end > offset ? record_end : offset + 1;
        continue;
      }

      live_bytes->insert(
          live_bytes->begin() + static_cast<std::ptrdiff_t>(insert_offset),
          kEeLiveInventoryFeature23EmptyCategoryBytes,
          0);
      record_end += kEeLiveInventoryFeature23EmptyCategoryBytes;
      cursor = insert_offset + kEeLiveInventoryFeature23EmptyCategoryBytes;
      rewritten = true;
      record_rewritten = true;

      if (result != nullptr) {
        result->category_padding_inserted += static_cast<uint32_t>(
            kEeLiveInventoryFeature23CategoryCount - kLegacyLiveInventoryCategoryCount);
        result->bytes_inserted += static_cast<uint32_t>(
            kEeLiveInventoryFeature23EmptyCategoryBytes);
        AppendLiveInventoryFeature23RewriteDetail(
            result,
            L"simple",
            offset,
            object_id,
            mask,
            first_entries,
            second_entries,
            static_cast<uint32_t>(kEeLiveInventoryFeature23EmptyCategoryBytes));
      }
    }

    if ((mask & kLegacyLiveInventoryRichCategoryMask) != 0) {
      size_t insert_offset = 0;
      uint32_t first_entries = 0;
      uint32_t second_entries = 0;
      if (!TryAdvanceLegacyLiveInventoryCategoryBlock(
              *live_bytes,
              cursor,
              record_end,
              kLegacyLiveInventoryCategoryCount,
              &insert_offset,
              &first_entries,
              &second_entries)) {
        if (result != nullptr) {
          ++result->records_skipped_parse;
          AppendLiveInventoryFeature23SkipDetail(
              result,
              L"rich-parse",
              offset,
              object_id,
              mask);
        }
        offset = record_end > offset ? record_end : offset + 1;
        continue;
      }

      category_fragment_bits += static_cast<size_t>(second_entries) * 2;

      if (live_bytes->size() >
          kMaxReasonableReassembledGameplayPayload -
              kEeLiveInventoryFeature23EmptyCategoryBytes) {
        offset = record_end > offset ? record_end : offset + 1;
        continue;
      }

      live_bytes->insert(
          live_bytes->begin() + static_cast<std::ptrdiff_t>(insert_offset),
          kEeLiveInventoryFeature23EmptyCategoryBytes,
          0);
      record_end += kEeLiveInventoryFeature23EmptyCategoryBytes;
      cursor = insert_offset + kEeLiveInventoryFeature23EmptyCategoryBytes;
      rewritten = true;
      record_rewritten = true;

      if (result != nullptr) {
        result->category_padding_inserted += static_cast<uint32_t>(
            kEeLiveInventoryFeature23CategoryCount - kLegacyLiveInventoryCategoryCount);
        result->bytes_inserted += static_cast<uint32_t>(
            kEeLiveInventoryFeature23EmptyCategoryBytes);
        AppendLiveInventoryFeature23RewriteDetail(
            result,
            L"rich",
            offset,
            object_id,
            mask,
            first_entries,
            second_entries,
            static_cast<uint32_t>(kEeLiveInventoryFeature23EmptyCategoryBytes));
      }
    }

    if ((mask & kLegacyLiveInventoryLegacyIconListMask) != 0) {
      size_t legacy_icon_end = 0;
      uint32_t legacy_icon_first_entries = 0;
      uint32_t legacy_icon_second_entries = 0;
      uint32_t legacy_icon_fragment_bits = 0;
      if (!TryAdvanceLegacyLiveInventoryLegacyIconListBlock(
              *live_bytes,
              cursor,
              record_end,
              &legacy_icon_end,
              &legacy_icon_first_entries,
              &legacy_icon_second_entries,
              &legacy_icon_fragment_bits)) {
        if (result != nullptr) {
          ++result->records_skipped_parse;
          AppendLiveInventoryFeature23SkipDetail(
              result,
              L"legacy-0004-tail-parse",
              offset,
              object_id,
              mask);
        }
        offset = record_end > offset ? record_end : offset + 1;
        continue;
      }

      if (result != nullptr) {
        ++result->legacy_icon_blocks_preserved;
        result->legacy_icon_entries_preserved +=
            legacy_icon_first_entries + legacy_icon_second_entries;
        result->legacy_icon_bytes_preserved +=
            static_cast<uint32_t>(legacy_icon_end - cursor);
        AppendLiveInventoryFeature23LegacyIconPreservedDetail(
            result,
            offset,
            object_id,
            mask,
            legacy_icon_first_entries,
            legacy_icon_second_entries,
            static_cast<uint32_t>(legacy_icon_end - cursor));
      }
      category_fragment_bits += legacy_icon_fragment_bits;
      cursor = legacy_icon_end;
    }

    if (result != nullptr && record_rewritten) {
      ++result->records_rewritten;
    }

    if (bit_cursor_reliable) {
      if (category_fragment_bits <= fragment_bits.size() &&
          bit_cursor <= fragment_bits.size() - category_fragment_bits) {
        bit_cursor += category_fragment_bits;
      } else {
        bit_cursor_reliable = false;
      }
    }

    offset = record_end > offset ? record_end : offset + 1;
  }

  if (fragment_bits_changed && fragment_bytes != nullptr) {
    RefreshCnwFragmentFinalBitHeader(&fragment_bits);
    PackCnwMsbBits(fragment_bits, fragment_bytes);
  }
  return rewritten;
}

void UnpackCnwMsbBits(
    const std::vector<unsigned char>& fragment_bytes,
    std::vector<unsigned char>* bits) {
  if (bits == nullptr) {
    return;
  }
  bits->clear();
  bits->reserve(fragment_bytes.size() * 8);
  for (unsigned char byte : fragment_bytes) {
    for (uint8_t bit = 0; bit < 8; ++bit) {
      bits->push_back((byte & (1u << (7 - bit))) != 0 ? 1 : 0);
    }
  }
}

bool DecodeCnwFragmentBits(
    const std::vector<unsigned char>& fragment_bytes,
    std::vector<unsigned char>* bits) {
  if (bits == nullptr) {
    return false;
  }
  bits->clear();
  if (fragment_bytes.empty()) {
    bits->assign(3, 0);
    return true;
  }

  UnpackCnwMsbBits(fragment_bytes, bits);
  if (bits->size() < 3) {
    return false;
  }
  const uint32_t final_fragment_bits =
      ((fragment_bytes[0] & 0x80u) != 0 ? 4u : 0u) |
      ((fragment_bytes[0] & 0x40u) != 0 ? 2u : 0u) |
      ((fragment_bytes[0] & 0x20u) != 0 ? 1u : 0u);
  const size_t meaningful_bits = final_fragment_bits == 0
      ? fragment_bytes.size() * 8
      : (fragment_bytes.size() - 1) * 8 + static_cast<size_t>(final_fragment_bits);
  if (meaningful_bits < 3 || meaningful_bits > bits->size()) {
    return false;
  }
  bits->resize(meaningful_bits);
  return true;
}

void RefreshCnwFragmentFinalBitHeader(std::vector<unsigned char>* bits) {
  if (bits == nullptr) {
    return;
  }
  if (bits->size() < 3) {
    bits->resize(3, 0);
  }
  const uint8_t final_fragment_bits = static_cast<uint8_t>(bits->size() % 8u);
  (*bits)[0] = (final_fragment_bits & 0x04u) != 0 ? 1 : 0;
  (*bits)[1] = (final_fragment_bits & 0x02u) != 0 ? 1 : 0;
  (*bits)[2] = (final_fragment_bits & 0x01u) != 0 ? 1 : 0;
}

void PackCnwMsbBits(
    const std::vector<unsigned char>& bits,
    std::vector<unsigned char>* fragment_bytes) {
  if (fragment_bytes == nullptr) {
    return;
  }
  fragment_bytes->assign((bits.size() + 7) / 8, 0);
  for (size_t index = 0; index < bits.size(); ++index) {
    if (bits[index] == 0) {
      continue;
    }
    (*fragment_bytes)[index / 8] |= static_cast<unsigned char>(1u << (7 - (index % 8)));
  }
}

bool SetCnwMsbBit(
    std::vector<unsigned char>* bits,
    size_t bit_index,
    bool value,
    bool* extended_or_changed) {
  if (extended_or_changed != nullptr) {
    *extended_or_changed = false;
  }
  if (bits == nullptr || bit_index > kMaxReasonableReassembledGameplayPayload * 8ull) {
    return false;
  }
  if (bit_index >= bits->size()) {
    bits->resize(bit_index + 1, 0);
    if (extended_or_changed != nullptr) {
      *extended_or_changed = true;
    }
  }
  const unsigned char new_value = value ? 1 : 0;
  if ((*bits)[bit_index] != new_value) {
    (*bits)[bit_index] = new_value;
    if (extended_or_changed != nullptr) {
      *extended_or_changed = true;
    }
  }
  return true;
}

bool InsertCnwMsbBit(std::vector<unsigned char>* bits, size_t bit_index, bool value) {
  if (bits == nullptr || bit_index > kMaxReasonableReassembledGameplayPayload * 8ull) {
    return false;
  }
  if (bit_index > bits->size()) {
    bits->resize(bit_index, 0);
  }
  bits->insert(bits->begin() + static_cast<std::ptrdiff_t>(bit_index), value ? 1 : 0);
  return true;
}

bool InsertCnwMsbBits(
    std::vector<unsigned char>* bits,
    size_t bit_index,
    const std::vector<unsigned char>& inserted_bits) {
  if (bits == nullptr || bit_index > kMaxReasonableReassembledGameplayPayload * 8ull ||
      inserted_bits.empty()) {
    return false;
  }
  if (bit_index > bits->size()) {
    bits->resize(bit_index, 0);
  }
  bits->insert(
      bits->begin() + static_cast<std::ptrdiff_t>(bit_index),
      inserted_bits.begin(),
      inserted_bits.end());
  return true;
}

bool EraseCnwMsbBits(std::vector<unsigned char>* bits, size_t bit_index, size_t bit_count) {
  if (bits == nullptr || bit_index > kMaxReasonableReassembledGameplayPayload * 8ull) {
    return false;
  }
  if (bit_count == 0) {
    return true;
  }
  if (bit_index > bits->size() || bits->size() - bit_index < bit_count) {
    return false;
  }
  bits->erase(
      bits->begin() + static_cast<std::ptrdiff_t>(bit_index),
      bits->begin() + static_cast<std::ptrdiff_t>(bit_index + bit_count));
  return true;
}

bool LooksLikeLegacyAddShortLocStringAt(
    const std::vector<unsigned char>& bytes,
    unsigned char object_type,
    size_t name_offset,
    size_t record_end,
    size_t* legacy_tail_end) {
  if (legacy_tail_end != nullptr) {
    *legacy_tail_end = 0;
  }
  if (name_offset > record_end || record_end > bytes.size() ||
      record_end - name_offset < 4 ||
      LooksLikeInlineCExoStringAt(bytes, name_offset, nullptr, nullptr, nullptr)) {
    return false;
  }

  size_t tail_end = 0;
  if (object_type == 10) {
    tail_end = name_offset + 4 + 2;
  } else if (object_type == 9) {
    tail_end = name_offset + 4 + 1 + 2 + 2;
  } else {
    return false;
  }

  if (tail_end > record_end) {
    return false;
  }
  if (tail_end != record_end &&
      !LooksLikeExistingEeIdentityVisualTransformMap(bytes, tail_end, record_end)) {
    return false;
  }
  if (legacy_tail_end != nullptr) {
    *legacy_tail_end = tail_end;
  }
  return true;
}

bool LooksLikeLegacyDoorAddModelTokenAt(
    const std::vector<unsigned char>& bytes,
    size_t token_offset,
    size_t record_end,
    size_t* token_length) {
  if (token_length != nullptr) {
    *token_length = 0;
  }
  constexpr size_t kLegacyDoorModelTokenBytes = 4;
  if (token_offset > record_end ||
      record_end > bytes.size() ||
      record_end - token_offset != kLegacyDoorModelTokenBytes + 2) {
    return false;
  }

  bool any_printable = false;
  for (size_t index = 0; index < kLegacyDoorModelTokenBytes; ++index) {
    const unsigned char value = bytes[token_offset + index];
    if (!IsLegacyDoorModelTokenByte(value)) {
      return false;
    }
    any_printable = true;
  }

  uint16_t state = 0;
  if (!any_printable ||
      !TryReadU16LeFromBytes(bytes, token_offset + kLegacyDoorModelTokenBytes, &state)) {
    return false;
  }
  (void)state;
  if (token_length != nullptr) {
    *token_length = kLegacyDoorModelTokenBytes;
  }
  return true;
}

bool LooksLikeLegacyDoorUpdateModelTokenAt(
    const std::vector<unsigned char>& bytes,
    size_t token_offset,
    size_t record_end,
    size_t* token_length) {
  if (token_length != nullptr) {
    *token_length = 0;
  }
  constexpr size_t kLegacyDoorModelTokenBytes = 4;
  if (token_offset > record_end ||
      record_end > bytes.size() ||
      record_end - token_offset != kLegacyDoorModelTokenBytes) {
    return false;
  }

  bool any_alpha = false;
  for (size_t index = 0; index < kLegacyDoorModelTokenBytes; ++index) {
    const unsigned char value = bytes[token_offset + index];
    if (!IsLegacyDoorModelTokenByte(value)) {
      return false;
    }
    any_alpha = any_alpha ||
        (value >= 'A' && value <= 'Z') ||
        (value >= 'a' && value <= 'z');
  }

  if (!any_alpha) {
    return false;
  }
  if (token_length != nullptr) {
    *token_length = kLegacyDoorModelTokenBytes;
  }
  return true;
}

bool LooksLikeDoorAddNamePayloadAt(
    const std::vector<unsigned char>& bytes,
    size_t name_offset,
    size_t record_end,
    bool* short_locstring,
    size_t* name_end,
    size_t* legacy_model_token_offset,
    size_t* legacy_model_token_length) {
  if (short_locstring != nullptr) {
    *short_locstring = false;
  }
  if (name_end != nullptr) {
    *name_end = name_offset;
  }
  if (legacy_model_token_offset != nullptr) {
    *legacy_model_token_offset = 0;
  }
  if (legacy_model_token_length != nullptr) {
    *legacy_model_token_length = 0;
  }
  if (name_offset > record_end || record_end > bytes.size()) {
    return false;
  }

  size_t inline_end = 0;
  if (LooksLikeInlineCExoStringAt(bytes, name_offset, nullptr, &inline_end, nullptr)) {
    const size_t tail_end = inline_end + 2;
    if (tail_end <= record_end &&
        (tail_end == record_end ||
         LooksLikeExistingEeIdentityVisualTransformMap(bytes, tail_end, record_end))) {
      if (name_end != nullptr) {
        *name_end = inline_end;
      }
      return true;
    }
    size_t token_length = 0;
    if (LooksLikeLegacyDoorAddModelTokenAt(bytes, inline_end, record_end, &token_length)) {
      if (name_end != nullptr) {
        *name_end = inline_end;
      }
      if (legacy_model_token_offset != nullptr) {
        *legacy_model_token_offset = inline_end;
      }
      if (legacy_model_token_length != nullptr) {
        *legacy_model_token_length = token_length;
      }
      return true;
    }
  }

  size_t tail_end = 0;
  if (LooksLikeLegacyAddShortLocStringAt(bytes, 10, name_offset, record_end, &tail_end)) {
    if (short_locstring != nullptr) {
      *short_locstring = true;
    }
    if (name_end != nullptr) {
      *name_end = name_offset + 4;
    }
    return true;
  }
  return false;
}

bool TryFindLegacyCompactDoorAddEmptyName(
    const std::vector<unsigned char>& bytes,
    size_t record_offset,
    size_t record_end,
    bool* has_visual_transform_map,
    size_t* visual_transform_insert_offset,
    size_t* name_insert_offset,
    const BridgeRuntime* runtime) {
  if (has_visual_transform_map != nullptr) {
    *has_visual_transform_map = false;
  }
  if (visual_transform_insert_offset != nullptr) {
    *visual_transform_insert_offset = 0;
  }
  if (name_insert_offset != nullptr) {
    *name_insert_offset = 0;
  }
  if (record_offset > bytes.size() || record_end > bytes.size() ||
      record_end <= record_offset || bytes.size() - record_offset < 16 ||
      bytes[record_offset] != 'A' || bytes[record_offset + 1] != 10 ||
      !LooksLikeLegacyLiveObjectIdAt(bytes, record_offset + 2)) {
    return false;
  }

  uint32_t first_dword = 0;
  uint32_t generic_door_row = 0;
  uint16_t state = 0;
  if (!TryReadU32LeFromBytes(bytes, record_offset + 6, &first_dword) ||
      first_dword != 0 ||
      !TryReadU32LeFromBytes(bytes, record_offset + 10, &generic_door_row) ||
      !IsKnownGenericDoorRow(runtime, generic_door_row)) {
    return false;
  }

  const size_t legacy_name_offset = record_offset + 14;
  if (record_end == legacy_name_offset + 2 &&
      TryReadU16LeFromBytes(bytes, legacy_name_offset, &state)) {
    (void)state;
    if (visual_transform_insert_offset != nullptr) {
      *visual_transform_insert_offset = legacy_name_offset;
    }
    if (name_insert_offset != nullptr) {
      *name_insert_offset = legacy_name_offset;
    }
    return true;
  }

  const size_t ee_name_offset = legacy_name_offset + kEeLiveVisualTransformEmptyMapBytes;
  if (record_end == ee_name_offset + 2 &&
      HasEeIdentityVisualTransformMapBytesAt(bytes, legacy_name_offset, record_end) &&
      TryReadU16LeFromBytes(bytes, ee_name_offset, &state)) {
    (void)state;
    if (has_visual_transform_map != nullptr) {
      *has_visual_transform_map = true;
    }
    if (visual_transform_insert_offset != nullptr) {
      *visual_transform_insert_offset = legacy_name_offset;
    }
    if (name_insert_offset != nullptr) {
      *name_insert_offset = ee_name_offset;
    }
    return true;
  }

  return false;
}

bool TryFindDoorAddNameForAddRecordRewrite(
    const std::vector<unsigned char>& bytes,
    size_t record_offset,
    size_t record_end,
    size_t* name_offset,
    bool* short_locstring,
    size_t* legacy_model_token_offset,
    size_t* legacy_model_token_length,
    const BridgeRuntime* runtime) {
  if (name_offset != nullptr) {
    *name_offset = 0;
  }
  if (short_locstring != nullptr) {
    *short_locstring = false;
  }
  if (legacy_model_token_offset != nullptr) {
    *legacy_model_token_offset = 0;
  }
  if (legacy_model_token_length != nullptr) {
    *legacy_model_token_length = 0;
  }
  if (record_offset > bytes.size() || record_end > bytes.size() ||
      record_end <= record_offset || bytes.size() - record_offset < 10 ||
      bytes[record_offset] != 'A' || bytes[record_offset + 1] != 10 ||
      !LooksLikeLegacyLiveObjectIdAt(bytes, record_offset + 2)) {
    return false;
  }

  uint32_t first_dword = 0;
  if (!TryReadU32LeFromBytes(bytes, record_offset + 6, &first_dword)) {
    return false;
  }
  if (first_dword == 0) {
    uint32_t generic_door_row = 0;
    if (!TryReadU32LeFromBytes(bytes, record_offset + 10, &generic_door_row) ||
        !IsKnownGenericDoorRow(runtime, generic_door_row)) {
      return false;
    }
  }

  const size_t object_start = record_offset + 2;
  const size_t legacy_name_offset = object_start + (first_dword == 0 ? 12 : 8);
  bool candidate_short = false;
  size_t candidate_end = 0;
  size_t candidate_token_offset = 0;
  size_t candidate_token_length = 0;
  if (HasEeIdentityVisualTransformMapBytesAt(bytes, legacy_name_offset, record_end) &&
      LooksLikeDoorAddNamePayloadAt(
          bytes,
          legacy_name_offset + kEeLiveVisualTransformEmptyMapBytes,
          record_end,
          &candidate_short,
          &candidate_end,
          &candidate_token_offset,
          &candidate_token_length)) {
    (void)candidate_end;
    if (name_offset != nullptr) {
      *name_offset = legacy_name_offset + kEeLiveVisualTransformEmptyMapBytes;
    }
    if (short_locstring != nullptr) {
      *short_locstring = candidate_short;
    }
    if (legacy_model_token_offset != nullptr) {
      *legacy_model_token_offset = candidate_token_offset;
    }
    if (legacy_model_token_length != nullptr) {
      *legacy_model_token_length = candidate_token_length;
    }
    return true;
  }

  if (!LooksLikeDoorAddNamePayloadAt(
          bytes,
          legacy_name_offset,
          record_end,
          &candidate_short,
          &candidate_end,
          &candidate_token_offset,
          &candidate_token_length)) {
    return false;
  }
  (void)candidate_end;
  if (name_offset != nullptr) {
    *name_offset = legacy_name_offset;
  }
  if (short_locstring != nullptr) {
    *short_locstring = candidate_short;
  }
  if (legacy_model_token_offset != nullptr) {
    *legacy_model_token_offset = candidate_token_offset;
  }
  if (legacy_model_token_length != nullptr) {
    *legacy_model_token_length = candidate_token_length;
  }
  return true;
}

bool LooksLikeLegacyPlaceableAddTailAt(
    const std::vector<unsigned char>& bytes,
    size_t tail_offset,
    size_t record_end,
    size_t* legacy_tail_end);

bool TryFindPlaceableAddNameForAddRecordRewrite(
    const std::vector<unsigned char>& bytes,
    size_t record_offset,
    size_t record_end,
    size_t* name_offset,
    size_t* visual_transform_offset,
    bool* short_locstring) {
  if (name_offset != nullptr) {
    *name_offset = 0;
  }
  if (visual_transform_offset != nullptr) {
    *visual_transform_offset = 0;
  }
  if (short_locstring != nullptr) {
    *short_locstring = false;
  }
  if (record_offset > bytes.size() || record_end > bytes.size() ||
      record_end <= record_offset || bytes.size() - record_offset < 11 ||
      bytes[record_offset] != 'A' || bytes[record_offset + 1] != 9 ||
      !LooksLikeLegacyLiveObjectIdAt(bytes, record_offset + 2)) {
    return false;
  }

  const size_t candidate_name = record_offset + 6;
  size_t candidate_tail = 0;
  size_t inline_end = 0;
  bool candidate_short = false;
  if (LooksLikeInlineCExoStringAt(bytes, candidate_name, nullptr, &inline_end, nullptr)) {
    candidate_tail = inline_end;
  } else {
    size_t legacy_tail_end = 0;
    if (!LooksLikeLegacyAddShortLocStringAt(
            bytes,
            9,
            candidate_name,
            record_end,
            &legacy_tail_end)) {
      return false;
    }
    (void)legacy_tail_end;
    candidate_tail = candidate_name + 4;
    candidate_short = true;
  }

  size_t legacy_tail_end = 0;
  if (!LooksLikeLegacyPlaceableAddTailAt(bytes, candidate_tail, record_end, &legacy_tail_end)) {
    return false;
  }
  if (name_offset != nullptr) {
    *name_offset = candidate_name;
  }
  if (visual_transform_offset != nullptr) {
    // EE reads the appearance tail before the add-record visual-transform map.
    // The map therefore belongs after the legacy tail, not at its first byte.
    *visual_transform_offset = legacy_tail_end;
  }
  if (short_locstring != nullptr) {
    *short_locstring = candidate_short;
  }
  return true;
}

bool TryReadLegacyTriggerAddShape(
    const std::vector<unsigned char>& bytes,
    size_t record_offset,
    size_t record_end,
    uint8_t* primary_flag,
    uint8_t* vertex_count) {
  if (primary_flag != nullptr) {
    *primary_flag = 0;
  }
  if (vertex_count != nullptr) {
    *vertex_count = 0;
  }
  constexpr size_t kTriggerReadBufferBytesBeforeVertices = 16;
  constexpr size_t kTriggerVertexBytes = 12;
  if (record_offset > bytes.size() || record_end > bytes.size() ||
      bytes.size() - record_offset < kTriggerReadBufferBytesBeforeVertices ||
      bytes[record_offset] != 'A' || bytes[record_offset + 1] != 7 ||
      !LooksLikeLegacyLiveObjectIdAt(bytes, record_offset + 2) ||
      LooksLikeInlineCExoStringAt(bytes, record_offset + 6, nullptr, nullptr, nullptr)) {
    return false;
  }

  const uint8_t observed_primary = bytes[record_offset + 10];
  const uint8_t observed_vertices = bytes[record_offset + 15];
  float height = 0.0f;
  if (observed_primary > 1 ||
      observed_vertices == 0 ||
      observed_vertices > 64 ||
      !TryReadFloatLeFromBytes(bytes, record_offset + 11, &height) ||
      !(height >= -1000.0f && height <= 1000.0f)) {
    return false;
  }

  const size_t expected_end =
      record_offset + kTriggerReadBufferBytesBeforeVertices +
      static_cast<size_t>(observed_vertices) * kTriggerVertexBytes;
  if (expected_end != record_end) {
    return false;
  }
  for (uint8_t index = 0; index < observed_vertices; ++index) {
    const size_t vertex_offset =
        record_offset + kTriggerReadBufferBytesBeforeVertices +
        static_cast<size_t>(index) * kTriggerVertexBytes;
    for (size_t component = 0; component < 3; ++component) {
      float value = 0.0f;
      if (!TryReadFloatLeFromBytes(bytes, vertex_offset + component * 4, &value) ||
          !std::isfinite(value) ||
          std::fabs(value) > 100000.0f) {
        return false;
      }
    }
  }

  if (primary_flag != nullptr) {
    *primary_flag = observed_primary;
  }
  if (vertex_count != nullptr) {
    *vertex_count = observed_vertices;
  }
  return true;
}

void AppendLiveAddRecordRewriteDetail(
    LiveAddRecordRewriteResult* result,
    size_t record_offset,
    unsigned char object_type,
    uint32_t object_id,
    const wchar_t* action) {
  if (result == nullptr || result->details.size() > 1800) {
    return;
  }
  wchar_t text[320]{};
  swprintf_s(
      text,
      L"%s+%zu type=%u/%s id=0x%08X %s",
      result->details.empty() ? L"" : L"; ",
      record_offset,
      static_cast<unsigned int>(object_type),
      LegacyLiveObjectTypeName(object_type),
      object_id,
      action != nullptr ? action : L"rewritten");
  result->details += text;
}

std::wstring FormatCnwBitSlice(
    const std::vector<unsigned char>& bits,
    size_t start,
    size_t count) {
  std::wstring text;
  wchar_t header[64]{};
  swprintf_s(header, L"%zu:", start);
  text += header;
  for (size_t index = 0; index < count; ++index) {
    const size_t bit_index = start + index;
    text += bit_index < bits.size() && bits[bit_index] != 0 ? L'1' : L'0';
  }
  return text;
}

void AppendLiveAddRecordRewriteDiagnostic(
    LiveAddRecordRewriteResult* result,
    const std::vector<unsigned char>& bytes,
    size_t record_offset,
    size_t record_end,
    uint32_t object_id,
    size_t bit_cursor,
    size_t optional_bit,
    size_t final_visual_bit,
    size_t record_bit_span,
    size_t name_offset,
    size_t visual_transform_offset,
    bool short_locstring,
    bool legacy_outer_locstring,
    bool optional_changed,
    bool map_inserted,
    const std::vector<unsigned char>& before_bits,
    const std::vector<unsigned char>& after_bits) {
  if (result == nullptr || result->diagnostics.size() > 3600) {
    return;
  }

  const size_t safe_record_end = std::min(record_end, bytes.size());
  const size_t safe_name_offset = std::min(name_offset, safe_record_end);
  std::string name_preview;
  uint32_t name_length = 0;
  size_t name_end = safe_name_offset;
  uint32_t strref = 0;
  if (!short_locstring) {
    (void)LooksLikeInlineCExoStringAt(
        bytes,
        safe_name_offset,
        &name_length,
        &name_end,
        &name_preview);
  } else if (safe_name_offset + 4 <= bytes.size() &&
      TryReadU32LeFromBytes(bytes, safe_name_offset, &strref)) {
    char text[64]{};
    std::snprintf(text, sizeof(text), "<tlk:%u>", strref);
    name_preview = text;
    name_length = 0;
    name_end = safe_name_offset + 4;
  }

  uint8_t appearance_type = 0;
  uint16_t appearance_id = 0;
  uint16_t bodybag = 0;
  if (name_end < bytes.size()) {
    appearance_type = bytes[name_end];
  }
  if (name_end + 3 <= bytes.size()) {
    (void)TryReadU16LeFromBytes(bytes, name_end + 1, &appearance_id);
  }
  if (name_end + 5 <= bytes.size()) {
    (void)TryReadU16LeFromBytes(bytes, name_end + 3, &bodybag);
  }

  const size_t raw_length = safe_record_end > record_offset
      ? safe_record_end - record_offset
      : 0;
  const size_t bit_slice_start = bit_cursor >= 4 ? bit_cursor - 4 : 0;
  const size_t bit_slice_count = 24;

  wchar_t text[1400]{};
  swprintf_s(
      text,
      L"%s+%zu placeable id=0x%08X bits[cursor=%zu opt=%zu final=%zu span=%zu before=%s after=%s] name_off=%zu name_len=%u name='%s' short=%d outer=%d vt_off=%zu tail[type=0x%02X/%u app=0x%04X/%u bodybag=0x%04X/%u] opt_changed=%d map=%d raw-len=%zu raw=[%s]",
      result->diagnostics.empty() ? L"" : L"; ",
      record_offset,
      object_id,
      bit_cursor,
      optional_bit,
      final_visual_bit,
      record_bit_span,
      FormatCnwBitSlice(before_bits, bit_slice_start, bit_slice_count).c_str(),
      FormatCnwBitSlice(after_bits, bit_slice_start, bit_slice_count).c_str(),
      name_offset,
      name_length,
      AsciiPreviewToWide(name_preview, 96).c_str(),
      short_locstring ? 1 : 0,
      legacy_outer_locstring ? 1 : 0,
      visual_transform_offset,
      static_cast<unsigned int>(appearance_type),
      static_cast<unsigned int>(appearance_type),
      static_cast<unsigned int>(appearance_id),
      static_cast<unsigned int>(appearance_id),
      static_cast<unsigned int>(bodybag),
      static_cast<unsigned int>(bodybag),
      optional_changed ? 1 : 0,
      map_inserted ? 1 : 0,
      raw_length,
      raw_length != 0
          ? FormatLimitedBytes(bytes.data() + record_offset, raw_length, 96).c_str()
          : L"");
  result->diagnostics += text;
}

bool ShouldSkipLegacyLiveShortAddRecordBytes(
    const BridgeRuntime* runtime,
    const std::vector<unsigned char>& bytes,
    size_t record_offset,
    size_t record_end,
    std::wstring* reason) {
  if (reason != nullptr) {
    reason->clear();
  }
  if (record_offset > bytes.size() ||
      record_end > bytes.size() ||
      record_end <= record_offset ||
      record_end - record_offset > 96 ||
      bytes.size() - record_offset < 8 ||
      bytes[record_offset] != 'A' ||
      (bytes[record_offset + 1] != 9 && bytes[record_offset + 1] != 10)) {
    return false;
  }

  const unsigned char object_type = bytes[record_offset + 1];
  if (!LooksLikeLegacyLiveObjectIdAt(bytes, record_offset + 2)) {
    if (reason != nullptr) {
      *reason = L"invalid-object-id";
    }
    return true;
  }

  if (object_type == 9) {
    size_t name_offset = 0;
    size_t tail_offset = 0;
    bool short_locstring = false;
    if (TryFindPlaceableAddNameForAddRecordRewrite(
            bytes,
            record_offset,
            record_end,
            &name_offset,
            &tail_offset,
            &short_locstring)) {
      (void)name_offset;
      (void)tail_offset;
      (void)short_locstring;
      return false;
    }
  } else if (object_type == 10) {
    size_t name_offset = 0;
    bool short_locstring = false;
    if (TryFindDoorAddNameForAddRecordRewrite(
            bytes,
            record_offset,
            record_end,
            &name_offset,
            &short_locstring,
            nullptr,
            nullptr,
            runtime)) {
      (void)name_offset;
      (void)short_locstring;
      return false;
    }
    if (TryFindLegacyCompactDoorAddEmptyName(
            bytes,
            record_offset,
            record_end,
            nullptr,
            nullptr,
            nullptr,
            runtime)) {
      return false;
    }
    uint32_t first_dword = 0;
    uint32_t generic_row = 0;
    if (TryReadU32LeFromBytes(bytes, record_offset + 6, &first_dword) &&
        first_dword == 0 &&
        TryReadU32LeFromBytes(bytes, record_offset + 10, &generic_row) &&
        !IsKnownGenericDoorRow(runtime, generic_row)) {
      if (reason != nullptr) {
        wchar_t text[96]{};
        swprintf_s(text, L"short-door-add-invalid-generic-row=%u", generic_row);
        *reason = text;
      }
      return true;
    }
  }

  if (reason != nullptr) {
    *reason = object_type == 9
        ? L"short-placeable-add-without-ee-name"
        : L"short-door-add-without-ee-name";
  }
  return true;
}

bool TryGetLegacyLiveShortAddFragmentBitSpan(
    const std::vector<unsigned char>& bytes,
    const std::vector<unsigned char>& bits,
    size_t record_offset,
    size_t record_end,
    size_t bit_cursor,
    size_t* bit_span) {
  if (bit_span != nullptr) {
    *bit_span = 0;
  }
  if (bit_span == nullptr ||
      record_offset > bytes.size() ||
      record_end > bytes.size() ||
      record_end <= record_offset ||
      bytes.size() - record_offset < 6 ||
      bytes[record_offset] != 'A' ||
      (bytes[record_offset + 1] != 9 && bytes[record_offset + 1] != 10) ||
      !LooksLikeLegacyLiveObjectIdAt(bytes, record_offset + 2)) {
    return false;
  }

  const unsigned char object_type = bytes[record_offset + 1];
  if (object_type == 10) {
    // Legacy door add state/name fragment fields are six BOOLs in the normal
    // and compact stub shapes. When the read-buffer side is too short for EE,
    // the paired skipped record still owns those legacy bits.
    *bit_span = 6;
    return bit_cursor <= bits.size() && *bit_span <= bits.size() - bit_cursor;
  }

  (void)bits;
  // See AdvanceLegacyLiveAddRecordBitCursor: skipped legacy placeable adds own
  // ten source bits. Synthetic EE bits are only erased when they were actually
  // inserted, not while accounting for an unrewritten legacy record.
  *bit_span = 10;
  return bit_cursor <= bits.size() && *bit_span <= bits.size() - bit_cursor;
}

bool RewriteLegacyLiveObjectAddRecords(
    BridgeRuntime* runtime,
    std::vector<unsigned char>* live_bytes,
    std::vector<unsigned char>* fragment_bytes,
    LiveAddRecordRewriteResult* result) {
  if (result != nullptr) {
    result->records_examined = 0;
    result->records_rewritten = 0;
    result->short_locstrings_flattened = 0;
    result->trigger_records_rewritten = 0;
    result->bits_set_or_extended = 0;
    result->bits_inserted = 0;
    result->fragment_bits_trimmed = 0;
    result->old_fragment_bytes = fragment_bytes != nullptr
        ? static_cast<uint32_t>(fragment_bytes->size())
        : 0;
    result->new_fragment_bytes = result->old_fragment_bytes;
    result->short_add_records_skipped = 0;
    result->short_add_bytes_skipped = 0;
    result->short_add_bits_skipped = 0;
    result->details.clear();
    result->diagnostics.clear();
  }
  if (live_bytes == nullptr || fragment_bytes == nullptr || live_bytes->size() < 10) {
    return false;
  }

  std::vector<unsigned char> bits;
  if (!DecodeCnwFragmentBits(*fragment_bytes, &bits)) {
    return false;
  }
  bool rewritten = false;
  bool bit_cursor_reliable = true;
  size_t bit_cursor = 3;

  for (size_t offset = 0; offset + 10 <= live_bytes->size();) {
    if ((*live_bytes)[offset] == 'A' &&
        ((*live_bytes)[offset + 1] == 9 || (*live_bytes)[offset + 1] == 10)) {
      const unsigned char short_add_object_type = (*live_bytes)[offset + 1];
      size_t record_end = FindNextLegacyLiveObjectSubMessageBoundaryAfter(*live_bytes, offset);
      if (record_end > live_bytes->size()) {
        record_end = live_bytes->size();
      }
      std::wstring skip_reason;
      if (ShouldSkipLegacyLiveShortAddRecordBytes(
              runtime,
              *live_bytes,
              offset,
              record_end,
              &skip_reason)) {
        uint32_t object_id = 0;
        if (live_bytes->size() - offset >= 6) {
          TryReadU32LeFromBytes(*live_bytes, offset + 2, &object_id);
        }
        size_t skipped_bits = 0;
        if (bit_cursor_reliable) {
          size_t next_bit_cursor = bit_cursor;
          if (AdvanceLegacyLiveAddRecordBitCursor(
                  *live_bytes,
                  bits,
                  offset,
                  record_end,
                  &next_bit_cursor) &&
              next_bit_cursor >= bit_cursor) {
            skipped_bits = next_bit_cursor - bit_cursor;
            if (!EraseCnwMsbBits(&bits, bit_cursor, skipped_bits)) {
              skipped_bits = 0;
              bit_cursor_reliable = false;
            }
          } else {
            bit_cursor_reliable = false;
          }
          if (!bit_cursor_reliable &&
              TryGetLegacyLiveShortAddFragmentBitSpan(
                  *live_bytes,
                  bits,
                  offset,
                  record_end,
                  bit_cursor,
                  &skipped_bits)) {
            if (EraseCnwMsbBits(&bits, bit_cursor, skipped_bits)) {
              bit_cursor_reliable = true;
            } else {
              skipped_bits = 0;
            }
          }
        }
        const size_t removed_bytes = record_end - offset;
        live_bytes->erase(
            live_bytes->begin() + static_cast<std::ptrdiff_t>(offset),
            live_bytes->begin() + static_cast<std::ptrdiff_t>(record_end));
        rewritten = true;
        if (result != nullptr) {
          ++result->records_examined;
          ++result->records_rewritten;
          ++result->short_add_records_skipped;
          result->short_add_bytes_skipped += static_cast<uint32_t>(removed_bytes);
          result->short_add_bits_skipped += static_cast<uint32_t>(skipped_bits);
          std::wstring action = L"short-add-skip";
          if (!skip_reason.empty()) {
            action += L":";
            action += skip_reason;
          }
          if (skipped_bits != 0) {
            wchar_t bits_text[48]{};
            swprintf_s(bits_text, L":bits=%zu", skipped_bits);
            action += bits_text;
          }
          AppendLiveAddRecordRewriteDetail(
              result,
              offset,
              short_add_object_type,
              object_id,
              action.c_str());
        }
        continue;
      }
    }

    if (!LooksLikeLegacyLiveObjectSubMessageBoundaryBytes(*live_bytes, offset)) {
      ++offset;
      continue;
    }

    if (result != nullptr) {
      ++result->records_examined;
    }

    const unsigned char opcode = (*live_bytes)[offset];
    const unsigned char object_type = (*live_bytes)[offset + 1];
    size_t record_end = FindNextLegacyLiveObjectSubMessageBoundaryAfter(*live_bytes, offset);
    if (record_end > live_bytes->size()) {
      record_end = live_bytes->size();
    }

    size_t delete_fragment_bits = 0;
    if (TryGetLegacyLiveDeleteFragmentBitCount(
            *live_bytes,
            offset,
            record_end,
            &delete_fragment_bits)) {
      if (bit_cursor_reliable) {
        if (delete_fragment_bits > bits.size() ||
            bit_cursor > bits.size() - delete_fragment_bits) {
          bit_cursor_reliable = false;
        } else {
          bit_cursor += delete_fragment_bits;
        }
      }
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }

    if (opcode == 'I') {
      size_t inventory_fragment_bits = 0;
      if (bit_cursor_reliable) {
        if (TryGetLegacyLiveInventoryFragmentBitCount(
              *live_bytes,
              offset,
              record_end,
              &inventory_fragment_bits)) {
          if (inventory_fragment_bits > bits.size() ||
              bit_cursor > bits.size() - inventory_fragment_bits) {
            bit_cursor_reliable = false;
          } else {
            bit_cursor += inventory_fragment_bits;
          }
        } else {
          bit_cursor_reliable = false;
        }
      }
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }

    if (opcode == 'G' &&
        (object_type == 'I' || object_type == 'i' ||
         object_type == 'R' || object_type == 'r') &&
        record_end > offset + 3 &&
        (*live_bytes)[offset + 2] == 'A') {
      if (bit_cursor_reliable &&
          !TryAdvanceLegacyLiveGuiItemCreateBitCursorForEe(
              *live_bytes,
              offset,
              record_end,
              bits,
              &bit_cursor,
              true)) {
        bit_cursor_reliable = false;
      }
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }

    if (IsLegacyLiveReadBufferOnlySubMessage(*live_bytes, offset, record_end)) {
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }

    if (AdvanceKnownLegacyLiveCreatureBitCursor(
            *live_bytes,
            offset,
            record_end,
            bits,
            &bit_cursor,
            nullptr,
            runtime,
            true)) {
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }

    if (opcode == 'U' &&
        AdvanceRewrittenLiveUpdateRecordBitCursor(*live_bytes, offset, record_end, &bit_cursor)) {
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }

    if (opcode != 'A' || (object_type != 7 && object_type != 9 && object_type != 10) ||
        !LooksLikeLegacyLiveObjectIdAt(*live_bytes, offset + 2)) {
      bit_cursor_reliable = false;
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }

    if (!bit_cursor_reliable) {
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }

    uint32_t object_id = 0;
    TryReadU32LeFromBytes(*live_bytes, offset + 2, &object_id);

    if (object_type == 10) {
      bool compact_has_visual_transform = false;
      size_t compact_visual_insert_offset = 0;
      size_t compact_name_insert_offset = 0;
      if (TryFindLegacyCompactDoorAddEmptyName(
              *live_bytes,
              offset,
              record_end,
              &compact_has_visual_transform,
              &compact_visual_insert_offset,
              &compact_name_insert_offset,
              runtime)) {
        bool compact_map_inserted = false;
        if (!compact_has_visual_transform) {
          if (compact_visual_insert_offset > record_end ||
              compact_visual_insert_offset > live_bytes->size() ||
              compact_name_insert_offset < compact_visual_insert_offset) {
            bit_cursor_reliable = false;
            offset = record_end > offset ? record_end : offset + 1;
            continue;
          }
          InsertEeLiveVisualTransformIdentityMap(live_bytes, compact_visual_insert_offset);
          record_end += kEeLiveVisualTransformEmptyMapBytes;
          compact_name_insert_offset += kEeLiveVisualTransformEmptyMapBytes;
          compact_map_inserted = true;
        }
        live_bytes->insert(
            live_bytes->begin() + static_cast<std::ptrdiff_t>(compact_name_insert_offset),
            4,
            0);
        record_end += 4;
        bool changed = false;
        if (SetCnwMsbBit(&bits, bit_cursor, false, &changed) && changed &&
            result != nullptr) {
          ++result->bits_set_or_extended;
        }
        rewritten = true;
        if (result != nullptr) {
          ++result->records_rewritten;
          AppendLiveAddRecordRewriteDetail(
              result,
              offset,
              object_type,
              object_id,
              compact_has_visual_transform
                  ? L"door-empty-name-string-existing-visual"
                  : (compact_map_inserted
                      ? L"door-empty-name-string+visual-map"
                      : L"door-empty-name-string"));
        }
        bit_cursor += 6;
        offset = record_end > offset ? record_end : offset + 1;
        continue;
      }

      size_t name_offset = 0;
      size_t legacy_model_token_offset = 0;
      size_t legacy_model_token_length = 0;
      bool short_locstring = false;
      if (!TryFindDoorAddNameForAddRecordRewrite(
              *live_bytes,
              offset,
              record_end,
              &name_offset,
              &short_locstring,
              &legacy_model_token_offset,
              &legacy_model_token_length,
              runtime)) {
        bit_cursor_reliable = false;
        offset = record_end > offset ? record_end : offset + 1;
        continue;
      }
      uint32_t first_dword = 0;
      if (!TryReadU32LeFromBytes(*live_bytes, offset + 6, &first_dword)) {
        bit_cursor_reliable = false;
        offset = record_end > offset ? record_end : offset + 1;
        continue;
      }
      const size_t door_visual_offset =
          offset + 2 + (first_dword == 0 ? 12 : 8);
      bool door_map_inserted = false;
      if (door_visual_offset > record_end || door_visual_offset > live_bytes->size()) {
        bit_cursor_reliable = false;
        offset = record_end > offset ? record_end : offset + 1;
        continue;
      }
      if (!HasEeIdentityVisualTransformMapBytesAt(*live_bytes, door_visual_offset, record_end)) {
        InsertEeLiveVisualTransformIdentityMap(live_bytes, door_visual_offset);
        if (name_offset >= door_visual_offset) {
          name_offset += kEeLiveVisualTransformEmptyMapBytes;
        }
        if (legacy_model_token_length != 0 &&
            legacy_model_token_offset >= door_visual_offset) {
          legacy_model_token_offset += kEeLiveVisualTransformEmptyMapBytes;
        }
        record_end += kEeLiveVisualTransformEmptyMapBytes;
        door_map_inserted = true;
      }
      bool legacy_model_token_removed = false;
      if (legacy_model_token_length != 0) {
        if (legacy_model_token_offset > record_end ||
            legacy_model_token_length > record_end - legacy_model_token_offset ||
            legacy_model_token_offset < name_offset) {
          bit_cursor_reliable = false;
          offset = record_end > offset ? record_end : offset + 1;
          continue;
        }
        live_bytes->erase(
            live_bytes->begin() + static_cast<std::ptrdiff_t>(legacy_model_token_offset),
            live_bytes->begin() + static_cast<std::ptrdiff_t>(
                legacy_model_token_offset + legacy_model_token_length));
        record_end -= legacy_model_token_length;
        legacy_model_token_removed = true;
      }

      bool changed = false;
      bool local_rewritten = door_map_inserted || legacy_model_token_removed;
      size_t door_record_bit_span = 6;
      const bool legacy_outer_locstring =
          !short_locstring && bit_cursor < bits.size() && bits[bit_cursor] != 0;
      if (short_locstring) {
        WriteU32Le(live_bytes->data() + name_offset, 0);
        if (!SetCnwMsbBit(&bits, bit_cursor, false, &changed) ||
            !InsertCnwMsbBit(&bits, bit_cursor + 1, false)) {
          bit_cursor_reliable = false;
          offset = record_end > offset ? record_end : offset + 1;
          continue;
        }
        if (changed && result != nullptr) {
          ++result->bits_set_or_extended;
        }
        if (result != nullptr) {
          ++result->bits_inserted;
          ++result->short_locstrings_flattened;
        }
        local_rewritten = true;
        door_record_bit_span = 6;
      } else if (legacy_outer_locstring) {
        // Diamond and EE both spend an inner/client-tlk bit when the outer
        // name-mode flag is true. The old hook consumed that original bit and
        // returned false so the rest of the door flags stayed aligned.
        bool inner_changed = false;
        if (!SetCnwMsbBit(&bits, bit_cursor + 1, false, &inner_changed)) {
          bit_cursor_reliable = false;
          offset = record_end > offset ? record_end : offset + 1;
          continue;
        }
        if (inner_changed && result != nullptr) {
          ++result->bits_set_or_extended;
        }
        local_rewritten = true;
        door_record_bit_span = 7;
      } else {
        if (!SetCnwMsbBit(&bits, bit_cursor, false, &changed)) {
          bit_cursor_reliable = false;
          offset = record_end > offset ? record_end : offset + 1;
          continue;
        }
        if (changed && result != nullptr) {
          ++result->bits_set_or_extended;
        }
        local_rewritten = local_rewritten || changed;
      }
      if (local_rewritten) {
        rewritten = true;
        if (result != nullptr) {
          ++result->records_rewritten;
          std::wstring action = door_map_inserted
              ? (short_locstring
                  ? L"door-short-direct-empty-name+absent-bool+visual-map"
                  : (legacy_outer_locstring
                      ? L"door-inline-locstring-inner-string+visual-map"
                      : L"door-name-string-flag+visual-map"))
              : (short_locstring
                  ? L"door-short-direct-empty-name+absent-bool"
                  : (legacy_outer_locstring
                      ? L"door-inline-locstring-inner-string"
                      : L"door-name-string-flag"));
          if (legacy_model_token_removed) {
            action += L"+legacy-model-token-strip";
          }
          AppendLiveAddRecordRewriteDetail(
              result,
              offset,
              object_type,
              object_id,
              action.c_str());
        }
      }
      bit_cursor += door_record_bit_span;
    } else if (object_type == 9) {
      size_t name_offset = 0;
      size_t visual_transform_offset = 0;
      bool short_locstring = false;
      if (!TryFindPlaceableAddNameForAddRecordRewrite(
              *live_bytes,
              offset,
              record_end,
              &name_offset,
              &visual_transform_offset,
              &short_locstring)) {
        bit_cursor_reliable = false;
        offset = record_end > offset ? record_end : offset + 1;
        continue;
      }
      if (bit_cursor >= bits.size()) {
        bit_cursor_reliable = false;
        offset = record_end > offset ? record_end : offset + 1;
        continue;
      }
      const std::vector<unsigned char> before_placeable_bits = bits;
      const bool legacy_outer_locstring = bits[bit_cursor] != 0;
      const bool inline_locstring_name = !short_locstring && legacy_outer_locstring;
      const size_t source_name_inner_bits = inline_locstring_name ? 1 : 0;
      const size_t destination_name_inner_bits =
          (short_locstring || inline_locstring_name) ? 1 : 0;
      const size_t required_source_bits = 10 + source_name_inner_bits;
      if (before_placeable_bits.size() - bit_cursor < required_source_bits) {
        bit_cursor_reliable = false;
        offset = record_end > offset ? record_end : offset + 1;
        continue;
      }

      bool outer_changed = false;
      bool inner_changed = false;
      bool optional_changed = false;
      uint32_t semantic_state_bits_changed = 0;
      uint32_t inserted_bits_this_record = 0;
      const size_t optional_bit = bit_cursor + 2 + destination_name_inner_bits;
      const size_t final_visual_bit = bit_cursor + 10 + destination_name_inner_bits;
      const size_t record_bit_span = 11 + destination_name_inner_bits;
      const wchar_t* action = L"placeable-string-name+optional-target+final-visual";

      if (short_locstring) {
        // The hook forced short 1.69 locstring names through EE's locstring
        // reader, then supplied a synthetic inner "inline string" flag without
        // consuming a legacy bit. Preserve that branch packet-side so the
        // following appearance/useable flags still map to the same readers.
        if (!SetCnwMsbBit(&bits, bit_cursor, true, &outer_changed) ||
            !InsertCnwMsbBit(&bits, bit_cursor + 1, false)) {
          bit_cursor_reliable = false;
          offset = record_end > offset ? record_end : offset + 1;
          continue;
        }
        ++inserted_bits_this_record;
        WriteU32Le(live_bytes->data() + name_offset, 0);
        action = L"placeable-short-locstring-name-inner-string+optional-target+final-visual";
        if (result != nullptr) {
          ++result->short_locstrings_flattened;
        }
      } else if (inline_locstring_name) {
        // The legacy outer bit is true, so Diamond and EE both route through
        // the locstring helper and spend the following inner/client-tlk bit.
        // Keep the branch and force that existing inner bit false, matching
        // the old hook's consumed-original behavior.
        if (!SetCnwMsbBit(&bits, bit_cursor + 1, false, &inner_changed)) {
          bit_cursor_reliable = false;
          offset = record_end > offset ? record_end : offset + 1;
          continue;
        }
        action = L"placeable-inline-locstring-name-inner-string+optional-target+final-visual";
      }

      const bool optional_ok = SetCnwMsbBit(&bits, optional_bit, false, &optional_changed);
      if (!optional_ok || !InsertCnwMsbBit(&bits, final_visual_bit, false)) {
        bit_cursor_reliable = false;
        offset = record_end > offset ? record_end : offset + 1;
        continue;
      }
      ++inserted_bits_this_record;

      // Diamond and EE agree on the first post-name state BOOL and optional
      // target slot. After that, Diamond's var_4C belongs in EE's first
      // post-target storage slot and Diamond's var_48 belongs in EE's
      // SetUseable reader; keep the post-target state bits in read order and
      // add only EE's final visual/effect gate.
      const size_t source_shift = source_name_inner_bits;
      const size_t post_name_bit = bit_cursor + 1 + destination_name_inner_bits;
      if (bits.size() <= post_name_bit + 9) {
        bit_cursor_reliable = false;
        offset = record_end > offset ? record_end : offset + 1;
        continue;
      }
      const auto legacy_add_bit = [&](size_t source_relative_bit) -> bool {
        const size_t source_index = bit_cursor + source_relative_bit;
        return source_index < before_placeable_bits.size() &&
            before_placeable_bits[source_index] != 0;
      };
      const auto set_placeable_state_bit =
          [&](size_t destination_bit, bool value) -> bool {
            bool changed = false;
            if (!SetCnwMsbBit(&bits, destination_bit, value, &changed)) {
              return false;
            }
            if (changed) {
              ++semantic_state_bits_changed;
            }
            return true;
          };
      if (!set_placeable_state_bit(post_name_bit + 0, legacy_add_bit(1 + source_shift)) ||
          !set_placeable_state_bit(post_name_bit + 2, legacy_add_bit(3 + source_shift)) ||
          !set_placeable_state_bit(post_name_bit + 3, legacy_add_bit(4 + source_shift)) ||
          !set_placeable_state_bit(post_name_bit + 4, legacy_add_bit(5 + source_shift)) ||
          !set_placeable_state_bit(post_name_bit + 5, legacy_add_bit(6 + source_shift)) ||
          !set_placeable_state_bit(post_name_bit + 6, legacy_add_bit(7 + source_shift)) ||
          !set_placeable_state_bit(post_name_bit + 7, legacy_add_bit(8 + source_shift)) ||
          !set_placeable_state_bit(post_name_bit + 8, legacy_add_bit(9 + source_shift)) ||
          !set_placeable_state_bit(post_name_bit + 9, false)) {
        bit_cursor_reliable = false;
        offset = record_end > offset ? record_end : offset + 1;
        continue;
      }
      if (semantic_state_bits_changed != 0) {
        action = short_locstring
            ? L"placeable-short-locstring-name-inner-string+optional-target+semantic-state-map+final-visual"
            : (inline_locstring_name
                ? L"placeable-inline-locstring-name-inner-string+optional-target+semantic-state-map+final-visual"
                : L"placeable-string-name+optional-target+semantic-state-map+final-visual");
      }

      bool map_inserted = false;
      if (!LooksLikeExistingEeIdentityVisualTransformMap(
              *live_bytes,
              visual_transform_offset,
              record_end)) {
        if (visual_transform_offset > record_end ||
            visual_transform_offset > live_bytes->size()) {
          bit_cursor_reliable = false;
          offset = record_end > offset ? record_end : offset + 1;
          continue;
        }
        InsertEeLiveVisualTransformIdentityMap(live_bytes, visual_transform_offset);
        record_end += kEeLiveVisualTransformEmptyMapBytes;
        map_inserted = true;
      }

      if (result != nullptr) {
        if (outer_changed) {
          ++result->bits_set_or_extended;
        }
        if (inner_changed) {
          ++result->bits_set_or_extended;
        }
        if (optional_changed) {
          ++result->bits_set_or_extended;
        }
        result->bits_set_or_extended += semantic_state_bits_changed;
        result->bits_inserted += inserted_bits_this_record;
        ++result->records_rewritten;
        AppendLiveAddRecordRewriteDetail(
            result,
            offset,
            object_type,
            object_id,
            map_inserted ? L"placeable-bits+semantic-state-map+visual-map" : action);
        AppendLiveAddRecordRewriteDiagnostic(
            result,
            *live_bytes,
            offset,
            record_end,
            object_id,
            bit_cursor,
            optional_bit,
            final_visual_bit,
            record_bit_span,
            name_offset,
            visual_transform_offset,
            short_locstring,
            legacy_outer_locstring,
            optional_changed,
            map_inserted,
            before_placeable_bits,
            bits);
      }
      rewritten = true;
      bit_cursor += record_bit_span;
    } else if (object_type == 7) {
      uint8_t primary_flag = 0;
      uint8_t vertex_count = 0;
      if (!TryReadLegacyTriggerAddShape(
              *live_bytes,
              offset,
              record_end,
              &primary_flag,
              &vertex_count)) {
        bit_cursor_reliable = false;
        offset = record_end > offset ? record_end : offset + 1;
        continue;
      }

      std::vector<unsigned char> inserted_bits{0, static_cast<unsigned char>(primary_flag ? 1 : 0), 0};
      if (primary_flag != 0) {
        inserted_bits.push_back(0);
      }
      if (!InsertCnwMsbBits(&bits, bit_cursor, inserted_bits)) {
        bit_cursor_reliable = false;
        offset = record_end > offset ? record_end : offset + 1;
        continue;
      }

      WriteU32Le(live_bytes->data() + offset + 6, 0);
      (*live_bytes)[offset + 10] = 1;
      rewritten = true;
      if (result != nullptr) {
        ++result->records_rewritten;
        ++result->trigger_records_rewritten;
        result->bits_inserted += static_cast<uint32_t>(inserted_bits.size());
        wchar_t action[128]{};
        swprintf_s(
            action,
            L"trigger-locstring+primary=%u+cursor vertices=%u",
            static_cast<unsigned int>(primary_flag),
            static_cast<unsigned int>(vertex_count));
        AppendLiveAddRecordRewriteDetail(result, offset, object_type, object_id, action);
      }
      bit_cursor += inserted_bits.size();
    }

    offset = record_end > offset ? record_end : offset + 1;
  }

  if (!rewritten) {
    return false;
  }

  if (bit_cursor_reliable &&
      bit_cursor >= 3 &&
      bit_cursor < bits.size()) {
    // Once every top-level live record in this pass has been accounted for,
    // leftover fragment bits are not a legal later payload. EE's dispatcher
    // treats fragment-only leftovers as "more data" and reads one byte past
    // the byte stream, so repack to the validated post-record cursor.
    const size_t trimmed = bits.size() - bit_cursor;
    bits.resize(bit_cursor);
    if (result != nullptr) {
      result->fragment_bits_trimmed += static_cast<uint32_t>(
          std::min<size_t>(trimmed, std::numeric_limits<uint32_t>::max()));
      wchar_t reason[112]{};
      swprintf_s(reason, L"fragment-tail-repacked-at-validated-end bits=%zu", trimmed);
      AppendLiveAddRecordRewriteDetail(
          result,
          live_bytes->size(),
          0,
          0,
          reason);
    }
  }

  RefreshCnwFragmentFinalBitHeader(&bits);
  PackCnwMsbBits(bits, fragment_bytes);
  if (result != nullptr) {
    result->new_fragment_bytes = static_cast<uint32_t>(fragment_bytes->size());
  }
  return true;
}

bool LooksLikeLegacyCreatureAddTransformFields(
    const std::vector<unsigned char>& bytes,
    size_t offset,
    size_t record_end) {
  constexpr size_t kCreatureAddVisualTransformReadOffset = 32;
  if (offset > bytes.size() || record_end > bytes.size() ||
      record_end < offset + kCreatureAddVisualTransformReadOffset) {
    return false;
  }

  uint32_t object_id = 0;
  uint16_t state = 0;
  if (!TryReadU32LeFromBytes(bytes, offset + 2, &object_id) ||
      (object_id & 0x80000000u) == 0 ||
      !TryReadU16LeFromBytes(bytes, offset + 30, &state)) {
    return false;
  }

  for (size_t index = 0; index < 6; ++index) {
    float value = 0.0f;
    if (!TryReadFloatLeFromBytes(bytes, offset + 6 + index * 4, &value) ||
        !std::isfinite(value) ||
        std::fabs(value) > 1000000000.0f) {
      return false;
    }
  }
  return true;
}

void AppendLiveAddVisualTransformRewriteDetail(
    LiveAddVisualTransformRewriteResult* result,
    size_t record_offset,
    unsigned char object_type,
    uint32_t object_id,
    uint32_t bytes_inserted) {
  if (result == nullptr || result->details.size() > 1800) {
    return;
  }

  wchar_t text[256]{};
  swprintf_s(
      text,
      L"%s+%zu type=%u/%s id=0x%08X inserted=%u",
      result->details.empty() ? L"" : L"; ",
      record_offset,
      static_cast<unsigned int>(object_type),
      LegacyLiveObjectTypeName(object_type),
      object_id,
      bytes_inserted);
  result->details += text;
}

bool LooksLikeLegacyDoorAddNameAt(
    const std::vector<unsigned char>& bytes,
    size_t name_offset,
    size_t record_end) {
  if (name_offset > record_end || record_end > bytes.size()) {
    return false;
  }

  uint32_t inline_length = 0;
  size_t inline_end = 0;
  if (LooksLikeInlineCExoStringAt(bytes, name_offset, &inline_length, &inline_end, nullptr)) {
    return inline_end <= record_end &&
        record_end - inline_end >= 2 &&
        LooksLikeLegacyLiveObjectSubMessageBoundaryBytes(bytes, inline_end + 2);
  }

  const size_t legacy_tail_end = name_offset + 4 + 2;
  if (legacy_tail_end > record_end) {
    return false;
  }
  if (legacy_tail_end == record_end) {
    return true;
  }
  return LooksLikeExistingEeIdentityVisualTransformMap(bytes, legacy_tail_end, record_end);
}

bool TryFindLegacyDoorAddVisualTransformInsertOffset(
    const std::vector<unsigned char>& bytes,
    size_t record_offset,
    size_t record_end,
    size_t* insert_offset) {
  if (insert_offset != nullptr) {
    *insert_offset = 0;
  }
  if (record_offset > bytes.size() || record_end > bytes.size() ||
      record_end <= record_offset || bytes.size() - record_offset < 10 ||
      bytes[record_offset] != 'A' || bytes[record_offset + 1] != 10 ||
      !LooksLikeLegacyLiveObjectIdAt(bytes, record_offset + 2)) {
    return false;
  }

  uint32_t first_dword = 0;
  if (!TryReadU32LeFromBytes(bytes, record_offset + 6, &first_dword)) {
    return false;
  }

  const size_t object_start = record_offset + 2;
  const size_t name_offset = object_start + (first_dword == 0 ? 12 : 8);
  if (TryFindLegacyCompactDoorAddEmptyName(
          bytes,
          record_offset,
          record_end,
          nullptr,
          nullptr,
          nullptr)) {
    return false;
  }
  if (name_offset > record_end || !LooksLikeLegacyDoorAddNameAt(bytes, name_offset, record_end)) {
    return false;
  }

  if (insert_offset != nullptr) {
    *insert_offset = name_offset;
  }
  return true;
}

bool LooksLikeLegacyPlaceableAddTailAt(
    const std::vector<unsigned char>& bytes,
    size_t tail_offset,
    size_t record_end,
    size_t* legacy_tail_end) {
  if (legacy_tail_end != nullptr) {
    *legacy_tail_end = 0;
  }
  constexpr size_t kLegacyPlaceableTailBytes = 1 + 2 + 2;
  if (tail_offset > record_end || record_end - tail_offset < kLegacyPlaceableTailBytes) {
    return false;
  }
  const size_t tail_end = tail_offset + kLegacyPlaceableTailBytes;
  if (tail_end != record_end &&
      !LooksLikeExistingEeIdentityVisualTransformMap(bytes, tail_end, record_end)) {
    return false;
  }
  if (legacy_tail_end != nullptr) {
    *legacy_tail_end = tail_end;
  }
  return true;
}

bool TryFindLegacyPlaceableAddVisualTransformInsertOffset(
    const std::vector<unsigned char>& bytes,
    size_t record_offset,
    size_t record_end,
    size_t* insert_offset) {
  if (insert_offset != nullptr) {
    *insert_offset = 0;
  }
  if (record_offset > bytes.size() || record_end > bytes.size() ||
      record_end <= record_offset || bytes.size() - record_offset < 11 ||
      bytes[record_offset] != 'A' || bytes[record_offset + 1] != 9 ||
      !LooksLikeLegacyLiveObjectIdAt(bytes, record_offset + 2)) {
    return false;
  }

  const size_t name_offset = record_offset + 6;
  uint32_t inline_length = 0;
  size_t inline_end = 0;
  size_t legacy_tail_end = 0;
  if (LooksLikeInlineCExoStringAt(bytes, name_offset, &inline_length, &inline_end, nullptr)) {
    if (!LooksLikeLegacyPlaceableAddTailAt(bytes, inline_end, record_end, &legacy_tail_end)) {
      return false;
    }
  } else {
    const size_t short_tail_offset = name_offset + 4;
    if (!LooksLikeLegacyPlaceableAddTailAt(
            bytes,
            short_tail_offset,
            record_end,
            &legacy_tail_end)) {
      return false;
    }
  }

  if (insert_offset != nullptr) {
    *insert_offset = legacy_tail_end;
  }
  return true;
}

bool RewriteLegacyLiveAddVisualTransformMaps(
    std::vector<unsigned char>* live_bytes,
    LiveAddVisualTransformRewriteResult* result) {
  constexpr size_t kCreatureAddVisualTransformReadOffset = 32;
  if (result != nullptr) {
    result->records_examined = 0;
    result->maps_inserted = 0;
    result->bytes_inserted = 0;
    result->details.clear();
  }
  if (live_bytes == nullptr || live_bytes->size() < 10) {
    return false;
  }

  bool rewritten = false;
  for (size_t offset = 0; offset + 10 <= live_bytes->size();) {
    if (!LooksLikeLegacyLiveObjectSubMessageBoundaryBytes(*live_bytes, offset)) {
      ++offset;
      continue;
    }

    if (result != nullptr) {
      ++result->records_examined;
    }

    const unsigned char opcode = (*live_bytes)[offset];
    const unsigned char object_type = (*live_bytes)[offset + 1];
    size_t record_end = FindNextLegacyLiveObjectSubMessageBoundaryAfter(*live_bytes, offset);
    if (record_end > live_bytes->size()) {
      record_end = live_bytes->size();
    }

    if (opcode != 'A' || object_type != 5 ||
        !LooksLikeLegacyLiveObjectIdAt(*live_bytes, offset + 2)) {
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }

    size_t insert_offset = 0;
    insert_offset = offset + kCreatureAddVisualTransformReadOffset;
    if (record_end < insert_offset ||
        !LooksLikeLegacyCreatureAddTransformFields(*live_bytes, offset, record_end)) {
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }

    if (LooksLikeExistingEeIdentityVisualTransformMap(*live_bytes, insert_offset, record_end)) {
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }

    if (insert_offset != record_end) {
      offset = record_end > offset ? record_end : offset + 1;
      continue;
    }

    uint32_t object_id = 0;
    TryReadU32LeFromBytes(*live_bytes, offset + 2, &object_id);
    InsertEeLiveVisualTransformIdentityMap(live_bytes, insert_offset);
    record_end += kEeLiveVisualTransformEmptyMapBytes;
    rewritten = true;

    if (result != nullptr) {
      ++result->maps_inserted;
      result->bytes_inserted += static_cast<uint32_t>(kEeLiveVisualTransformEmptyMapBytes);
      AppendLiveAddVisualTransformRewriteDetail(
          result,
          offset,
          object_type,
          object_id,
          static_cast<uint32_t>(kEeLiveVisualTransformEmptyMapBytes));
    }

    offset = record_end > offset ? record_end : offset + 1;
  }

  return rewritten;
}

bool IsReasonableTlkResref(std::string_view value) {
  if (value.empty() || value.size() > 32) {
    return false;
  }
  for (char ch : value) {
    if (!IsResrefChar(static_cast<unsigned char>(ch))) {
      return false;
    }
  }
  return true;
}

std::string NormalizeTlkResref(std::string_view value) {
  std::string result = TrimAscii(value);
  while (!result.empty() && (result.back() == '\0' || result.back() == ' ')) {
    result.pop_back();
  }

  const std::string lowered = LowerAscii(result);
  if (lowered.size() > 4 && lowered.substr(lowered.size() - 4) == ".tlk") {
    result.resize(result.size() - 4);
  }
  return IsReasonableTlkResref(result) ? result : std::string();
}

std::wstring JoinAsciiListPreview(const std::vector<std::string>& values, size_t max_count = 8) {
  if (values.empty()) {
    return L"<empty>";
  }

  std::wstring result;
  const size_t count = std::min(values.size(), max_count);
  for (size_t index = 0; index < count; ++index) {
    if (index != 0) {
      result.append(L", ");
    }
    result.append(AsciiPreviewToWide(values[index], 32));
  }
  if (values.size() > count) {
    result.append(L", ...");
  }
  return result;
}

std::wstring HgModuleHakOrderPreview(size_t max_count = 8) {
  std::wstring result;
  const size_t count = std::min(kHgModuleHakOrderTopFirst.size(), max_count);
  for (size_t index = 0; index < count; ++index) {
    if (index != 0) {
      result.append(L", ");
    }
    result.append(AsciiPreviewToWide(kHgModuleHakOrderTopFirst[index], 32));
  }
  if (kHgModuleHakOrderTopFirst.size() > count) {
    result.append(L", ...");
  }
  return result.empty() ? L"<empty>" : result;
}

bool ReadModuleInfoRawString(const unsigned char* packet, size_t packet_size, size_t* cursor, std::string* value) {
  if (packet == nullptr || cursor == nullptr || value == nullptr || *cursor > packet_size ||
      packet_size - *cursor < 4) {
    return false;
  }

  const uint32_t length = ReadU32Le(packet + *cursor);
  *cursor += 4;
  if (length > kMaxReasonableModuleInfoString || length > packet_size - *cursor) {
    return false;
  }

  value->assign(
      reinterpret_cast<const char*>(packet + *cursor),
      reinterpret_cast<const char*>(packet + *cursor + length));
  *cursor += length;
  return true;
}

bool TryParseModuleInfoPacket(const unsigned char* packet, size_t packet_size, ModuleInfoPacketView* view) {
  if (view != nullptr) {
    *view = ModuleInfoPacketView{};
  }
  if (packet == nullptr || view == nullptr || packet_size < 16 || !IsHighLevelGameplayEnvelope(packet[0]) ||
      packet[1] != 3 || packet[2] != 1) {
    return false;
  }

  const uint32_t declared = ReadU32Le(packet + 3);
  if (declared < 4 || declared > packet_size) {
    return false;
  }

  size_t cursor = 7;
  std::string module_name;
  std::string module_description;
  std::string custom_tlk;
  if (!ReadModuleInfoRawString(packet, packet_size, &cursor, &module_name) ||
      !ReadModuleInfoRawString(packet, packet_size, &cursor, &module_description)) {
    return false;
  }

  if (cursor >= packet_size) {
    return false;
  }
  ++cursor;
  if (!ReadModuleInfoRawString(packet, packet_size, &cursor, &custom_tlk)) {
    return false;
  }

  view->declared = declared;
  view->cursor_after_custom_tlk = cursor;
  view->module_name = std::move(module_name);
  view->module_description = std::move(module_description);
  view->custom_tlk = std::move(custom_tlk);
  view->normalized_custom_tlk = NormalizeTlkResref(view->custom_tlk);
  return true;
}

bool TryFindLegacyModuleHakBlock(
    const unsigned char* packet,
    size_t packet_size,
    const ModuleInfoPacketView& view,
    LegacyHakBlockCandidate* candidate) {
  if (candidate != nullptr) {
    *candidate = LegacyHakBlockCandidate{};
  }
  if (packet == nullptr || candidate == nullptr || view.cursor_after_custom_tlk >= packet_size) {
    return false;
  }

  const size_t search_start = view.cursor_after_custom_tlk;
  const size_t search_end = std::min(packet_size, search_start + 32);
  for (size_t offset = search_start; offset < search_end; ++offset) {
    const uint32_t count = packet[offset];
    if (count > kMaxReasonableLegacyHakCount) {
      continue;
    }

    const size_t skip = 1 + static_cast<size_t>(count) * kLegacyHakResRefBytes + kLegacyModuleResRefBytes;
    if (skip > packet_size - offset || packet_size - offset - skip < 4) {
      continue;
    }

    const uint32_t resource_count = ReadU32Le(packet + offset + skip);
    if (resource_count == 0 || resource_count > kMaxReasonableModuleResourceCount) {
      continue;
    }

    std::vector<std::string> haks;
    haks.reserve(count);
    bool valid = true;
    for (uint32_t index = 0; index < count; ++index) {
      std::string hak;
      if (!ExtractFixedResref16(packet + offset + 1 + static_cast<size_t>(index) * kLegacyHakResRefBytes, &hak)) {
        valid = false;
        break;
      }
      haks.push_back(std::move(hak));
    }
    if (!valid) {
      continue;
    }

    std::string module_resref;
    if (!ExtractFixedResref16AllowEmpty(
            packet + offset + 1 + static_cast<size_t>(count) * kLegacyHakResRefBytes,
            &module_resref)) {
      continue;
    }

    candidate->offset = offset;
    candidate->hak_count = count;
    candidate->skipped_bytes = static_cast<uint32_t>(skip);
    candidate->resource_count_peek = resource_count;
    candidate->haks = std::move(haks);
    candidate->module_resref = std::move(module_resref);
    return true;
  }

  return false;
}

struct LoadModuleResourceNameTableRewrite {
  uint32_t old_count = 0;
  uint32_t new_count = 0;
  uint32_t old_declared = 0;
  uint32_t new_declared = 0;
  uint32_t tail_removed = 0;
  uint32_t zero_length_name_repairs = 0;
  bool zero_length_name_terminator = false;
  uint32_t old_fragment_bytes = 0;
  uint32_t new_fragment_bytes = 0;
  uint8_t tail_byte = 0;
};

bool IsLikelyLoadModuleAreaNameByte(unsigned char ch) {
  return ch == '\t' || ch == '\r' || ch == '\n' || (ch >= 0x20 && ch <= 0x7E);
}

bool IsLikelyLoadModuleAreaResourceId(uint32_t id) {
  return (id & 0x80000000u) != 0 && id != 0xFFFFFFFFu;
}

bool IsLikelyLoadModuleAreaName(
    const std::vector<unsigned char>& payload,
    size_t offset,
    uint32_t length,
    uint32_t declared) {
  if (length == 0 ||
      length > kMaxReasonableLoadModuleAreaNameLength ||
      offset > declared ||
      length > declared - offset) {
    return false;
  }
  for (uint32_t index = 0; index < length; ++index) {
    if (!IsLikelyLoadModuleAreaNameByte(payload[offset + index])) {
      return false;
    }
  }
  return true;
}

bool TryInferZeroLengthLoadModuleAreaName(
    const std::vector<unsigned char>& payload,
    size_t entry_offset,
    uint32_t declared,
    uint32_t* inferred_length) {
  if (inferred_length != nullptr) {
    *inferred_length = 0;
  }
  if (inferred_length == nullptr ||
      entry_offset + 8 >= declared ||
      declared > payload.size()) {
    return false;
  }

  const size_t name_offset = entry_offset + 8;
  const uint32_t max_candidate = static_cast<uint32_t>(std::min<size_t>(
      kMaxReasonableLoadModuleAreaNameLength,
      declared - name_offset));
  for (uint32_t candidate_length = 1; candidate_length <= max_candidate; ++candidate_length) {
    if (!IsLikelyLoadModuleAreaName(payload, name_offset, candidate_length, declared)) {
      break;
    }

    const size_t next_entry_offset = name_offset + candidate_length;
    if (next_entry_offset + 8 > declared) {
      continue;
    }
    const uint32_t next_id = ReadU32Le(payload.data() + next_entry_offset);
    const uint32_t next_name_length = ReadU32Le(payload.data() + next_entry_offset + 4);
    if (!IsLikelyLoadModuleAreaResourceId(next_id) ||
        next_name_length > kMaxReasonableLoadModuleAreaNameLength ||
        next_entry_offset + 8 > declared ||
        next_name_length > declared - next_entry_offset - 8) {
      continue;
    }
    if (next_name_length != 0 &&
        !IsLikelyLoadModuleAreaName(
            payload,
            next_entry_offset + 8,
            next_name_length,
            declared)) {
      continue;
    }

    *inferred_length = candidate_length;
    return true;
  }

  return false;
}

bool TryRewriteLoadModuleResourceNameTableTail(
    std::vector<unsigned char>* payload,
    size_t count_offset,
    LoadModuleResourceNameTableRewrite* rewrite) {
  if (rewrite != nullptr) {
    *rewrite = LoadModuleResourceNameTableRewrite{};
  }
  if (payload == nullptr || payload->size() < 8 || count_offset + 4 > payload->size() ||
      !IsHighLevelGameplayEnvelope((*payload)[0]) || (*payload)[1] != 3 || (*payload)[2] != 1) {
    return false;
  }

  const uint32_t declared = ReadU32Le(payload->data() + 3);
  if (declared < 7 || declared > payload->size() || count_offset + 4 > declared) {
    return false;
  }

  const uint32_t old_count = ReadU32Le(payload->data() + count_offset);
  if (old_count == 0 || old_count > kMaxReasonableModuleResourceCount) {
    return false;
  }

  size_t cursor = count_offset + 4;
  uint32_t valid_count = 0;
  uint32_t zero_length_name_repairs = 0;
  bool zero_length_name_terminator = false;
  while (valid_count < old_count) {
    if (cursor + 8 > declared) {
      break;
    }

    uint32_t name_length = ReadU32Le(payload->data() + cursor + 4);
    if (name_length == 0) {
      if (valid_count >= kLoadModuleZeroNameTerminatorMinEntries) {
        cursor += 8;
        ++valid_count;
        zero_length_name_terminator = true;
        break;
      }

      uint32_t inferred_length = 0;
      if (TryInferZeroLengthLoadModuleAreaName(
              *payload,
              cursor,
              declared,
              &inferred_length)) {
        WriteU32Le(payload->data() + cursor + 4, inferred_length);
        name_length = inferred_length;
        ++zero_length_name_repairs;
      }
    }
    if (name_length > kMaxReasonableLoadModuleAreaNameLength ||
        name_length > declared - cursor - 8) {
      break;
    }

    cursor += 8 + static_cast<size_t>(name_length);
    ++valid_count;
  }

  if (valid_count == 0 || (valid_count >= old_count && !zero_length_name_terminator)) {
    return false;
  }

  // Diamond keeps a larger resource/name tail here. EE's LoadModule only
  // consumes the area-name table, then one read-buffer byte and two BOOL bits.
  // Keep the accepted table entries, synthesize a neutral byte, and preserve
  // the fragment bytes so the shared BOOL tail is still read from the stream.
  const size_t fragment_offset = declared;
  if (cursor + 1 > fragment_offset) {
    return false;
  }
  std::vector<unsigned char> fragments(
      payload->begin() + static_cast<std::ptrdiff_t>(fragment_offset),
      payload->end());

  const uint32_t new_declared = static_cast<uint32_t>(cursor + 1);
  const uint32_t tail_removed = declared - new_declared;
  if (tail_removed == 0) {
    return false;
  }

  WriteU32Le(payload->data() + count_offset, valid_count);
  payload->resize(cursor);
  payload->push_back(0);
  payload->insert(payload->end(), fragments.begin(), fragments.end());
  WriteU32Le(payload->data() + 3, new_declared);

  if (rewrite != nullptr) {
    rewrite->old_count = old_count;
    rewrite->new_count = valid_count;
    rewrite->old_declared = declared;
    rewrite->new_declared = new_declared;
    rewrite->tail_removed = tail_removed;
    rewrite->zero_length_name_repairs = zero_length_name_repairs;
    rewrite->zero_length_name_terminator = zero_length_name_terminator;
    rewrite->old_fragment_bytes = static_cast<uint32_t>(fragments.size());
    rewrite->new_fragment_bytes = static_cast<uint32_t>(fragments.size());
    rewrite->tail_byte = 0;
  }
  return true;
}

std::wstring FormatLoadModuleResourceNameTableSummary(
    const std::vector<unsigned char>& payload,
    size_t count_offset) {
  if (payload.size() < 8 || count_offset + 4 > payload.size()) {
    return L"unavailable";
  }

  const uint32_t declared = ReadU32Le(payload.data() + 3);
  if (declared < 7 || declared > payload.size() || count_offset + 4 > declared) {
    return L"invalid-declared=" + std::to_wstring(declared) +
        L" payload=" + std::to_wstring(payload.size()) +
        L" count_offset=" + std::to_wstring(count_offset);
  }

  const uint32_t count = ReadU32Le(payload.data() + count_offset);
  size_t cursor = count_offset + 4;
  uint32_t parsed = 0;
  uint32_t zero_length_names = 0;
  std::wstring samples;
  std::wstring stop_reason = L"complete";
  size_t stop_offset = cursor;
  uint32_t stop_id = 0;
  uint32_t stop_length = 0;

  auto append_sample = [&](uint32_t index, size_t offset, uint32_t id, uint32_t name_length, std::string_view name) {
    const bool interesting =
        index < 6 ||
        (index >= 64 && index <= 78) ||
        index + 4 >= count ||
        name_length == 0 ||
        name_length > 512;
    if (!interesting) {
      return;
    }
    if (!samples.empty()) {
      samples.append(L"; ");
    }
    wchar_t id_text[16]{};
    swprintf_s(id_text, L"0x%08X", id);
    samples.append(L"#");
    samples.append(std::to_wstring(index));
    samples.append(L"@");
    samples.append(std::to_wstring(offset));
    samples.append(L" id=");
    samples.append(id_text);
    samples.append(L" len=");
    samples.append(std::to_wstring(name_length));
    samples.append(L" '");
    samples.append(AsciiPreviewToWide(name, 48));
    samples.append(L"'");
  };

  while (parsed < count) {
    if (cursor + 8 > declared) {
      stop_reason = L"entry-header-past-declared";
      stop_offset = cursor;
      break;
    }

    const size_t entry_offset = cursor;
    const uint32_t id = ReadU32Le(payload.data() + cursor);
    const uint32_t name_length = ReadU32Le(payload.data() + cursor + 4);
    cursor += 8;
    if (name_length > declared - cursor) {
      stop_reason = L"name-past-declared";
      stop_offset = entry_offset;
      stop_id = id;
      stop_length = name_length;
      break;
    }

    std::string_view name(
        reinterpret_cast<const char*>(payload.data() + cursor),
        name_length);
    if (name_length == 0) {
      ++zero_length_names;
    }
    append_sample(parsed, entry_offset, id, name_length, name);
    cursor += name_length;
    stop_offset = cursor;
    ++parsed;
  }

  const size_t boundary_offset = stop_offset < declared ? stop_offset : declared;
  const size_t boundary_available = boundary_offset < payload.size()
      ? std::min<size_t>(payload.size() - boundary_offset, 96)
      : 0;
  const size_t before_offset = boundary_offset > 32 ? boundary_offset - 32 : count_offset;
  const size_t before_available = before_offset < payload.size() && boundary_offset > before_offset
      ? std::min<size_t>(boundary_offset - before_offset, 64)
      : 0;

  wchar_t stop_id_text[16]{};
  swprintf_s(stop_id_text, L"0x%08X", stop_id);
  std::wstring summary =
      L"declared=" + std::to_wstring(declared) +
      L" payload=" + std::to_wstring(payload.size()) +
      L" count_offset=" + std::to_wstring(count_offset) +
      L" count=" + std::to_wstring(count) +
      L" parsed=" + std::to_wstring(parsed) +
      L" zero_names=" + std::to_wstring(zero_length_names) +
      L" stop='" + stop_reason + L"'" +
      L" stop_offset=" + std::to_wstring(stop_offset) +
      L" stop_id=" + stop_id_text +
      L" stop_len=" + std::to_wstring(stop_length) +
      L" remaining=" + (declared >= stop_offset ? std::to_wstring(declared - stop_offset) : L"past") +
      L" before=[" + (before_available != 0
          ? FormatLimitedBytes(payload.data() + before_offset, before_available, before_available)
          : L"<none>") +
      L"] after=[" + (boundary_available != 0
          ? FormatLimitedBytes(payload.data() + boundary_offset, boundary_available, boundary_available)
          : L"<none>") +
      L"] samples=[" + (samples.empty() ? L"<none>" : samples) + L"]";
  return summary;
}

bool AppendEeLoadModuleFeatureTailBits(
    std::vector<unsigned char>* payload,
    uint32_t* inserted_bits,
    uint32_t* old_fragment_bytes,
    uint32_t* new_fragment_bytes) {
  if (inserted_bits != nullptr) {
    *inserted_bits = 0;
  }
  if (old_fragment_bytes != nullptr) {
    *old_fragment_bytes = 0;
  }
  if (new_fragment_bytes != nullptr) {
    *new_fragment_bytes = 0;
  }
  if (payload == nullptr || payload->size() < 8 || !IsHighLevelGameplayEnvelope((*payload)[0]) ||
      (*payload)[1] != 3 || (*payload)[2] != 1) {
    return false;
  }

  const uint32_t declared = ReadU32Le(payload->data() + 3);
  if (declared < 3 || declared > payload->size()) {
    return false;
  }

  const size_t fragment_offset = declared;
  std::vector<unsigned char> fragments(
      payload->begin() + static_cast<std::ptrdiff_t>(fragment_offset),
      payload->end());
  if (old_fragment_bytes != nullptr) {
    *old_fragment_bytes = static_cast<uint32_t>(fragments.size());
  }

  std::vector<unsigned char> bits;
  if (fragments.empty()) {
    bits = {0, 0, 0};
  } else {
    UnpackCnwMsbBits(fragments, &bits);
    const uint32_t final_fragment_bits =
        ((fragments[0] & 0x80u) != 0 ? 4u : 0u) |
        ((fragments[0] & 0x40u) != 0 ? 2u : 0u) |
        ((fragments[0] & 0x20u) != 0 ? 1u : 0u);
    const size_t meaningful_bits = final_fragment_bits == 0
        ? fragments.size() * 8
        : (fragments.size() - 1) * 8 + static_cast<size_t>(final_fragment_bits);
    if (meaningful_bits < 3 || meaningful_bits > bits.size()) {
      return false;
    }
    bits.resize(meaningful_bits);
  }

  // The proxy presents an EE-facing server build. EE therefore reads the two
  // optional LoadModule BOOLs behind feature gates 0x22 and 0x23, while HG's
  // 1.69 server stream only contains the shared BYTE + BOOL + BOOL tail.
  bits.push_back(0);
  bits.push_back(0);
  const uint8_t final_fragment_bits = static_cast<uint8_t>(bits.size() % 8u);
  bits[0] = (final_fragment_bits & 0x04u) != 0 ? 1 : 0;
  bits[1] = (final_fragment_bits & 0x02u) != 0 ? 1 : 0;
  bits[2] = (final_fragment_bits & 0x01u) != 0 ? 1 : 0;

  std::vector<unsigned char> rewritten_fragments;
  PackCnwMsbBits(bits, &rewritten_fragments);
  if (rewritten_fragments.empty()) {
    rewritten_fragments.push_back(0);
  }

  payload->resize(fragment_offset);
  payload->insert(payload->end(), rewritten_fragments.begin(), rewritten_fragments.end());
  if (inserted_bits != nullptr) {
    *inserted_bits = 2;
  }
  if (new_fragment_bytes != nullptr) {
    *new_fragment_bytes = static_cast<uint32_t>(rewritten_fragments.size());
  }
  return true;
}

bool BnxrAppendCountedString(std::vector<unsigned char>* bytes, std::string_view value) {
  if (bytes == nullptr || value.size() > 255 ||
      bytes->size() > kMaxReasonableReassembledGameplayPayload - 1 ||
      value.size() > kMaxReasonableReassembledGameplayPayload - bytes->size() - 1) {
    return false;
  }
  bytes->push_back(static_cast<unsigned char>(value.size()));
  bytes->insert(bytes->end(), value.begin(), value.end());
  return true;
}

bool ParseBnxrModuleName(
    const std::vector<unsigned char>& packet,
    std::string* module_name,
    size_t* module_end) {
  if (module_name != nullptr) {
    module_name->clear();
  }
  if (module_end != nullptr) {
    *module_end = 0;
  }
  if (packet.size() < kBnxrModuleNameOffset ||
      !StartsWith(packet.data(), packet.size(), "BNXR") ||
      packet[6] != kBnxrExtendedMarker) {
    return false;
  }

  const size_t length_hint_end =
      kBnxrModuleNameOffset + static_cast<size_t>(packet[18]);
  if (packet.size() < length_hint_end) {
    return false;
  }

  const size_t name_length = packet[kBnxrModuleNameLengthOffset];
  const size_t end = kBnxrModuleNameOffset + name_length;
  if (end > packet.size()) {
    return false;
  }
  if (module_name != nullptr) {
    module_name->assign(
        reinterpret_cast<const char*>(packet.data() + kBnxrModuleNameOffset),
        name_length);
  }
  if (module_end != nullptr) {
    *module_end = end;
  }
  return true;
}

bool TrySkipExistingBnxrNwsyncAdvert(
    const std::vector<unsigned char>& packet,
    size_t module_end,
    size_t* suffix_start) {
  if (suffix_start != nullptr) {
    *suffix_start = module_end;
  }
  if (suffix_start == nullptr || module_end >= packet.size() ||
      packet[module_end] != kBnxrNwsyncSectionTag) {
    return false;
  }

  size_t cursor = module_end + 1;
  if (cursor >= packet.size()) {
    return false;
  }
  if (packet[cursor++] == 0) {
    *suffix_start = cursor;
    return true;
  }
  if (cursor >= packet.size()) {
    return false;
  }
  const size_t url_length = packet[cursor++];
  if (url_length > packet.size() - cursor) {
    return false;
  }
  cursor += url_length;
  if (cursor >= packet.size()) {
    return false;
  }
  const size_t primary_hash_length = packet[cursor++];
  if (primary_hash_length > packet.size() - cursor) {
    return false;
  }
  cursor += primary_hash_length;
  if (cursor >= packet.size()) {
    return false;
  }
  const size_t manifest_count = packet[cursor++];
  for (size_t index = 0; index < manifest_count; ++index) {
    if (cursor + 3 > packet.size()) {
      return false;
    }
    cursor += 2;  // flags, language
    const size_t hash_length = packet[cursor++];
    if (hash_length > packet.size() - cursor) {
      return false;
    }
    cursor += hash_length;
  }
  *suffix_start = cursor;
  return true;
}

bool FindBnxrSuffixAfterAdvertSlot(
    const std::vector<unsigned char>& packet,
    size_t module_end,
    size_t* suffix_start,
    bool* replaced_existing,
    unsigned char* consumed_section_tag) {
  if (suffix_start != nullptr) {
    *suffix_start = module_end;
  }
  if (replaced_existing != nullptr) {
    *replaced_existing = false;
  }
  if (consumed_section_tag != nullptr) {
    *consumed_section_tag = 0;
  }
  if (suffix_start == nullptr || replaced_existing == nullptr ||
      consumed_section_tag == nullptr || module_end > packet.size()) {
    return false;
  }

  if (module_end == packet.size()) {
    return true;
  }

  *consumed_section_tag = packet[module_end];
  if (packet[module_end] == kBnxrNwsyncSectionTag) {
    *replaced_existing = TrySkipExistingBnxrNwsyncAdvert(packet, module_end, suffix_start);
    return *replaced_existing;
  }

  // EE's BNXR reader probes exactly one byte after the module name as an
  // optional extended-section tag before it reads the following description.
  // When injecting our own tag, preserve bytes after that consumed probe byte.
  *suffix_start = module_end + 1;
  return true;
}

bool BuildBnxrNwsyncAdvertSection(const BridgeRuntime* runtime, std::vector<unsigned char>* section) {
  if (runtime == nullptr || section == nullptr ||
      runtime->options.nwsync_repository_hash.empty() ||
      runtime->options.nwsync_url.empty() ||
      runtime->options.nwsync_manifests.size() > 255 ||
      runtime->options.nwsync_url.size() > 255 ||
      runtime->options.nwsync_repository_hash.size() > 255) {
    return false;
  }

  section->clear();
  section->reserve(
      1 + 1 + 1 + runtime->options.nwsync_url.size() + 1 +
      runtime->options.nwsync_repository_hash.size() + 1 +
      runtime->options.nwsync_manifests.size() * 43);
  section->push_back(kBnxrNwsyncSectionTag);
  section->push_back(1);
  if (!BnxrAppendCountedString(section, runtime->options.nwsync_url) ||
      !BnxrAppendCountedString(section, runtime->options.nwsync_repository_hash)) {
    return false;
  }
  section->push_back(static_cast<unsigned char>(runtime->options.nwsync_manifests.size()));
  for (const NwsyncManifestAdvert& manifest : runtime->options.nwsync_manifests) {
    if (manifest.hash.size() > 255 ||
        section->size() > kMaxReasonableReassembledGameplayPayload - 3 ||
        manifest.hash.size() > kMaxReasonableReassembledGameplayPayload - section->size() - 3) {
      return false;
    }
    section->push_back(manifest.flags);
    section->push_back(manifest.language);
    if (!BnxrAppendCountedString(section, manifest.hash)) {
      return false;
    }
  }
  return true;
}

bool RewriteBnxrNwsyncAdvertisementIfPossible(BridgeRuntime* runtime, std::vector<unsigned char>* packet) {
  if (runtime == nullptr || packet == nullptr ||
      !runtime->options.enable_nwsync_advertisement ||
      !StartsWith(packet->data(), packet->size(), "BNXR")) {
    return false;
  }

  std::string module_name;
  size_t module_end = 0;
  if (!ParseBnxrModuleName(*packet, &module_name, &module_end)) {
    ++runtime->bnxr_nwsync_advert_skipped_count;
    if (runtime->bnxr_nwsync_advert_skipped_count <= 8 || runtime->options.packet_dump) {
      LogFormat(
          L"server->client BNXR NWSync rewrite skipped: parse failed skips=%llu packet=%s",
          static_cast<unsigned long long>(runtime->bnxr_nwsync_advert_skipped_count),
          PacketPrefix(packet->data(), packet->size()).c_str());
    }
    return false;
  }
  runtime->latest_bnxr_module_name = module_name;

  std::vector<unsigned char> advert_section;
  if (!BuildBnxrNwsyncAdvertSection(runtime, &advert_section)) {
    ++runtime->bnxr_nwsync_advert_skipped_count;
    if (runtime->bnxr_nwsync_advert_skipped_count <= 8 || runtime->options.packet_dump) {
      LogFormat(
          L"server->client BNXR NWSync rewrite skipped: invalid advert hash='%s' url='%s' manifests=%zu",
          AsciiPreviewToWide(runtime->options.nwsync_repository_hash).c_str(),
          AsciiPreviewToWide(runtime->options.nwsync_url).c_str(),
          runtime->options.nwsync_manifests.size());
    }
    return false;
  }

  size_t suffix_start = module_end;
  bool replaced_existing = false;
  unsigned char consumed_section_tag = 0;
  if (!FindBnxrSuffixAfterAdvertSlot(
          *packet,
          module_end,
          &suffix_start,
          &replaced_existing,
          &consumed_section_tag)) {
    ++runtime->bnxr_nwsync_advert_skipped_count;
    if (runtime->bnxr_nwsync_advert_skipped_count <= 8 || runtime->options.packet_dump) {
      LogFormat(
          L"server->client BNXR NWSync rewrite skipped: existing section tag malformed tag=0x%02X old_len=%zu module_end=%zu packet=%s",
          static_cast<unsigned int>(consumed_section_tag),
          packet->size(),
          module_end,
          PacketPrefix(packet->data(), packet->size()).c_str());
    }
    return false;
  }
  if (module_end + advert_section.size() > kMaxReasonableReassembledGameplayPayload ||
      packet->size() - suffix_start >
          kMaxReasonableReassembledGameplayPayload - module_end - advert_section.size()) {
    ++runtime->bnxr_nwsync_advert_skipped_count;
    LogFormat(
        L"server->client BNXR NWSync rewrite refused: rewritten packet too large old=%zu module_end=%zu advert=%zu suffix=%zu",
        packet->size(),
        module_end,
        advert_section.size(),
        packet->size() - suffix_start);
    return false;
  }

  std::vector<unsigned char> rewritten;
  rewritten.reserve(module_end + advert_section.size() + (packet->size() - suffix_start));
  rewritten.insert(rewritten.end(), packet->begin(), packet->begin() + static_cast<std::ptrdiff_t>(module_end));
  rewritten.insert(rewritten.end(), advert_section.begin(), advert_section.end());
  rewritten.insert(rewritten.end(), packet->begin() + static_cast<std::ptrdiff_t>(suffix_start), packet->end());

  const size_t old_size = packet->size();
  *packet = std::move(rewritten);
  ++runtime->bnxr_nwsync_advert_rewrite_count;
  LogFormat(
      L"server->client BNXR NWSync advert rewritten #%llu: module='%s' old_len=%zu new_len=%zu module_end=%zu inserted=%zu suffix_start=%zu suffix_preserved=%zu consumed_tag=0x%02X replaced_existing=%d root='%s' url='%s' manifests=%zu",
      static_cast<unsigned long long>(runtime->bnxr_nwsync_advert_rewrite_count),
      AsciiPreviewToWide(module_name).c_str(),
      old_size,
      packet->size(),
      module_end,
      advert_section.size(),
      suffix_start,
      old_size - suffix_start,
      static_cast<unsigned int>(consumed_section_tag),
      replaced_existing ? 1 : 0,
      AsciiPreviewToWide(runtime->options.nwsync_repository_hash).c_str(),
      AsciiPreviewToWide(runtime->options.nwsync_url).c_str(),
      runtime->options.nwsync_manifests.size());
  return true;
}

bool ReadFirstMsbBits(const unsigned char* bytes, size_t length, uint32_t bit_count, uint32_t* value) {
  if (bytes == nullptr || value == nullptr || bit_count > 31 || length * 8 < bit_count) {
    return false;
  }
  uint32_t result = 0;
  for (uint32_t bit = 0; bit < bit_count; ++bit) {
    const size_t byte_index = bit / 8;
    const uint32_t bit_index = bit % 8;
    result = (result << 1) | ((bytes[byte_index] >> (7 - bit_index)) & 1u);
  }
  *value = result;
  return true;
}

bool IsLegacyQuickbarPlausibleType(uint8_t type) {
  return type <= 48;
}

bool LegacyQuickbarTypeHasNoPayload(uint8_t type) {
  switch (type) {
    case 0:
    case 5:
    case 6:
    case 7:
    case 9:
    case 19:
    case 20:
    case 21:
    case 22:
    case 23:
    case 24:
    case 25:
    case 26:
    case 35:
    case 36:
    case 38:
    case 40:
    case 41:
      return true;
    default:
      return false;
  }
}

bool LegacyQuickbarTypeHasIntPayload(uint8_t type) {
  switch (type) {
    case 3:
    case 4:
    case 8:
    case 10:
    case 27:
    case 28:
    case 31:
    case 32:
    case 33:
    case 34:
    case 37:
    case 42:
    case 43:
    case 45:
    case 46:
    case 47:
    case 48:
      return true;
    default:
      return false;
  }
}

std::string FixedResrefPreview(const unsigned char* bytes, size_t length) {
  if (bytes == nullptr || length < kCResRefTextBytes) {
    return {};
  }
  std::string result;
  result.reserve(kCResRefTextBytes);
  for (size_t index = 0; index < kCResRefTextBytes; ++index) {
    const unsigned char ch = bytes[index];
    if (ch == 0) {
      break;
    }
    result.push_back(ch >= 0x20 && ch <= 0x7E ? static_cast<char>(ch) : '.');
  }
  return result;
}

bool ReadQuickbarStringPreview(
    const unsigned char* read_buffer,
    size_t read_size,
    size_t* cursor,
    std::string* preview) {
  if (preview != nullptr) {
    preview->clear();
  }
  if (read_buffer == nullptr || cursor == nullptr || *cursor > read_size || read_size - *cursor < 4) {
    return false;
  }

  const uint32_t length = ReadU32Le(read_buffer + *cursor);
  constexpr uint32_t kMaxReasonableQuickbarStringBytes = 4096;
  if (length > kMaxReasonableQuickbarStringBytes || length > read_size - *cursor - 4) {
    return false;
  }

  *cursor += 4;
  if (preview != nullptr) {
    preview->assign(
        reinterpret_cast<const char*>(read_buffer + *cursor),
        reinterpret_cast<const char*>(read_buffer + *cursor + length));
  }
  *cursor += length;
  return true;
}

bool AdvanceLegacyQuickbarNonItem(
    const unsigned char* read_buffer,
    size_t read_size,
    size_t cursor,
    QuickbarButtonInventory* button,
    size_t* next_cursor) {
  if (read_buffer == nullptr || button == nullptr || next_cursor == nullptr || cursor >= read_size) {
    return false;
  }

  QuickbarButtonInventory parsed = *button;
  parsed.offset = cursor;
  parsed.type = read_buffer[cursor++];

  if (!IsLegacyQuickbarPlausibleType(parsed.type) || parsed.type == 1) {
    return false;
  }

  if (LegacyQuickbarTypeHasNoPayload(parsed.type)) {
    parsed.parsed = true;
    parsed.no_payload = true;
    parsed.next_offset = cursor;
    *button = parsed;
    *next_cursor = cursor;
    return true;
  }

  if (parsed.type == 2) {
    if (read_size - cursor < 7) {
      return false;
    }
    parsed.parsed = true;
    parsed.spell = true;
    parsed.byte_payload = true;
    parsed.byte_value = read_buffer[cursor++];
    parsed.int_payload = true;
    parsed.int_value = ReadU32Le(read_buffer + cursor);
    cursor += 4;
    parsed.spell_metamagic = read_buffer[cursor];
    parsed.spell_domain = read_buffer[cursor + 1];
    parsed.next_offset = cursor + 2;
    *button = parsed;
    *next_cursor = parsed.next_offset;
    return true;
  }

  if (LegacyQuickbarTypeHasIntPayload(parsed.type)) {
    if (read_size - cursor < 4) {
      return false;
    }
    parsed.parsed = true;
    parsed.int_payload = true;
    parsed.int_value = ReadU32Le(read_buffer + cursor);
    parsed.next_offset = cursor + 4;
    *button = parsed;
    *next_cursor = parsed.next_offset;
    return true;
  }

  if (parsed.type == 44) {
    if (read_size - cursor < 5) {
      return false;
    }
    parsed.parsed = true;
    parsed.int_payload = true;
    parsed.int_value = ReadU32Le(read_buffer + cursor);
    parsed.byte_payload = true;
    parsed.byte_value = read_buffer[cursor + 4];
    parsed.next_offset = cursor + 5;
    *button = parsed;
    *next_cursor = parsed.next_offset;
    return true;
  }

  if (parsed.type >= 11 && parsed.type <= 17) {
    if (read_size - cursor < kCResRefTextBytes) {
      return false;
    }
    parsed.resref_payload = true;
    parsed.resref = FixedResrefPreview(read_buffer + cursor, read_size - cursor);
    parsed.has_resref_bytes = true;
    std::copy(
        read_buffer + cursor,
        read_buffer + cursor + kCResRefTextBytes,
        parsed.resref_bytes.begin());
    cursor += kCResRefTextBytes;
    if (!ReadQuickbarStringPreview(read_buffer, read_size, &cursor, &parsed.text)) {
      return false;
    }
    parsed.parsed = true;
    parsed.string_payload = true;
    parsed.next_offset = cursor;
    *button = parsed;
    *next_cursor = cursor;
    return true;
  }

  if (parsed.type == 18) {
    if (!ReadQuickbarStringPreview(read_buffer, read_size, &cursor, &parsed.text) ||
        !ReadQuickbarStringPreview(read_buffer, read_size, &cursor, &parsed.text2)) {
      return false;
    }
    parsed.parsed = true;
    parsed.string_payload = true;
    parsed.string2_payload = true;
    parsed.next_offset = cursor;
    *button = parsed;
    *next_cursor = cursor;
    return true;
  }

  if (parsed.type == 29 || parsed.type == 30) {
    if (read_size - cursor < kCResRefTextBytes) {
      return false;
    }
    parsed.parsed = true;
    parsed.resref_payload = true;
    parsed.resref = FixedResrefPreview(read_buffer + cursor, read_size - cursor);
    parsed.has_resref_bytes = true;
    std::copy(
        read_buffer + cursor,
        read_buffer + cursor + kCResRefTextBytes,
        parsed.resref_bytes.begin());
    parsed.next_offset = cursor + kCResRefTextBytes;
    *button = parsed;
    *next_cursor = parsed.next_offset;
    return true;
  }

  return false;
}

int ScoreLegacyQuickbarCandidateWindow(
    const unsigned char* read_buffer,
    size_t read_size,
    size_t cursor,
    size_t remaining_slots) {
  if (read_buffer == nullptr || cursor >= read_size || remaining_slots == 0) {
    return -1000000;
  }

  int score = 0;
  const size_t slots_to_probe = std::min<size_t>(remaining_slots, 8);
  for (size_t probe = 0; probe < slots_to_probe; ++probe) {
    if (cursor >= read_size) {
      return probe == 0 ? -1000000 : score - 20;
    }

    const uint8_t type = read_buffer[cursor];
    if (!IsLegacyQuickbarPlausibleType(type)) {
      return -1000000;
    }
    if (type == 1 || type == 9) {
      return score + 12;
    }

    QuickbarButtonInventory parsed{};
    size_t next_cursor = cursor;
    if (!AdvanceLegacyQuickbarNonItem(read_buffer, read_size, cursor, &parsed, &next_cursor) ||
        next_cursor <= cursor) {
      return -1000000;
    }

    if (parsed.spell) {
      score += 80;
    } else if (parsed.no_payload) {
      score += parsed.type == 0 ? 8 : 24;
    } else {
      score += 4;
    }
    cursor = next_cursor;
  }

  return score;
}

bool ChooseLegacyQuickbarItemEnd(
    const unsigned char* read_buffer,
    size_t read_size,
    size_t slot,
    size_t cursor,
    size_t* next_cursor) {
  if (read_buffer == nullptr || next_cursor == nullptr || cursor >= read_size) {
    return false;
  }

  const size_t remaining_slots_after_this = kLegacyQuickbarButtonCount - slot - 1;
  const size_t item_payload_start = cursor + 1;
  const size_t min_candidate = std::min(read_size, item_payload_start + 8);
  const size_t max_candidate = std::min(read_size, item_payload_start + 512);
  int best_score = -1000000;
  size_t best_candidate = 0;

  for (size_t candidate = min_candidate; candidate <= max_candidate; ++candidate) {
    if (candidate + remaining_slots_after_this > read_size) {
      break;
    }
    if (remaining_slots_after_this > 0 &&
        (candidate >= read_size || !IsLegacyQuickbarPlausibleType(read_buffer[candidate]))) {
      continue;
    }

    int score = remaining_slots_after_this == 0
        ? 100
        : ScoreLegacyQuickbarCandidateWindow(read_buffer, read_size, candidate, remaining_slots_after_this);
    if (score < 0) {
      continue;
    }
    if (remaining_slots_after_this > 0) {
      const uint8_t next_type = read_buffer[candidate];
      if (next_type == 2) {
        score += 35;
      } else if (next_type == 0) {
        score += 2;
      } else if (LegacyQuickbarTypeHasNoPayload(next_type)) {
        score += 8;
      }
    }
    const size_t skipped = candidate > item_payload_start ? candidate - item_payload_start : 0;
    score -= static_cast<int>(std::min<size_t>(skipped / 32, 80));
    if (score > best_score) {
      best_score = score;
      best_candidate = candidate;
    }
  }

  if (best_score < 0) {
    return false;
  }

  *next_cursor = best_candidate;
  return true;
}

std::wstring FormatQuickbarButtonInventorySummary(const std::vector<QuickbarButtonInventory>& buttons) {
  std::wstring summary;
  for (const QuickbarButtonInventory& button : buttons) {
    if (!button.parsed || (!button.spell && !button.item_candidate && button.no_payload && button.type == 0)) {
      continue;
    }

    wchar_t entry[384]{};
    if (button.spell) {
      swprintf_s(
          entry,
          L"%zu:spell(class=%u,id=%u,meta=%u,dom=%u)",
          button.slot,
          static_cast<unsigned int>(button.byte_value),
          button.int_value,
          static_cast<unsigned int>(button.spell_metamagic),
          static_cast<unsigned int>(button.spell_domain));
    } else if (button.item_payload) {
      const std::wstring primary_name = AsciiPreviewToWide(button.primary_item.name_preview, 32);
      const std::wstring secondary_name = AsciiPreviewToWide(button.secondary_item.name_preview, 32);
      swprintf_s(
          entry,
          L"%zu:item(type=%u,off=%zu..%zu,frag=%zu:%u..%zu:%u,p=%d/0x%08X base=%u model=%u,s=%d/0x%08X base=%u model=%u,name='%s'%s%s%s)",
          button.slot,
          static_cast<unsigned int>(button.type),
          button.offset,
          button.next_offset,
          button.source_fragment_offset,
          static_cast<unsigned int>(button.source_fragment_bit),
          button.next_fragment_offset,
          static_cast<unsigned int>(button.next_fragment_bit),
          button.primary_item.present ? 1 : 0,
          button.primary_item.object_id,
          button.primary_item.base_item,
          static_cast<unsigned int>(button.primary_item.appearance_type),
          button.secondary_item.present ? 1 : 0,
          button.secondary_item.object_id,
          button.secondary_item.base_item,
          static_cast<unsigned int>(button.secondary_item.appearance_type),
          primary_name.c_str(),
          secondary_name.empty() ? L"" : L",sname='",
          secondary_name.c_str(),
          secondary_name.empty() ? L"" : L"'");
    } else if (button.item_candidate) {
      swprintf_s(
          entry,
          L"%zu:item-candidate(type=%u,off=%zu..%zu,bytes=%zu)",
          button.slot,
          static_cast<unsigned int>(button.type),
          button.offset,
          button.next_offset,
          button.next_offset > button.offset ? button.next_offset - button.offset : 0);
    } else if (button.int_payload || button.byte_payload) {
      if (button.byte_payload) {
        swprintf_s(
            entry,
            L"%zu:type%u(int=%u/0x%08X,byte=%u)",
            button.slot,
            static_cast<unsigned int>(button.type),
            button.int_value,
            button.int_value,
            static_cast<unsigned int>(button.byte_value));
      } else {
        swprintf_s(
            entry,
            L"%zu:type%u(int=%u/0x%08X)",
            button.slot,
            static_cast<unsigned int>(button.type),
            button.int_value,
            button.int_value);
      }
    } else if (button.resref_payload || button.string_payload || button.string2_payload) {
      swprintf_s(
          entry,
          L"%zu:type%u(resref='%s',text='%s'%s%s%s)",
          button.slot,
          static_cast<unsigned int>(button.type),
          AsciiPreviewToWide(button.resref, 32).c_str(),
          AsciiPreviewToWide(button.text, 32).c_str(),
          button.string2_payload ? L",text2='" : L"",
          button.string2_payload ? AsciiPreviewToWide(button.text2, 32).c_str() : L"",
          button.string2_payload ? L"'" : L"");
    } else {
      swprintf_s(entry, L"%zu:type%u", button.slot, static_cast<unsigned int>(button.type));
    }

    if (!summary.empty()) {
      summary += L"; ";
    }
    summary += entry;
    if (summary.size() > 3000) {
      summary += L"; ...";
      break;
    }
  }

  return summary.empty() ? std::wstring(L"<all-empty>") : summary;
}

void ParseQuickbarButtonInventory(const unsigned char* payload, QuickbarPacketView* view) {
  if (payload == nullptr || view == nullptr || view->read_size < kLegacyQuickbarReadCursorStart) {
    return;
  }

  const unsigned char* read_buffer = payload;
  const size_t read_size = view->read_size;
  std::vector<QuickbarButtonInventory> buttons;
  buttons.reserve(kLegacyQuickbarButtonCount);

  size_t cursor = kLegacyQuickbarReadCursorStart;
  for (size_t slot = 0; slot < kLegacyQuickbarButtonCount; ++slot) {
    if (cursor >= read_size) {
      view->unsupported_buttons += static_cast<int>(kLegacyQuickbarButtonCount - slot);
      break;
    }

    QuickbarButtonInventory button{};
    button.slot = slot;
    button.offset = cursor;
    button.type = read_buffer[cursor];

    size_t next_cursor = cursor;
    if (button.type == 1) {
      if (!ChooseLegacyQuickbarItemEnd(read_buffer, read_size, slot, cursor, &next_cursor)) {
        view->unsupported_buttons += static_cast<int>(kLegacyQuickbarButtonCount - slot);
        break;
      }
      button.parsed = true;
      button.item_candidate = true;
      button.next_offset = next_cursor;
      ++view->item_candidates;
      view->score += 60;
    } else if (!AdvanceLegacyQuickbarNonItem(read_buffer, read_size, cursor, &button, &next_cursor)) {
      view->unsupported_buttons += static_cast<int>(kLegacyQuickbarButtonCount - slot);
      break;
    } else if (button.spell) {
      ++view->spells;
      view->score += 80;
    } else if (button.no_payload) {
      ++view->no_payload_buttons;
      view->score += button.type == 0 ? 8 : 24;
    } else {
      ++view->general_buttons;
      view->score += 32;
    }

    buttons.push_back(button);
    ++view->parsed_slots;
    cursor = next_cursor;
  }

  view->buttons_parsed = view->parsed_slots != 0 || read_size == kLegacyQuickbarReadCursorStart;
  view->final_cursor = cursor;
  view->button_summary = FormatQuickbarButtonInventorySummary(buttons);
  view->buttons = std::move(buttons);
}

bool TryParseQuickbarPacket(const unsigned char* packet, size_t packet_size, QuickbarPacketView* view) {
  if (view != nullptr) {
    *view = QuickbarPacketView{};
  }
  if (packet == nullptr || view == nullptr || packet_size < 7 || !IsHighLevelGameplayEnvelope(packet[0]) ||
      packet[1] != 30 || packet[2] != 1) {
    return false;
  }

  const unsigned char* payload = packet + 3;
  const size_t payload_size = packet_size - 3;
  const uint32_t declared = ReadU32Le(payload);
  if (declared < 3) {
    return false;
  }
  const size_t read_size = static_cast<size_t>(declared - 3);
  if (read_size < kLegacyQuickbarReadCursorStart || read_size > payload_size) {
    return false;
  }

  view->declared = declared;
  view->read_size = read_size;
  view->fragment_size = payload_size - read_size;
  if (view->fragment_size > 0) {
    const unsigned char* fragments = payload + read_size;
    uint32_t bits = 0;
    if (ReadFirstMsbBits(fragments, view->fragment_size, 3, &bits)) {
      view->have_final_fragment_bits = true;
      view->final_fragment_bits = bits;
    }
  }
  ParseQuickbarButtonInventory(payload, view);
  return true;
}

bool FailQuickbarPayloadBuild(std::wstring* reason, const wchar_t* format, ...) {
  if (reason != nullptr) {
    wchar_t message[512]{};
    va_list args;
    va_start(args, format);
    _vsnwprintf_s(message, _TRUNCATE, format, args);
    va_end(args);
    *reason = message;
  }
  return false;
}

bool AppendU32Le(std::vector<unsigned char>* bytes, uint32_t value) {
  if (bytes == nullptr) {
    return false;
  }
  const size_t offset = bytes->size();
  bytes->resize(offset + 4);
  WriteU32Le(bytes->data() + offset, value);
  return true;
}

bool AppendQuickbarString(std::vector<unsigned char>* bytes, const std::string& value) {
  constexpr size_t kMaxReasonableQuickbarStringBytes = 4096;
  if (bytes == nullptr || value.size() > kMaxReasonableQuickbarStringBytes) {
    return false;
  }
  if (!AppendU32Le(bytes, static_cast<uint32_t>(value.size()))) {
    return false;
  }
  bytes->insert(bytes->end(), value.begin(), value.end());
  return true;
}

bool AppendQuickbarResref16(std::vector<unsigned char>* bytes, const QuickbarButtonInventory& button) {
  if (bytes == nullptr || !button.has_resref_bytes) {
    return false;
  }
  bytes->insert(bytes->end(), button.resref_bytes.begin(), button.resref_bytes.end());
  return true;
}

struct QuickbarPacketReader {
  const unsigned char* read_buffer = nullptr;
  size_t read_size = 0;
  const unsigned char* fragments = nullptr;
  size_t fragment_size = 0;
  size_t cursor = kLegacyQuickbarReadCursorStart;
  size_t fragment_cursor = 0;
  uint8_t fragment_bit = 0;
  uint8_t final_fragment_bits = 0;
};

struct QuickbarPacketWriter {
  std::vector<unsigned char> read_buffer = std::vector<unsigned char>(4, 0);
  std::vector<unsigned char> fragment_bits = {0, 0, 0};
};

bool FailQuickbarFullParse(std::wstring* reason, const wchar_t* format, ...) {
  if (reason != nullptr) {
    wchar_t message[512]{};
    va_list args;
    va_start(args, format);
    _vsnwprintf_s(message, _TRUNCATE, format, args);
    va_end(args);
    *reason = message;
  }
  return false;
}

std::wstring FormatQuickbarReaderWindow(const QuickbarPacketReader& reader) {
  if (reader.read_buffer == nullptr) {
    return L"<no-reader>";
  }

  const size_t start = reader.cursor > 16 ? reader.cursor - 16 : 0;
  const size_t end = std::min(reader.read_size, reader.cursor + 64);
  const size_t length = end >= start ? end - start : 0;
  wchar_t prefix[192]{};
  swprintf_s(
      prefix,
      L"cursor=%zu/%zu frag=%zu/%zu:%u finalbits=%u window@%zu=[",
      reader.cursor,
      reader.read_size,
      reader.fragment_cursor,
      reader.fragment_size,
      static_cast<unsigned int>(reader.fragment_bit),
      static_cast<unsigned int>(reader.final_fragment_bits),
      start);
  std::wstring result = prefix;
  result += FormatLimitedBytes(reader.read_buffer + start, length, 96);
  result += L"]";
  return result;
}

bool ReadQuickbarReaderBit(QuickbarPacketReader* reader, uint32_t* bit) {
  if (bit != nullptr) {
    *bit = 0;
  }
  if (reader == nullptr || bit == nullptr || reader->fragments == nullptr ||
      reader->fragment_cursor >= reader->fragment_size || reader->fragment_bit >= 8) {
    return false;
  }

  *bit = (reader->fragments[reader->fragment_cursor] >> (7 - reader->fragment_bit)) & 1u;
  ++reader->fragment_bit;
  if (reader->fragment_bit >= 8) {
    reader->fragment_bit = 0;
    ++reader->fragment_cursor;
  }
  return true;
}

bool ReadQuickbarReaderBits(QuickbarPacketReader* reader, uint8_t bit_count, uint32_t* value) {
  if (value != nullptr) {
    *value = 0;
  }
  if (reader == nullptr || value == nullptr || bit_count > 32) {
    return false;
  }

  uint32_t result = 0;
  for (uint8_t index = 0; index < bit_count; ++index) {
    uint32_t bit = 0;
    if (!ReadQuickbarReaderBit(reader, &bit)) {
      return false;
    }
    result = (result << 1) | (bit & 1u);
  }
  *value = result;
  return true;
}

bool ReadQuickbarReaderBool(QuickbarPacketReader* reader, bool* value) {
  uint32_t bit = 0;
  if (!ReadQuickbarReaderBit(reader, &bit)) {
    return false;
  }
  if (value != nullptr) {
    *value = bit != 0;
  }
  return true;
}

bool ReadQuickbarReaderByte(QuickbarPacketReader* reader, uint8_t* value) {
  if (reader == nullptr || value == nullptr || reader->read_buffer == nullptr ||
      reader->cursor >= reader->read_size) {
    return false;
  }
  *value = reader->read_buffer[reader->cursor++];
  return true;
}

bool ReadQuickbarReaderWord(QuickbarPacketReader* reader, uint16_t* value) {
  if (reader == nullptr || value == nullptr || reader->read_buffer == nullptr ||
      reader->cursor > reader->read_size || reader->read_size - reader->cursor < 2) {
    return false;
  }
  *value = ReadU16Le(reader->read_buffer + reader->cursor);
  reader->cursor += 2;
  return true;
}

bool ReadQuickbarReaderDword(QuickbarPacketReader* reader, uint32_t* value) {
  if (reader == nullptr || value == nullptr || reader->read_buffer == nullptr ||
      reader->cursor > reader->read_size || reader->read_size - reader->cursor < 4) {
    return false;
  }
  *value = ReadU32Le(reader->read_buffer + reader->cursor);
  reader->cursor += 4;
  return true;
}

bool ReadQuickbarReaderUnsignedIntBits(
    QuickbarPacketReader* reader,
    uint8_t bit_count,
    uint64_t* value) {
  if (value != nullptr) {
    *value = 0;
  }
  if (reader == nullptr || value == nullptr || bit_count > 64) {
    return false;
  }

  uint64_t result = 0;
  uint8_t remaining = bit_count;
  while (remaining >= 32) {
    uint32_t chunk = 0;
    if (!ReadQuickbarReaderDword(reader, &chunk)) {
      return false;
    }
    result = (result << 32) | chunk;
    remaining -= 32;
  }
  while (remaining >= 16) {
    uint16_t chunk = 0;
    if (!ReadQuickbarReaderWord(reader, &chunk)) {
      return false;
    }
    result = (result << 16) | chunk;
    remaining -= 16;
  }
  while (remaining >= 8) {
    uint8_t chunk = 0;
    if (!ReadQuickbarReaderByte(reader, &chunk)) {
      return false;
    }
    result = (result << 8) | chunk;
    remaining -= 8;
  }
  if (remaining != 0) {
    uint32_t chunk = 0;
    if (!ReadQuickbarReaderBits(reader, remaining, &chunk)) {
      return false;
    }
    result = (result << remaining) | chunk;
  }

  *value = result;
  return true;
}

bool ReadQuickbarReaderSignedIntBits(
    QuickbarPacketReader* reader,
    uint8_t bit_count,
    int64_t* value) {
  if (value != nullptr) {
    *value = 0;
  }
  if (reader == nullptr || value == nullptr || bit_count == 0 || bit_count > 64) {
    return false;
  }

  uint32_t sign = 0;
  uint64_t magnitude = 0;
  if (!ReadQuickbarReaderBit(reader, &sign) ||
      !ReadQuickbarReaderUnsignedIntBits(reader, static_cast<uint8_t>(bit_count - 1), &magnitude)) {
    return false;
  }

  if (sign == 0) {
    if (magnitude > static_cast<uint64_t>(INT64_MAX)) {
      return false;
    }
    *value = static_cast<int64_t>(magnitude);
    return true;
  }

  if (magnitude > static_cast<uint64_t>(INT64_MAX)) {
    return false;
  }
  *value = -static_cast<int64_t>(magnitude);
  return true;
}

bool ReadQuickbarReaderString(
    QuickbarPacketReader* reader,
    std::string* value,
    uint32_t max_length = 4096) {
  if (value != nullptr) {
    value->clear();
  }
  uint32_t length = 0;
  if (!ReadQuickbarReaderDword(reader, &length) ||
      reader == nullptr || reader->read_buffer == nullptr ||
      reader->cursor > reader->read_size ||
      length > max_length ||
      length > reader->read_size - reader->cursor) {
    return false;
  }
  if (value != nullptr) {
    value->assign(
        reinterpret_cast<const char*>(reader->read_buffer + reader->cursor),
        reinterpret_cast<const char*>(reader->read_buffer + reader->cursor + length));
  }
  reader->cursor += length;
  return true;
}

bool ReadQuickbarReaderFixedResref(
    QuickbarPacketReader* reader,
    QuickbarButtonInventory* button,
    std::string* value) {
  if (value != nullptr) {
    value->clear();
  }
  if (reader == nullptr || reader->read_buffer == nullptr ||
      reader->cursor > reader->read_size ||
      reader->read_size - reader->cursor < kCResRefTextBytes) {
    return false;
  }

  std::string preview = FixedResrefPreview(reader->read_buffer + reader->cursor, kCResRefTextBytes);
  if (value != nullptr) {
    *value = preview;
  }
  if (button != nullptr) {
    button->resref = preview;
    button->has_resref_bytes = true;
    std::copy(
        reader->read_buffer + reader->cursor,
        reader->read_buffer + reader->cursor + kCResRefTextBytes,
        button->resref_bytes.begin());
  }
  reader->cursor += kCResRefTextBytes;
  return true;
}

bool ReadQuickbarReaderLocString(
    QuickbarPacketReader* reader,
    QuickbarLocStringField* field,
    std::string* preview) {
  if (field != nullptr) {
    *field = QuickbarLocStringField{};
  }
  if (preview != nullptr) {
    preview->clear();
  }

  bool custom_tlk = false;
  if (!ReadQuickbarReaderBool(reader, &custom_tlk)) {
    return false;
  }
  if (field != nullptr) {
    field->custom_tlk = custom_tlk;
  }

  if (custom_tlk) {
    uint32_t language_selector = 0;
    uint32_t string_ref = 0;
    if (!ReadQuickbarReaderBits(reader, 1, &language_selector) ||
        !ReadQuickbarReaderDword(reader, &string_ref)) {
      return false;
    }
    if (field != nullptr) {
      field->language_selector = language_selector != 0;
      field->string_ref = string_ref;
    }
    if (preview != nullptr) {
      char text[96]{};
      sprintf_s(text, "strref:%u%s", string_ref, language_selector != 0 ? ":alt" : "");
      *preview = text;
    }
    return true;
  }

  std::string text;
  if (!ReadQuickbarReaderString(reader, &text)) {
    return false;
  }
  if (field != nullptr) {
    field->text = text;
  }
  if (preview != nullptr) {
    *preview = text;
  }
  return true;
}

bool LooksLikeEePlayerListIdentityField(const QuickbarPacketReader& reader) {
  if (reader.read_buffer == nullptr ||
      reader.cursor > reader.read_size ||
      reader.read_size - reader.cursor < 5) {
    return false;
  }

  const uint8_t identity_type = reader.read_buffer[reader.cursor];
  const uint32_t identity_length = ReadU32Le(reader.read_buffer + reader.cursor + 1);
  if (identity_type > 4 || identity_length > 256) {
    return false;
  }
  return identity_length <= reader.read_size - reader.cursor - 5;
}

bool SkipEePlayerListIdentityField(QuickbarPacketReader* reader) {
  uint8_t identity_type = 0;
  std::string identity;
  return ReadQuickbarReaderByte(reader, &identity_type) &&
      ReadQuickbarReaderString(reader, &identity, 256);
}

struct PlayerListLayoutProbe {
  size_t cursor = 0;
  size_t consumed_fragment_bits = 0;
  size_t consumed_fragment_bytes = 0;
  uint8_t final_fragment_bits = 0;
  uint8_t entry_count = 0;
};

bool ProbePlayerListLayout(
    const unsigned char* cnw,
    size_t payload_size,
    unsigned int minor,
    size_t read_size,
    size_t fragment_size,
    PlayerListLayoutProbe* result) {
  if (cnw == nullptr ||
      read_size < kLegacyQuickbarReadCursorStart ||
      read_size > payload_size ||
      fragment_size == 0 ||
      read_size + fragment_size != payload_size) {
    return false;
  }

  QuickbarPacketReader reader{};
  reader.read_buffer = cnw;
  reader.read_size = read_size;
  reader.fragments = cnw + read_size;
  reader.fragment_size = fragment_size;
  reader.cursor = kLegacyQuickbarReadCursorStart;

  uint32_t final_fragment_bits = 0;
  bool player_list_flag = false;
  if (!ReadQuickbarReaderBits(&reader, 3, &final_fragment_bits) ||
      !ReadQuickbarReaderBool(&reader, &player_list_flag)) {
    return false;
  }
  reader.final_fragment_bits = static_cast<uint8_t>(final_fragment_bits);

  uint8_t entry_count = 1;
  if (minor == 0x01 && !ReadQuickbarReaderByte(&reader, &entry_count)) {
    return false;
  }
  if (entry_count == 0) {
    return false;
  }

  for (uint32_t entry = 0; entry < entry_count; ++entry) {
    uint32_t player_id = 0;
    uint32_t player_object = 0;
    bool dm_flag = false;
    std::string player_name;
    bool has_creature = false;
    if (!ReadQuickbarReaderDword(&reader, &player_id) ||
        !ReadQuickbarReaderDword(&reader, &player_object) ||
        !ReadQuickbarReaderBool(&reader, &dm_flag) ||
        !ReadQuickbarReaderString(&reader, &player_name, 256) ||
        !ReadQuickbarReaderBool(&reader, &has_creature)) {
      return false;
    }

    if (LooksLikeEePlayerListIdentityField(reader) &&
        !SkipEePlayerListIdentityField(&reader)) {
      return false;
    }

    if (has_creature) {
      uint32_t creature_object = 0;
      QuickbarLocStringField first_locstring;
      QuickbarLocStringField second_locstring;
      uint16_t portrait_id = 0;
      if (!ReadQuickbarReaderDword(&reader, &creature_object) ||
          !ReadQuickbarReaderLocString(&reader, &first_locstring, nullptr) ||
          !ReadQuickbarReaderLocString(&reader, &second_locstring, nullptr) ||
          !ReadQuickbarReaderWord(&reader, &portrait_id)) {
        return false;
      }
      if (portrait_id >= 0xFFFEu &&
          !ReadQuickbarReaderFixedResref(&reader, nullptr, nullptr)) {
        return false;
      }
    }
  }

  const size_t consumed_fragment_bits = reader.fragment_cursor * 8 + reader.fragment_bit;
  const size_t consumed_fragment_bytes = reader.fragment_cursor + (reader.fragment_bit != 0 ? 1 : 0);
  if (reader.cursor != read_size ||
      consumed_fragment_bytes != fragment_size ||
      consumed_fragment_bits < 3 ||
      reader.final_fragment_bits != static_cast<uint8_t>(consumed_fragment_bits % 8u)) {
    return false;
  }

  if (result != nullptr) {
    result->cursor = reader.cursor;
    result->consumed_fragment_bits = consumed_fragment_bits;
    result->consumed_fragment_bytes = consumed_fragment_bytes;
    result->final_fragment_bits = reader.final_fragment_bits;
    result->entry_count = entry_count;
  }
  return true;
}

bool NormalizeLegacyShortDeclaredPlayerListPayloadIfNeeded(
    std::vector<unsigned char>* payload,
    PlayerListShortDeclaredNormalizationResult* result) {
  if (result != nullptr) {
    *result = PlayerListShortDeclaredNormalizationResult{};
  }
  if (payload == nullptr ||
      payload->size() < 9 ||
      !IsHighLevelGameplayEnvelope((*payload)[0]) ||
      (*payload)[1] != 0x0A ||
      (*payload)[2] != 0x01) {
    return false;
  }

  const unsigned char* cnw = payload->data() + 3;
  const size_t old_payload_size = payload->size() - 3;
  const uint32_t raw_declared = ReadU32Le(cnw);
  if (raw_declared >= 7) {
    const size_t raw_read_size = static_cast<size_t>(raw_declared - 3u);
    if (raw_read_size >= kLegacyQuickbarReadCursorStart &&
        raw_read_size <= old_payload_size &&
        old_payload_size - raw_read_size != 0) {
      return false;
    }
  }

  const uint16_t legacy_declared = ReadU16Le(cnw);
  if (legacy_declared < 7) {
    return false;
  }
  const size_t legacy_read_size = static_cast<size_t>(legacy_declared - 3u);
  if (legacy_read_size < 2 + kLegacyQuickbarReadCursorStart ||
      legacy_read_size > old_payload_size) {
    return false;
  }
  const size_t fragment_size = old_payload_size - legacy_read_size;
  if (fragment_size == 0 || fragment_size > 64) {
    return false;
  }

  const size_t normalized_read_size = legacy_read_size + 2;
  const uint32_t normalized_declared = static_cast<uint32_t>(normalized_read_size + 3u);
  const size_t new_payload_size = old_payload_size + 2;
  if (normalized_read_size < kLegacyQuickbarReadCursorStart ||
      normalized_read_size > new_payload_size ||
      new_payload_size - normalized_read_size != fragment_size) {
    return false;
  }

  std::vector<unsigned char> candidate;
  candidate.reserve(payload->size() + 2);
  candidate.insert(candidate.end(), payload->begin(), payload->begin() + 3);
  AppendU32Le(&candidate, normalized_declared);
  candidate.insert(candidate.end(), payload->begin() + 5, payload->end());

  PlayerListLayoutProbe probe;
  if (!ProbePlayerListLayout(
          candidate.data() + 3,
          candidate.size() - 3,
          0x01,
          normalized_read_size,
          fragment_size,
          &probe)) {
    return false;
  }

  if (result != nullptr) {
    result->raw_declared = raw_declared;
    result->legacy_declared = legacy_declared;
    result->normalized_declared = normalized_declared;
    result->fragment_bytes = static_cast<uint32_t>(fragment_size);
    result->entries = probe.entry_count;
    result->old_payload_length = payload->size();
    result->new_payload_length = candidate.size();
  }
  *payload = std::move(candidate);
  return true;
}

bool RewritePlayerListPayloadIfPossible(
    BridgeRuntime* runtime,
    std::vector<unsigned char>* payload,
    PlayerListRewriteResult* result,
    std::wstring* failure_reason) {
  if (result != nullptr) {
    *result = PlayerListRewriteResult{};
  }
  if (failure_reason != nullptr) {
    failure_reason->clear();
  }
  if (runtime == nullptr || payload == nullptr || payload->size() < 7 ||
      !IsHighLevelGameplayEnvelope((*payload)[0]) ||
      (*payload)[1] != 0x0A ||
      ((*payload)[2] != 0x01 && (*payload)[2] != 0x02)) {
    return false;
  }

  const size_t original_wire_payload_size = payload->size();
  PlayerListShortDeclaredNormalizationResult short_declared_normalization;
  const bool normalized_legacy_short_declared =
      NormalizeLegacyShortDeclaredPlayerListPayloadIfNeeded(
          payload,
          &short_declared_normalization);

  const unsigned char envelope = (*payload)[0];
  const unsigned int minor = (*payload)[2];
  const unsigned char* cnw = payload->data() + 3;
  const size_t payload_size = payload->size() - 3;
  const uint32_t declared = ReadU32Le(cnw);
  if (declared < 7) {
    return FailQuickbarFullParse(failure_reason, L"invalid PlayerList CNW declared=%u", declared);
  }
  size_t read_size = static_cast<size_t>(declared - 3);
  if (read_size < kLegacyQuickbarReadCursorStart || read_size > payload_size) {
    return FailQuickbarFullParse(
        failure_reason,
        L"PlayerList read_size=%zu outside payload_size=%zu declared=%u",
        read_size,
        payload_size,
        declared);
  }
  size_t fragment_size = payload_size - read_size;
  if (fragment_size == 0) {
    return FailQuickbarFullParse(failure_reason, L"PlayerList has no CNW fragment stream");
  }
  bool normalized_legacy_wide_read_layout = false;
  PlayerListLayoutProbe layout_probe;
  if (!ProbePlayerListLayout(cnw, payload_size, minor, read_size, fragment_size, &layout_probe) &&
      minor == 0x01) {
    const size_t max_fragment_size = std::min<size_t>(
        64,
        payload_size > kLegacyQuickbarReadCursorStart
            ? payload_size - kLegacyQuickbarReadCursorStart
            : 0);
    for (size_t candidate_fragment_size = 1;
         candidate_fragment_size <= max_fragment_size;
         ++candidate_fragment_size) {
      const size_t candidate_read_size = payload_size - candidate_fragment_size;
      if (candidate_read_size == read_size) {
        continue;
      }
      PlayerListLayoutProbe candidate_probe;
      if (ProbePlayerListLayout(
              cnw,
              payload_size,
              minor,
              candidate_read_size,
              candidate_fragment_size,
              &candidate_probe)) {
        read_size = candidate_read_size;
        fragment_size = candidate_fragment_size;
        layout_probe = candidate_probe;
        normalized_legacy_wide_read_layout = true;
        break;
      }
    }
  }
  std::vector<unsigned char> original_fragments(cnw + read_size, cnw + payload_size);

  QuickbarPacketReader reader{};
  reader.read_buffer = cnw;
  reader.read_size = read_size;
  reader.fragments = cnw + read_size;
  reader.fragment_size = fragment_size;
  reader.cursor = kLegacyQuickbarReadCursorStart;

  uint32_t final_fragment_bits = 0;
  bool player_list_flag = false;
  if (!ReadQuickbarReaderBits(&reader, 3, &final_fragment_bits) ||
      !ReadQuickbarReaderBool(&reader, &player_list_flag)) {
    return FailQuickbarFullParse(failure_reason, L"PlayerList missing leading fragment bits");
  }
  reader.final_fragment_bits = static_cast<uint8_t>(final_fragment_bits);

  uint8_t entry_count = 1;
  if (minor == 0x01 && !ReadQuickbarReaderByte(&reader, &entry_count)) {
    return FailQuickbarFullParse(failure_reason, L"PlayerList_All missing entry count");
  }
  if (entry_count == 0) {
    return FailQuickbarFullParse(failure_reason, L"PlayerList contains zero entries");
  }

  std::vector<size_t> insert_offsets;
  std::wstring details;
  if (normalized_legacy_short_declared) {
    wchar_t line[320]{};
    _snwprintf_s(
        line,
        _TRUNCATE,
        L"layout=legacy-short-declared raw_declared=%u short_declared=%u normalized_declared=%u fragments=%u payload=%zu->%zu entries_probe=%u; ",
        short_declared_normalization.raw_declared,
        static_cast<unsigned int>(short_declared_normalization.legacy_declared),
        short_declared_normalization.normalized_declared,
        short_declared_normalization.fragment_bytes,
        short_declared_normalization.old_payload_length,
        short_declared_normalization.new_payload_length,
        short_declared_normalization.entries);
    details = line;
  }
  if (normalized_legacy_wide_read_layout) {
    details += L"layout=legacy-wide-read; ";
  }
  for (uint32_t entry = 0; entry < entry_count; ++entry) {
    const size_t entry_start = reader.cursor;
    uint32_t player_id = 0;
    uint32_t player_object = 0;
    bool dm_flag = false;
    std::string player_name;
    bool has_creature = false;
    if (!ReadQuickbarReaderDword(&reader, &player_id) ||
        !ReadQuickbarReaderDword(&reader, &player_object) ||
        !ReadQuickbarReaderBool(&reader, &dm_flag) ||
        !ReadQuickbarReaderString(&reader, &player_name, 256) ||
        !ReadQuickbarReaderBool(&reader, &has_creature)) {
      return FailQuickbarFullParse(
          failure_reason,
          L"PlayerList entry %u header parse failed at cursor=%zu frag=%zu:%u",
          entry,
          entry_start,
          reader.fragment_cursor,
          static_cast<unsigned int>(reader.fragment_bit));
    }

    const size_t identity_offset = reader.cursor;
    bool already_ee_shaped = false;
    if (LooksLikeEePlayerListIdentityField(reader)) {
      already_ee_shaped = SkipEePlayerListIdentityField(&reader);
    }
    if (!already_ee_shaped) {
      insert_offsets.push_back(identity_offset);
    }

    uint32_t creature_object = 0x7F000000u;
    std::string first_name;
    std::string second_name;
    uint16_t portrait_id = 0;
    std::string portrait_resref;
    if (has_creature) {
      QuickbarLocStringField first_locstring;
      QuickbarLocStringField second_locstring;
      if (!ReadQuickbarReaderDword(&reader, &creature_object) ||
          !ReadQuickbarReaderLocString(&reader, &first_locstring, &first_name) ||
          !ReadQuickbarReaderLocString(&reader, &second_locstring, &second_name) ||
          !ReadQuickbarReaderWord(&reader, &portrait_id)) {
        return FailQuickbarFullParse(
            failure_reason,
            L"PlayerList entry %u creature body parse failed at cursor=%zu frag=%zu:%u name=%s",
            entry,
            reader.cursor,
            reader.fragment_cursor,
            static_cast<unsigned int>(reader.fragment_bit),
            AsciiPreviewToWide(player_name).c_str());
      }
      if (portrait_id >= 0xFFFEu) {
        if (!ReadQuickbarReaderFixedResref(&reader, nullptr, &portrait_resref)) {
          return FailQuickbarFullParse(
              failure_reason,
              L"PlayerList entry %u custom portrait resref parse failed at cursor=%zu",
              entry,
              reader.cursor);
        }
      }
    }

    if (entry < 6) {
      wchar_t line[384]{};
      _snwprintf_s(
          line,
          _TRUNCATE,
          L"%sentry%u id=%u obj=0x%08X dm=%d creature=%d creature_obj=0x%08X name='%s' char='%s' identity=%s offset=%zu",
          details.empty() ? L"" : L"; ",
          entry,
          player_id,
          player_object,
          dm_flag ? 1 : 0,
          has_creature ? 1 : 0,
          creature_object,
          AsciiPreviewToWide(player_name).c_str(),
          AsciiPreviewToWide(first_name).c_str(),
          already_ee_shaped ? L"present" : L"legacy",
          identity_offset);
      details += line;
    }
  }

  const size_t consumed_fragment_bits = reader.fragment_cursor * 8 + reader.fragment_bit;
  const size_t consumed_fragment_bytes = reader.fragment_cursor + (reader.fragment_bit != 0 ? 1 : 0);
  if (consumed_fragment_bits < 3 || consumed_fragment_bytes > fragment_size) {
    return FailQuickbarFullParse(
        failure_reason,
        L"PlayerList fragment cursor invalid bits=%zu bytes=%zu fragment_size=%zu",
        consumed_fragment_bits,
        consumed_fragment_bytes,
        fragment_size);
  }

  std::vector<unsigned char> fragment_bits;
  if (!DecodeCnwFragmentBits(original_fragments, &fragment_bits) ||
      consumed_fragment_bits > fragment_bits.size()) {
    return FailQuickbarFullParse(
        failure_reason,
        L"PlayerList fragment decode failed consumed_bits=%zu fragment_bytes=%zu",
        consumed_fragment_bits,
        fragment_size);
  }
  const bool fragments_need_rewrite =
      consumed_fragment_bytes != fragment_size ||
      reader.final_fragment_bits != static_cast<uint8_t>(consumed_fragment_bits % 8u);
  std::vector<unsigned char> rewritten_fragments = original_fragments;
  if (fragments_need_rewrite) {
    fragment_bits.resize(consumed_fragment_bits);
    RefreshCnwFragmentFinalBitHeader(&fragment_bits);
    PackCnwMsbBits(fragment_bits, &rewritten_fragments);
    if (rewritten_fragments.empty()) {
      rewritten_fragments.push_back(0);
    }
  }

  const uint32_t normalized_declared_base =
      read_size > UINT32_MAX - 3u ? UINT32_MAX : static_cast<uint32_t>(read_size + 3u);
  const bool declared_normalized = normalized_declared_base > declared;
  if (insert_offsets.empty()) {
    if (!fragments_need_rewrite) {
      if (!declared_normalized) {
        return FailQuickbarFullParse(
            failure_reason,
            L"PlayerList already appears EE-shaped entries=%u cursor=%zu read_size=%zu fragments=%zu",
            static_cast<unsigned int>(entry_count),
            reader.cursor,
            reader.read_size,
            fragment_size);
      }
    }
  }

  constexpr unsigned char kEeEmptyIdentity[] = {0x00, 0x00, 0x00, 0x00, 0x00};
  const size_t total_inserted = insert_offsets.size() * sizeof(kEeEmptyIdentity);
  if (normalized_declared_base > UINT32_MAX - total_inserted ||
      payload->size() > kMaxReasonableReassembledGameplayPayload - total_inserted) {
    return FailQuickbarFullParse(
        failure_reason,
        L"PlayerList rewrite would exceed size cap declared=%u inserted=%zu payload=%zu",
        normalized_declared_base,
        total_inserted,
        payload->size());
  }

  for (auto it = insert_offsets.rbegin(); it != insert_offsets.rend(); ++it) {
    const size_t offset = *it;
    if (offset > read_size) {
      return FailQuickbarFullParse(
          failure_reason,
          L"PlayerList insertion offset outside read buffer offset=%zu read_size=%zu",
          offset,
          read_size);
    }
    payload->insert(
        payload->begin() + static_cast<std::ptrdiff_t>(3 + offset),
        kEeEmptyIdentity,
        kEeEmptyIdentity + sizeof(kEeEmptyIdentity));
  }

  const uint32_t new_declared = normalized_declared_base + static_cast<uint32_t>(total_inserted);
  WriteU32Le(payload->data() + 3, new_declared);
  if (fragments_need_rewrite) {
    const size_t new_read_size = read_size + total_inserted;
    const size_t new_fragment_offset = 3 + new_read_size;
    if (new_fragment_offset > payload->size()) {
      return FailQuickbarFullParse(
          failure_reason,
          L"PlayerList fragment rewrite offset outside payload offset=%zu payload=%zu",
          new_fragment_offset,
          payload->size());
    }
    payload->resize(new_fragment_offset);
    payload->insert(payload->end(), rewritten_fragments.begin(), rewritten_fragments.end());
  }

  if (result != nullptr) {
    result->envelope = envelope;
    result->minor = minor;
    result->old_declared = declared;
    result->new_declared = new_declared;
    result->entries = entry_count;
    result->insertions = static_cast<uint32_t>(insert_offsets.size());
    result->bytes_inserted = static_cast<uint32_t>(total_inserted);
    result->old_fragment_bytes = static_cast<uint32_t>(fragment_size);
    result->new_fragment_bytes = static_cast<uint32_t>(rewritten_fragments.size());
    result->consumed_fragment_bits = static_cast<uint32_t>(consumed_fragment_bits);
    result->fragments_rewritten = fragments_need_rewrite;
    result->old_payload_length = original_wire_payload_size;
    result->new_payload_length = payload->size();
    result->details = std::move(details);
  }
  return true;
}

void AppendEeLoadBarStartPayload(std::vector<unsigned char>* payload, uint32_t stall_event_id) {
  if (payload == nullptr) {
    return;
  }
  payload->push_back('P');
  payload->push_back(0x2C);
  payload->push_back(0x01);
  AppendU32Le(payload, 0x0Bu);
  AppendU32Le(payload, stall_event_id);
  payload->push_back(0x60);
}

void AppendEeLoadBarEndPayload(std::vector<unsigned char>* payload, uint32_t stall_event_id) {
  if (payload == nullptr) {
    return;
  }
  payload->push_back('P');
  payload->push_back(0x2C);
  payload->push_back(0x03);
  AppendU32Le(payload, 0x0Bu);
  AppendU32Le(payload, stall_event_id);
  payload->push_back(0xE0);
}

bool SequenceAtOrAfter(uint16_t sequence, uint16_t base) {
  return static_cast<uint16_t>(sequence - base) < 0x8000u;
}

bool SequenceBefore(uint16_t sequence, uint16_t base) {
  return sequence != base && static_cast<uint16_t>(base - sequence) < 0x8000u;
}

bool SequenceInForwardClosedRange(uint16_t sequence, uint16_t first, uint16_t last) {
  return SequenceAtOrAfter(sequence, first) && SequenceAtOrAfter(last, sequence);
}

uint16_t SequenceDeltaForOriginal(
    const std::vector<ServerSequenceShift>& shifts,
    uint16_t original_sequence) {
  uint32_t delta = 0;
  for (const ServerSequenceShift& shift : shifts) {
    if (shift.delta != 0 && SequenceAtOrAfter(original_sequence, shift.base)) {
      delta += shift.delta;
    }
  }
  return static_cast<uint16_t>(delta & 0xFFFFu);
}

uint16_t ShiftSequenceForPeer(
    const std::vector<ServerSequenceShift>& shifts,
    uint16_t original_sequence) {
  return static_cast<uint16_t>(original_sequence + SequenceDeltaForOriginal(shifts, original_sequence));
}

uint16_t UnshiftAckForOrigin(
    const std::vector<ServerSequenceShift>& shifts,
    uint16_t shifted_ack_sequence) {
  uint16_t cumulative_delta = 0;
  for (const ServerSequenceShift& shift : shifts) {
    if (shift.delta == 0) {
      continue;
    }

    const uint16_t synthetic_first = static_cast<uint16_t>(shift.base + cumulative_delta);
    if (SequenceBefore(shifted_ack_sequence, synthetic_first)) {
      return static_cast<uint16_t>(shifted_ack_sequence - cumulative_delta);
    }

    const uint16_t synthetic_last = static_cast<uint16_t>(synthetic_first + shift.delta - 1);
    if (SequenceInForwardClosedRange(shifted_ack_sequence, synthetic_first, synthetic_last)) {
      return static_cast<uint16_t>(shift.base - 1);
    }

    cumulative_delta = static_cast<uint16_t>(cumulative_delta + shift.delta);
  }
  return static_cast<uint16_t>(shifted_ack_sequence - cumulative_delta);
}

uint16_t ShiftServerSequenceForClient(const BridgeRuntime& runtime, uint16_t original_sequence) {
  return ShiftSequenceForPeer(runtime.server_sequence_shifts, original_sequence);
}

uint16_t UnshiftServerAckForServer(const BridgeRuntime& runtime, uint16_t shifted_ack_sequence) {
  return UnshiftAckForOrigin(runtime.server_sequence_shifts, shifted_ack_sequence);
}

uint16_t ShiftClientSequenceForServer(const BridgeRuntime& runtime, uint16_t original_sequence) {
  return ShiftSequenceForPeer(runtime.client_sequence_shifts, original_sequence);
}

uint16_t UnshiftClientAckForClient(const BridgeRuntime& runtime, uint16_t shifted_ack_sequence) {
  return UnshiftAckForOrigin(runtime.client_sequence_shifts, shifted_ack_sequence);
}

bool BuildSyntheticGameplayFrame(
    uint16_t sequence,
    uint16_t ack_sequence,
    const std::vector<unsigned char>& payload,
    std::vector<unsigned char>* packet) {
  if (packet == nullptr || payload.size() > 0xFFFFu) {
    return false;
  }

  packet->assign(kLegacyGameplayPayloadOffset, 0);
  (*packet)[0] = 'M';
  WriteU16Be(packet->data() + 3, sequence);
  WriteU16Be(packet->data() + 5, ack_sequence);
  (*packet)[7] = 0x0A;
  WriteU16Be(packet->data() + 8, 1);
  WriteU16Be(packet->data() + 10, static_cast<uint16_t>(payload.size()));
  packet->insert(packet->end(), payload.begin(), payload.end());
  return EncodeNetLayerFrameCrc(packet);
}

bool BuildSyntheticGameplayAckFrame(uint16_t ack_sequence, std::vector<unsigned char>* packet) {
  if (packet == nullptr || ack_sequence == 0) {
    return false;
  }

  packet->assign(kLegacyGameplayPayloadOffset, 0);
  (*packet)[0] = 'M';
  WriteU16Be(packet->data() + 3, 0);
  WriteU16Be(packet->data() + 5, ack_sequence);
  (*packet)[7] = 0x10;
  WriteU16Be(packet->data() + 8, 0);
  WriteU16Be(packet->data() + 10, 0);
  return EncodeNetLayerFrameCrc(packet);
}

void ScheduleAreaClientAreaLoadBarCompletion(
    BridgeRuntime* runtime,
    uint16_t after_sequence,
    uint16_t ack_sequence,
    const wchar_t* context) {
  if (runtime == nullptr) {
    return;
  }
  runtime->pending_area_loadbar_completion = true;
  runtime->pending_area_loadbar_after_sequence = after_sequence;
  runtime->pending_area_loadbar_ack_sequence = ack_sequence;
  runtime->pending_area_loadbar_after_sequence_is_client = false;
  runtime->pending_area_loadbar_shift_base = 0;
  if (runtime->options.packet_dump) {
    LogFormat(
        L"%s Area_ClientArea synthetic LoadBar completion scheduled: after_seq=%u ack=%u active_shifts=%zu",
        context != nullptr ? context : L"server->client",
        after_sequence,
        ack_sequence,
        runtime->server_sequence_shifts.size());
  }
}

void ScheduleAreaClientAreaLoadBarCompletionAfterClientSequence(
    BridgeRuntime* runtime,
    uint16_t after_client_sequence,
    uint16_t ack_sequence,
    uint16_t shift_base,
    const wchar_t* context) {
  if (runtime == nullptr) {
    return;
  }
  runtime->pending_area_loadbar_completion = true;
  runtime->pending_area_loadbar_after_sequence = after_client_sequence;
  runtime->pending_area_loadbar_ack_sequence = ack_sequence;
  runtime->pending_area_loadbar_after_sequence_is_client = true;
  runtime->pending_area_loadbar_shift_base = shift_base;
  if (runtime->options.packet_dump) {
    LogFormat(
        L"%s Area_ClientArea synthetic LoadBar completion scheduled after client seq: after_client_seq=%u ack=%u shift_base=%u active_shifts=%zu",
        context != nullptr ? context : L"server->client",
        after_client_sequence,
        ack_sequence,
        shift_base,
        runtime->server_sequence_shifts.size());
  }
}

void QueuePendingServerSequenceShiftAfterCurrent(
    BridgeRuntime* runtime,
    uint16_t base,
    uint16_t delta,
    const wchar_t* context) {
  if (runtime == nullptr || delta == 0) {
    return;
  }
  if (runtime->pending_server_sequence_shift_after_current) {
    LogFormat(
        L"%s server sequence shift after current replaced: old_base=%u old_delta=%u new_base=%u new_delta=%u",
        context != nullptr ? context : L"server->client",
        runtime->pending_server_sequence_shift_base,
        runtime->pending_server_sequence_shift_delta,
        base,
        delta);
  }
  runtime->pending_server_sequence_shift_after_current = true;
  runtime->pending_server_sequence_shift_base = base;
  runtime->pending_server_sequence_shift_delta = delta;
  if (runtime->options.packet_dump) {
    LogFormat(
        L"%s server sequence shift after current scheduled: base=%u delta=%u active_shifts=%zu",
        context != nullptr ? context : L"server->client",
        base,
        delta,
        runtime->server_sequence_shifts.size());
  }
}

void ApplyPendingServerSequenceShiftAfterCurrent(BridgeRuntime* runtime, const wchar_t* context) {
  if (runtime == nullptr || !runtime->pending_server_sequence_shift_after_current) {
    return;
  }
  const uint16_t base = runtime->pending_server_sequence_shift_base;
  const uint16_t delta = runtime->pending_server_sequence_shift_delta;
  runtime->pending_server_sequence_shift_after_current = false;
  runtime->pending_server_sequence_shift_base = 0;
  runtime->pending_server_sequence_shift_delta = 0;
  if (delta == 0) {
    return;
  }
  runtime->server_sequence_shifts.push_back(ServerSequenceShift{base, delta});
  LogFormat(
      L"%s server sequence shift after current applied: shift_base=%u shift_delta=%u active_shifts=%zu",
      context != nullptr ? context : L"server->client",
      base,
      delta,
      runtime->server_sequence_shifts.size());
}

bool ShiftServerFrameSequenceForClient(BridgeRuntime* runtime, std::vector<unsigned char>* packet) {
  if (runtime == nullptr || packet == nullptr || packet->empty() || packet->front() != 'M' ||
      runtime->server_sequence_shifts.empty()) {
    return false;
  }

  GameplayWrapperView view;
  if (!TryParseGameplayWrapper(packet->data(), packet->size(), &view) || view.sequence == 0) {
    return false;
  }

  const uint16_t shifted_sequence = ShiftServerSequenceForClient(*runtime, view.sequence);
  if (shifted_sequence == view.sequence) {
    return false;
  }

  WriteU16Be(packet->data() + 3, shifted_sequence);
  const bool crc_updated = EncodeNetLayerFrameCrc(packet);
  ++runtime->server_sequence_shift_count;
  if (runtime->server_sequence_shift_count <= 40 || runtime->options.packet_dump) {
    LogFormat(
        L"server->client M sequence shifted #%llu: seq=%u->%u ack=%u shifts=%zu crc_updated=%d high=%d name='%s'",
        static_cast<unsigned long long>(runtime->server_sequence_shift_count),
        view.sequence,
        shifted_sequence,
        view.ack_sequence,
        runtime->server_sequence_shifts.size(),
        crc_updated ? 1 : 0,
        view.has_high_envelope ? 1 : 0,
        view.has_high_envelope ? KnownMajorMinorName(view.high_major, view.high_minor) : L"<none>");
  }
  return true;
}

void ShiftServerFramesForClient(
    BridgeRuntime* runtime,
    std::vector<unsigned char>* packet,
    std::vector<std::vector<unsigned char>>* extra_packets) {
  ShiftServerFrameSequenceForClient(runtime, packet);
  if (extra_packets == nullptr) {
    return;
  }
  for (std::vector<unsigned char>& extra_packet : *extra_packets) {
    ShiftServerFrameSequenceForClient(runtime, &extra_packet);
  }
}

