void ObserveLatestClientSequenceFromClient(BridgeRuntime* runtime, const std::vector<unsigned char>& packet) {
  if (runtime == nullptr || packet.empty() || packet.front() != 'M') {
    return;
  }

  GameplayWrapperView view;
  if (!TryParseGameplayWrapper(packet.data(), packet.size(), &view) || view.sequence == 0) {
    return;
  }

  runtime->latest_client_sequence_from_client = view.sequence;
  runtime->have_latest_client_sequence_from_client = true;
}

void ObserveClientVaultListStartupMessage(BridgeRuntime* runtime, const std::vector<unsigned char>& packet) {
  if (runtime == nullptr || packet.empty() || packet.front() != 'M') {
    return;
  }

  GameplayWrapperView view;
  if (!TryParseGameplayWrapper(packet.data(), packet.size(), &view) || !view.has_high_envelope) {
    return;
  }

  if (view.high_major == 0x11 && view.high_minor == 0x01) {
    ++runtime->client_charlist_request_observed_count;
    const bool first = !runtime->client_charlist_request_observed;
    runtime->client_charlist_request_observed = true;
    if (first || runtime->client_charlist_request_observed_count <= 8 || runtime->options.packet_dump) {
      LogFormat(
          L"client CharList_Request observed #%llu: seq=%u ack=%u latest_known=%d latest_seq=%u",
          static_cast<unsigned long long>(runtime->client_charlist_request_observed_count),
          view.sequence,
          view.ack_sequence,
          runtime->have_latest_client_sequence_from_client ? 1 : 0,
          runtime->latest_client_sequence_from_client);
    }
    return;
  }

  if (view.high_major == 0x31 && view.high_minor == 0x01) {
    ++runtime->client_play_module_character_list_start_observed_count;
    const bool first = !runtime->client_play_module_character_list_start_observed;
    runtime->client_play_module_character_list_start_observed = true;
    if (first ||
        runtime->client_play_module_character_list_start_observed_count <= 8 ||
        runtime->options.packet_dump) {
      LogFormat(
          L"client PlayModuleCharacterList_Start observed #%llu: seq=%u ack=%u latest_known=%d latest_seq=%u",
          static_cast<unsigned long long>(runtime->client_play_module_character_list_start_observed_count),
          view.sequence,
          view.ack_sequence,
          runtime->have_latest_client_sequence_from_client ? 1 : 0,
          runtime->latest_client_sequence_from_client);
    }
  }
}

void QueueSyntheticVaultListReplay(BridgeRuntime* runtime, uint16_t server_ack_sequence, const wchar_t* reason) {
  constexpr uint16_t kSyntheticVaultListFrameCount = 2;
  if (runtime == nullptr) {
    return;
  }

  if (runtime->vault_list_replay_queued) {
    ++runtime->vault_list_replay_skipped_count;
    if (runtime->vault_list_replay_skipped_count <= 8 || runtime->options.packet_dump) {
      LogFormat(
          L"client->server synthetic vault-list replay skipped #%llu: already queued reason=%s",
          static_cast<unsigned long long>(runtime->vault_list_replay_skipped_count),
          reason != nullptr ? reason : L"<unknown>");
    }
    return;
  }

  if (!runtime->client_charlist_request_observed) {
    ++runtime->vault_list_replay_skipped_count;
    LogFormat(
        L"client->server synthetic vault-list replay skipped #%llu: no client CharList_Request observed reason=%s",
        static_cast<unsigned long long>(runtime->vault_list_replay_skipped_count),
        reason != nullptr ? reason : L"<unknown>");
    return;
  }

  if (!runtime->have_latest_client_sequence_from_client) {
    ++runtime->vault_list_replay_skipped_count;
    LogFormat(
        L"client->server synthetic vault-list replay skipped #%llu: latest client sequence is unknown reason=%s server_ack=%u",
        static_cast<unsigned long long>(runtime->vault_list_replay_skipped_count),
        reason != nullptr ? reason : L"<unknown>",
        server_ack_sequence);
    return;
  }

  const uint16_t ack_sequence = server_ack_sequence != 0 ? server_ack_sequence : 0xFFFFu;
  const uint16_t original_after = runtime->latest_client_sequence_from_client;
  const uint16_t original_charlist_sequence = static_cast<uint16_t>(original_after + 1);
  const uint16_t original_play_start_sequence = static_cast<uint16_t>(original_after + 2);
  const uint16_t shifted_charlist_sequence =
      ShiftClientSequenceForServer(*runtime, original_charlist_sequence);
  const uint16_t shifted_play_start_sequence =
      ShiftClientSequenceForServer(*runtime, original_play_start_sequence);

  std::vector<unsigned char> charlist_payload{0x70, 0x11, 0x01};
  std::vector<unsigned char> play_start_payload{0x70, 0x31, 0x01};
  std::vector<unsigned char> charlist_packet;
  std::vector<unsigned char> play_start_packet;
  if (!BuildSyntheticGameplayFrame(
          shifted_charlist_sequence,
          ack_sequence,
          charlist_payload,
          &charlist_packet) ||
      !BuildSyntheticGameplayFrame(
          shifted_play_start_sequence,
          ack_sequence,
          play_start_payload,
          &play_start_packet)) {
    ++runtime->vault_list_replay_skipped_count;
    LogFormat(
        L"client->server synthetic vault-list replay build failed #%llu: original_after=%u original_seq=%u/%u shifted_seq=%u/%u ack=%u reason=%s",
        static_cast<unsigned long long>(runtime->vault_list_replay_skipped_count),
        original_after,
        original_charlist_sequence,
        original_play_start_sequence,
        shifted_charlist_sequence,
        shifted_play_start_sequence,
        ack_sequence,
        reason != nullptr ? reason : L"<unknown>");
    return;
  }

  runtime->client_sequence_shifts.push_back(
      ServerSequenceShift{original_charlist_sequence, kSyntheticVaultListFrameCount});
  runtime->pending_client_to_server_packets.push_back(std::move(charlist_packet));
  runtime->pending_client_to_server_packets.push_back(std::move(play_start_packet));
  runtime->latest_client_sequence_from_client = original_play_start_sequence;
  runtime->have_latest_client_sequence_from_client = true;
  runtime->vault_list_replay_queued = true;
  ++runtime->vault_list_replay_synthetic_count;
  LogFormat(
      L"client->server synthetic vault-list replay queued #%llu: reason=%s original_after=%u original_seq=%u/%u shifted_seq=%u/%u ack=%u charlist_seen=%llu play_start_seen=%llu shift_base=%u shift_delta=%u client_shifts=%zu",
      static_cast<unsigned long long>(runtime->vault_list_replay_synthetic_count),
      reason != nullptr ? reason : L"<unknown>",
      original_after,
      original_charlist_sequence,
      original_play_start_sequence,
      shifted_charlist_sequence,
      shifted_play_start_sequence,
      ack_sequence,
      static_cast<unsigned long long>(runtime->client_charlist_request_observed_count),
      static_cast<unsigned long long>(runtime->client_play_module_character_list_start_observed_count),
      original_charlist_sequence,
      kSyntheticVaultListFrameCount,
      runtime->client_sequence_shifts.size());
}

void MaybeQueueVaultListReplayAfterServerModuleRunning(BridgeRuntime* runtime, const std::vector<unsigned char>& packet) {
  if (runtime == nullptr || packet.empty() || packet.front() != 'M') {
    return;
  }

  GameplayWrapperView view;
  if (!TryParseGameplayWrapper(packet.data(), packet.size(), &view) ||
      !view.has_high_envelope ||
      view.high_major != 0x01 ||
      view.high_minor != 0x03) {
    return;
  }

  ++runtime->server_status_module_running_observed_count;
  if (runtime->server_status_module_running_observed_count <= 8 || runtime->options.packet_dump) {
    LogFormat(
        L"server ServerStatus_ModuleRunning observed #%llu for vault-list timing: seq=%u ack=%u payload=%zu client_charlist_seen=%d play_start_seen=%d replay_queued=%d",
        static_cast<unsigned long long>(runtime->server_status_module_running_observed_count),
        view.sequence,
        view.ack_sequence,
        view.payload_length,
        runtime->client_charlist_request_observed ? 1 : 0,
        runtime->client_play_module_character_list_start_observed ? 1 : 0,
        runtime->vault_list_replay_queued ? 1 : 0);
  }

  if (runtime->client_charlist_request_observed && !runtime->vault_list_replay_queued) {
    ++runtime->vault_list_replay_skipped_count;
    if (runtime->vault_list_replay_skipped_count <= 8 || runtime->options.packet_dump) {
      LogFormat(
          L"client->server synthetic vault-list replay skipped #%llu: disabled after ServerStatus_ModuleRunning; preserving original client request timing",
          static_cast<unsigned long long>(runtime->vault_list_replay_skipped_count));
    }
  }
}

void QueueSyntheticAreaLoadedClientPacket(BridgeRuntime* runtime, uint16_t server_ack_sequence) {
  if (runtime == nullptr || !runtime->have_latest_client_sequence_from_client) {
    LogFormat(
        L"client->server synthetic Area_AreaLoaded skipped: latest client sequence is unknown ack=%u",
        server_ack_sequence);
    return;
  }

  std::vector<unsigned char> payload{0x70, 0x04, 0x03};
  const uint16_t original_after = runtime->latest_client_sequence_from_client;
  const uint16_t original_sequence = static_cast<uint16_t>(original_after + 1);
  const uint16_t shifted_sequence = ShiftClientSequenceForServer(*runtime, original_sequence);
  std::vector<unsigned char> packet;
  if (!BuildSyntheticGameplayFrame(shifted_sequence, server_ack_sequence, payload, &packet)) {
    LogFormat(
        L"client->server synthetic Area_AreaLoaded build failed: original_seq=%u shifted_seq=%u ack=%u",
        original_sequence,
        shifted_sequence,
        server_ack_sequence);
    return;
  }

  runtime->client_sequence_shifts.push_back(ServerSequenceShift{original_sequence, 1});
  runtime->pending_client_to_server_packets.push_back(std::move(packet));
  runtime->latest_client_sequence_from_client = original_sequence;
  ++runtime->area_client_area_loaded_synthetic_count;
  LogFormat(
      L"client->server synthetic Area_AreaLoaded queued #%llu: original_seq=%u shifted_seq=%u ack=%u shift_base=%u shift_delta=1 client_shifts=%zu",
      static_cast<unsigned long long>(runtime->area_client_area_loaded_synthetic_count),
      original_sequence,
      shifted_sequence,
      server_ack_sequence,
      original_sequence,
      runtime->client_sequence_shifts.size());
}

void ScheduleSyntheticAreaLoadedClientPacketAfterClientAck(
    BridgeRuntime* runtime,
    uint16_t server_ack_sequence,
    uint16_t release_client_ack_sequence) {
  if (runtime == nullptr) {
    return;
  }

  if (runtime->pending_area_loaded_client_packet) {
    LogFormat(
        L"client->server synthetic Area_AreaLoaded deferred packet replaced: old_server_ack=%u old_release_client_ack=%u new_server_ack=%u new_release_client_ack=%u",
        runtime->pending_area_loaded_server_ack_sequence,
        runtime->pending_area_loaded_release_client_ack_sequence,
        server_ack_sequence,
        release_client_ack_sequence);
  }

  runtime->pending_area_loaded_client_packet = true;
  runtime->pending_area_loaded_server_ack_sequence = server_ack_sequence;
  runtime->pending_area_loaded_release_client_ack_sequence = release_client_ack_sequence;
  ++runtime->area_client_area_loaded_deferred_count;
  LogFormat(
      L"client->server synthetic Area_AreaLoaded deferred #%llu: server_ack=%u release_client_ack=%u latest_client_seq_known=%d latest_client_seq=%u",
      static_cast<unsigned long long>(runtime->area_client_area_loaded_deferred_count),
      server_ack_sequence,
      release_client_ack_sequence,
      runtime->have_latest_client_sequence_from_client ? 1 : 0,
      runtime->latest_client_sequence_from_client);
}

void MaybeReleasePendingSyntheticAreaLoadedAfterClientAck(
    BridgeRuntime* runtime,
    const std::vector<unsigned char>& packet) {
  if (runtime == nullptr || !runtime->pending_area_loaded_client_packet ||
      packet.empty() || packet.front() != 'M') {
    return;
  }

  GameplayWrapperView view;
  if (!TryParseGameplayWrapper(packet.data(), packet.size(), &view) || view.ack_sequence == 0) {
    return;
  }

  const uint16_t release_ack = runtime->pending_area_loaded_release_client_ack_sequence;
  if (!SequenceAtOrAfter(view.ack_sequence, release_ack)) {
    if (runtime->options.packet_dump) {
      LogFormat(
          L"client->server synthetic Area_AreaLoaded still deferred: observed_client_ack=%u release_client_ack=%u server_ack=%u",
          view.ack_sequence,
          release_ack,
          runtime->pending_area_loaded_server_ack_sequence);
    }
    return;
  }

  const uint16_t server_ack_sequence = runtime->pending_area_loaded_server_ack_sequence;
  runtime->pending_area_loaded_client_packet = false;
  runtime->pending_area_loaded_server_ack_sequence = 0;
  runtime->pending_area_loaded_release_client_ack_sequence = 0;
  ++runtime->area_client_area_loaded_released_count;
  LogFormat(
      L"client->server synthetic Area_AreaLoaded releasing #%llu: observed_client_ack=%u release_client_ack=%u server_ack=%u client_seq=%u",
      static_cast<unsigned long long>(runtime->area_client_area_loaded_released_count),
      view.ack_sequence,
      release_ack,
      server_ack_sequence,
      view.sequence);
  QueueSyntheticAreaLoadedClientPacket(runtime, server_ack_sequence);
}

uint16_t QueuePendingAreaClientAreaLoadBarCompletion(
    BridgeRuntime* runtime,
    std::vector<std::vector<unsigned char>>* extra_packets) {
  constexpr uint32_t kDefaultAreaStallEventId = 2;
  if (runtime == nullptr || extra_packets == nullptr || !runtime->pending_area_loadbar_completion) {
    return 0;
  }
  if (!runtime->options.synthesize_area_loadbar) {
    LogFormat(
        L"server->client Area_ClientArea synthetic LoadBar completion suppressed by --no-synthetic-area-loadbar: after_seq=%u after_is_client=%d ack=%u shift_base=%u active_shifts=%zu",
        runtime->pending_area_loadbar_after_sequence,
        runtime->pending_area_loadbar_after_sequence_is_client ? 1 : 0,
        runtime->pending_area_loadbar_ack_sequence,
        runtime->pending_area_loadbar_shift_base,
        runtime->server_sequence_shifts.size());
    runtime->pending_area_loadbar_completion = false;
    runtime->pending_area_loadbar_after_sequence_is_client = false;
    runtime->pending_area_loadbar_shift_base = 0;
    return 0;
  }

  std::vector<unsigned char> start_payload;
  std::vector<unsigned char> end_payload;
  AppendEeLoadBarStartPayload(&start_payload, kDefaultAreaStallEventId);
  AppendEeLoadBarEndPayload(&end_payload, kDefaultAreaStallEventId);

  const uint16_t original_after = runtime->pending_area_loadbar_after_sequence;
  const uint16_t shifted_after = runtime->pending_area_loadbar_after_sequence_is_client
      ? original_after
      : ShiftServerSequenceForClient(*runtime, original_after);
  const uint16_t start_sequence = static_cast<uint16_t>(shifted_after + 1);
  const uint16_t end_sequence = static_cast<uint16_t>(shifted_after + 2);
  const uint16_t ack_sequence = runtime->pending_area_loadbar_ack_sequence;

  std::vector<unsigned char> start_packet;
  std::vector<unsigned char> end_packet;
  if (!BuildSyntheticGameplayFrame(start_sequence, ack_sequence, start_payload, &start_packet) ||
      !BuildSyntheticGameplayFrame(end_sequence, ack_sequence, end_payload, &end_packet)) {
    LogFormat(
        L"server->client Area_ClientArea synthetic LoadBar completion failed to build: after_original_seq=%u shifted_after_seq=%u ack=%u",
        original_after,
        shifted_after,
        ack_sequence);
    runtime->pending_area_loadbar_completion = false;
    runtime->pending_area_loadbar_after_sequence_is_client = false;
    runtime->pending_area_loadbar_shift_base = 0;
    return 0;
  }

  const uint16_t base = runtime->pending_area_loadbar_shift_base != 0
      ? runtime->pending_area_loadbar_shift_base
      : static_cast<uint16_t>(original_after + 1);
  runtime->server_sequence_shifts.push_back(ServerSequenceShift{base, kSyntheticAreaLoadBarFrameCount});
  extra_packets->push_back(std::move(start_packet));
  extra_packets->push_back(std::move(end_packet));
  ++runtime->area_client_area_loadbar_completion_count;
  LogFormat(
      L"server->client Area_ClientArea synthetic LoadBar M frames queued #%llu: after_seq=%u after_is_client=%d shifted_after_seq=%u start_seq=%u end_seq=%u ack=%u shift_base=%u shift_delta=%u active_shifts=%zu",
      static_cast<unsigned long long>(runtime->area_client_area_loadbar_completion_count),
      original_after,
      runtime->pending_area_loadbar_after_sequence_is_client ? 1 : 0,
      shifted_after,
      start_sequence,
      end_sequence,
      ack_sequence,
      base,
      kSyntheticAreaLoadBarFrameCount,
      runtime->server_sequence_shifts.size());
  runtime->pending_area_loadbar_completion = false;
  runtime->pending_area_loadbar_after_sequence_is_client = false;
  runtime->pending_area_loadbar_shift_base = 0;
  return kSyntheticAreaLoadBarFrameCount;
}

void QueuePendingAreaClientAreaSideEffects(
    BridgeRuntime* runtime,
    std::vector<std::vector<unsigned char>>* extra_packets) {
  if (runtime == nullptr || !runtime->pending_area_loadbar_completion) {
    return;
  }

  const uint16_t server_ack_sequence =
      runtime->pending_area_loadbar_after_sequence_is_client &&
          runtime->pending_area_loadbar_shift_base != 0
      ? static_cast<uint16_t>(runtime->pending_area_loadbar_shift_base - 1)
      : runtime->pending_area_loadbar_after_sequence;
  const uint16_t shifted_after_sequence = runtime->pending_area_loadbar_after_sequence_is_client
      ? runtime->pending_area_loadbar_after_sequence
      : ShiftServerSequenceForClient(*runtime, runtime->pending_area_loadbar_after_sequence);
  const uint16_t server_to_client_ack_sequence = runtime->pending_area_loadbar_ack_sequence;
  const uint16_t synthetic_loadbar_frame_count =
      QueuePendingAreaClientAreaLoadBarCompletion(runtime, extra_packets);
  const uint16_t release_client_ack_sequence =
      static_cast<uint16_t>(shifted_after_sequence + synthetic_loadbar_frame_count);
  if (runtime->options.synthesize_area_loaded) {
    ScheduleSyntheticAreaLoadedClientPacketAfterClientAck(
        runtime,
        server_ack_sequence,
        release_client_ack_sequence);
  } else {
    LogFormat(
        L"client->server synthetic Area_AreaLoaded deferred: proxy cannot observe successful EE Area_ClientArea dispatch after_seq=%u ack=%u",
        server_ack_sequence,
        server_to_client_ack_sequence);
  }
}

bool IsAreaResrefChar(unsigned char ch) {
  return (ch >= 'a' && ch <= 'z') ||
      (ch >= 'A' && ch <= 'Z') ||
      (ch >= '0' && ch <= '9') ||
      ch == '_';
}

bool IsFixedAreaResrefCandidateAt(
    const std::vector<unsigned char>& payload,
    size_t offset,
    size_t fragment_offset,
    std::string* preview) {
  if (preview != nullptr) {
    preview->clear();
  }
  if (offset + kCResRefTextBytes > fragment_offset || fragment_offset > payload.size()) {
    return false;
  }

  size_t length = 0;
  while (length < kCResRefTextBytes && payload[offset + length] != 0) {
    if (!IsAreaResrefChar(payload[offset + length])) {
      return false;
    }
    ++length;
  }
  if (length < 2) {
    return false;
  }
  for (size_t index = length; index < kCResRefTextBytes; ++index) {
    if (payload[offset + index] != 0) {
      return false;
    }
  }
  if (preview != nullptr) {
    preview->assign(
        reinterpret_cast<const char*>(payload.data() + offset),
        reinterpret_cast<const char*>(payload.data() + offset + length));
  }
  return true;
}

std::wstring FormatAreaFixedResrefCandidates(
    const std::vector<unsigned char>& payload,
    size_t fragment_offset) {
  constexpr size_t kPayloadHeaderBytes = 3;
  constexpr size_t kMaxLoggedCandidates = 32;
  std::wstring summary;
  size_t logged = 0;
  size_t total = 0;

  if (fragment_offset > payload.size() || fragment_offset < kPayloadHeaderBytes + kCResRefTextBytes) {
    return L"<unavailable>";
  }

  for (size_t offset = kPayloadHeaderBytes; offset + kCResRefTextBytes <= fragment_offset; ++offset) {
    std::string preview;
    if (!IsFixedAreaResrefCandidateAt(payload, offset, fragment_offset, &preview)) {
      continue;
    }
    ++total;
    if (logged >= kMaxLoggedCandidates) {
      continue;
    }
    if (!summary.empty()) {
      summary += L"; ";
    }
    summary += L"+";
    summary += std::to_wstring(offset - kPayloadHeaderBytes);
    summary += L"='";
    summary += AsciiPreviewToWide(preview, 32);
    summary += L"'";
    ++logged;
  }

  if (summary.empty()) {
    return L"<none>";
  }
  if (total > logged) {
    summary += L"; ... ";
    summary += std::to_wstring(total - logged);
    summary += L" more";
  }
  return summary;
}

bool IsPrintableAreaStringByte(unsigned char ch) {
  return ch == '\t' || ch == '\r' || ch == '\n' || (ch >= 0x20 && ch <= 0x7E);
}

std::wstring FormatAreaLengthStringCandidates(
    const std::vector<unsigned char>& payload,
    size_t fragment_offset) {
  constexpr size_t kPayloadHeaderBytes = 3;
  constexpr uint32_t kMaxAreaDiagnosticStringBytes = 160;
  constexpr size_t kMaxLoggedCandidates = 16;
  std::wstring summary;
  size_t logged = 0;
  size_t total = 0;

  if (fragment_offset > payload.size() || fragment_offset < kPayloadHeaderBytes + sizeof(uint32_t)) {
    return L"<unavailable>";
  }

  for (size_t offset = kPayloadHeaderBytes; offset + sizeof(uint32_t) <= fragment_offset; ++offset) {
    const uint32_t length = ReadU32Le(payload.data() + offset);
    if (length == 0 ||
        length > kMaxAreaDiagnosticStringBytes ||
        length > fragment_offset - offset - sizeof(uint32_t)) {
      continue;
    }

    bool printable = true;
    for (size_t index = 0; index < length; ++index) {
      if (!IsPrintableAreaStringByte(payload[offset + sizeof(uint32_t) + index])) {
        printable = false;
        break;
      }
    }
    if (!printable) {
      continue;
    }

    ++total;
    if (logged >= kMaxLoggedCandidates) {
      continue;
    }
    std::string preview(
        reinterpret_cast<const char*>(payload.data() + offset + sizeof(uint32_t)),
        reinterpret_cast<const char*>(payload.data() + offset + sizeof(uint32_t) + length));
    if (!summary.empty()) {
      summary += L"; ";
    }
    summary += L"+";
    summary += std::to_wstring(offset - kPayloadHeaderBytes);
    summary += L"[";
    summary += std::to_wstring(length);
    summary += L"]='";
    summary += AsciiPreviewToWide(preview, 80);
    summary += L"'";
    ++logged;
  }

  if (summary.empty()) {
    return L"<none>";
  }
  if (total > logged) {
    summary += L"; ... ";
    summary += std::to_wstring(total - logged);
    summary += L" more";
  }
  return summary;
}

constexpr size_t kAreaPayloadHeaderBytes = 3;
constexpr size_t kAreaWidthReadOffset = 162;
constexpr size_t kAreaHeightReadOffset = 166;
constexpr size_t kAreaTileSetReadOffset = 170;
constexpr size_t kAreaFirstTileReadOffset = kAreaTileSetReadOffset + kCResRefTextBytes;
constexpr uint32_t kMaxReasonableAreaDimension = 512;
constexpr uint32_t kMaxReasonableAreaTileCount = 65536;

struct AreaTileStreamScan {
  bool valid = false;
  uint32_t width = 0;
  uint32_t packet_height = 0;
  uint32_t inferred_height = 0;
  uint32_t tile_count = 0;
  uint32_t max_tile_id = 0;
  size_t tile_start_read_offset = kAreaFirstTileReadOffset;
  size_t tile_end_read_offset = kAreaFirstTileReadOffset;
  bool has_following_dword = false;
  uint32_t following_dword = 0;
  std::wstring stop_reason;
};

int64_t SignExtendU32ToI64(uint32_t value) {
  if (value <= 0x7FFFFFFFu) {
    return static_cast<int64_t>(value);
  }
  return -static_cast<int64_t>((~value) + 1u);
}

bool TryAreaReadU32(
    const std::vector<unsigned char>& payload,
    size_t fragment_offset,
    size_t read_offset,
    uint32_t* value) {
  const size_t payload_offset = kAreaPayloadHeaderBytes + read_offset;
  if (payload_offset > fragment_offset ||
      fragment_offset - payload_offset < sizeof(uint32_t)) {
    if (value != nullptr) {
      *value = 0;
    }
    return false;
  }
  return TryReadU32LeFromBytes(payload, payload_offset, value);
}

bool TryAreaReadU16(
    const std::vector<unsigned char>& payload,
    size_t fragment_offset,
    size_t read_offset,
    uint16_t* value) {
  const size_t payload_offset = kAreaPayloadHeaderBytes + read_offset;
  if (payload_offset > fragment_offset ||
      fragment_offset - payload_offset < sizeof(uint16_t)) {
    if (value != nullptr) {
      *value = 0;
    }
    return false;
  }
  return TryReadU16LeFromBytes(payload, payload_offset, value);
}

size_t AreaTileRecordByteCount(uint16_t flags) {
  size_t length = sizeof(uint32_t) + sizeof(uint32_t) + sizeof(uint32_t) + sizeof(uint16_t);
  if ((flags & 0x0001u) != 0) {
    ++length;
  }
  if ((flags & 0x0002u) != 0) {
    ++length;
  }
  // EE's writer always ORs the source-light bits and then writes both bytes.
  length += 2;
  if ((flags & 0x0010u) != 0) {
    ++length;
  }
  if ((flags & 0x0020u) != 0) {
    ++length;
  }
  if ((flags & 0x0040u) != 0) {
    ++length;
  }
  if ((flags & 0x0080u) != 0) {
    ++length;
  }
  return length;
}

bool LooksLikeEeAreaTileRecordAt(
    const std::vector<unsigned char>& payload,
    size_t fragment_offset,
    size_t read_offset,
    size_t* record_length,
    uint32_t* tile_id_out,
    uint16_t* flags_out,
    std::wstring* failure_reason) {
  if (record_length != nullptr) {
    *record_length = 0;
  }
  if (tile_id_out != nullptr) {
    *tile_id_out = 0;
  }
  if (flags_out != nullptr) {
    *flags_out = 0;
  }

  uint32_t tile_id = 0;
  uint32_t orientation = 0;
  uint32_t raw_height = 0;
  uint16_t flags = 0;
  if (!TryAreaReadU32(payload, fragment_offset, read_offset, &tile_id) ||
      !TryAreaReadU32(payload, fragment_offset, read_offset + 4, &orientation) ||
      !TryAreaReadU32(payload, fragment_offset, read_offset + 8, &raw_height) ||
      !TryAreaReadU16(payload, fragment_offset, read_offset + 12, &flags)) {
    if (failure_reason != nullptr) {
      *failure_reason = L"truncated tile header";
    }
    return false;
  }
  if (tile_id > 65535u) {
    if (failure_reason != nullptr) {
      *failure_reason = L"tile id outside plausible tileset range";
    }
    return false;
  }
  if (orientation > 3u) {
    if (failure_reason != nullptr) {
      *failure_reason = L"tile orientation outside 0..3";
    }
    return false;
  }
  const int64_t signed_height = SignExtendU32ToI64(raw_height);
  if (signed_height < -256 || signed_height > 1024) {
    if (failure_reason != nullptr) {
      *failure_reason = L"tile height outside plausible range";
    }
    return false;
  }
  if ((flags & 0xFF00u) != 0 || (flags & 0x000Cu) != 0x000Cu) {
    if (failure_reason != nullptr) {
      *failure_reason = L"tile light/animation mask outside EE writer shape";
    }
    return false;
  }

  const size_t length = AreaTileRecordByteCount(flags);
  const size_t payload_offset = kAreaPayloadHeaderBytes + read_offset;
  if (payload_offset > fragment_offset || length > fragment_offset - payload_offset) {
    if (failure_reason != nullptr) {
      *failure_reason = L"tile optional bytes truncated";
    }
    return false;
  }
  if (record_length != nullptr) {
    *record_length = length;
  }
  if (tile_id_out != nullptr) {
    *tile_id_out = tile_id;
  }
  if (flags_out != nullptr) {
    *flags_out = flags;
  }
  return true;
}

AreaTileStreamScan ScanAreaTileStream(
    const std::vector<unsigned char>& payload,
    size_t fragment_offset) {
  AreaTileStreamScan scan;
  if (fragment_offset > payload.size()) {
    scan.stop_reason = L"fragment offset outside payload";
    return scan;
  }
  if (!TryAreaReadU32(payload, fragment_offset, kAreaWidthReadOffset, &scan.width) ||
      !TryAreaReadU32(payload, fragment_offset, kAreaHeightReadOffset, &scan.packet_height)) {
    scan.stop_reason = L"missing width/height";
    return scan;
  }
  if (scan.width == 0 || scan.width > kMaxReasonableAreaDimension) {
    scan.stop_reason = L"width outside scan range";
    return scan;
  }

  size_t cursor = kAreaFirstTileReadOffset;
  while (scan.tile_count < kMaxReasonableAreaTileCount) {
    size_t record_length = 0;
    uint32_t tile_id = 0;
    uint16_t flags = 0;
    std::wstring stop_reason;
    if (!LooksLikeEeAreaTileRecordAt(
            payload,
            fragment_offset,
            cursor,
            &record_length,
            &tile_id,
            &flags,
            &stop_reason)) {
      scan.stop_reason = stop_reason.empty() ? L"next record is not tile-shaped" : stop_reason;
      break;
    }
    (void)flags;
    ++scan.tile_count;
    scan.max_tile_id = std::max(scan.max_tile_id, tile_id);
    cursor += record_length;
  }

  scan.tile_end_read_offset = cursor;
  if (scan.tile_count == 0) {
    if (scan.stop_reason.empty()) {
      scan.stop_reason = L"no tile-shaped records";
    }
    return scan;
  }
  if (scan.tile_count >= kMaxReasonableAreaTileCount) {
    scan.stop_reason = L"tile count exceeded scan limit";
    return scan;
  }
  if (scan.tile_count % scan.width != 0) {
    scan.stop_reason += L"; count not divisible by width";
    return scan;
  }
  scan.inferred_height = scan.tile_count / scan.width;
  if (scan.inferred_height == 0 || scan.inferred_height > kMaxReasonableAreaDimension) {
    scan.stop_reason += L"; inferred height outside scan range";
    return scan;
  }
  const size_t following_payload_offset = kAreaPayloadHeaderBytes + scan.tile_end_read_offset;
  if (following_payload_offset <= fragment_offset &&
      fragment_offset - following_payload_offset >= sizeof(uint32_t)) {
    scan.has_following_dword =
        TryReadU32LeFromBytes(payload, following_payload_offset, &scan.following_dword);
  }
  scan.valid = true;
  return scan;
}

std::wstring FormatAreaTileStreamScan(const AreaTileStreamScan& scan) {
  std::wstring summary = L"tile-scan ";
  if (!scan.valid) {
    summary += L"invalid";
    if (!scan.stop_reason.empty()) {
      summary += L":";
      summary += scan.stop_reason;
    }
    summary += L" width=" + std::to_wstring(scan.width);
    summary += L" packet-height=" + std::to_wstring(scan.packet_height);
    summary += L" count=" + std::to_wstring(scan.tile_count);
    summary += L" end@" + std::to_wstring(scan.tile_end_read_offset);
    return summary;
  }
  summary += L"count=" + std::to_wstring(scan.tile_count);
  summary += L" width=" + std::to_wstring(scan.width);
  summary += L" inferred-height=" + std::to_wstring(scan.inferred_height);
  summary += L" packet-height=" + std::to_wstring(scan.packet_height);
  summary += L" end@" + std::to_wstring(scan.tile_end_read_offset);
  summary += L" max-tile=" + std::to_wstring(scan.max_tile_id);
  if (scan.has_following_dword) {
    wchar_t cell[64]{};
    swprintf_s(cell, L" following-u32=%u/0x%08X", scan.following_dword, scan.following_dword);
    summary += cell;
  }
  return summary;
}

bool RepairMissingAreaHeightFromTileStream(
    std::vector<unsigned char>* payload,
    size_t fragment_offset,
    AreaTileStreamScan* scan_out,
    std::wstring* failure_reason) {
  if (scan_out != nullptr) {
    *scan_out = AreaTileStreamScan{};
  }
  if (failure_reason != nullptr) {
    failure_reason->clear();
  }
  if (payload == nullptr) {
    if (failure_reason != nullptr) {
      *failure_reason = L"missing payload";
    }
    return false;
  }
  AreaTileStreamScan scan = ScanAreaTileStream(*payload, fragment_offset);
  if (scan_out != nullptr) {
    *scan_out = scan;
  }
  if (!scan.valid) {
    if (failure_reason != nullptr) {
      *failure_reason = FormatAreaTileStreamScan(scan);
    }
    return false;
  }
  if (scan.packet_height != 0) {
    return false;
  }
  if (scan.inferred_height == 0 || scan.inferred_height > kMaxReasonableAreaDimension) {
    if (failure_reason != nullptr) {
      *failure_reason = L"inferred height outside range";
    }
    return false;
  }
  return TryWriteU32LeToBytes(
      payload,
      kAreaPayloadHeaderBytes + kAreaHeightReadOffset,
      scan.inferred_height);
}

std::wstring FormatAreaClientAreaStaticHeader(
    const std::vector<unsigned char>& payload,
    size_t fragment_offset) {
  constexpr size_t kPreDimensionBytesOffset = 156;
  constexpr size_t kPreDimensionBytesLength = 6;
  constexpr size_t kFirstTileOffset = kAreaTileSetReadOffset + kCResRefTextBytes;
  constexpr size_t kFirstTileOrientationOffset = kFirstTileOffset + sizeof(uint32_t);
  constexpr size_t kFirstTileThirdIntOffset = kFirstTileOrientationOffset + sizeof(uint32_t);
  constexpr size_t kFirstTileFlagsOffset = kFirstTileThirdIntOffset + sizeof(uint32_t);
  constexpr size_t kRawPreviewOffset = 144;
  constexpr size_t kRawPreviewBytes = 80;

  auto has_read_buffer_bytes = [&](size_t read_buffer_offset, size_t length) {
    const size_t payload_offset = kAreaPayloadHeaderBytes + read_buffer_offset;
    return payload_offset <= payload.size() &&
        length <= payload.size() - payload_offset &&
        payload_offset <= fragment_offset &&
        length <= fragment_offset - payload_offset;
  };
  auto payload_offset_for = [&](size_t read_buffer_offset) {
    return kAreaPayloadHeaderBytes + read_buffer_offset;
  };

  std::wstring summary;
  auto append = [&](const std::wstring& value) {
    if (!summary.empty()) {
      summary += L" ";
    }
    summary += value;
  };
  auto append_u32 = [&](const wchar_t* label, size_t read_buffer_offset) {
    uint32_t value = 0;
    std::wstring part(label);
    part += L"@";
    part += std::to_wstring(read_buffer_offset);
    part += L"=";
    if (has_read_buffer_bytes(read_buffer_offset, sizeof(uint32_t)) &&
        TryReadU32LeFromBytes(payload, payload_offset_for(read_buffer_offset), &value)) {
      wchar_t cell[64]{};
      swprintf_s(cell, L"%u/0x%08X", value, value);
      part += cell;
    } else {
      part += L"<unavailable>";
    }
    append(part);
  };

  if (has_read_buffer_bytes(kPreDimensionBytesOffset, kPreDimensionBytesLength)) {
    append(
        L"pre-dim@156=[" +
        FormatLimitedBytes(
            payload.data() + payload_offset_for(kPreDimensionBytesOffset),
            kPreDimensionBytesLength,
            kPreDimensionBytesLength) +
        L"]");
  } else {
    append(L"pre-dim@156=<unavailable>");
  }

  append_u32(L"width", kAreaWidthReadOffset);
  append_u32(L"height", kAreaHeightReadOffset);

  std::wstring tileset_part = L"tileset@170='";
  if (has_read_buffer_bytes(kAreaTileSetReadOffset, kCResRefTextBytes)) {
    const std::string tileset =
        FixedResrefPreview(
            payload.data() + payload_offset_for(kAreaTileSetReadOffset),
            kCResRefTextBytes);
    tileset_part += tileset.empty() ? L"<empty>" : AsciiPreviewToWide(tileset, 32);
  } else {
    tileset_part += L"<unavailable>";
  }
  tileset_part += L"'";
  append(tileset_part);

  append_u32(L"tile0-id", kFirstTileOffset);
  append_u32(L"tile0-orient", kFirstTileOrientationOffset);
  append_u32(L"tile0-third", kFirstTileThirdIntOffset);

  std::wstring flags_part = L"tile0-flags@198=";
  uint16_t flags = 0;
  if (has_read_buffer_bytes(kFirstTileFlagsOffset, sizeof(uint16_t)) &&
      TryReadU16LeFromBytes(payload, payload_offset_for(kFirstTileFlagsOffset), &flags)) {
    wchar_t cell[64]{};
    swprintf_s(cell, L"%u/0x%04X", static_cast<unsigned int>(flags), static_cast<unsigned int>(flags));
    flags_part += cell;
  } else {
    flags_part += L"<unavailable>";
  }
  append(flags_part);

  if (has_read_buffer_bytes(kRawPreviewOffset, 1)) {
    const size_t payload_offset = payload_offset_for(kRawPreviewOffset);
    const size_t available = std::min(
        kRawPreviewBytes,
        std::min(payload.size(), fragment_offset) - payload_offset);
    append(
        L"raw@144=[" +
        FormatLimitedBytes(payload.data() + payload_offset, available, kRawPreviewBytes) +
        L"]");
  }

  append(FormatAreaTileStreamScan(ScanAreaTileStream(payload, fragment_offset)));

  return summary.empty() ? L"<unavailable>" : summary;
}

void LogAreaClientAreaDiagnostics(
    const wchar_t* context,
    const std::vector<unsigned char>& payload,
    size_t fragment_offset,
    uint32_t declared,
    uint32_t legacy_area_object_id,
    std::string_view area_resref,
    unsigned char old_fragment_byte,
    unsigned char new_fragment_byte) {
  constexpr size_t kPayloadHeaderBytes = 3;
  constexpr size_t kDeclaredBytes = sizeof(uint32_t);
  constexpr size_t kTransitionIndexOffset = kPayloadHeaderBytes + kDeclaredBytes;
  constexpr size_t kStartXOffset = kTransitionIndexOffset + sizeof(uint32_t);
  constexpr size_t kEeAreaObjectIdOffset = kStartXOffset + 4 * sizeof(uint32_t);
  constexpr size_t kEeAreaResrefOffset = kEeAreaObjectIdOffset + sizeof(uint32_t);

  uint32_t transition_index = 0;
  if (payload.size() >= kTransitionIndexOffset + sizeof(uint32_t)) {
    transition_index = ReadU32Le(payload.data() + kTransitionIndexOffset);
  }

  std::array<float, 4> floats{};
  std::array<bool, 4> have_float{};
  for (size_t index = 0; index < floats.size(); ++index) {
    have_float[index] =
        TryReadFloatLeFromBytes(payload, kStartXOffset + index * sizeof(uint32_t), &floats[index]);
  }

  uint32_t ee_area_object_id = 0;
  const bool have_ee_area_object_id =
      fragment_offset >= kEeAreaObjectIdOffset + sizeof(uint32_t) &&
      TryReadU32LeFromBytes(payload, kEeAreaObjectIdOffset, &ee_area_object_id);
  const std::string ee_resref =
      kEeAreaResrefOffset + kCResRefTextBytes <= fragment_offset
          ? FixedResrefPreview(payload.data() + kEeAreaResrefOffset, fragment_offset - kEeAreaResrefOffset)
          : std::string();
  const size_t tail_start = fragment_offset > 24 ? fragment_offset - 24 : kPayloadHeaderBytes;
  const size_t tail_length = fragment_offset > tail_start ? fragment_offset - tail_start : 0;
  const size_t fragment_preview_length = fragment_offset < payload.size()
      ? std::min<size_t>(payload.size() - fragment_offset, 12)
      : 0;

  LogFormat(
      L"%s Area_ClientArea diagnostics: declared=%u byte_read_size=%zu fragment_offset=%zu fragment_size=%zu transition=%u floats=[%s%.3f,%s%.3f,%s%.3f,%s%.3f] legacy_object=0x%08X legacy_resref='%s' ee_object_at+%zu=%s0x%08X ee_resref_at+%zu='%s' first_fragment=0x%02X->0x%02X static=[%s] fixed_resrefs=[%s] strings=[%s] read_tail=[%s] fragments=[%s]",
      context != nullptr ? context : L"server->client",
      declared,
      declared >= kPayloadHeaderBytes ? static_cast<size_t>(declared - kPayloadHeaderBytes) : 0,
      fragment_offset,
      fragment_offset <= payload.size() ? payload.size() - fragment_offset : 0,
      transition_index,
      have_float[0] ? L"" : L"?",
      have_float[0] ? floats[0] : 0.0f,
      have_float[1] ? L"" : L"?",
      have_float[1] ? floats[1] : 0.0f,
      have_float[2] ? L"" : L"?",
      have_float[2] ? floats[2] : 0.0f,
      have_float[3] ? L"" : L"?",
      have_float[3] ? floats[3] : 0.0f,
      legacy_area_object_id,
      AsciiPreviewToWide(area_resref, 32).c_str(),
      kEeAreaObjectIdOffset - kPayloadHeaderBytes,
      have_ee_area_object_id ? L"" : L"?",
      have_ee_area_object_id ? ee_area_object_id : 0,
      kEeAreaResrefOffset - kPayloadHeaderBytes,
      ee_resref.empty() ? L"<empty>" : AsciiPreviewToWide(ee_resref, 32).c_str(),
      static_cast<unsigned int>(old_fragment_byte),
      static_cast<unsigned int>(new_fragment_byte),
      FormatAreaClientAreaStaticHeader(payload, fragment_offset).c_str(),
      FormatAreaFixedResrefCandidates(payload, fragment_offset).c_str(),
      FormatAreaLengthStringCandidates(payload, fragment_offset).c_str(),
      tail_length != 0 ? FormatLimitedBytes(payload.data() + tail_start, tail_length, 48).c_str() : L"<none>",
      fragment_preview_length != 0
          ? FormatLimitedBytes(payload.data() + fragment_offset, fragment_preview_length, 24).c_str()
          : L"<none>");
}

bool RewriteAreaClientAreaPayloadIfPossible(
    BridgeRuntime* runtime,
    std::vector<unsigned char>* payload,
    const wchar_t* context,
    std::wstring* failure_reason) {
  if (failure_reason != nullptr) {
    failure_reason->clear();
  }
  if (runtime == nullptr || payload == nullptr || payload->size() < 7 ||
      !runtime->options.rewrite_area_client_area ||
      !IsHighLevelGameplayEnvelope((*payload)[0]) ||
      (*payload)[1] != 0x04 ||
      (*payload)[2] != 0x01) {
    return false;
  }

  ++runtime->area_client_area_candidate_count;
  const uint32_t declared = ReadU32Le(payload->data() + 3);
  if (declared < 7) {
    ++runtime->area_client_area_rewrite_skipped_count;
    return FailQuickbarFullParse(failure_reason, L"Area_ClientArea invalid declared=%u", declared);
  }
  const size_t payload_size = payload->size() - 3;
  const size_t read_size = static_cast<size_t>(declared - 3);
  if (read_size < kLegacyQuickbarReadCursorStart || read_size > payload_size) {
    ++runtime->area_client_area_rewrite_skipped_count;
    return FailQuickbarFullParse(
        failure_reason,
        L"Area_ClientArea read_size=%zu outside payload_size=%zu declared=%u",
        read_size,
        payload_size,
        declared);
  }

  const size_t fragment_offset = 3 + read_size;
  const size_t fragment_size = payload->size() - fragment_offset;
  if (fragment_size == 0) {
    ++runtime->area_client_area_rewrite_skipped_count;
    return FailQuickbarFullParse(failure_reason, L"Area_ClientArea has no fragment stream");
  }

  // EE still reads the legacy area object id before the area resref. The only
  // byte-stream gap this bridge needs to fill here is the two zero WORD counts
  // EE reads after static sounds/creatures near the end of the area body.
  constexpr size_t kLegacyAreaObjectIdOffset =
      3 + sizeof(uint32_t) + sizeof(uint32_t) + 4 * sizeof(uint32_t);
  constexpr size_t kLegacyAreaObjectIdBytes = sizeof(uint32_t);
  if (fragment_offset < kLegacyAreaObjectIdOffset + kLegacyAreaObjectIdBytes + kCResRefTextBytes) {
    ++runtime->area_client_area_rewrite_skipped_count;
    return FailQuickbarFullParse(
        failure_reason,
        L"Area_ClientArea too short for legacy object-id/resref removal declared=%u fragment_offset=%zu",
        declared,
        fragment_offset);
  }
  const uint32_t legacy_area_object_id = ReadU32Le(payload->data() + kLegacyAreaObjectIdOffset);
  const std::string area_resref =
      FixedResrefPreview(
          payload->data() + kLegacyAreaObjectIdOffset + kLegacyAreaObjectIdBytes,
          payload->size() - kLegacyAreaObjectIdOffset - kLegacyAreaObjectIdBytes);

  // EE reaches the raw-area-name discriminator at fragment bit cursor 4 after
  // consuming the earlier area flag in CNWCArea::LoadArea.
  constexpr unsigned char kAreaNameFlagMask = 0x08;
  constexpr size_t kLegacyAreaPostStaticCountPaddingBytes = 4;
  if (declared > UINT32_MAX - kLegacyAreaPostStaticCountPaddingBytes) {
    ++runtime->area_client_area_rewrite_skipped_count;
    return FailQuickbarFullParse(
        failure_reason,
        L"Area_ClientArea declared too large for post-static padding declared=%u",
        declared);
  }
  const uint32_t new_declared = declared + static_cast<uint32_t>(kLegacyAreaPostStaticCountPaddingBytes);
  const size_t new_read_size = read_size + kLegacyAreaPostStaticCountPaddingBytes;
  const size_t new_fragment_offset = fragment_offset + kLegacyAreaPostStaticCountPaddingBytes;
  const unsigned char old_fragment_byte = (*payload)[fragment_offset];
  const unsigned char new_fragment_byte = static_cast<unsigned char>(old_fragment_byte | kAreaNameFlagMask);

  LogAreaClientAreaDiagnostics(
      context,
      *payload,
      fragment_offset,
      declared,
      legacy_area_object_id,
      area_resref,
      old_fragment_byte,
      old_fragment_byte);

  AreaTileStreamScan area_tile_scan;
  std::wstring area_height_repair_failure;
  const bool repaired_area_height =
      RepairMissingAreaHeightFromTileStream(
          payload,
          fragment_offset,
          &area_tile_scan,
          &area_height_repair_failure);
  if (repaired_area_height) {
    LogFormat(
        L"%s Area_ClientArea height repaired from tile stream: width=%u packet_height=%u inferred_height=%u tile_count=%u tile_end@%zu max_tile=%u following=%s%u/0x%08X",
        context != nullptr ? context : L"server->client",
        area_tile_scan.width,
        area_tile_scan.packet_height,
        area_tile_scan.inferred_height,
        area_tile_scan.tile_count,
        area_tile_scan.tile_end_read_offset,
        area_tile_scan.max_tile_id,
        area_tile_scan.has_following_dword ? L"" : L"?",
        area_tile_scan.has_following_dword ? area_tile_scan.following_dword : 0,
        area_tile_scan.has_following_dword ? area_tile_scan.following_dword : 0);
  } else if (!area_height_repair_failure.empty()) {
    LogFormat(
        L"%s Area_ClientArea height repair skipped: %s",
        context != nullptr ? context : L"server->client",
        area_height_repair_failure.c_str());
  }

  payload->insert(
      payload->begin() + static_cast<std::vector<unsigned char>::difference_type>(
          fragment_offset),
      kLegacyAreaPostStaticCountPaddingBytes,
      0);
  WriteU32Le(payload->data() + 3, new_declared);
  (*payload)[new_fragment_offset] = new_fragment_byte;
  ++runtime->area_client_area_rewrite_count;
  LogFormat(
      L"%s Area_ClientArea object/name/tail rewritten #%llu/%llu: declared=%u->%u read_size=%zu->%zu fragment_offset=%zu->%zu fragment_size=%zu legacy_object=0x%08X area_resref='%s' removed_object_bytes=0 inserted_post_static_count_bytes=%zu first_fragment=0x%02X->0x%02X payload=%zu",
      context != nullptr ? context : L"server->client",
      static_cast<unsigned long long>(runtime->area_client_area_rewrite_count),
      static_cast<unsigned long long>(runtime->area_client_area_candidate_count),
      declared,
      new_declared,
      read_size,
      new_read_size,
      fragment_offset,
      new_fragment_offset,
      fragment_size,
      legacy_area_object_id,
      AsciiPreviewToWide(area_resref, 32).c_str(),
      kLegacyAreaPostStaticCountPaddingBytes,
      static_cast<unsigned int>(old_fragment_byte),
      static_cast<unsigned int>(new_fragment_byte),
      payload->size());
  LogAreaClientAreaDiagnostics(
      context,
      *payload,
      new_fragment_offset,
      new_declared,
      legacy_area_object_id,
      area_resref,
      old_fragment_byte,
      new_fragment_byte);
  return true;
}

bool LegacyQuickbarBaseItemRequiresActivePropertyWord(uint32_t base_item_id) {
  return base_item_id == 0x10;
}

bool ParseQuickbarItemAppearance(
    const BridgeRuntime& runtime,
    QuickbarPacketReader* reader,
    QuickbarItemObject* item,
    std::wstring* failure_reason) {
  if (reader == nullptr || item == nullptr || reader->read_buffer == nullptr) {
    return FailQuickbarFullParse(failure_reason, L"item appearance missing reader/item");
  }

  const size_t start = reader->cursor;
  uint32_t base_item_id = 0;
  if (!ReadQuickbarReaderDword(reader, &base_item_id)) {
    return FailQuickbarFullParse(failure_reason, L"item appearance missing base item id");
  }
  item->base_item = base_item_id;

  const int model_type = GetBaseItemModelType(runtime, base_item_id);
  const size_t legacy_size = LegacyItemAppearanceReadSize(model_type);
  if (legacy_size == 0) {
    return FailQuickbarFullParse(
        failure_reason,
        L"item appearance base lookup failed base=%u/0x%08X",
        base_item_id,
        base_item_id);
  }
  if (start > reader->read_size || reader->read_size - start < legacy_size) {
    return FailQuickbarFullParse(
        failure_reason,
        L"item appearance truncated base=%u/0x%08X model=%d size=%zu",
        base_item_id,
        base_item_id,
        model_type,
        legacy_size);
  }

  reader->cursor = start + legacy_size;
  item->appearance_type = static_cast<uint8_t>(model_type);
  item->appearance_bytes.assign(
      reader->read_buffer + start,
      reader->read_buffer + start + legacy_size);
  return true;
}

bool ParseQuickbarActiveItemPropertiesStandard(
    QuickbarPacketReader* reader,
    uint32_t base_item_id,
    QuickbarActiveItemProperties* properties,
    std::string* name_preview,
    std::wstring* failure_reason) {
  if (properties != nullptr) {
    *properties = QuickbarActiveItemProperties{};
  }
  if (name_preview != nullptr) {
    name_preview->clear();
  }

  if (LegacyQuickbarBaseItemRequiresActivePropertyWord(base_item_id)) {
    uint16_t armor_word = 0;
    if (!ReadQuickbarReaderWord(reader, &armor_word)) {
      return FailQuickbarFullParse(failure_reason, L"active item properties missing armor word");
    }
    if (properties != nullptr) {
      properties->has_armor_word = true;
      properties->armor_word = armor_word;
    }
  }

  bool name_is_locstring = false;
  if (!ReadQuickbarReaderBool(reader, &name_is_locstring)) {
    return FailQuickbarFullParse(failure_reason, L"active item properties missing name kind bit");
  }
  if (properties != nullptr) {
    properties->name_is_locstring = name_is_locstring;
  }
  if (name_is_locstring) {
    if (!ReadQuickbarReaderLocString(
            reader,
            properties != nullptr ? &properties->locstring_name : nullptr,
            name_preview)) {
      return FailQuickbarFullParse(failure_reason, L"active item properties failed locstring name");
    }
  } else {
    std::string name;
    if (!ReadQuickbarReaderString(reader, &name)) {
      return FailQuickbarFullParse(failure_reason, L"active item properties failed string name");
    }
    if (properties != nullptr) {
      properties->string_name = name;
    }
    if (name_preview != nullptr) {
      *name_preview = name;
    }
  }

  bool bool_value = false;
  uint32_t dword_value = 0;
  uint8_t property_count = 0;
  if (!ReadQuickbarReaderBool(reader, &bool_value)) {
    return FailQuickbarFullParse(failure_reason, L"active item properties missing post-name bool 1");
  }
  if (properties != nullptr) {
    properties->post_name_bool1 = bool_value;
  }
  if (!ReadQuickbarReaderDword(reader, &dword_value)) {
    return FailQuickbarFullParse(failure_reason, L"active item properties missing cost dword");
  }
  if (properties != nullptr) {
    properties->cost = dword_value;
  }
  if (!ReadQuickbarReaderDword(reader, &dword_value)) {
    return FailQuickbarFullParse(failure_reason, L"active item properties missing stack/charges dword");
  }
  if (properties != nullptr) {
    properties->stack_or_charges = dword_value;
  }
  if (!ReadQuickbarReaderBool(reader, &bool_value)) {
    return FailQuickbarFullParse(failure_reason, L"active item properties missing post-name bool 2");
  }
  if (properties != nullptr) {
    properties->post_name_bool2 = bool_value;
  }
  if (!ReadQuickbarReaderBool(reader, &bool_value)) {
    return FailQuickbarFullParse(failure_reason, L"active item properties missing post-name bool 3");
  }
  if (properties != nullptr) {
    properties->post_name_bool3 = bool_value;
  }
  if (!ReadQuickbarReaderBool(reader, &bool_value)) {
    return FailQuickbarFullParse(failure_reason, L"active item properties missing post-name bool 4");
  }
  if (properties != nullptr) {
    properties->post_name_bool4 = bool_value;
  }
  if (!ReadQuickbarReaderByte(reader, &property_count)) {
    return FailQuickbarFullParse(failure_reason, L"active item properties missing property count");
  }
  constexpr uint8_t kMaxReasonableQuickbarItemProperties = 128;
  if (property_count > kMaxReasonableQuickbarItemProperties) {
    return FailQuickbarFullParse(
        failure_reason,
        L"active item properties unreasonable property count=%u base=%u/0x%08X name='%s'",
        static_cast<unsigned int>(property_count),
        base_item_id,
        base_item_id,
        name_preview != nullptr ? AsciiPreviewToWide(*name_preview, 64).c_str() : L"");
  }
  if (properties != nullptr) {
    properties->properties.reserve(property_count);
  }

  for (uint8_t index = 0; index < property_count; ++index) {
    QuickbarActivePropertyEntry entry{};
    if (!ReadQuickbarReaderWord(reader, &entry.property) ||
        !ReadQuickbarReaderWord(reader, &entry.subtype) ||
        !ReadQuickbarReaderWord(reader, &entry.cost_table_value) ||
        !ReadQuickbarReaderByte(reader, &entry.param)) {
      return FailQuickbarFullParse(
          failure_reason,
          L"active item properties truncated property index=%u/%u base=%u/0x%08X name='%s'",
          static_cast<unsigned int>(index),
          static_cast<unsigned int>(property_count),
          base_item_id,
          base_item_id,
          name_preview != nullptr ? AsciiPreviewToWide(*name_preview, 64).c_str() : L"");
    }
    if (properties != nullptr) {
      properties->properties.push_back(entry);
    }
  }

  uint8_t state_mask = 0;
  uint8_t value_mask = 0;
  if (!ReadQuickbarReaderByte(reader, &state_mask) ||
      !ReadQuickbarReaderByte(reader, &value_mask)) {
    return FailQuickbarFullParse(failure_reason, L"active item properties missing state/value masks");
  }
  if (properties != nullptr) {
    properties->state_mask = state_mask;
    properties->value_mask = value_mask;
  }

  for (uint8_t bit = 0; bit < 8; ++bit) {
    if ((value_mask & (1u << bit)) == 0) {
      continue;
    }
    uint8_t value = 0;
    if (!ReadQuickbarReaderByte(reader, &value)) {
      return FailQuickbarFullParse(
          failure_reason,
          L"active item properties missing value mask byte bit=%u mask=0x%02X",
          static_cast<unsigned int>(bit),
          static_cast<unsigned int>(value_mask));
    }
    if (properties != nullptr) {
      properties->value_mask_bytes.push_back(value);
    }
  }
  return true;
}

bool ParseQuickbarActiveItemPropertiesBareInlineFallback(
    QuickbarPacketReader* reader,
    uint32_t base_item_id,
    QuickbarActiveItemProperties* properties,
    std::string* name_preview,
    std::wstring* failure_reason) {
  if (properties != nullptr) {
    *properties = QuickbarActiveItemProperties{};
  }
  if (name_preview != nullptr) {
    name_preview->clear();
  }
  if (reader == nullptr ||
      reader->read_buffer == nullptr ||
      reader->cursor > reader->read_size) {
    return FailQuickbarFullParse(
        failure_reason,
        L"active item bare-inline fallback missing reader");
  }

  QuickbarPacketReader probe = *reader;
  QuickbarActiveItemProperties prefix_props{};
  if (LegacyQuickbarBaseItemRequiresActivePropertyWord(base_item_id)) {
    uint16_t armor_word = 0;
    if (!ReadQuickbarReaderWord(&probe, &armor_word)) {
      return FailQuickbarFullParse(
          failure_reason,
          L"active item bare-inline fallback missing armor word");
    }
    prefix_props.has_armor_word = true;
    prefix_props.armor_word = armor_word;
  }

  const size_t name_length_offset = probe.cursor;
  if (probe.read_size - name_length_offset < 4 + 1 + 9 ||
      ReadU32Le(probe.read_buffer + name_length_offset) != 0) {
    return FailQuickbarFullParse(
        failure_reason,
        L"active item bare-inline fallback shape missing");
  }

  const size_t text_start = name_length_offset + 4;
  constexpr size_t kMaxQuickbarBareActiveItemNameBytes = 128;
  const size_t text_limit =
      std::min(probe.read_size, text_start + kMaxQuickbarBareActiveItemNameBytes);
  size_t printable_end = text_start;
  while (printable_end < text_limit &&
      IsLegacyBareActiveItemNameByte(probe.read_buffer[printable_end])) {
    ++printable_end;
  }
  if (printable_end == text_start) {
    return FailQuickbarFullParse(
        failure_reason,
        L"active item bare-inline fallback has no printable text");
  }

  std::wstring last_failure;
  for (size_t candidate_text_end = printable_end;
       candidate_text_end > text_start;
       --candidate_text_end) {
    QuickbarPacketReader trial = probe;
    QuickbarActiveItemProperties candidate = prefix_props;
    std::string candidate_name(
        reinterpret_cast<const char*>(probe.read_buffer + text_start),
        reinterpret_cast<const char*>(probe.read_buffer + candidate_text_end));

    bool legacy_name_bit = false;
    if (!ReadQuickbarReaderBool(&trial, &legacy_name_bit)) {
      last_failure = L"active item bare-inline fallback missing name bit";
      continue;
    }
    trial.cursor = candidate_text_end;
    candidate.name_is_locstring = false;
    candidate.string_name = candidate_name;

    bool bool_value = false;
    uint32_t dword_value = 0;
    if (!ReadQuickbarReaderBool(&trial, &bool_value)) {
      last_failure = L"active item bare-inline fallback missing post-name bool 1";
      continue;
    }
    candidate.post_name_bool1 = bool_value;
    if (!ReadQuickbarReaderDword(&trial, &dword_value)) {
      last_failure = L"active item bare-inline fallback missing cost dword";
      continue;
    }
    candidate.cost = dword_value;
    if (!ReadQuickbarReaderDword(&trial, &dword_value)) {
      last_failure = L"active item bare-inline fallback missing stack/charges dword";
      continue;
    }
    candidate.stack_or_charges = dword_value;
    if (!ReadQuickbarReaderBool(&trial, &bool_value)) {
      last_failure = L"active item bare-inline fallback missing post-name bool 2";
      continue;
    }
    candidate.post_name_bool2 = bool_value;
    if (!ReadQuickbarReaderBool(&trial, &bool_value)) {
      last_failure = L"active item bare-inline fallback missing post-name bool 3";
      continue;
    }
    candidate.post_name_bool3 = bool_value;
    if (!ReadQuickbarReaderBool(&trial, &bool_value)) {
      last_failure = L"active item bare-inline fallback missing post-name bool 4";
      continue;
    }
    candidate.post_name_bool4 = bool_value;

    uint8_t property_count = 0;
    if (!ReadQuickbarReaderByte(&trial, &property_count)) {
      last_failure = L"active item bare-inline fallback missing property count";
      continue;
    }
    constexpr uint8_t kMaxReasonableQuickbarItemProperties = 128;
    if (property_count > kMaxReasonableQuickbarItemProperties) {
      wchar_t detail[160]{};
      swprintf_s(
          detail,
          L"active item bare-inline fallback unreasonable property count=%u",
          static_cast<unsigned int>(property_count));
      last_failure = detail;
      continue;
    }
    candidate.properties.reserve(property_count);
    bool table_ok = true;
    for (uint8_t index = 0; index < property_count; ++index) {
      QuickbarActivePropertyEntry entry{};
      if (!ReadQuickbarReaderWord(&trial, &entry.property) ||
          !ReadQuickbarReaderWord(&trial, &entry.subtype) ||
          !ReadQuickbarReaderWord(&trial, &entry.cost_table_value) ||
          !ReadQuickbarReaderByte(&trial, &entry.param)) {
        wchar_t detail[160]{};
        swprintf_s(
            detail,
            L"active item bare-inline fallback truncated property index=%u/%u",
            static_cast<unsigned int>(index),
            static_cast<unsigned int>(property_count));
        last_failure = detail;
        table_ok = false;
        break;
      }
      candidate.properties.push_back(entry);
    }
    if (!table_ok) {
      continue;
    }

    uint8_t state_mask = 0;
    uint8_t value_mask = 0;
    if (!ReadQuickbarReaderByte(&trial, &state_mask) ||
        !ReadQuickbarReaderByte(&trial, &value_mask)) {
      last_failure = L"active item bare-inline fallback missing state/value masks";
      continue;
    }
    candidate.state_mask = state_mask;
    candidate.value_mask = value_mask;
    bool values_ok = true;
    for (uint8_t bit = 0; bit < 8; ++bit) {
      if ((value_mask & (1u << bit)) == 0) {
        continue;
      }
      uint8_t value = 0;
      if (!ReadQuickbarReaderByte(&trial, &value)) {
        wchar_t detail[160]{};
        swprintf_s(
            detail,
            L"active item bare-inline fallback missing value mask byte bit=%u mask=0x%02X",
            static_cast<unsigned int>(bit),
            static_cast<unsigned int>(value_mask));
        last_failure = detail;
        values_ok = false;
        break;
      }
      candidate.value_mask_bytes.push_back(value);
    }
    if (!values_ok) {
      continue;
    }

    *reader = trial;
    if (properties != nullptr) {
      *properties = std::move(candidate);
    }
    if (name_preview != nullptr) {
      *name_preview = std::move(candidate_name);
    }
    return true;
  }

  return FailQuickbarFullParse(
      failure_reason,
      L"active item bare-inline fallback parse failed%s%s",
      last_failure.empty() ? L"" : L": ",
      last_failure.empty() ? L"" : last_failure.c_str());
}

bool ParseQuickbarActiveItemProperties(
    QuickbarPacketReader* reader,
    uint32_t base_item_id,
    QuickbarActiveItemProperties* properties,
    std::string* name_preview,
    std::wstring* failure_reason) {
  if (reader == nullptr) {
    return FailQuickbarFullParse(failure_reason, L"active item properties missing reader");
  }

  const QuickbarPacketReader original_reader = *reader;
  QuickbarActiveItemProperties standard_properties;
  std::string standard_name;
  std::wstring standard_failure;
  if (ParseQuickbarActiveItemPropertiesStandard(
          reader,
          base_item_id,
          properties != nullptr ? properties : &standard_properties,
          name_preview != nullptr ? name_preview : &standard_name,
          &standard_failure)) {
    return true;
  }

  *reader = original_reader;
  QuickbarActiveItemProperties fallback_properties;
  std::string fallback_name;
  std::wstring fallback_failure;
  if (ParseQuickbarActiveItemPropertiesBareInlineFallback(
          reader,
          base_item_id,
          &fallback_properties,
          &fallback_name,
          &fallback_failure)) {
    if (properties != nullptr) {
      *properties = std::move(fallback_properties);
    }
    if (name_preview != nullptr) {
      *name_preview = std::move(fallback_name);
    }
    return true;
  }

  if (failure_reason != nullptr) {
    *failure_reason = standard_failure.empty()
        ? fallback_failure
        : standard_failure + L"; fallback=" + fallback_failure;
  }
  return false;
}

bool LooksLikeQuickbarItemObjectBodyAt(
    const BridgeRuntime& runtime,
    const QuickbarPacketReader& reader,
    bool include_int_param) {
  if (reader.read_buffer == nullptr || runtime.base_item_model_types.empty()) {
    return false;
  }
  size_t cursor = reader.cursor;
  const size_t minimum =
      sizeof(uint32_t) + (include_int_param ? sizeof(uint32_t) : 0u) + sizeof(uint32_t);
  if (cursor > reader.read_size || reader.read_size - cursor < minimum) {
    return false;
  }

  const uint32_t object_id = ReadU32Le(reader.read_buffer + cursor);
  if ((object_id & 0x80000000u) == 0 && object_id != 0xFFFFFFFFu) {
    return false;
  }
  cursor += sizeof(uint32_t);
  if (include_int_param) {
    cursor += sizeof(uint32_t);
  }

  const uint32_t base_item_id = ReadU32Le(reader.read_buffer + cursor);
  const int model_type = GetBaseItemModelType(runtime, base_item_id);
  const size_t legacy_size = LegacyItemAppearanceReadSize(model_type);
  return legacy_size != 0 && cursor <= reader.read_size &&
      reader.read_size - cursor >= legacy_size;
}

bool ParseQuickbarItemObjectBody(
    const BridgeRuntime& runtime,
    QuickbarPacketReader* reader,
    bool include_int_param,
    QuickbarItemObject* item,
    const wchar_t* label,
    std::wstring* failure_reason) {
  if (item == nullptr) {
    return FailQuickbarFullParse(failure_reason, L"item object missing output");
  }

  uint32_t object_id = 0;
  if (!ReadQuickbarReaderDword(reader, &object_id)) {
    return FailQuickbarFullParse(
        failure_reason,
        L"item object missing object id label=%s",
        label != nullptr ? label : L"?");
  }
  item->object_id = object_id;
  if (include_int_param) {
    uint32_t raw_int_param = 0;
    if (!ReadQuickbarReaderDword(reader, &raw_int_param)) {
      return FailQuickbarFullParse(
          failure_reason,
          L"item object missing int param label=%s",
          label != nullptr ? label : L"?");
    }
    item->int_param = static_cast<int32_t>(raw_int_param);
  }

  if (!ParseQuickbarItemAppearance(runtime, reader, item, failure_reason) ||
      !ParseQuickbarActiveItemProperties(
          reader,
          item->base_item,
          &item->active_props,
          &item->name_preview,
          failure_reason)) {
    if (failure_reason != nullptr && !failure_reason->empty() && label != nullptr) {
      *failure_reason = std::wstring(label) + L" " + *failure_reason;
    }
    return false;
  }

  item->active_props_parsed = true;
  return true;
}

bool ParseQuickbarItemObject(
    const BridgeRuntime& runtime,
    QuickbarPacketReader* reader,
    bool include_int_param,
    QuickbarItemObject* item,
    const wchar_t* label,
    std::wstring* failure_reason) {
  if (item == nullptr) {
    return FailQuickbarFullParse(failure_reason, L"item object missing output");
  }
  *item = QuickbarItemObject{};

  const QuickbarPacketReader before_present = reader != nullptr ? *reader : QuickbarPacketReader{};
  bool present = false;
  if (!ReadQuickbarReaderBool(reader, &present)) {
    return FailQuickbarFullParse(
        failure_reason,
        L"item object missing present bit label=%s",
        label != nullptr ? label : L"?");
  }
  item->present = present;
  if (!present) {
    if (LooksLikeQuickbarItemObjectBodyAt(runtime, *reader, include_int_param)) {
      constexpr uint8_t kMaxQuickbarItemPresenceResyncBits = 5;
      std::wstring first_resync_failure;
      for (uint8_t skipped_bits = 1;
           skipped_bits <= kMaxQuickbarItemPresenceResyncBits;
           ++skipped_bits) {
        QuickbarPacketReader trial = before_present;
        bool candidate_present = false;
        bool bits_ok = true;
        for (uint8_t index = 0; index <= skipped_bits; ++index) {
          if (!ReadQuickbarReaderBool(&trial, &candidate_present)) {
            bits_ok = false;
            break;
          }
        }
        if (!bits_ok || !candidate_present) {
          continue;
        }

        QuickbarItemObject candidate{};
        candidate.present = true;
        std::wstring body_failure;
        if (ParseQuickbarItemObjectBody(
                runtime,
                &trial,
                include_int_param,
                &candidate,
                label,
                &body_failure)) {
          *reader = trial;
          *item = std::move(candidate);
          LogFormat(
              L"quickbar item presence bit resynced: label=%s skipped_bits=%u cursor=%zu fragment=%zu:%u object=0x%08X base=%u/0x%08X name='%s'",
              label != nullptr ? label : L"?",
              static_cast<unsigned int>(skipped_bits),
              before_present.cursor,
              before_present.fragment_cursor,
              static_cast<unsigned int>(before_present.fragment_bit),
              item->object_id,
              item->base_item,
              item->base_item,
              AsciiPreviewToWide(item->name_preview, 64).c_str());
          return true;
        }
        if (first_resync_failure.empty()) {
          first_resync_failure = body_failure;
        }
      }

      if (failure_reason != nullptr && !first_resync_failure.empty()) {
        *failure_reason = std::wstring(label != nullptr ? label : L"?") +
            L" item present-bit resync failed after absent bit: " +
            first_resync_failure;
      }
      return false;
    }
    return true;
  }

  if (!ParseQuickbarItemObjectBody(
          runtime,
          reader,
          include_int_param,
          item,
          label,
          failure_reason)) {
    if (failure_reason != nullptr && !failure_reason->empty() && label != nullptr) {
      *failure_reason = std::wstring(label) + L" " + *failure_reason;
    }
    return false;
  }

  return true;
}

bool ParseQuickbarItemPayload(
    const BridgeRuntime& runtime,
    QuickbarPacketReader* reader,
    QuickbarButtonInventory* button,
    std::wstring* failure_reason) {
  if (reader == nullptr || button == nullptr) {
    return FailQuickbarFullParse(failure_reason, L"item payload missing reader/button");
  }

  if (!ParseQuickbarItemObject(
          runtime,
          reader,
          true,
          &button->primary_item,
          L"primary",
          failure_reason) ||
      !ParseQuickbarItemObject(
          runtime,
          reader,
          false,
          &button->secondary_item,
          L"secondary",
          failure_reason)) {
    return false;
  }

  button->parsed = true;
  button->item_payload = true;
  button->item_candidate = true;
  button->next_offset = reader->cursor;
  button->next_fragment_offset = reader->fragment_cursor;
  button->next_fragment_bit = reader->fragment_bit;
  return true;
}

bool ParseQuickbarNonItemFromReader(
    QuickbarPacketReader* reader,
    uint8_t type,
    QuickbarButtonInventory* button) {
  if (reader == nullptr || button == nullptr) {
    return false;
  }

  QuickbarButtonInventory parsed = *button;
  parsed.type = type;

  if (!IsLegacyQuickbarPlausibleType(type) || type == 1) {
    return false;
  }

  if (LegacyQuickbarTypeHasNoPayload(type)) {
    parsed.parsed = true;
    parsed.no_payload = true;
    parsed.next_offset = reader->cursor;
    parsed.next_fragment_offset = reader->fragment_cursor;
    parsed.next_fragment_bit = reader->fragment_bit;
    *button = std::move(parsed);
    return true;
  }

  if (type == 2) {
    uint8_t spell_class = 0;
    uint32_t spell_id = 0;
    uint8_t metamagic = 0;
    uint8_t domain = 0;
    if (!ReadQuickbarReaderByte(reader, &spell_class) ||
        !ReadQuickbarReaderDword(reader, &spell_id) ||
        !ReadQuickbarReaderByte(reader, &metamagic) ||
        !ReadQuickbarReaderByte(reader, &domain)) {
      return false;
    }
    parsed.parsed = true;
    parsed.spell = spell_id <= 10000;
    parsed.byte_payload = true;
    parsed.byte_value = spell_class;
    parsed.int_payload = true;
    parsed.int_value = spell_id;
    parsed.spell_metamagic = metamagic;
    parsed.spell_domain = domain;
    parsed.next_offset = reader->cursor;
    parsed.next_fragment_offset = reader->fragment_cursor;
    parsed.next_fragment_bit = reader->fragment_bit;
    *button = std::move(parsed);
    return true;
  }

  if (LegacyQuickbarTypeHasIntPayload(type)) {
    uint32_t value = 0;
    if (!ReadQuickbarReaderDword(reader, &value)) {
      return false;
    }
    parsed.parsed = true;
    parsed.int_payload = true;
    parsed.int_value = value;
    parsed.next_offset = reader->cursor;
    parsed.next_fragment_offset = reader->fragment_cursor;
    parsed.next_fragment_bit = reader->fragment_bit;
    *button = std::move(parsed);
    return true;
  }

  if (type == 44) {
    uint32_t value = 0;
    uint8_t byte_value = 0;
    if (!ReadQuickbarReaderDword(reader, &value) ||
        !ReadQuickbarReaderByte(reader, &byte_value)) {
      return false;
    }
    parsed.parsed = true;
    parsed.int_payload = true;
    parsed.int_value = value;
    parsed.byte_payload = true;
    parsed.byte_value = byte_value;
    parsed.next_offset = reader->cursor;
    parsed.next_fragment_offset = reader->fragment_cursor;
    parsed.next_fragment_bit = reader->fragment_bit;
    *button = std::move(parsed);
    return true;
  }

  if (type >= 11 && type <= 17) {
    std::string resref;
    std::string text;
    if (!ReadQuickbarReaderFixedResref(reader, &parsed, &resref) ||
        !ReadQuickbarReaderString(reader, &text)) {
      return false;
    }
    parsed.parsed = true;
    parsed.resref_payload = true;
    parsed.resref = resref;
    parsed.string_payload = true;
    parsed.text = text;
    parsed.next_offset = reader->cursor;
    parsed.next_fragment_offset = reader->fragment_cursor;
    parsed.next_fragment_bit = reader->fragment_bit;
    *button = std::move(parsed);
    return true;
  }

  if (type == 18) {
    std::string text1;
    std::string text2;
    if (!ReadQuickbarReaderString(reader, &text1) ||
        !ReadQuickbarReaderString(reader, &text2)) {
      return false;
    }
    parsed.parsed = true;
    parsed.string_payload = true;
    parsed.text = text1;
    parsed.string2_payload = true;
    parsed.text2 = text2;
    parsed.next_offset = reader->cursor;
    parsed.next_fragment_offset = reader->fragment_cursor;
    parsed.next_fragment_bit = reader->fragment_bit;
    *button = std::move(parsed);
    return true;
  }

  if (type == 29 || type == 30) {
    std::string resref;
    if (!ReadQuickbarReaderFixedResref(reader, &parsed, &resref)) {
      return false;
    }
    parsed.parsed = true;
    parsed.resref_payload = true;
    parsed.resref = resref;
    parsed.next_offset = reader->cursor;
    parsed.next_fragment_offset = reader->fragment_cursor;
    parsed.next_fragment_bit = reader->fragment_bit;
    *button = std::move(parsed);
    return true;
  }

  return false;
}

bool TryParseQuickbarPacketFull(
    const BridgeRuntime& runtime,
    const unsigned char* packet,
    size_t packet_size,
    QuickbarFullParseView* view,
    std::wstring* failure_reason) {
  if (view != nullptr) {
    *view = QuickbarFullParseView{};
  }
  if (failure_reason != nullptr) {
    failure_reason->clear();
  }
  if (packet == nullptr || view == nullptr || packet_size < 7 ||
      !IsHighLevelGameplayEnvelope(packet[0]) || packet[1] != 30 || packet[2] != 1) {
    return FailQuickbarFullParse(failure_reason, L"not a GuiQuickbar_SetAllButtons packet");
  }

  const unsigned char* payload = packet + 3;
  const size_t payload_size = packet_size - 3;
  const uint32_t declared = ReadU32Le(payload);
  if (declared < 3) {
    return FailQuickbarFullParse(failure_reason, L"invalid CNWMessage declared size");
  }
  const size_t read_size = static_cast<size_t>(declared - 3);
  if (read_size < kLegacyQuickbarReadCursorStart || read_size > payload_size) {
    return FailQuickbarFullParse(
        failure_reason,
        L"read buffer size %zu outside payload size %zu",
        read_size,
        payload_size);
  }
  if (runtime.base_item_model_types.empty()) {
    return FailQuickbarFullParse(failure_reason, L"baseitems model table unavailable");
  }

  QuickbarPacketReader reader{};
  reader.read_buffer = payload;
  reader.read_size = read_size;
  reader.fragments = payload + read_size;
  reader.fragment_size = payload_size - read_size;
  reader.cursor = kLegacyQuickbarReadCursorStart;
  if (reader.fragment_size == 0) {
    return FailQuickbarFullParse(failure_reason, L"quickbar packet has no fragment stream");
  }

  uint32_t final_fragment_bits = 0;
  if (!ReadQuickbarReaderBits(&reader, 3, &final_fragment_bits)) {
    return FailQuickbarFullParse(failure_reason, L"could not read quickbar fragment bit-size header");
  }
  reader.final_fragment_bits = static_cast<uint8_t>(final_fragment_bits);

  view->envelope = packet[0];
  view->declared = declared;
  view->read_size = read_size;
  view->fragment_size = payload_size - read_size;
  view->final_fragment_bits = reader.final_fragment_bits;

  for (size_t slot = 0; slot < kLegacyQuickbarButtonCount; ++slot) {
    if (reader.cursor >= reader.read_size) {
      if (slot > 0 || view->spells > 0 || view->item_buttons_translated > 0) {
        view->unsupported_buttons_blanked += static_cast<int>(kLegacyQuickbarButtonCount - slot);
        view->final_cursor = reader.cursor;
        break;
      }
      return FailQuickbarFullParse(
          failure_reason,
          L"cursor reached end at slot %zu read_size=%zu",
          slot,
          reader.read_size);
    }

    QuickbarButtonInventory parsed{};
    parsed.slot = slot;
    parsed.offset = reader.cursor;
    parsed.source_fragment_offset = reader.fragment_cursor;
    parsed.source_fragment_bit = reader.fragment_bit;

    uint8_t type = 0;
    if (!ReadQuickbarReaderByte(&reader, &type)) {
      if (slot > 0 || view->spells > 0 || view->item_buttons_translated > 0) {
        view->unsupported_buttons_blanked += static_cast<int>(kLegacyQuickbarButtonCount - slot);
        view->final_cursor = reader.cursor;
        break;
      }
      return FailQuickbarFullParse(
          failure_reason,
          L"could not read quickbar type at slot %zu cursor=%zu",
          slot,
          reader.cursor);
    }
    parsed.type = type;

    if (type == 1) {
      std::wstring item_failure;
      if (!ParseQuickbarItemPayload(runtime, &reader, &parsed, &item_failure)) {
        parsed.parsed = true;
        parsed.item_candidate = true;
        parsed.next_offset = reader.cursor;
        parsed.next_fragment_offset = reader.fragment_cursor;
        parsed.next_fragment_bit = reader.fragment_bit;
        view->buttons[slot] = parsed;
        std::vector<QuickbarButtonInventory> partial_buttons(
            view->buttons.begin(),
            view->buttons.begin() + static_cast<ptrdiff_t>(slot + 1));
        const std::wstring partial_summary =
            FormatQuickbarButtonInventorySummary(partial_buttons);
        view->button_summary = partial_summary;
        return FailQuickbarFullParse(
            failure_reason,
            L"could not parse item payload at slot %zu source=%zu cursor=%zu fragment=%zu:%u translated=%d spells=%d reason=%s state=[%s] partial=[%s]",
            slot,
            parsed.offset,
            reader.cursor,
            reader.fragment_cursor,
            static_cast<unsigned int>(reader.fragment_bit),
            view->item_buttons_translated,
            view->spells,
            item_failure.empty() ? L"<none>" : item_failure.c_str(),
            FormatQuickbarReaderWindow(reader).c_str(),
            partial_summary.c_str());
      }

      view->buttons[slot] = std::move(parsed);
      ++view->item_buttons_translated;
      view->score += 100;
      continue;
    }

    if (!ParseQuickbarNonItemFromReader(&reader, type, &parsed)) {
      if (slot > 0 || view->spells > 0 || view->item_buttons_translated > 0) {
        view->unsupported_buttons_blanked += static_cast<int>(kLegacyQuickbarButtonCount - slot);
        view->final_cursor = parsed.offset;
        break;
      }
      return FailQuickbarFullParse(
          failure_reason,
          L"unsupported quickbar type %u at slot %zu cursor=%zu fragment=%zu:%u",
          static_cast<unsigned int>(type),
          slot,
          parsed.offset,
          parsed.source_fragment_offset,
          static_cast<unsigned int>(parsed.source_fragment_bit));
    }

    view->buttons[slot] = std::move(parsed);
    const QuickbarButtonInventory& stored = view->buttons[slot];
    if (stored.spell) {
      ++view->spells;
      view->score += 80;
    } else if (stored.no_payload) {
      ++view->no_payload_buttons;
      view->score += stored.type == 0 ? 8 : 24;
    } else {
      ++view->general_buttons;
      view->score += 32;
    }
  }

  if (view->final_cursor == 0) {
    view->final_cursor = reader.cursor;
  }
  std::vector<QuickbarButtonInventory> summary_buttons(
      view->buttons.begin(),
      view->buttons.end());
  view->button_summary = FormatQuickbarButtonInventorySummary(summary_buttons);
  return true;
}

bool QuickbarWriteBit(QuickbarPacketWriter* writer, bool value) {
  if (writer == nullptr) {
    return false;
  }
  writer->fragment_bits.push_back(value ? 1 : 0);
  return true;
}

bool QuickbarWriteBits(QuickbarPacketWriter* writer, uint32_t value, uint8_t bit_count) {
  if (writer == nullptr || bit_count > 32) {
    return false;
  }
  for (uint8_t index = 0; index < bit_count; ++index) {
    const uint8_t shift = static_cast<uint8_t>(bit_count - index - 1);
    writer->fragment_bits.push_back(((value >> shift) & 1u) != 0 ? 1 : 0);
  }
  return true;
}

bool QuickbarWriteByte(QuickbarPacketWriter* writer, uint8_t value) {
  if (writer == nullptr) {
    return false;
  }
  writer->read_buffer.push_back(value);
  return true;
}

bool QuickbarWriteWord(QuickbarPacketWriter* writer, uint16_t value) {
  if (writer == nullptr) {
    return false;
  }
  AppendU16Le(&writer->read_buffer, value);
  return true;
}

bool QuickbarWriteDword(QuickbarPacketWriter* writer, uint32_t value) {
  return writer != nullptr && AppendU32Le(&writer->read_buffer, value);
}

bool QuickbarWriteInt(QuickbarPacketWriter* writer, int32_t value) {
  return QuickbarWriteDword(writer, static_cast<uint32_t>(value));
}

bool QuickbarWriteUnsignedIntBits(
    QuickbarPacketWriter* writer,
    uint64_t value,
    uint8_t bit_count) {
  if (writer == nullptr || bit_count > 64) {
    return false;
  }
  if (bit_count < 64 && (value >> bit_count) != 0) {
    return false;
  }

  uint8_t remaining = bit_count;
  while (remaining >= 32) {
    remaining -= 32;
    if (!QuickbarWriteDword(writer, static_cast<uint32_t>((value >> remaining) & 0xFFFFFFFFull))) {
      return false;
    }
  }
  while (remaining >= 16) {
    remaining -= 16;
    if (!QuickbarWriteWord(writer, static_cast<uint16_t>((value >> remaining) & 0xFFFFull))) {
      return false;
    }
  }
  while (remaining >= 8) {
    remaining -= 8;
    if (!QuickbarWriteByte(writer, static_cast<uint8_t>((value >> remaining) & 0xFFull))) {
      return false;
    }
  }
  if (remaining != 0 &&
      !QuickbarWriteBits(writer, static_cast<uint32_t>(value & ((1ull << remaining) - 1ull)), remaining)) {
    return false;
  }
  return true;
}

bool QuickbarWriteSignedIntBits(
    QuickbarPacketWriter* writer,
    int64_t value,
    uint8_t bit_count) {
  if (writer == nullptr || bit_count == 0 || bit_count > 64) {
    return false;
  }

  const bool negative = value < 0;
  const uint64_t magnitude = negative
      ? static_cast<uint64_t>(-(value + 1)) + 1ull
      : static_cast<uint64_t>(value);
  if (bit_count < 64 && (magnitude >> (bit_count - 1)) != 0) {
    return false;
  }
  return QuickbarWriteBit(writer, negative) &&
      QuickbarWriteUnsignedIntBits(writer, magnitude, static_cast<uint8_t>(bit_count - 1));
}

bool QuickbarWriteString(
    QuickbarPacketWriter* writer,
    const std::string& value,
    std::wstring* failure_reason) {
  if (writer == nullptr) {
    return FailQuickbarPayloadBuild(failure_reason, L"missing quickbar writer");
  }
  if (value.size() > UINT32_MAX) {
    return FailQuickbarPayloadBuild(failure_reason, L"quickbar string is too large");
  }
  if (!QuickbarWriteDword(writer, static_cast<uint32_t>(value.size()))) {
    return false;
  }
  writer->read_buffer.insert(writer->read_buffer.end(), value.begin(), value.end());
  return true;
}

bool QuickbarWriteFixedResref(
    QuickbarPacketWriter* writer,
    const QuickbarButtonInventory& button,
    std::wstring* failure_reason) {
  if (writer == nullptr || !button.has_resref_bytes) {
    return FailQuickbarPayloadBuild(failure_reason, L"quickbar resref bytes unavailable");
  }
  writer->read_buffer.insert(
      writer->read_buffer.end(),
      button.resref_bytes.begin(),
      button.resref_bytes.end());
  return true;
}

bool QuickbarWriteFixedResref16(
    QuickbarPacketWriter* writer,
    std::string_view resref,
    std::wstring* failure_reason) {
  if (writer == nullptr) {
    return FailQuickbarPayloadBuild(failure_reason, L"missing quickbar writer");
  }
  if (resref.empty() || resref.size() > kCResRefTextBytes) {
    return FailQuickbarPayloadBuild(
        failure_reason,
        L"invalid 16-byte resref length=%zu",
        resref.size());
  }
  for (const char ch : resref) {
    if (!IsResrefChar(static_cast<unsigned char>(ch))) {
      return FailQuickbarPayloadBuild(
          failure_reason,
          L"invalid character in 16-byte resref '%s'",
          AsciiPreviewToWide(resref, 32).c_str());
    }
  }

  const size_t offset = writer->read_buffer.size();
  writer->read_buffer.resize(offset + kCResRefTextBytes, 0);
  std::copy(resref.begin(), resref.end(), writer->read_buffer.begin() + offset);
  return true;
}

bool QuickbarWriteLocString(
    QuickbarPacketWriter* writer,
    const QuickbarLocStringField& field,
    std::wstring* failure_reason) {
  if (writer == nullptr) {
    return FailQuickbarPayloadBuild(failure_reason, L"missing quickbar writer");
  }
  QuickbarWriteBit(writer, field.custom_tlk);
  if (field.custom_tlk) {
    QuickbarWriteBits(writer, field.language_selector ? 1u : 0u, 1);
    return QuickbarWriteDword(writer, field.string_ref);
  }
  return QuickbarWriteString(writer, field.text, failure_reason);
}

bool BuildQuickbarFragmentBytes(QuickbarPacketWriter* writer, std::vector<unsigned char>* fragments) {
  if (writer == nullptr || fragments == nullptr || writer->fragment_bits.size() < 3) {
    return false;
  }

  const uint8_t final_fragment_bits =
      static_cast<uint8_t>(writer->fragment_bits.size() % 8u);
  writer->fragment_bits[0] = (final_fragment_bits & 0x04u) != 0 ? 1 : 0;
  writer->fragment_bits[1] = (final_fragment_bits & 0x02u) != 0 ? 1 : 0;
  writer->fragment_bits[2] = (final_fragment_bits & 0x01u) != 0 ? 1 : 0;
  PackCnwMsbBits(writer->fragment_bits, fragments);
  if (fragments->empty()) {
    fragments->push_back(0);
  }
  return true;
}

bool TryReadHighLevelCnwLeadingString(
    const unsigned char* packet,
    size_t packet_size,
    std::string* value,
    uint32_t max_length = 256) {
  if (value != nullptr) {
    value->clear();
  }
  if (packet == nullptr || value == nullptr || packet_size < 8 ||
      !IsHighLevelGameplayEnvelope(packet[0])) {
    return false;
  }

  const unsigned char* read_buffer = packet + 3;
  const size_t payload_size = packet_size - 3;
  const uint32_t declared = ReadU32Le(read_buffer);
  if (declared < 7) {
    return false;
  }
  const size_t read_size = static_cast<size_t>(declared - 3);
  if (read_size < kLegacyQuickbarReadCursorStart || read_size > payload_size) {
    return false;
  }

  QuickbarPacketReader reader{};
  reader.read_buffer = read_buffer;
  reader.read_size = read_size;
  reader.fragments = read_buffer + read_size;
  reader.fragment_size = payload_size - read_size;
  reader.cursor = kLegacyQuickbarReadCursorStart;
  if (reader.fragment_size > 0) {
    uint32_t final_bits = 0;
    if (ReadFirstMsbBits(reader.fragments, reader.fragment_size, 3, &final_bits)) {
      reader.final_fragment_bits = static_cast<uint8_t>(final_bits);
    }
  }
  return ReadQuickbarReaderString(&reader, value, max_length);
}

bool BuildEeServerStatusModuleResourcesPayload(
    const BridgeRuntime* runtime,
    unsigned char envelope,
    const std::string& status_module_name,
    std::vector<unsigned char>* payload,
    std::wstring* failure_reason) {
  if (runtime == nullptr || payload == nullptr) {
    return FailQuickbarPayloadBuild(failure_reason, L"missing runtime or payload");
  }
  if (!IsHighLevelGameplayEnvelope(envelope)) {
    return FailQuickbarPayloadBuild(failure_reason, L"unsupported high-level envelope");
  }
  if (runtime->options.nwsync_repository_hash.empty() || runtime->options.nwsync_url.empty()) {
    return FailQuickbarPayloadBuild(failure_reason, L"missing NWSync hash or URL");
  }
  if (runtime->options.nwsync_manifests.size() > 255) {
    return FailQuickbarPayloadBuild(failure_reason, L"too many NWSync manifest adverts");
  }

  // CNWCMessage::HandleServerToPlayerServerStatus reads a leading status
  // CExoString for ServerStatus_ModuleRunning before it calls
  // CNWCModule::LoadModuleResources. The module-resource reader then consumes
  // the NWSync advertisement, module resource name/description, and hak list.
  // Keep the resource name empty: EE later uses it as a custom-TLK alias seed,
  // and a human-readable BNXR name such as "Path of Ascension CEP Legends" can
  // make that fallback fail before the legacy Module_Info packet is processed.
  const std::string module_name;
  const std::string module_description;

  QuickbarPacketWriter writer;
  if (!QuickbarWriteString(&writer, status_module_name, failure_reason) ||
      !QuickbarWriteBit(&writer, true) ||
      !QuickbarWriteString(&writer, runtime->options.nwsync_repository_hash, failure_reason) ||
      !QuickbarWriteByte(&writer, 1) ||
      !QuickbarWriteString(&writer, runtime->options.nwsync_url, failure_reason) ||
      !QuickbarWriteByte(&writer, static_cast<uint8_t>(runtime->options.nwsync_manifests.size()))) {
    return false;
  }

  for (const NwsyncManifestAdvert& manifest : runtime->options.nwsync_manifests) {
    if (!QuickbarWriteString(&writer, manifest.hash, failure_reason) ||
        !QuickbarWriteByte(&writer, manifest.flags) ||
        !QuickbarWriteByte(&writer, manifest.language)) {
      return false;
    }
  }

  if (!QuickbarWriteString(&writer, module_name, failure_reason) ||
      !QuickbarWriteString(&writer, module_description, failure_reason) ||
      !QuickbarWriteByte(&writer, static_cast<uint8_t>(kHgModuleHakOrderTopFirst.size()))) {
    return false;
  }
  for (const char* hak : kHgModuleHakOrderTopFirst) {
    if (!QuickbarWriteFixedResref16(&writer, hak, failure_reason)) {
      return false;
    }
  }

  if (writer.read_buffer.size() + 3 > 0xFFFFFFFFull) {
    return FailQuickbarPayloadBuild(failure_reason, L"encoded module-resources payload too large");
  }
  WriteU32Le(writer.read_buffer.data(), static_cast<uint32_t>(writer.read_buffer.size() + 3));

  std::vector<unsigned char> fragments;
  if (!BuildQuickbarFragmentBytes(&writer, &fragments)) {
    return FailQuickbarPayloadBuild(failure_reason, L"module-resources fragment build failed");
  }
  if (writer.read_buffer.size() > kMaxReasonableReassembledGameplayPayload - 3 ||
      fragments.size() > kMaxReasonableReassembledGameplayPayload - 3 - writer.read_buffer.size()) {
    return FailQuickbarPayloadBuild(failure_reason, L"encoded module-resources payload exceeds cap");
  }

  payload->clear();
  payload->reserve(3 + writer.read_buffer.size() + fragments.size());
  payload->push_back(envelope);
  payload->push_back(1);
  payload->push_back(3);
  payload->insert(payload->end(), writer.read_buffer.begin(), writer.read_buffer.end());
  payload->insert(payload->end(), fragments.begin(), fragments.end());
  return true;
}

std::string QuickbarActiveItemFlattenedName(const QuickbarActiveItemProperties& properties) {
  if (!properties.name_is_locstring) {
    return properties.string_name;
  }
  return properties.locstring_name.custom_tlk ? std::string() : properties.locstring_name.text;
}

bool ExpandQuickbarActiveValueMaskBytes(
    const QuickbarActiveItemProperties& properties,
    std::array<uint8_t, 8>* expanded,
    std::wstring* failure_reason) {
  if (expanded == nullptr) {
    return FailQuickbarPayloadBuild(failure_reason, L"missing active value byte output");
  }

  expanded->fill(0);
  size_t value_index = 0;
  for (uint8_t bit = 0; bit < expanded->size(); ++bit) {
    if ((properties.value_mask & (1u << bit)) == 0) {
      continue;
    }
    if (value_index >= properties.value_mask_bytes.size()) {
      return FailQuickbarPayloadBuild(
          failure_reason,
          L"quickbar item active property value mask missing byte bit=%u mask=0x%02X count=%zu",
          static_cast<unsigned int>(bit),
          static_cast<unsigned int>(properties.value_mask),
          properties.value_mask_bytes.size());
    }
    (*expanded)[bit] = properties.value_mask_bytes[value_index++];
  }
  return true;
}

bool WriteQuickbarActiveItemProperties(
    QuickbarPacketWriter* writer,
    const QuickbarActiveItemProperties& properties,
    uint32_t base_item_id,
    std::wstring* failure_reason) {
  if (writer == nullptr) {
    return FailQuickbarPayloadBuild(failure_reason, L"missing quickbar writer");
  }
  if (properties.properties.size() > 255) {
    return FailQuickbarPayloadBuild(failure_reason, L"quickbar item has too many active properties");
  }

  std::array<uint8_t, 8> expanded_value_bytes{};
  if (!ExpandQuickbarActiveValueMaskBytes(properties, &expanded_value_bytes, failure_reason)) {
    return false;
  }

  if (LegacyQuickbarBaseItemRequiresActivePropertyWord(base_item_id)) {
    QuickbarWriteWord(writer, properties.has_armor_word ? properties.armor_word : 0);
  }

  const bool flatten_inline_locstring_name =
      properties.name_is_locstring && !properties.locstring_name.custom_tlk;
  const bool write_name_as_locstring =
      properties.name_is_locstring && !flatten_inline_locstring_name;
  QuickbarWriteBit(writer, write_name_as_locstring);
  if (write_name_as_locstring) {
    if (!QuickbarWriteLocString(writer, properties.locstring_name, failure_reason)) {
      return false;
    }
  } else if (!QuickbarWriteString(
                 writer,
                 QuickbarActiveItemFlattenedName(properties),
                 failure_reason)) {
    return false;
  }

  QuickbarWriteBit(writer, properties.post_name_bool1);
  QuickbarWriteDword(writer, properties.cost);
  QuickbarWriteDword(writer, properties.stack_or_charges);
  QuickbarWriteBit(writer, properties.post_name_bool2);
  QuickbarWriteBit(writer, properties.post_name_bool3);
  QuickbarWriteBit(writer, properties.post_name_bool4);
  QuickbarWriteBit(writer, false);

  QuickbarWriteByte(writer, static_cast<uint8_t>(properties.properties.size()));
  for (const QuickbarActivePropertyEntry& entry : properties.properties) {
    QuickbarWriteWord(writer, entry.property);
    QuickbarWriteWord(writer, entry.subtype);
    QuickbarWriteWord(writer, entry.cost_table_value);
    QuickbarWriteByte(writer, entry.param);
  }

  QuickbarWriteByte(writer, properties.state_mask);
  QuickbarWriteByte(writer, 0xFF);
  for (uint8_t value : expanded_value_bytes) {
    QuickbarWriteByte(writer, value);
  }
  return true;
}

bool WriteEmptyQuickbarActiveItemProperties(
    QuickbarPacketWriter* writer,
    uint32_t base_item_id,
    std::wstring* failure_reason) {
  if (writer == nullptr) {
    return FailQuickbarPayloadBuild(failure_reason, L"missing quickbar writer");
  }
  if (LegacyQuickbarBaseItemRequiresActivePropertyWord(base_item_id)) {
    QuickbarWriteWord(writer, 0);
  }
  QuickbarWriteBit(writer, false);
  QuickbarWriteDword(writer, 0);
  QuickbarWriteBit(writer, false);
  QuickbarWriteDword(writer, 0);
  QuickbarWriteDword(writer, 0);
  QuickbarWriteBit(writer, false);
  QuickbarWriteBit(writer, false);
  QuickbarWriteBit(writer, false);
  QuickbarWriteBit(writer, false);
  QuickbarWriteByte(writer, 0);
  QuickbarWriteByte(writer, 0);
  QuickbarWriteByte(writer, 0);
  return true;
}

bool WriteQuickbarItemAppearance(
    QuickbarPacketWriter* writer,
    const QuickbarItemObject& item,
    std::wstring* failure_reason) {
  if (writer == nullptr || item.appearance_bytes.size() < 4) {
    return FailQuickbarPayloadBuild(
        failure_reason,
        L"item 0x%08X has no captured appearance bytes",
        item.object_id);
  }
  QuickbarWriteDword(writer, ReadU32Le(item.appearance_bytes.data()));
  for (size_t index = 4; index < item.appearance_bytes.size(); ++index) {
    QuickbarWriteByte(writer, item.appearance_bytes[index]);
  }
  if (item.appearance_type == 3) {
    for (size_t index = 0; index < kEeLiveExtendedArmorTableBytes; ++index) {
      QuickbarWriteByte(writer, 0);
    }
  }
  // With the Diamond 1.69 server build gate, EE's visual-transform reader takes
  // the legacy CAurObjectVisualTransformData path. That path reads ten
  // LerpFloat values before the active item properties.
  for (uint32_t value : kEeLegacyVisualTransformIdentityDwords) {
    QuickbarWriteDword(writer, value);
  }
  return true;
}

bool WriteQuickbarItemObject(
    QuickbarPacketWriter* writer,
    const QuickbarItemObject& item,
    bool include_int_param,
    std::wstring* failure_reason) {
  if (writer == nullptr) {
    return FailQuickbarPayloadBuild(failure_reason, L"missing quickbar writer");
  }

  QuickbarWriteBit(writer, item.present);
  if (!item.present) {
    return true;
  }

  QuickbarWriteDword(writer, item.object_id);
  if (include_int_param) {
    // EE passes present_bool + 0x1F here, so present items still consume a
    // full 32-bit read-buffer INT rather than the signed fragment-bit path.
    QuickbarWriteInt(writer, item.int_param);
  }
  return WriteQuickbarItemAppearance(writer, item, failure_reason) &&
      (item.active_props_parsed
           ? WriteQuickbarActiveItemProperties(
                 writer,
                 item.active_props,
                 item.base_item,
                 failure_reason)
           : WriteEmptyQuickbarActiveItemProperties(writer, item.base_item, failure_reason));
}

bool FailQuickbarEeValidation(
    std::wstring* failure_reason,
    const QuickbarPacketReader& reader,
    size_t slot,
    const wchar_t* phase,
    const wchar_t* format,
    ...) {
  if (failure_reason != nullptr) {
    wchar_t detail[512]{};
    va_list args;
    va_start(args, format);
    _vsnwprintf_s(detail, _TRUNCATE, format, args);
    va_end(args);

    wchar_t prefix[160]{};
    swprintf_s(
        prefix,
        L"slot=%zu phase=%s ",
        slot,
        phase != nullptr ? phase : L"?");
    *failure_reason = prefix;
    *failure_reason += detail;
    *failure_reason += L" state=[";
    *failure_reason += FormatQuickbarReaderWindow(reader);
    *failure_reason += L"]";
  }
  return false;
}

bool ValidateEeQuickbarVisualTransformLegacyBuild(
    QuickbarPacketReader* reader,
    size_t slot,
    std::wstring* failure_reason) {
  for (size_t index = 0; index < kEeLegacyVisualTransformLerpFloatCount; ++index) {
    uint32_t neutral_lerp_float = 0;
    if (!ReadQuickbarReaderDword(reader, &neutral_lerp_float)) {
      return FailQuickbarEeValidation(
          failure_reason,
          reader != nullptr ? *reader : QuickbarPacketReader{},
          slot,
          L"appearance",
          L"missing legacy feature-0x23 visual-transform LerpFloat index=%zu",
          index);
    }
  }
  return true;
}

bool ValidateEeQuickbarItemAppearanceLegacyBuild(
    const BridgeRuntime& runtime,
    QuickbarPacketReader* reader,
    size_t slot,
    uint32_t* base_item_id,
    int* model_type,
    std::wstring* failure_reason) {
  if (base_item_id != nullptr) {
    *base_item_id = 0xFFFFFFFFu;
  }
  if (model_type != nullptr) {
    *model_type = -1;
  }
  if (reader == nullptr) {
    return FailQuickbarEeValidation(
        failure_reason,
        QuickbarPacketReader{},
        slot,
        L"appearance",
        L"missing reader");
  }

  uint32_t base = 0;
  if (!ReadQuickbarReaderDword(reader, &base)) {
    return FailQuickbarEeValidation(
        failure_reason,
        *reader,
        slot,
        L"appearance",
        L"missing base item");
  }
  if (base_item_id != nullptr) {
    *base_item_id = base;
  }

  const int model = GetBaseItemModelType(runtime, base);
  if (model_type != nullptr) {
    *model_type = model;
  }
  if (model < 0 || model > 3) {
    return FailQuickbarEeValidation(
        failure_reason,
        *reader,
        slot,
        L"appearance",
        L"base item model lookup failed base=%u/0x%08X",
        base,
        base);
  }

  const size_t part_count = model == 3 ? 19 : (model == 2 ? 3 : 1);
  for (size_t index = 0; index < part_count; ++index) {
    uint8_t ignored = 0;
    if (!ReadQuickbarReaderByte(reader, &ignored)) {
      return FailQuickbarEeValidation(
          failure_reason,
          *reader,
          slot,
          L"appearance",
          L"truncated part byte index=%zu model=%d base=%u",
          index,
          model,
          base);
    }
  }

  if (model == 1 || model == 3) {
    for (size_t index = 0; index < 6; ++index) {
      uint8_t ignored = 0;
      if (!ReadQuickbarReaderByte(reader, &ignored)) {
        return FailQuickbarEeValidation(
            failure_reason,
            *reader,
            slot,
            L"appearance",
            L"truncated color byte index=%zu model=%d base=%u",
            index,
            model,
            base);
      }
    }
  }

  if (model == 3) {
    for (size_t index = 0; index < kEeLiveExtendedArmorTableBytes; ++index) {
      uint8_t ignored = 0;
      if (!ReadQuickbarReaderByte(reader, &ignored)) {
        return FailQuickbarEeValidation(
            failure_reason,
            *reader,
            slot,
            L"appearance",
            L"truncated EE armor extension byte index=%zu base=%u",
            index,
            base);
      }
    }
  }

  if (model == 2) {
    uint8_t ignored = 0;
    if (!ReadQuickbarReaderByte(reader, &ignored)) {
      return FailQuickbarEeValidation(
          failure_reason,
          *reader,
          slot,
          L"appearance",
          L"truncated model-type-2 tail byte base=%u",
          base);
    }
  }

  return ValidateEeQuickbarVisualTransformLegacyBuild(reader, slot, failure_reason);
}

bool ValidateEeQuickbarActiveItemPropertiesLegacyBuild(
    QuickbarPacketReader* reader,
    size_t slot,
    uint32_t base_item_id,
    std::wstring* failure_reason) {
  if (reader == nullptr) {
    return FailQuickbarEeValidation(
        failure_reason,
        QuickbarPacketReader{},
        slot,
        L"active",
        L"missing reader");
  }

  if (LegacyQuickbarBaseItemRequiresActivePropertyWord(base_item_id)) {
    uint16_t armor_word = 0;
    if (!ReadQuickbarReaderWord(reader, &armor_word)) {
      return FailQuickbarEeValidation(
          failure_reason,
          *reader,
          slot,
          L"active",
          L"missing armor active-property word");
    }
  }

  bool name_is_locstring = false;
  if (!ReadQuickbarReaderBool(reader, &name_is_locstring)) {
    return FailQuickbarEeValidation(
        failure_reason,
        *reader,
        slot,
        L"active",
        L"missing name-kind bit");
  }
  if (name_is_locstring) {
    if (!ReadQuickbarReaderLocString(reader, nullptr, nullptr)) {
      return FailQuickbarEeValidation(
          failure_reason,
          *reader,
          slot,
          L"active",
          L"failed locstring name");
    }
  } else {
    std::string name;
    if (!ReadQuickbarReaderString(reader, &name)) {
      return FailQuickbarEeValidation(
          failure_reason,
          *reader,
          slot,
          L"active",
          L"failed string name");
    }
  }

  bool bool_value = false;
  uint32_t dword_value = 0;
  if (!ReadQuickbarReaderBool(reader, &bool_value) ||
      !ReadQuickbarReaderDword(reader, &dword_value) ||
      !ReadQuickbarReaderDword(reader, &dword_value) ||
      !ReadQuickbarReaderBool(reader, &bool_value) ||
      !ReadQuickbarReaderBool(reader, &bool_value) ||
      !ReadQuickbarReaderBool(reader, &bool_value) ||
      !ReadQuickbarReaderBool(reader, &bool_value)) {
    return FailQuickbarEeValidation(
        failure_reason,
        *reader,
        slot,
        L"active",
        L"truncated post-name scalar/BOOL sequence");
  }

  uint8_t property_count = 0;
  if (!ReadQuickbarReaderByte(reader, &property_count)) {
    return FailQuickbarEeValidation(
        failure_reason,
        *reader,
        slot,
        L"active",
        L"missing property count");
  }
  constexpr uint8_t kMaxReasonableQuickbarItemProperties = 128;
  if (property_count > kMaxReasonableQuickbarItemProperties) {
    return FailQuickbarEeValidation(
        failure_reason,
        *reader,
        slot,
        L"active",
        L"unreasonable property count=%u",
        static_cast<unsigned int>(property_count));
  }

  for (uint8_t index = 0; index < property_count; ++index) {
    uint16_t word_value = 0;
    uint8_t byte_value = 0;
    if (!ReadQuickbarReaderWord(reader, &word_value) ||
        !ReadQuickbarReaderWord(reader, &word_value) ||
        !ReadQuickbarReaderWord(reader, &word_value) ||
        !ReadQuickbarReaderByte(reader, &byte_value)) {
      return FailQuickbarEeValidation(
          failure_reason,
          *reader,
          slot,
          L"active",
          L"truncated property index=%u/%u",
          static_cast<unsigned int>(index),
          static_cast<unsigned int>(property_count));
    }
  }

  uint8_t state_mask = 0;
  uint8_t value_mask = 0;
  if (!ReadQuickbarReaderByte(reader, &state_mask) ||
      !ReadQuickbarReaderByte(reader, &value_mask)) {
    return FailQuickbarEeValidation(
        failure_reason,
        *reader,
        slot,
        L"active",
        L"missing state/value masks");
  }
  for (uint8_t bit = 0; bit < 8; ++bit) {
    if ((value_mask & (1u << bit)) == 0) {
      continue;
    }
    uint8_t value = 0;
    if (!ReadQuickbarReaderByte(reader, &value)) {
      return FailQuickbarEeValidation(
          failure_reason,
          *reader,
          slot,
          L"active",
          L"missing value-mask byte bit=%u mask=0x%02X",
          static_cast<unsigned int>(bit),
          static_cast<unsigned int>(value_mask));
    }
  }
  return true;
}

bool ValidateEeQuickbarItemObjectLegacyBuild(
    const BridgeRuntime& runtime,
    QuickbarPacketReader* reader,
    size_t slot,
    bool include_int_param,
    std::wstring* failure_reason) {
  if (reader == nullptr) {
    return FailQuickbarEeValidation(
        failure_reason,
        QuickbarPacketReader{},
        slot,
        L"item",
        L"missing reader");
  }

  bool present = false;
  if (!ReadQuickbarReaderBool(reader, &present)) {
    return FailQuickbarEeValidation(
        failure_reason,
        *reader,
        slot,
        L"item",
        L"missing present bit");
  }
  if (!present) {
    return true;
  }

  uint32_t object_id = 0;
  uint32_t int_param = 0;
  if (!ReadQuickbarReaderDword(reader, &object_id) ||
      (include_int_param && !ReadQuickbarReaderDword(reader, &int_param))) {
    return FailQuickbarEeValidation(
        failure_reason,
        *reader,
        slot,
        L"item",
        L"missing object id/int param");
  }

  uint32_t base_item_id = 0;
  int model_type = -1;
  if (!ValidateEeQuickbarItemAppearanceLegacyBuild(
          runtime,
          reader,
          slot,
          &base_item_id,
          &model_type,
          failure_reason)) {
    return false;
  }
  return ValidateEeQuickbarActiveItemPropertiesLegacyBuild(
      reader,
      slot,
      base_item_id,
      failure_reason);
}

bool ValidateEeQuickbarPayloadLegacyBuild(
    const BridgeRuntime& runtime,
    const std::vector<unsigned char>& payload,
    std::wstring* failure_reason) {
  if (failure_reason != nullptr) {
    failure_reason->clear();
  }
  if (payload.size() < 7 ||
      !IsHighLevelGameplayEnvelope(payload[0]) ||
      payload[1] != 30 ||
      payload[2] != 1) {
    return FailQuickbarFullParse(failure_reason, L"not a quickbar SetAllButtons payload");
  }

  const unsigned char* cnw = payload.data() + 3;
  const size_t payload_size = payload.size() - 3;
  const uint32_t declared = ReadU32Le(cnw);
  if (declared < 3) {
    return FailQuickbarFullParse(failure_reason, L"invalid quickbar declared=%u", declared);
  }
  const size_t read_size = static_cast<size_t>(declared - 3);
  if (read_size < kLegacyQuickbarReadCursorStart || read_size > payload_size) {
    return FailQuickbarFullParse(
        failure_reason,
        L"quickbar read_size=%zu outside payload_size=%zu declared=%u",
        read_size,
        payload_size,
        declared);
  }
  const size_t fragment_size = payload_size - read_size;
  if (fragment_size == 0) {
    return FailQuickbarFullParse(failure_reason, L"quickbar has no CNW fragment stream");
  }

  QuickbarPacketReader reader{};
  reader.read_buffer = cnw;
  reader.read_size = read_size;
  reader.fragments = cnw + read_size;
  reader.fragment_size = fragment_size;
  reader.cursor = kLegacyQuickbarReadCursorStart;

  uint32_t final_bits = 0;
  if (!ReadQuickbarReaderBits(&reader, 3, &final_bits)) {
    return FailQuickbarEeValidation(
        failure_reason,
        reader,
        0,
        L"header",
        L"missing final-fragment bit count");
  }
  reader.final_fragment_bits = static_cast<uint8_t>(final_bits);

  for (size_t slot = 0; slot < kLegacyQuickbarButtonCount; ++slot) {
    uint8_t type = 0;
    if (!ReadQuickbarReaderByte(&reader, &type)) {
      return FailQuickbarEeValidation(
          failure_reason,
          reader,
          slot,
          L"button",
          L"missing button type");
    }
    if (type == 1) {
      if (!ValidateEeQuickbarItemObjectLegacyBuild(
              runtime,
              &reader,
              slot,
              true,
              failure_reason) ||
          !ValidateEeQuickbarItemObjectLegacyBuild(
              runtime,
              &reader,
              slot,
              false,
              failure_reason)) {
        return false;
      }
      continue;
    }

    QuickbarButtonInventory scratch{};
    scratch.slot = slot;
    scratch.type = type;
    if (!ParseQuickbarNonItemFromReader(&reader, type, &scratch)) {
      return FailQuickbarEeValidation(
          failure_reason,
          reader,
          slot,
          L"button",
          L"unsupported or truncated non-item type=%u",
          static_cast<unsigned int>(type));
    }
  }

  if (reader.cursor != reader.read_size) {
    return FailQuickbarEeValidation(
        failure_reason,
        reader,
        kLegacyQuickbarButtonCount,
        L"tail",
        L"read cursor ended at %zu, expected %zu",
        reader.cursor,
        reader.read_size);
  }

  const size_t consumed_fragment_bits = reader.fragment_cursor * 8 + reader.fragment_bit;
  const size_t consumed_fragment_bytes = reader.fragment_cursor + (reader.fragment_bit != 0 ? 1 : 0);
  if (consumed_fragment_bytes != reader.fragment_size) {
    return FailQuickbarEeValidation(
        failure_reason,
        reader,
        kLegacyQuickbarButtonCount,
        L"tail",
        L"fragment cursor consumed %zu bytes, expected %zu",
        consumed_fragment_bytes,
        reader.fragment_size);
  }
  if (reader.final_fragment_bits != static_cast<uint8_t>(consumed_fragment_bits % 8u)) {
    return FailQuickbarEeValidation(
        failure_reason,
        reader,
        kLegacyQuickbarButtonCount,
        L"tail",
        L"final fragment bits=%u but consumed bits mod 8=%zu",
        static_cast<unsigned int>(reader.final_fragment_bits),
        consumed_fragment_bits % 8u);
  }
  return true;
}

bool ShouldPreserveQuickbarGeneralButton(const QuickbarButtonInventory& button) {
  return button.parsed &&
      !button.spell &&
      !button.item_payload &&
      (button.no_payload ||
       button.int_payload ||
       button.byte_payload ||
       button.resref_payload ||
       button.string_payload ||
       button.string2_payload);
}

bool WriteQuickbarGeneralButton(
    QuickbarPacketWriter* writer,
    const QuickbarButtonInventory& button,
    std::wstring* failure_reason) {
  if (writer == nullptr) {
    return FailQuickbarPayloadBuild(failure_reason, L"missing quickbar writer");
  }

  QuickbarWriteByte(writer, button.type);
  if (button.no_payload) {
    return true;
  }
  if (button.spell && button.type == 2) {
    QuickbarWriteByte(writer, button.byte_value);
    QuickbarWriteDword(writer, button.int_value);
    QuickbarWriteByte(writer, button.spell_metamagic);
    QuickbarWriteByte(writer, button.spell_domain);
    return true;
  }
  if (button.int_payload) {
    QuickbarWriteInt(writer, static_cast<int32_t>(button.int_value));
  }
  if (button.byte_payload && button.type == 44) {
    QuickbarWriteByte(writer, button.byte_value);
  }
  if (button.type >= 11 && button.type <= 17) {
    return QuickbarWriteFixedResref(writer, button, failure_reason) &&
        QuickbarWriteString(writer, button.text, failure_reason);
  }
  if (button.type == 18) {
    return QuickbarWriteString(writer, button.text, failure_reason) &&
        QuickbarWriteString(writer, button.text2, failure_reason);
  }
  if (button.type == 29 || button.type == 30) {
    return QuickbarWriteFixedResref(writer, button, failure_reason);
  }
  return true;
}

bool BuildEeQuickbarPayload(
    const QuickbarFullParseView& view,
    std::vector<unsigned char>* payload,
    std::wstring* failure_reason) {
  if (payload != nullptr) {
    payload->clear();
  }
  if (failure_reason != nullptr) {
    failure_reason->clear();
  }
  if (payload == nullptr) {
    return FailQuickbarPayloadBuild(failure_reason, L"missing output payload");
  }
  if (!IsHighLevelGameplayEnvelope(view.envelope)) {
    return FailQuickbarPayloadBuild(
        failure_reason,
        L"unsupported envelope 0x%02X",
        static_cast<unsigned int>(view.envelope));
  }

  QuickbarPacketWriter writer;
  for (size_t slot = 0; slot < view.buttons.size(); ++slot) {
    const QuickbarButtonInventory& button = view.buttons[slot];
    if (button.spell) {
      QuickbarWriteByte(&writer, 2);
      QuickbarWriteByte(&writer, button.byte_value);
      QuickbarWriteDword(&writer, button.int_value);
      QuickbarWriteByte(&writer, button.spell_metamagic);
      QuickbarWriteByte(&writer, button.spell_domain);
    } else if (button.item_payload &&
        (button.primary_item.present || button.secondary_item.present)) {
      QuickbarWriteByte(&writer, 1);
      if (!WriteQuickbarItemObject(
              &writer,
              button.primary_item,
              true,
              failure_reason) ||
          !WriteQuickbarItemObject(
              &writer,
              button.secondary_item,
              false,
              failure_reason)) {
        return false;
      }
    } else if (ShouldPreserveQuickbarGeneralButton(button)) {
      if (!WriteQuickbarGeneralButton(&writer, button, failure_reason)) {
        return false;
      }
    } else {
      QuickbarWriteByte(&writer, 0);
    }
  }

  if (writer.read_buffer.size() + 3 > 0xFFFFFFFFull) {
    return FailQuickbarPayloadBuild(failure_reason, L"encoded quickbar too large");
  }
  WriteU32Le(writer.read_buffer.data(), static_cast<uint32_t>(writer.read_buffer.size() + 3));

  std::vector<unsigned char> fragments;
  if (!BuildQuickbarFragmentBytes(&writer, &fragments)) {
    return FailQuickbarPayloadBuild(failure_reason, L"quickbar fragment build failed");
  }

  payload->reserve(3 + writer.read_buffer.size() + fragments.size());
  payload->push_back(view.envelope);
  payload->push_back(30);
  payload->push_back(1);
  payload->insert(payload->end(), writer.read_buffer.begin(), writer.read_buffer.end());
  payload->insert(payload->end(), fragments.begin(), fragments.end());
  return true;
}

bool BuildSimpleQuickbarPayload(
    const QuickbarPacketView& view,
    unsigned char envelope,
    std::vector<unsigned char>* payload,
    std::wstring* failure_reason) {
  if (payload != nullptr) {
    payload->clear();
  }
  if (failure_reason != nullptr) {
    failure_reason->clear();
  }
  if (payload == nullptr) {
    return FailQuickbarPayloadBuild(failure_reason, L"missing output payload");
  }
  if (!IsHighLevelGameplayEnvelope(envelope)) {
    return FailQuickbarPayloadBuild(failure_reason, L"unsupported envelope 0x%02X", static_cast<unsigned int>(envelope));
  }
  if (!view.buttons_parsed || view.parsed_slots != kLegacyQuickbarButtonCount ||
      view.buttons.size() != kLegacyQuickbarButtonCount) {
    return FailQuickbarPayloadBuild(
        failure_reason,
        L"incomplete button inventory parsed=%d slots=%zu stored=%zu",
        view.buttons_parsed ? 1 : 0,
        view.parsed_slots,
        view.buttons.size());
  }
  if (view.item_candidates != 0 || view.unsupported_buttons != 0) {
    return FailQuickbarPayloadBuild(
        failure_reason,
        L"unsupported button classes item_candidates=%d unsupported=%d",
        view.item_candidates,
        view.unsupported_buttons);
  }
  if (view.final_cursor != view.read_size) {
    return FailQuickbarPayloadBuild(
        failure_reason,
        L"read cursor mismatch final=%zu read_size=%zu",
        view.final_cursor,
        view.read_size);
  }

  std::vector<unsigned char> read_buffer(4, 0);
  for (size_t slot = 0; slot < view.buttons.size(); ++slot) {
    const QuickbarButtonInventory& button = view.buttons[slot];
    if (!button.parsed || button.slot != slot) {
      return FailQuickbarPayloadBuild(
          failure_reason,
          L"slot %zu inventory missing parsed=%d stored_slot=%zu",
          slot,
          button.parsed ? 1 : 0,
          button.slot);
    }
    if (!IsLegacyQuickbarPlausibleType(button.type) || button.type == 1) {
      return FailQuickbarPayloadBuild(
          failure_reason,
          L"slot %zu unsupported type=%u",
          slot,
          static_cast<unsigned int>(button.type));
    }

    read_buffer.push_back(button.type);
    if (button.no_payload) {
      continue;
    }
    if (button.spell && button.type == 2) {
      read_buffer.push_back(button.byte_value);
      AppendU32Le(&read_buffer, button.int_value);
      read_buffer.push_back(button.spell_metamagic);
      read_buffer.push_back(button.spell_domain);
    } else if (LegacyQuickbarTypeHasIntPayload(button.type)) {
      AppendU32Le(&read_buffer, button.int_value);
    } else if (button.type == 44) {
      AppendU32Le(&read_buffer, button.int_value);
      read_buffer.push_back(button.byte_value);
    } else if (button.type >= 11 && button.type <= 17) {
      if (!AppendQuickbarResref16(&read_buffer, button) ||
          !AppendQuickbarString(&read_buffer, button.text)) {
        return FailQuickbarPayloadBuild(
            failure_reason,
            L"slot %zu resref/string encode failed",
            slot);
      }
    } else if (button.type == 18) {
      if (!AppendQuickbarString(&read_buffer, button.text) ||
          !AppendQuickbarString(&read_buffer, button.text2)) {
        return FailQuickbarPayloadBuild(
            failure_reason,
            L"slot %zu string pair encode failed",
            slot);
      }
    } else if (button.type == 29 || button.type == 30) {
      if (!AppendQuickbarResref16(&read_buffer, button)) {
        return FailQuickbarPayloadBuild(
            failure_reason,
            L"slot %zu resref encode failed",
            slot);
      }
    } else {
      return FailQuickbarPayloadBuild(
          failure_reason,
          L"slot %zu has no writer for type=%u",
          slot,
          static_cast<unsigned int>(button.type));
    }
  }

  if (read_buffer.size() != view.read_size) {
    return FailQuickbarPayloadBuild(
        failure_reason,
        L"encoded read size mismatch encoded=%zu observed=%zu",
        read_buffer.size(),
        view.read_size);
  }
  if (read_buffer.size() + 3 > 0xFFFFFFFFull) {
    return FailQuickbarPayloadBuild(failure_reason, L"encoded quickbar too large");
  }

  WriteU32Le(read_buffer.data(), static_cast<uint32_t>(read_buffer.size() + 3));
  payload->reserve(3 + read_buffer.size() + 1);
  payload->push_back(envelope);
  payload->push_back(30);
  payload->push_back(1);
  payload->insert(payload->end(), read_buffer.begin(), read_buffer.end());
  payload->push_back(0);
  return true;
}

bool RewriteQuickbarOpcodeStreamToEmptyIfPossible(
    BridgeRuntime* runtime,
    std::vector<unsigned char>* payload,
    const wchar_t* context) {
  if (runtime == nullptr || payload == nullptr || payload->size() <= 3 ||
      (*payload)[0] != 'P' || (*payload)[1] != 30 || (*payload)[2] != 1) {
    return false;
  }

  const unsigned char first_opcode = (*payload)[3];
  if (payload->size() == 3 + kLegacyQuickbarButtonCount &&
      std::all_of(payload->begin() + 3, payload->end(), [](unsigned char value) {
        return value == 0;
      })) {
    return false;
  }

  std::vector<unsigned char> rewritten;
  rewritten.reserve(3 + kLegacyQuickbarButtonCount);
  rewritten.push_back('P');
  rewritten.push_back(30);
  rewritten.push_back(1);
  rewritten.insert(rewritten.end(), kLegacyQuickbarButtonCount, 0);

  const size_t old_payload_length = payload->size();
  const std::wstring old_prefix = FormatLimitedBytes(payload->data(), payload->size(), 96);
  *payload = std::move(rewritten);
  ++runtime->quickbar_simple_rewrite_count;
  ++runtime->quickbar_opcode_stream_blank_count;
  LogFormat(
      L"%s quickbar opcode-stream blanked #%llu: first_opcode=%u old_payload=%zu new_payload=%zu total_quickbar_rewrites=%llu old_prefix=[%s]",
      context != nullptr ? context : L"server->client",
      static_cast<unsigned long long>(runtime->quickbar_opcode_stream_blank_count),
      static_cast<unsigned int>(first_opcode),
      old_payload_length,
      payload->size(),
      static_cast<unsigned long long>(runtime->quickbar_simple_rewrite_count),
      old_prefix.c_str());
  return true;
}

bool RewriteSimpleQuickbarPayloadIfPossible(
    BridgeRuntime* runtime,
    std::vector<unsigned char>* payload,
    const wchar_t* context) {
  if (runtime == nullptr || payload == nullptr || !runtime->options.rewrite_quickbar_simple ||
      payload->empty()) {
    return false;
  }

  QuickbarPacketView view;
  if (!TryParseQuickbarPacket(payload->data(), payload->size(), &view)) {
    // Some EE-facing quickbar packets are a direct 36-slot opcode stream
    // instead of a CNW read-buffer/fragment payload. Only use the empty-slot
    // stabilization fallback after the CNW layout has been ruled out; otherwise
    // the low byte of the CNW declared length looks like an opcode and erases
    // legitimate legacy quickbars.
    return RewriteQuickbarOpcodeStreamToEmptyIfPossible(runtime, payload, context);
  }

  if (view.fragment_size != 0 && view.item_candidates != 0) {
    QuickbarFullParseView full_view;
    std::wstring parse_failure;
    if (TryParseQuickbarPacketFull(
            *runtime,
            payload->data(),
            payload->size(),
            &full_view,
            &parse_failure) &&
        full_view.item_buttons_translated != 0) {
      std::vector<unsigned char> new_payload;
      std::wstring build_failure;
      if (!BuildEeQuickbarPayload(full_view, &new_payload, &build_failure)) {
        if (runtime->options.packet_dump) {
          LogFormat(
              L"%s quickbar item rewrite refused: reason=%s summary=[%s]",
              context != nullptr ? context : L"server->client",
              build_failure.empty() ? L"<unknown>" : build_failure.c_str(),
              full_view.button_summary.c_str());
        }
        return false;
      }
      std::wstring validate_failure;
      if (!ValidateEeQuickbarPayloadLegacyBuild(*runtime, new_payload, &validate_failure)) {
        LogFormat(
            L"%s quickbar item rewrite refused after EE-layout validation: reason=%s summary=[%s] new-payload=[%s]",
            context != nullptr ? context : L"server->client",
            validate_failure.empty() ? L"<unknown>" : validate_failure.c_str(),
            full_view.button_summary.c_str(),
            FormatLimitedBytes(new_payload.data(), new_payload.size(), 160).c_str());
        return false;
      }
      if (runtime->options.packet_dump) {
        QuickbarPacketView ee_view;
        if (TryParseQuickbarPacket(new_payload.data(), new_payload.size(), &ee_view)) {
          LogFormat(
              L"%s quickbar item EE-layout validation ok: declared=%u read_size=%zu fragment_size=%zu final_bits=%u new_payload=%zu",
              context != nullptr ? context : L"server->client",
              ee_view.declared,
              ee_view.read_size,
              ee_view.fragment_size,
              static_cast<unsigned int>(ee_view.final_fragment_bits),
              new_payload.size());
        }
      }

      if (new_payload == *payload) {
        if (runtime->options.packet_dump) {
          LogFormat(
              L"%s quickbar item rewrite no-op: payload_len=%zu summary=[%s]",
              context != nullptr ? context : L"server->client",
              payload->size(),
              full_view.button_summary.c_str());
        }
        return false;
      }

      const size_t old_payload_length = payload->size();
      *payload = std::move(new_payload);
      ++runtime->quickbar_simple_rewrite_count;
      ++runtime->quickbar_item_rewrite_count;
      runtime->quickbar_item_buttons_translated_count += full_view.item_buttons_translated;
      runtime->quickbar_item_buttons_blanked_count +=
          full_view.item_buttons_blanked + full_view.unsupported_buttons_blanked;
      LogFormat(
          L"%s quickbar item rewritten #%llu: declared=%u read_size=%zu fragment_size=%zu final_bits=%u items=%d unsupported_blanked=%d old_payload=%zu new_payload=%zu total_items=%llu summary=[%s]",
          context != nullptr ? context : L"server->client",
          static_cast<unsigned long long>(runtime->quickbar_item_rewrite_count),
          full_view.declared,
          full_view.read_size,
          full_view.fragment_size,
          static_cast<unsigned int>(full_view.final_fragment_bits),
          full_view.item_buttons_translated,
          full_view.unsupported_buttons_blanked,
          old_payload_length,
          payload->size(),
          static_cast<unsigned long long>(runtime->quickbar_item_buttons_translated_count),
          full_view.button_summary.c_str());
      return true;
    }

    if (runtime->options.packet_dump) {
      LogFormat(
          L"%s quickbar item rewrite skipped: reason=%s heuristic_summary=[%s]",
          context != nullptr ? context : L"server->client",
          parse_failure.empty() ? L"<unknown>" : parse_failure.c_str(),
          view.button_summary.c_str());
      LogFormat(
          L"%s quickbar item rewrite skipped raw payload: len=%zu payload=[%s]",
          context != nullptr ? context : L"server->client",
          payload->size(),
          FormatLimitedBytes(payload->data(), payload->size(), payload->size()).c_str());
    }
  }

  if (view.fragment_size == 0 || !view.buttons_parsed ||
      view.parsed_slots != kLegacyQuickbarButtonCount ||
      view.buttons.size() != kLegacyQuickbarButtonCount ||
      view.final_cursor != view.read_size ||
      view.item_candidates != 0 ||
      view.unsupported_buttons != 0) {
    if (runtime->options.packet_dump) {
      LogFormat(
          L"%s quickbar simple rewrite skipped: fragment_size=%zu parsed=%d slots=%zu stored=%zu final=%zu read_size=%zu item_candidates=%d unsupported=%d summary=[%s]",
          context != nullptr ? context : L"server->client",
          view.fragment_size,
          view.buttons_parsed ? 1 : 0,
          view.parsed_slots,
          view.buttons.size(),
          view.final_cursor,
          view.read_size,
          view.item_candidates,
          view.unsupported_buttons,
          view.button_summary.c_str());
    }
    return false;
  }

  std::vector<unsigned char> new_payload;
  std::wstring failure_reason;
  if (!BuildSimpleQuickbarPayload(view, (*payload)[0], &new_payload, &failure_reason)) {
    if (runtime->options.packet_dump) {
      LogFormat(
          L"%s quickbar simple rewrite refused: reason=%s summary=[%s]",
          context != nullptr ? context : L"server->client",
          failure_reason.empty() ? L"<unknown>" : failure_reason.c_str(),
          view.button_summary.c_str());
    }
    return false;
  }

  if (new_payload == *payload) {
    if (runtime->options.packet_dump) {
      LogFormat(
          L"%s quickbar simple rewrite no-op: payload_len=%zu summary=[%s]",
          context != nullptr ? context : L"server->client",
          payload->size(),
          view.button_summary.c_str());
    }
    return false;
  }

  const size_t old_payload_length = payload->size();
  *payload = std::move(new_payload);
  ++runtime->quickbar_simple_rewrite_count;
  LogFormat(
      L"%s quickbar simple rewritten #%llu: declared=%u read_size=%zu fragment_size=%zu slots=%zu old_payload=%zu new_payload=%zu summary=[%s]",
      context != nullptr ? context : L"server->client",
      static_cast<unsigned long long>(runtime->quickbar_simple_rewrite_count),
      view.declared,
      view.read_size,
      view.fragment_size,
      view.parsed_slots,
      old_payload_length,
      payload->size(),
      view.button_summary.c_str());
  return true;
}

bool QuickbarFullParseFailureMayNeedMoreFragments(const std::wstring& reason) {
  return reason.find(L"fragment") != std::wstring::npos ||
      reason.find(L"present bit") != std::wstring::npos ||
      reason.find(L"name kind bit") != std::wstring::npos ||
      reason.find(L"locstring name") != std::wstring::npos ||
      reason.find(L"post-name bool") != std::wstring::npos;
}

bool QuickbarPayloadNeedsMoreItemFragmentBytes(
    BridgeRuntime* runtime,
    const unsigned char* payload,
    size_t payload_length,
    std::wstring* failure_reason,
    std::wstring* summary) {
  if (failure_reason != nullptr) {
    failure_reason->clear();
  }
  if (summary != nullptr) {
    summary->clear();
  }
  if (runtime == nullptr || payload == nullptr || payload_length == 0 ||
      !runtime->options.rewrite_quickbar_simple) {
    return false;
  }

  QuickbarPacketView view;
  if (!TryParseQuickbarPacket(payload, payload_length, &view) ||
      view.fragment_size == 0 || view.item_candidates == 0) {
    return false;
  }
  if (summary != nullptr) {
    *summary = view.button_summary;
  }

  QuickbarFullParseView full_view;
  std::wstring parse_failure;
  if (TryParseQuickbarPacketFull(
          *runtime,
          payload,
          payload_length,
          &full_view,
          &parse_failure)) {
    return false;
  }
  if (failure_reason != nullptr) {
    *failure_reason = parse_failure;
  }
  return QuickbarFullParseFailureMayNeedMoreFragments(parse_failure);
}

void ObserveModuleInfoHighLevel(
    BridgeRuntime* runtime,
    const wchar_t* direction,
    const unsigned char* payload,
    size_t payload_length) {
  if (runtime == nullptr) {
    return;
  }

  ++runtime->module_info_observed_count;
  ModuleInfoPacketView view;
  if (!TryParseModuleInfoPacket(payload, payload_length, &view)) {
    if (runtime->module_info_observed_count <= 20 || runtime->options.packet_dump) {
      LogFormat(
          L"%s module-info high-level parse failed #%llu: payload-len=%zu payload=[%s]",
          direction != nullptr ? direction : L"<unknown>",
          static_cast<unsigned long long>(runtime->module_info_observed_count),
          payload_length,
          FormatLimitedBytes(payload, payload_length, 64).c_str());
    }
    return;
  }

  LogFormat(
      L"%s module-info high-level parsed #%llu: declared=%u cursor_after_tlk=%zu module='%s' desc_len=%zu custom_tlk='%s' normalized_tlk='%s'",
      direction != nullptr ? direction : L"<unknown>",
      static_cast<unsigned long long>(runtime->module_info_observed_count),
      view.declared,
      view.cursor_after_custom_tlk,
      AsciiPreviewToWide(view.module_name).c_str(),
      view.module_description.size(),
      AsciiPreviewToWide(view.custom_tlk).c_str(),
      AsciiPreviewToWide(view.normalized_custom_tlk).c_str());

  LegacyHakBlockCandidate hak_block;
  if (TryFindLegacyModuleHakBlock(payload, payload_length, view, &hak_block)) {
    ++runtime->module_hak_block_candidate_count;
    LogFormat(
        L"%s legacy module hak block candidate #%llu: offset=%zu count=%u skip=%u resource_count=%u module_resref='%s' haks=[%s]",
        direction != nullptr ? direction : L"<unknown>",
        static_cast<unsigned long long>(runtime->module_hak_block_candidate_count),
        hak_block.offset,
        hak_block.hak_count,
        hak_block.skipped_bytes,
        hak_block.resource_count_peek,
        AsciiPreviewToWide(hak_block.module_resref).c_str(),
        JoinAsciiListPreview(hak_block.haks).c_str());
  } else if (runtime->module_info_observed_count <= 20 || runtime->options.packet_dump) {
    const size_t available =
        view.cursor_after_custom_tlk < payload_length ? payload_length - view.cursor_after_custom_tlk : 0;
    const size_t preview_length = std::min<size_t>(available, 64);
    LogFormat(
        L"%s legacy module hak block candidate not found: cursor=%zu payload-len=%zu scan=[%s]",
        direction != nullptr ? direction : L"<unknown>",
        view.cursor_after_custom_tlk,
        payload_length,
        FormatLimitedBytes(
            payload + view.cursor_after_custom_tlk,
            preview_length,
            preview_length).c_str());
  }
}

void ObserveQuickbarHighLevel(
    BridgeRuntime* runtime,
    const wchar_t* direction,
    const unsigned char* payload,
    size_t payload_length) {
  if (runtime == nullptr) {
    return;
  }

  QuickbarPacketView view;
  if (!TryParseQuickbarPacket(payload, payload_length, &view)) {
    if (runtime->quickbar_candidate_count <= 20 || runtime->options.packet_dump) {
      LogFormat(
          L"%s quickbar high-level parse failed: payload-len=%zu payload=[%s]",
          direction != nullptr ? direction : L"<unknown>",
          payload_length,
          FormatLimitedBytes(payload, payload_length, 64).c_str());
    }
    return;
  }

  ++runtime->quickbar_cnw_observed_count;
  LogFormat(
      L"%s quickbar high-level CNW layout #%llu: declared=%u read_size=%zu fragment_size=%zu final_fragment_bits=%s%u buttons=%d slots=%zu final_cursor=%zu score=%d spells=%d no_payload=%d general=%d item_candidates=%d unsupported=%d summary=[%s]",
      direction != nullptr ? direction : L"<unknown>",
      static_cast<unsigned long long>(runtime->quickbar_cnw_observed_count),
      view.declared,
      view.read_size,
      view.fragment_size,
      view.have_final_fragment_bits ? L"" : L"unknown/",
      view.final_fragment_bits,
      view.buttons_parsed ? 1 : 0,
      view.parsed_slots,
      view.final_cursor,
      view.score,
      view.spells,
      view.no_payload_buttons,
      view.general_buttons,
      view.item_candidates,
      view.unsupported_buttons,
      view.button_summary.empty() ? L"<none>" : view.button_summary.c_str());
  if (view.buttons_parsed) {
    ++runtime->quickbar_button_inventory_count;
  }
}

void ObservePartyHighLevel(
    BridgeRuntime* runtime,
    const wchar_t* direction,
    const unsigned char* payload,
    size_t payload_length) {
  if (runtime == nullptr || payload == nullptr || payload_length < 3 || payload[1] != 14) {
    return;
  }

  const unsigned int minor = payload[2];
  if (payload[0] == 0x70 && payload_length == 3) {
    ++runtime->party_packet_diagnostic_count;
    if (runtime->party_packet_diagnostic_count <= 120 || runtime->options.packet_dump) {
      LogFormat(
          L"%s party packet diagnostic #%llu: name='%s' major=14/0x0E minor=%u/0x%02X payload-len=%zu suspicious=0 party-empty-high-envelope raw=[%s]",
          direction != nullptr ? direction : L"<unknown>",
          static_cast<unsigned long long>(runtime->party_packet_diagnostic_count),
          KnownMajorMinorName(14, minor),
          minor,
          minor,
          payload_length,
          FormatLimitedBytes(payload, payload_length, 128).c_str());
    }
    return;
  }

  const bool internal_size_known = payload_length >= 7;
  const uint32_t internal_size = internal_size_known ? ReadU32Le(payload + 3) : 0;
  const uint32_t expected_internal_size =
      payload_length > 0 && payload_length - 1 <= UINT32_MAX
          ? static_cast<uint32_t>(payload_length - 1)
          : 0;
  const bool internal_size_matches =
      internal_size_known && internal_size == expected_internal_size;
  constexpr size_t kDataBegin = 7;
  const size_t data_end = payload_length > 0 ? payload_length - 1 : 0;
  const size_t data_available =
      data_end >= kDataBegin ? data_end - kDataBegin : 0;

  bool shape_ok = internal_size_matches;
  uint32_t count = 0;
  uint32_t player_index = 0;
  uint32_t object_id = 0;
  bool count_known = false;
  bool player_index_known = false;
  bool object_id_known = false;
  std::wstring detail;
  const bool list_like = minor == 1 || minor == 3 || minor == 4;

  if (list_like) {
    count_known = payload_length >= kDataBegin + 4;
    if (count_known) {
      count = ReadU32Le(payload + kDataBegin);
    }
    const size_t id_begin = kDataBegin + 4;
    const size_t id_bytes_available = data_end >= id_begin ? data_end - id_begin : 0;
    const uint32_t ids_available = static_cast<uint32_t>(id_bytes_available / 4);
    const uint64_t needed = 4ull + static_cast<uint64_t>(count) * 4ull;
    shape_ok = shape_ok &&
        count_known &&
        count <= 256 &&
        needed <= data_available &&
        (id_bytes_available % 4u) == 0;

    std::wstring ids;
    const uint32_t ids_to_log = std::min<uint32_t>(count, 8);
    for (uint32_t index = 0; index < ids_to_log; ++index) {
      const size_t offset = id_begin + static_cast<size_t>(index) * 4;
      if (payload_length < offset + 4) {
        break;
      }
      wchar_t id_text[64]{};
      swprintf_s(
          id_text,
          L"%s0x%08X",
          ids.empty() ? L"" : L",",
          ReadU32Le(payload + offset));
      ids += id_text;
    }
    if (count > ids_to_log) {
      ids += L",...";
    }

    wchar_t text[1024]{};
    swprintf_s(
        text,
        L"party-list-shape minor=%u internal-size-known=%d internal-size=%u expected=%u match=%d count-known=%d count=%u data-bytes=%zu id-bytes=%zu ids-available=%u ids=[%s] shape-ok=%d",
        minor,
        internal_size_known ? 1 : 0,
        internal_size,
        expected_internal_size,
        internal_size_matches ? 1 : 0,
        count_known ? 1 : 0,
        count,
        data_available,
        id_bytes_available,
        ids_available,
        ids.empty() ? L"<none>" : ids.c_str(),
        shape_ok ? 1 : 0);
    detail = text;
  } else if (minor == 9) {
    object_id_known = payload_length >= kDataBegin + 4;
    if (object_id_known) {
      object_id = ReadU32Le(payload + kDataBegin);
    }
    shape_ok = shape_ok && object_id_known && data_available >= 4;
    wchar_t text[512]{};
    swprintf_s(
        text,
        L"party-invite-shape minor=%u internal-size-known=%d internal-size=%u expected=%u match=%d object-known=%d object=0x%08X data-bytes=%zu shape-ok=%d",
        minor,
        internal_size_known ? 1 : 0,
        internal_size,
        expected_internal_size,
        internal_size_matches ? 1 : 0,
        object_id_known ? 1 : 0,
        object_id,
        data_available,
        shape_ok ? 1 : 0);
    detail = text;
  } else if (minor == 14) {
    player_index_known = payload_length >= kDataBegin + 4;
    object_id_known = payload_length >= kDataBegin + 8;
    if (player_index_known) {
      player_index = ReadU32Le(payload + kDataBegin);
    }
    if (object_id_known) {
      object_id = ReadU32Le(payload + kDataBegin + 4);
    }
    shape_ok = shape_ok && player_index_known && object_id_known && data_available >= 8;
    wchar_t text[512]{};
    swprintf_s(
        text,
        L"party-transfer-shape minor=%u internal-size-known=%d internal-size=%u expected=%u match=%d player-known=%d player=%u object-known=%d object=0x%08X data-bytes=%zu shape-ok=%d",
        minor,
        internal_size_known ? 1 : 0,
        internal_size,
        expected_internal_size,
        internal_size_matches ? 1 : 0,
        player_index_known ? 1 : 0,
        player_index,
        object_id_known ? 1 : 0,
        object_id,
        data_available,
        shape_ok ? 1 : 0);
    detail = text;
  } else {
    wchar_t text[384]{};
    swprintf_s(
        text,
        L"party-shape minor=%u internal-size-known=%d internal-size=%u expected=%u match=%d data-bytes=%zu",
        minor,
        internal_size_known ? 1 : 0,
        internal_size,
        expected_internal_size,
        internal_size_matches ? 1 : 0,
        data_available);
    detail = text;
  }

  const bool suspicious = !shape_ok;
  ++runtime->party_packet_diagnostic_count;
  if (runtime->party_packet_diagnostic_count <= 120 || suspicious || runtime->options.packet_dump) {
    LogFormat(
        L"%s party packet diagnostic #%llu: name='%s' major=14/0x0E minor=%u/0x%02X payload-len=%zu suspicious=%d %s raw=[%s]",
        direction != nullptr ? direction : L"<unknown>",
        static_cast<unsigned long long>(runtime->party_packet_diagnostic_count),
        KnownMajorMinorName(14, minor),
        minor,
        minor,
        payload_length,
        suspicious ? 1 : 0,
        detail.empty() ? L"<none>" : detail.c_str(),
        FormatLimitedBytes(payload, payload_length, 128).c_str());
  }
}

void ObserveLiveObjectHighLevel(
    BridgeRuntime* runtime,
    const wchar_t* direction,
    const unsigned char* payload,
    size_t payload_length) {
  if (runtime == nullptr) {
    return;
  }

  ++runtime->live_object_observed_count;
  const bool opcode_known = payload != nullptr && payload_length > 7;
  const unsigned char opcode = opcode_known ? payload[7] : 0;
  std::wstring summary;
  bool transition_related = false;
  if (!TryFormatLegacyLiveObjectPacketSummary(payload, payload_length, &summary, &transition_related)) {
    if (runtime->live_object_observed_count <= 40 || runtime->options.packet_dump) {
      const uint32_t wire_declared =
          payload != nullptr && payload_length >= 7 ? ReadU32Le(payload + 3) : 0;
      LogFormat(
          L"%s live-object high-level summary unavailable #%llu: %s payload-len=%zu wire_declared=%u payload=[%s]",
          direction != nullptr ? direction : L"<unknown>",
          static_cast<unsigned long long>(runtime->live_object_observed_count),
          FormatLiveObjectOpcode(opcode_known, opcode).c_str(),
          payload_length,
          wire_declared,
          FormatLimitedBytes(payload, payload_length, 80).c_str());
    }
    return;
  }

  ++runtime->live_object_summary_count;
  LogFormat(
      L"%s live-object high-level summary #%llu/%llu: %s payload-len=%zu transition-related=%d %s",
      direction != nullptr ? direction : L"<unknown>",
      static_cast<unsigned long long>(runtime->live_object_summary_count),
      static_cast<unsigned long long>(runtime->live_object_observed_count),
      FormatLiveObjectOpcode(opcode_known, opcode).c_str(),
      payload_length,
      transition_related ? 1 : 0,
      summary.c_str());
}

bool ObserveDirectGameplayHeader(BridgeRuntime* runtime, const wchar_t* direction, const unsigned char* payload, size_t payload_length) {
  if (runtime == nullptr || payload == nullptr || payload_length < 3 || payload[0] != 'P') {
    return false;
  }

  ++runtime->gameplay_direct_header_count;
  const unsigned int major = payload[1];
  const unsigned int minor = payload[2];
  const bool module_info = major == 3 && minor == 1;
  const bool live_object = major == 5 && minor == 1;
  const bool player_list = major == 0x0A && (minor == 0x01 || minor == 0x02 || minor == 0x03 || minor == 0x04);
  const bool party_packet = major == 14;
  const bool quickbar = major == 30 && minor == 1;
  const bool device = major == 0x36 && minor == 1;
  if (module_info) {
    ++runtime->module_info_candidate_count;
  }
  if (live_object) {
    ++runtime->live_object_candidate_count;
  }
  if (quickbar) {
    ++runtime->quickbar_candidate_count;
  }

  if (runtime->gameplay_direct_header_count <= 80 || module_info || live_object || player_list || party_packet || quickbar || device || runtime->options.packet_dump) {
    LogFormat(
        L"%s gameplay direct P payload observed #%llu: major=%u minor=%u name='%s' module-info=%d live-object=%d player-list=%d party=%d quickbar-setall=%d device=%d payload-len=%zu payload=[%s]",
        direction != nullptr ? direction : L"<unknown>",
        static_cast<unsigned long long>(runtime->gameplay_direct_header_count),
        major,
        minor,
        KnownMajorMinorName(major, minor),
        module_info ? 1 : 0,
        live_object ? 1 : 0,
        player_list ? 1 : 0,
        party_packet ? 1 : 0,
        quickbar ? 1 : 0,
        device ? 1 : 0,
        payload_length,
        FormatLimitedBytes(payload, payload_length, player_list ? 160 : 48).c_str());
  }
  if (module_info) {
    ObserveModuleInfoHighLevel(runtime, direction, payload, payload_length);
  }
  if (live_object) {
    ObserveLiveObjectHighLevel(runtime, direction, payload, payload_length);
  }
  if (party_packet) {
    ObservePartyHighLevel(runtime, direction, payload, payload_length);
  }
  if (quickbar) {
    ObserveQuickbarHighLevel(runtime, direction, payload, payload_length);
  }
  return true;
}

bool ObserveCnwHighGameplayHeader(BridgeRuntime* runtime, const wchar_t* direction, const unsigned char* payload, size_t payload_length) {
  if (runtime == nullptr || payload == nullptr || payload_length == 0 || payload[0] != 0x70) {
    return false;
  }

  ++runtime->gameplay_cnw_high_header_count;
  const unsigned int major = payload_length > 1 ? payload[1] : 0;
  const unsigned int minor = payload_length > 2 ? payload[2] : 0;
  const bool module_info = major == 3 && minor == 1;
  const bool live_object = major == 5 && minor == 1;
  const bool player_list = major == 0x0A && (minor == 0x01 || minor == 0x02 || minor == 0x03 || minor == 0x04);
  const bool party_packet = major == 14;
  const bool quickbar = major == 30 && minor == 1;
  const bool device = major == 0x36 && minor == 1;
  if (module_info) {
    ++runtime->module_info_candidate_count;
  }
  if (live_object) {
    ++runtime->live_object_candidate_count;
  }
  if (quickbar) {
    ++runtime->quickbar_candidate_count;
  }

  uint32_t declared = 0;
  const bool declared_known = payload_length >= 7;
  if (declared_known) {
    declared = ReadU32Le(payload + 3);
  }
  const bool complete = declared_known && declared <= payload_length;
  if (declared_known && !complete) {
    ++runtime->gameplay_reassembly_candidate_count;
  }

  if (runtime->gameplay_cnw_high_header_count <= 120 || module_info || live_object || player_list || party_packet || quickbar || device || runtime->options.packet_dump) {
    LogFormat(
        L"%s gameplay CNW high payload observed #%llu: high=[70 %02X %02X] name='%s' module-info=%d live-object=%d player-list=%d party=%d quickbar-setall=%d device=%d payload-len=%zu body-len=%zu declared=%s%u complete=%d reassembly_candidates=%llu payload=[%s]",
        direction != nullptr ? direction : L"<unknown>",
        static_cast<unsigned long long>(runtime->gameplay_cnw_high_header_count),
        major,
        minor,
        KnownMajorMinorName(major, minor),
        module_info ? 1 : 0,
        live_object ? 1 : 0,
        player_list ? 1 : 0,
        party_packet ? 1 : 0,
        quickbar ? 1 : 0,
        device ? 1 : 0,
        payload_length,
        payload_length >= 3 ? payload_length - 3 : 0,
        declared_known ? L"" : L"unknown/",
        declared,
        complete ? 1 : 0,
        static_cast<unsigned long long>(runtime->gameplay_reassembly_candidate_count),
        FormatLimitedBytes(payload, payload_length, player_list ? 160 : 48).c_str());
  }
  if (module_info) {
    ObserveModuleInfoHighLevel(runtime, direction, payload, payload_length);
  }
  if (live_object) {
    ObserveLiveObjectHighLevel(runtime, direction, payload, payload_length);
  }
  if (party_packet) {
    ObservePartyHighLevel(runtime, direction, payload, payload_length);
  }
  if (quickbar) {
    ObserveQuickbarHighLevel(runtime, direction, payload, payload_length);
  }
  return true;
}

void ObserveGameplayPacket(BridgeRuntime* runtime, const wchar_t* direction, const unsigned char* packet, size_t length) {
  if (runtime == nullptr || packet == nullptr || length == 0 || packet[0] != 'M') {
    return;
  }

  ++runtime->gameplay_packet_count;
  ObserveGameplayWrapper(runtime, direction, packet, length);
  GameplayWrapperView view;
  if (!TryParseGameplayWrapper(packet, length, &view) || !view.has_payload) {
    if (runtime->gameplay_packet_count <= 40 || runtime->options.packet_dump) {
      LogFormat(
          L"%s gameplay packet observed without payload window: length=%zu prefix=%s",
          direction != nullptr ? direction : L"<unknown>",
          length,
          PacketPrefix(packet, length).c_str());
    }
    return;
  }

  const unsigned char* payload = packet + kLegacyGameplayPayloadOffset;
  const size_t payload_length = view.payload_length;
  ++runtime->gameplay_payload_observed_count;
  if (ObserveDirectGameplayHeader(runtime, direction, payload, payload_length)) {
    return;
  }
  if (ObserveCnwHighGameplayHeader(runtime, direction, payload, payload_length)) {
    return;
  }

  if (runtime->gameplay_payload_observed_count <= 40 || runtime->options.packet_dump) {
    LogFormat(
        L"%s gameplay payload shape unknown #%llu: payload-offset=%zu payload-len=%zu payload=[%s]",
        direction != nullptr ? direction : L"<unknown>",
        static_cast<unsigned long long>(runtime->gameplay_payload_observed_count),
        kLegacyGameplayPayloadOffset,
        payload_length,
        FormatLimitedBytes(payload, payload_length, 48).c_str());
  }
}

bool IsDeviceAdvertisePropertyPayload(const unsigned char* payload, size_t payload_length) {
  return payload != nullptr &&
      payload_length >= 3 &&
      IsHighLevelGameplayEnvelope(payload[0]) &&
      payload[1] == 0x36 &&
      payload[2] == 0x01;
}

std::wstring FormatDeviceAdvertisePropertyPayloadSummary(const unsigned char* payload, size_t payload_length) {
  if (!IsDeviceAdvertisePropertyPayload(payload, payload_length)) {
    return L"<not-device-advertise>";
  }

  uint32_t declared = 0;
  const bool declared_known = payload_length >= 7;
  if (declared_known) {
    declared = ReadU32Le(payload + 3);
  }

  std::string property_name;
  bool has_property_name = false;
  bool has_flag = false;
  uint32_t flag = 0;
  bool has_value = false;
  uint32_t value = 0;
  size_t cursor = 7;
  if (payload_length >= cursor + 4) {
    const uint32_t name_length = ReadU32Le(payload + cursor);
    cursor += 4;
    constexpr uint32_t kMaxDevicePropertyNameBytes = 256;
    if (name_length <= kMaxDevicePropertyNameBytes && name_length <= payload_length - cursor) {
      property_name.assign(
          reinterpret_cast<const char*>(payload + cursor),
          reinterpret_cast<const char*>(payload + cursor + name_length));
      cursor += name_length;
      has_property_name = true;
      if (payload_length >= cursor + 4) {
        flag = ReadU32Le(payload + cursor);
        cursor += 4;
        has_flag = true;
        if (flag == 1 && payload_length >= cursor + 4) {
          value = ReadU32Le(payload + cursor);
          has_value = true;
        }
      }
    }
  }

  wchar_t buffer[512]{};
  swprintf_s(
      buffer,
      L"declared=%s%u property='%s' has_flag=%d flag=%u has_value=%d value=%u payload_len=%zu",
      declared_known ? L"" : L"unknown/",
      declared,
      has_property_name ? AsciiPreviewToWide(property_name, 80).c_str() : L"<unparsed>",
      has_flag ? 1 : 0,
      flag,
      has_value ? 1 : 0,
      value,
      payload_length);
  return buffer;
}

bool ConsumeClientDevicePropertyIfPossible(BridgeRuntime* runtime, std::vector<unsigned char>* packet) {
  if (runtime == nullptr || packet == nullptr || !runtime->options.consume_client_device_properties ||
      packet->empty()) {
    return false;
  }

  if (packet->front() != 'M') {
    if (!IsDeviceAdvertisePropertyPayload(packet->data(), packet->size())) {
      return false;
    }
    ++runtime->client_device_property_observed_count;
    ++runtime->client_device_property_skipped_count;
    ++runtime->dropped_unsupported_client_count;
    ++runtime->unsupported_transform_count;
    LogFormat(
        L"client direct Device_AdvertiseProperty payload dropped: %s unsupported-drops=%llu prefix=%s",
        FormatDeviceAdvertisePropertyPayloadSummary(packet->data(), packet->size()).c_str(),
        static_cast<unsigned long long>(runtime->dropped_unsupported_client_count),
        PacketPrefix(packet->data(), packet->size()).c_str());
    return true;
  }

  GameplayPayloadWindow window;
  if (!ExtractGameplayPayloadWindow(*packet, &window)) {
    return false;
  }
  const unsigned char* payload = window.payload.data();
  const size_t payload_length = window.payload.size();
  if (!IsDeviceAdvertisePropertyPayload(payload, payload_length)) {
    return false;
  }

  ++runtime->client_device_property_observed_count;
  if (window.view.uses_extended_packet_length) {
    ++runtime->client_device_property_skipped_count;
    LogFormat(
        L"client Device_AdvertiseProperty consume skipped: extended packet length not supported seq=%u %s prefix=%s",
        window.view.sequence,
        FormatDeviceAdvertisePropertyPayloadSummary(payload, payload_length).c_str(),
        PacketPrefix(packet->data(), packet->size()).c_str());
    return false;
  }

  const uint16_t old_crc = ReadU16Be(packet->data() + 1);
  const size_t old_payload_length = payload_length;
  const std::wstring summary = FormatDeviceAdvertisePropertyPayloadSummary(payload, payload_length);
  std::vector<unsigned char> empty_payload;
  bool packetized_length_updated = false;
  bool crc_updated = false;
  if (!ReplaceGameplayPayloadWindow(
          packet,
          window,
          empty_payload,
          &packetized_length_updated,
          &crc_updated)) {
    return false;
  }
  const uint16_t new_crc = packet->size() >= 3 ? ReadU16Be(packet->data() + 1) : 0;
  ++runtime->client_device_property_consumed_count;
  LogFormat(
      L"client Device_AdvertiseProperty consumed #%llu: seq=%u ack=%u pkt_seq=%u old_payload=%zu new_payload=0 trailing_preserved=%zu pkt_len_updated=%d crc_updated=%d crc=0x%04X->0x%04X %s",
      static_cast<unsigned long long>(runtime->client_device_property_consumed_count),
      window.view.sequence,
      window.view.ack_sequence,
      window.view.packetized_sequence,
      old_payload_length,
      window.trailing.size(),
      packetized_length_updated ? 1 : 0,
      crc_updated ? 1 : 0,
      old_crc,
      new_crc,
      summary.c_str());
  return false;
}

bool TryDecodeClientGuiInventoryStatusPayload(
    const std::vector<unsigned char>& payload,
    uint32_t* object_id,
    bool* open_known,
    bool* open) {
  if (object_id != nullptr) {
    *object_id = 0;
  }
  if (open_known != nullptr) {
    *open_known = false;
  }
  if (open != nullptr) {
    *open = false;
  }

  // EE writes this as a CNW high-priority GuiInventory_Status payload:
  // [70 0D 01] [declared=0x0B] [OBJECTID] [one BOOL fragment byte].
  constexpr size_t kExpectedPayloadBytes = 12;
  constexpr size_t kDeclaredOffset = 3;
  constexpr size_t kObjectIdOffset = 7;
  constexpr size_t kFragmentOffset = 11;
  if (payload.size() != kExpectedPayloadBytes ||
      payload[0] != 0x70 ||
      payload[1] != 0x0D ||
      payload[2] != 0x01 ||
      ReadU32Le(payload.data() + kDeclaredOffset) != 0x0Bu) {
    return false;
  }

  if (object_id != nullptr) {
    *object_id = ReadU32Le(payload.data() + kObjectIdOffset);
  }

  std::vector<unsigned char> fragment_bytes(
      payload.begin() + static_cast<std::ptrdiff_t>(kFragmentOffset),
      payload.end());
  std::vector<unsigned char> bits;
  if (DecodeCnwFragmentBits(fragment_bytes, &bits) && bits.size() >= 4) {
    if (open_known != nullptr) {
      *open_known = true;
    }
    if (open != nullptr) {
      *open = bits[3] != 0;
    }
  }
  return true;
}

bool RewriteClientGuiInventoryStatusSelfIdIfPossible(
    BridgeRuntime* runtime,
    std::vector<unsigned char>* packet) {
  if (runtime == nullptr || packet == nullptr ||
      !runtime->options.rewrite_client_gui_inventory_self_id ||
      packet->empty() || packet->front() != 'M') {
    return false;
  }

  GameplayPayloadWindow window;
  if (!ExtractGameplayPayloadWindow(*packet, &window)) {
    return false;
  }

  uint32_t object_id = 0;
  bool open_known = false;
  bool open = false;
  if (!TryDecodeClientGuiInventoryStatusPayload(window.payload, &object_id, &open_known, &open)) {
    return false;
  }

  ++runtime->client_gui_inventory_status_observed_count;
  if (object_id != kEeSelfObjectId) {
    if (runtime->options.packet_dump) {
      LogFormat(
          L"client GuiInventory_Status observed without self-id rewrite #%llu: seq=%u ack=%u object=0x%08X open=%s%s payload=[%s]",
          static_cast<unsigned long long>(runtime->client_gui_inventory_status_observed_count),
          window.view.sequence,
          window.view.ack_sequence,
          object_id,
          open_known ? L"" : L"unknown/",
          open_known ? (open ? L"1" : L"0") : L"0",
          FormatLimitedBytes(window.payload.data(), window.payload.size(), 48).c_str());
    }
    return false;
  }

  std::vector<unsigned char> rewritten_payload = window.payload;
  WriteU32Le(rewritten_payload.data() + 7, kLegacyInvalidObjectId);

  const uint16_t old_crc = ReadU16Be(packet->data() + 1);
  bool packetized_length_updated = false;
  bool crc_updated = false;
  if (!ReplaceGameplayPayloadWindow(
          packet,
          window,
          rewritten_payload,
          &packetized_length_updated,
          &crc_updated)) {
    ++runtime->client_gui_inventory_status_rewrite_skipped_count;
    LogFormat(
        L"client GuiInventory_Status self-id rewrite skipped: payload replacement failed seq=%u ack=%u old_object=0x%08X",
        window.view.sequence,
        window.view.ack_sequence,
        object_id);
    return false;
  }

  const uint16_t new_crc = packet->size() >= 3 ? ReadU16Be(packet->data() + 1) : 0;
  ++runtime->client_gui_inventory_status_self_rewrite_count;
  LogFormat(
      L"client GuiInventory_Status self-id rewritten #%llu/%llu: seq=%u ack=%u object=0x%08X->0x%08X open=%s%s payload=%zu trailing_preserved=%zu pkt_len_updated=%d crc_updated=%d crc=0x%04X->0x%04X",
      static_cast<unsigned long long>(runtime->client_gui_inventory_status_self_rewrite_count),
      static_cast<unsigned long long>(runtime->client_gui_inventory_status_observed_count),
      window.view.sequence,
      window.view.ack_sequence,
      object_id,
      kLegacyInvalidObjectId,
      open_known ? L"" : L"unknown/",
      open_known ? (open ? L"1" : L"0") : L"0",
      window.payload.size(),
      window.trailing.size(),
      packetized_length_updated ? 1 : 0,
      crc_updated ? 1 : 0,
      old_crc,
      new_crc);
  return true;
}

bool RewriteClientInputSelfObjectIdsIfPossible(
    BridgeRuntime* runtime,
    std::vector<unsigned char>* packet) {
  if (runtime == nullptr || packet == nullptr ||
      !runtime->options.rewrite_client_input_self_object_ids ||
      packet->empty() || packet->front() != 'M') {
    return false;
  }

  GameplayPayloadWindow window;
  if (!ExtractGameplayPayloadWindow(*packet, &window)) {
    return false;
  }

  const std::vector<unsigned char>& payload = window.payload;
  if (payload.size() < 11 ||
      payload[0] != 0x70 ||
      payload[1] != 0x06 ||
      payload.size() > kMaxReasonableReassembledGameplayPayload) {
    return false;
  }

  const unsigned int minor = payload[2];
  const uint32_t declared = ReadU32Le(payload.data() + 3);
  if (declared < 7 || declared > payload.size()) {
    return false;
  }

  const wchar_t* message_name = KnownMajorMinorName(0x06, minor);
  const wchar_t* field_name = L"";
  size_t object_offset = SIZE_MAX;
  bool recognized_shape = false;

  if (minor == 0x05) {
    if (declared != 11 || payload.size() < declared) {
      return false;
    }
    object_offset = 7;
    field_name = L"examine-object";
    recognized_shape = true;
  } else if (minor == 0x09) {
    constexpr size_t kUseItemBaseReadBytes = 12;
    if (declared < kUseItemBaseReadBytes || payload.size() <= declared) {
      return false;
    }

    std::vector<unsigned char> fragment_bytes(
        payload.begin() + static_cast<std::ptrdiff_t>(declared),
        payload.end());
    std::vector<unsigned char> bits;
    if (!DecodeCnwFragmentBits(fragment_bytes, &bits) || bits.size() < 5) {
      return false;
    }

    size_t bit_cursor = 3;
    size_t read_cursor = kUseItemBaseReadBytes;
    const bool has_optional_byte = bits[bit_cursor++] != 0;
    if (has_optional_byte) {
      if (read_cursor >= declared) {
        return false;
      }
      ++read_cursor;
    }

    if (bit_cursor >= bits.size()) {
      return false;
    }
    const bool has_target_object = bits[bit_cursor++] != 0;
    if (!has_target_object) {
      if (runtime->options.packet_dump) {
        LogFormat(
            L"client Input_UseItem target omitted; server default legacy target is 0x%08X seq=%u ack=%u declared=%u payload=%zu bits=%zu raw=[%s]",
            kLegacyInvalidObjectId,
            window.view.sequence,
            window.view.ack_sequence,
            declared,
            payload.size(),
            bits.size(),
            FormatLimitedBytes(payload.data(), payload.size(), 64).c_str());
      }
      return false;
    }

    if (read_cursor > declared ||
        static_cast<size_t>(declared) - read_cursor < sizeof(uint32_t)) {
      return false;
    }
    object_offset = read_cursor;
    field_name = L"use-item-target";
    read_cursor += sizeof(uint32_t);

    if (bit_cursor >= bits.size()) {
      return false;
    }
    const bool has_position = bits[bit_cursor++] != 0;
    if (has_position) {
      if (read_cursor > declared ||
          static_cast<size_t>(declared) - read_cursor < sizeof(uint32_t) * 3) {
        return false;
      }
      read_cursor += sizeof(uint32_t) * 3;
    }

    if (read_cursor != declared) {
      ++runtime->client_input_self_object_rewrite_skipped_count;
      if (runtime->options.packet_dump) {
        LogFormat(
            L"client Input_UseItem self-id rewrite skipped: read-order cursor mismatch seq=%u ack=%u declared=%u cursor=%zu optional_byte=%d target=%d position=%d bits=%zu payload=[%s]",
            window.view.sequence,
            window.view.ack_sequence,
            declared,
            read_cursor,
            has_optional_byte ? 1 : 0,
            has_target_object ? 1 : 0,
            has_position ? 1 : 0,
            bits.size(),
            FormatLimitedBytes(payload.data(), payload.size(), 96).c_str());
      }
      return false;
    }
    recognized_shape = true;
  } else {
    return false;
  }

  if (!recognized_shape ||
      object_offset > payload.size() ||
      payload.size() - object_offset < sizeof(uint32_t)) {
    return false;
  }

  const uint32_t object_id = ReadU32Le(payload.data() + object_offset);
  ++runtime->client_input_self_object_observed_count;
  if (object_id != kEeSelfObjectId) {
    if (runtime->options.packet_dump) {
      LogFormat(
          L"client %s observed without self-id rewrite #%llu: seq=%u ack=%u field=%s object=0x%08X declared=%u payload=%zu raw=[%s]",
          message_name,
          static_cast<unsigned long long>(runtime->client_input_self_object_observed_count),
          window.view.sequence,
          window.view.ack_sequence,
          field_name,
          object_id,
          declared,
          payload.size(),
          FormatLimitedBytes(payload.data(), payload.size(), 96).c_str());
    }
    return false;
  }

  std::vector<unsigned char> rewritten_payload = payload;
  WriteU32Le(rewritten_payload.data() + object_offset, kLegacyInvalidObjectId);

  const uint16_t old_crc = packet->size() >= 3 ? ReadU16Be(packet->data() + 1) : 0;
  bool packetized_length_updated = false;
  bool crc_updated = false;
  if (!ReplaceGameplayPayloadWindow(
          packet,
          window,
          rewritten_payload,
          &packetized_length_updated,
          &crc_updated)) {
    ++runtime->client_input_self_object_rewrite_skipped_count;
    LogFormat(
        L"client %s self-id rewrite skipped: payload replacement failed seq=%u ack=%u field=%s object=0x%08X offset=%zu",
        message_name,
        window.view.sequence,
        window.view.ack_sequence,
        field_name,
        object_id,
        object_offset);
    return false;
  }

  const uint16_t new_crc = packet->size() >= 3 ? ReadU16Be(packet->data() + 1) : 0;
  ++runtime->client_input_self_object_rewrite_count;
  LogFormat(
      L"client %s self-id rewritten #%llu/%llu: seq=%u ack=%u field=%s offset=%zu object=0x%08X->0x%08X declared=%u payload=%zu trailing_preserved=%zu pkt_len_updated=%d crc_updated=%d crc=0x%04X->0x%04X",
      message_name,
      static_cast<unsigned long long>(runtime->client_input_self_object_rewrite_count),
      static_cast<unsigned long long>(runtime->client_input_self_object_observed_count),
      window.view.sequence,
      window.view.ack_sequence,
      field_name,
      object_offset,
      object_id,
      kLegacyInvalidObjectId,
      declared,
      payload.size(),
      window.trailing.size(),
      packetized_length_updated ? 1 : 0,
      crc_updated ? 1 : 0,
      old_crc,
      new_crc);
  return true;
}

void ObserveClientGuiEventNotifyIfPossible(
    BridgeRuntime* runtime,
    const std::vector<unsigned char>& packet) {
  if (runtime == nullptr || packet.empty() || packet.front() != 'M') {
    return;
  }

  GameplayPayloadWindow window;
  if (!ExtractGameplayPayloadWindow(packet, &window)) {
    return;
  }
  const std::vector<unsigned char>& payload = window.payload;
  if (payload.size() < 15 ||
      payload[0] != 0x70 ||
      payload[1] != 0x35 ||
      payload[2] != 0x01) {
    return;
  }

  const uint32_t declared = ReadU32Le(payload.data() + 3);
  if (declared < 15 || declared > payload.size()) {
    return;
  }

  const uint16_t event_a = ReadU16Le(payload.data() + 7);
  const uint16_t event_b = ReadU16Le(payload.data() + 9);
  const uint32_t object_id = ReadU32Le(payload.data() + 11);
  const size_t fragment_bytes = payload.size() - declared;

  std::wstring vector_summary = L"<absent>";
  if (declared >= 27) {
    const uint32_t raw_x = ReadU32Le(payload.data() + 15);
    const uint32_t raw_y = ReadU32Le(payload.data() + 19);
    const uint32_t raw_z = ReadU32Le(payload.data() + 23);
    float x = 0.0f;
    float y = 0.0f;
    float z = 0.0f;
    std::memcpy(&x, &raw_x, sizeof(x));
    std::memcpy(&y, &raw_y, sizeof(y));
    std::memcpy(&z, &raw_z, sizeof(z));
    wchar_t buffer[160]{};
    swprintf_s(
        buffer,
        L"x=%g y=%g z=%g raw=%08X/%08X/%08X",
        static_cast<double>(x),
        static_cast<double>(y),
        static_cast<double>(z),
        raw_x,
        raw_y,
        raw_z);
    vector_summary = buffer;
  }

  ++runtime->client_gui_event_notify_observed_count;
  if (runtime->client_gui_event_notify_observed_count <= 80 ||
      runtime->options.packet_dump) {
    LogFormat(
        L"client GuiEvent_Notify observed #%llu: seq=%u ack=%u event_a=0x%04X/%u event_b=0x%04X/%u object=0x%08X declared=%u payload=%zu fragments=%zu vector=%s raw=[%s]",
        static_cast<unsigned long long>(
            runtime->client_gui_event_notify_observed_count),
        window.view.sequence,
        window.view.ack_sequence,
        event_a,
        event_a,
        event_b,
        event_b,
        object_id,
        declared,
        payload.size(),
        fragment_bytes,
        vector_summary.c_str(),
        FormatLimitedBytes(payload.data(), payload.size(), 96).c_str());
  }
}

void ObserveClientInputUseObjectIfPossible(
    BridgeRuntime* runtime,
    const std::vector<unsigned char>& packet) {
  if (runtime == nullptr || packet.empty() || packet.front() != 'M') {
    return;
  }

  GameplayPayloadWindow window;
  if (!ExtractGameplayPayloadWindow(packet, &window)) {
    return;
  }
  const std::vector<unsigned char>& payload = window.payload;
  if (payload.size() < 11 ||
      payload[0] != 0x70 ||
      payload[1] != 0x06 ||
      payload[2] != 0x0B) {
    return;
  }

  const uint32_t declared = ReadU32Le(payload.data() + 3);
  if (declared < 11 || declared > payload.size()) {
    return;
  }

  const uint32_t object_id = ReadU32Le(payload.data() + 7);
  std::vector<unsigned char> fragment_bytes(
      payload.begin() + static_cast<std::ptrdiff_t>(declared),
      payload.end());
  std::vector<unsigned char> bits;
  const bool bits_ok = DecodeCnwFragmentBits(fragment_bytes, &bits);
  const bool has_bool_a = bits_ok && bits.size() > 3;
  const bool has_bool_b = bits_ok && bits.size() > 4;
  const int bool_a = has_bool_a ? (bits[3] != 0 ? 1 : 0) : -1;
  const int bool_b = has_bool_b ? (bits[4] != 0 ? 1 : 0) : -1;

  ++runtime->client_input_use_object_observed_count;
  if (runtime->client_input_use_object_observed_count <= 80 ||
      runtime->options.packet_dump) {
    LogFormat(
        L"client Input_UseObject observed #%llu: seq=%u ack=%u object=0x%08X declared=%u payload=%zu fragments=%zu bits_ok=%d bool_a=%d bool_b=%d bit_slice=%s raw=[%s]",
        static_cast<unsigned long long>(
            runtime->client_input_use_object_observed_count),
        window.view.sequence,
        window.view.ack_sequence,
        object_id,
        declared,
        payload.size(),
        fragment_bytes.size(),
        bits_ok ? 1 : 0,
        bool_a,
        bool_b,
        bits_ok ? FormatCnwBitSlice(bits, 0, std::min<size_t>(bits.size(), 24)).c_str()
                : L"<decode-failed>",
        FormatLimitedBytes(payload.data(), payload.size(), 96).c_str());
  }
}

bool TryResolveLiveObjectPayloadDeclaredLength(
    const std::vector<unsigned char>& payload,
    uint32_t* declared,
    uint32_t* wire_declared) {
  if (declared != nullptr) {
    *declared = 0;
  }
  if (wire_declared != nullptr) {
    *wire_declared = 0;
  }
  if (declared == nullptr || payload.size() < 7 ||
      !IsHighLevelGameplayEnvelope(payload[0]) || payload[1] != 5 || payload[2] != 1 ||
      payload.size() > kMaxReasonableReassembledGameplayPayload) {
    return false;
  }

  const uint32_t value = ReadU32Le(payload.data() + 3);
  if (wire_declared != nullptr) {
    *wire_declared = value;
  }
  if (value == 0) {
    *declared = static_cast<uint32_t>(payload.size());
    return true;
  }
  if (value < 7 || value > payload.size() ||
      value > kMaxReasonableReassembledGameplayPayload) {
    return false;
  }
  *declared = value;
  return true;
}

bool LooksLikeSalvageableLegacyLiveObjectRecordAt(
    const std::vector<unsigned char>& bytes,
    size_t record_offset,
    size_t* record_end_out) {
  if (record_end_out != nullptr) {
    *record_end_out = bytes.size();
  }
  if (!LooksLikeLegacyLiveObjectSubMessageBoundaryBytes(bytes, record_offset) ||
      record_offset + 6 > bytes.size()) {
    return false;
  }

  size_t record_end = FindNextLegacyLiveObjectSubMessageBoundaryAfter(bytes, record_offset);
  if (record_end > bytes.size()) {
    record_end = bytes.size();
  }
  if (record_end <= record_offset) {
    return false;
  }

  const unsigned char opcode = bytes[record_offset];
  const unsigned char object_type = bytes[record_offset + 1];
  bool plausible = false;
  if (opcode == 'A' && object_type == 9) {
    size_t name_offset = 0;
    size_t tail_offset = 0;
    bool short_locstring = false;
    plausible = TryFindPlaceableAddNameForAddRecordRewrite(
        bytes,
        record_offset,
        record_end,
        &name_offset,
        &tail_offset,
        &short_locstring);
  } else if (opcode == 'A' && object_type == 10) {
    size_t name_offset = 0;
    bool short_locstring = false;
    plausible = TryFindDoorAddNameForAddRecordRewrite(
        bytes,
        record_offset,
        record_end,
        &name_offset,
        &short_locstring) ||
        TryFindLegacyCompactDoorAddEmptyName(
            bytes,
            record_offset,
            record_end,
            nullptr,
            nullptr,
            nullptr);
  } else if (opcode == 'A' && object_type == 7) {
    uint8_t primary_flag = 0;
    uint8_t vertex_count = 0;
    plausible = TryReadLegacyTriggerAddShape(
        bytes,
        record_offset,
        record_end,
        &primary_flag,
        &vertex_count);
  } else if (opcode == 'U' &&
      (object_type == 5 || object_type == 7 || object_type == 9 || object_type == 10) &&
      record_offset + 10 <= record_end) {
    uint32_t raw_mask = 0;
    plausible = TryReadU32LeFromBytes(bytes, record_offset + 6, &raw_mask) &&
        raw_mask != 0 &&
        raw_mask != 0xFFFFFFFFu;
  } else if (opcode == 'D' &&
      (object_type == 5 || object_type == 6 || object_type == 7 ||
       object_type == 9 || object_type == 10)) {
    plausible = record_end - record_offset <= 16;
  } else if (opcode == 'I') {
    plausible = true;
  }

  if (!plausible) {
    return false;
  }
  if (record_end_out != nullptr) {
    *record_end_out = record_end;
  }
  return true;
}

bool FindSalvageableLegacyLiveObjectBoundaryAfterPrefixedFragments(
    const std::vector<unsigned char>& payload,
    size_t* boundary_offset,
    size_t* record_end) {
  if (boundary_offset != nullptr) {
    *boundary_offset = 0;
  }
  if (record_end != nullptr) {
    *record_end = 0;
  }
  if (payload.size() < 16 ||
      payload.size() > kMaxReasonableReassembledGameplayPayload ||
      !IsHighLevelGameplayEnvelope(payload[0]) ||
      payload[1] != 5 ||
      payload[2] != 1) {
    return false;
  }

  constexpr size_t kLegacyPrefixedFragmentPayloadOffset = 7;
  constexpr size_t kMaxLeadInScanBytes = 2048;
  const size_t scan_end = std::min(
      payload.size(),
      kLegacyPrefixedFragmentPayloadOffset + kMaxLeadInScanBytes);
  for (size_t candidate = kLegacyPrefixedFragmentPayloadOffset;
       candidate + 1 < scan_end;
       ++candidate) {
    size_t candidate_record_end = 0;
    if (!LooksLikeSalvageableLegacyLiveObjectRecordAt(
            payload,
            candidate,
            &candidate_record_end)) {
      continue;
    }
    if (boundary_offset != nullptr) {
      *boundary_offset = candidate;
    }
    if (record_end != nullptr) {
      *record_end = candidate_record_end;
    }
    return true;
  }
  return false;
}

bool ShouldRewriteZlibStreamLiveObjectPayload(const std::vector<unsigned char>& payload) {
  if (payload.size() < 8 ||
      payload.size() > kMaxReasonableReassembledGameplayPayload ||
      !IsHighLevelGameplayEnvelope(payload[0]) ||
      payload[1] != 5 ||
      payload[2] != 1) {
    return false;
  }

  const uint32_t wire_declared = ReadU32Le(payload.data() + 3);
  if (wire_declared >= 7 && wire_declared <= payload.size()) {
    return true;
  }

  // Diamond sometimes emits live-object zlib stream chunks as P 5/1, then
  // four legacy fragment bytes, then the live-object read buffer. Those look
  // invalid to EE until we move the fragment bytes to the CNW tail.
  if (LooksLikeLegacyLiveObjectSubMessageBoundaryBytes(payload, 7)) {
    return true;
  }

  // Some stream chunks begin with the same invalid P 5/1 + fragment prefix,
  // but the read buffer starts in the middle of a legacy record and only later
  // reaches a valid object boundary. Promote those so the normalizer can drop
  // the partial lead-in instead of emitting a bogus declared length to EE.
  return FindSalvageableLegacyLiveObjectBoundaryAfterPrefixedFragments(
      payload,
      nullptr,
      nullptr);
}

struct LiveObjectShortDeclaredExpansionCandidate {
  uint32_t new_declared = 0;
  size_t fragment_bytes = 0;
  size_t fragment_bits = 0;
  size_t estimated_bit_cursor = 0;
  uint32_t records = 0;
  uint32_t records_after_old_declared = 0;
  uint32_t known_bit_records = 0;
  uint32_t unknown_bit_records = 0;
  bool cuts_old_record = false;
  size_t score = SIZE_MAX;
};

bool EvaluateLiveObjectShortDeclaredExpansionCandidate(
    const std::vector<unsigned char>& payload,
    uint32_t old_declared,
    size_t fragment_tail_bytes,
    LiveObjectShortDeclaredExpansionCandidate* candidate) {
  if (candidate != nullptr) {
    *candidate = LiveObjectShortDeclaredExpansionCandidate{};
  }
  if (payload.size() < 16 ||
      old_declared < 7 ||
      old_declared >= payload.size() ||
      fragment_tail_bytes < 3 ||
      fragment_tail_bytes >= payload.size() - 7) {
    return false;
  }

  const size_t new_declared_size = payload.size() - fragment_tail_bytes;
  if (new_declared_size <= old_declared ||
      new_declared_size > kMaxReasonableReassembledGameplayPayload) {
    return false;
  }

  std::vector<unsigned char> fragment_bytes(
      payload.begin() + static_cast<std::ptrdiff_t>(new_declared_size),
      payload.end());
  if (fragment_bytes.size() >= 3 &&
      fragment_bytes[0] == 'W' &&
      fragment_bytes[1] <= 0x0F &&
      fragment_bytes[2] == 0x0E) {
    return false;
  }
  if (!fragment_bytes.empty() &&
      fragment_bytes.front() == 0x0E &&
      new_declared_size >= 2 &&
      payload[new_declared_size - 2] == 'W' &&
      payload[new_declared_size - 1] <= 0x0F) {
    return false;
  }
  if (fragment_bytes.size() >= 2 &&
      new_declared_size >= 1 &&
      payload[new_declared_size - 1] == 'W' &&
      fragment_bytes[0] <= 0x0F &&
      fragment_bytes[1] == 0x0E) {
    return false;
  }
  for (size_t probe = 0;
       probe + 2 < fragment_bytes.size() && probe < 8;
       ++probe) {
    if (fragment_bytes[probe] == 'W' &&
        fragment_bytes[probe + 1] <= 0x0F &&
        fragment_bytes[probe + 2] == 0x0E) {
      return false;
    }
  }
  std::vector<unsigned char> fragment_bits;
  if (!DecodeCnwFragmentBits(fragment_bytes, &fragment_bits) ||
      fragment_bits.size() < 3) {
    return false;
  }

  std::vector<unsigned char> live_bytes(
      payload.begin() + 7,
      payload.begin() + static_cast<std::ptrdiff_t>(new_declared_size));
  if (!LooksLikeLegacyLiveObjectSubMessageBoundaryBytes(live_bytes, 0)) {
    return false;
  }

  const size_t old_live_end = static_cast<size_t>(old_declared - 7);
  size_t offset = 0;
  size_t bit_cursor = 3;
  uint32_t records = 0;
  uint32_t records_after_old_declared = 0;
  uint32_t known_bit_records = 0;
  uint32_t unknown_bit_records = 0;
  bool cuts_old_record = false;
  while (offset + 1 < live_bytes.size()) {
    if (!LooksLikeLegacyLiveObjectSubMessageBoundaryBytes(live_bytes, offset)) {
      // A candidate that only works by scanning through arbitrary bytes is too
      // loose for an envelope repair. Once a record parser has moved us to a
      // boundary, the next byte should be another boundary or the true end.
      return false;
    }

    size_t record_end = FindNextLegacyLiveObjectSubMessageBoundaryAfter(live_bytes, offset);
    if (record_end > live_bytes.size()) {
      record_end = live_bytes.size();
    }
    if (record_end <= offset) {
      return false;
    }

    ++records;
    if (offset >= old_live_end) {
      ++records_after_old_declared;
    } else if (record_end > old_live_end) {
      cuts_old_record = true;
    }

    bool bit_cursor_known = false;
    const unsigned char opcode = live_bytes[offset];
    if (opcode == 'I') {
      size_t inventory_fragment_bits = 0;
      if (TryGetLegacyLiveInventoryFragmentBitCount(
              live_bytes,
              offset,
              record_end,
              &inventory_fragment_bits)) {
        bit_cursor += inventory_fragment_bits;
        bit_cursor_known = true;
      }
    } else if (opcode == 'G' &&
        offset + 3 <= record_end &&
        (live_bytes[offset + 1] == 'I' || live_bytes[offset + 1] == 'i' ||
         live_bytes[offset + 1] == 'R' || live_bytes[offset + 1] == 'r') &&
        live_bytes[offset + 2] == 'A') {
      size_t trial_bit_cursor = bit_cursor;
      LegacyGuiInventoryAddShape shape;
      if (TryGetLegacyLiveGuiItemCreateRecordShape(
              live_bytes,
              offset,
              record_end,
              nullptr,
              &shape) &&
          shape.record_end == record_end &&
          AdvanceLegacyActiveItemPropertiesBitCursorForEe(
              live_bytes,
              shape.active_offset,
              shape.record_end,
              shape.base_item_id,
              fragment_bits,
              &trial_bit_cursor,
              false)) {
        bit_cursor = trial_bit_cursor;
        bit_cursor_known = true;
      }
    } else if (AdvanceLegacyLiveDeleteRecordBitCursorForEe(
            live_bytes,
            offset,
            record_end,
            fragment_bits,
            &bit_cursor)) {
      bit_cursor_known = true;
    } else if (IsLegacyLiveReadBufferOnlySubMessage(live_bytes, offset, record_end)) {
      bit_cursor_known = true;
    } else {
      size_t trial_bit_cursor = bit_cursor;
      std::wstring skip_reason;
      if (opcode == 'A' &&
          (offset + 1 < live_bytes.size()) &&
          (live_bytes[offset + 1] == 9 || live_bytes[offset + 1] == 10) &&
          ShouldSkipLegacyLiveShortAddRecordBytes(
              nullptr,
              live_bytes,
              offset,
              record_end,
              &skip_reason) &&
          AdvanceLegacyLiveShortAddRecordBitCursor(
              live_bytes,
              fragment_bits,
              offset,
              record_end,
              &trial_bit_cursor)) {
        bit_cursor = trial_bit_cursor;
        bit_cursor_known = true;
      } else if (AdvanceKnownLegacyLiveCreatureBitCursor(
              live_bytes,
              offset,
              record_end,
              fragment_bits,
              &trial_bit_cursor)) {
        bit_cursor = trial_bit_cursor;
        bit_cursor_known = true;
      } else {
        trial_bit_cursor = bit_cursor;
        if (AdvanceLegacyLiveAddRecordBitCursor(
                live_bytes,
                fragment_bits,
                offset,
                record_end,
                &trial_bit_cursor)) {
          bit_cursor = trial_bit_cursor;
          bit_cursor_known = true;
        } else {
          trial_bit_cursor = bit_cursor;
          if (AdvanceRewrittenLiveUpdateRecordBitCursor(
                  live_bytes,
                  offset,
                  record_end,
                  &trial_bit_cursor)) {
            bit_cursor = trial_bit_cursor;
            bit_cursor_known = true;
          }
        }
      }
    }

    if (bit_cursor_known) {
      ++known_bit_records;
    } else {
      ++unknown_bit_records;
    }
    if (bit_cursor > fragment_bits.size() + 128) {
      return false;
    }

    offset = record_end;
  }

  if (offset != live_bytes.size() ||
      records < 3 ||
      (!cuts_old_record && records_after_old_declared == 0) ||
      (unknown_bit_records == 0 && bit_cursor > fragment_bits.size())) {
    return false;
  }

  LiveObjectShortDeclaredExpansionCandidate local;
  local.new_declared = static_cast<uint32_t>(new_declared_size);
  local.fragment_bytes = fragment_tail_bytes;
  local.fragment_bits = fragment_bits.size();
  local.estimated_bit_cursor = bit_cursor;
  local.records = records;
  local.records_after_old_declared = records_after_old_declared;
  local.known_bit_records = known_bit_records;
  local.unknown_bit_records = unknown_bit_records;
  local.cuts_old_record = cuts_old_record;
  const size_t unused_bits =
      fragment_bits.size() > bit_cursor ? fragment_bits.size() - bit_cursor : 0;
  const size_t short_tail_penalty =
      fragment_tail_bytes < 6 ? (6 - fragment_tail_bytes) * 64 : 0;
  const size_t low_fragment_header_penalty =
      !fragment_bytes.empty() && fragment_bytes.front() == 0x0E
          ? 1000000ull
          : (!fragment_bytes.empty() && fragment_bytes.front() < 0x10 ? 50000ull : 0ull);
  local.score =
      static_cast<size_t>(unknown_bit_records) * 100000ull +
      low_fragment_header_penalty +
      unused_bits * 16 +
      short_tail_penalty +
      fragment_tail_bytes;
  if (candidate != nullptr) {
    *candidate = local;
  }
  return true;
}

bool ExpandLegacyLiveObjectShortDeclaredPayloadIfNeeded(
    BridgeRuntime* runtime,
    std::vector<unsigned char>* payload,
    uint32_t old_wire_declared,
    const wchar_t* context) {
  if (runtime == nullptr || payload == nullptr ||
      old_wire_declared < 7 ||
      old_wire_declared >= payload->size() ||
      !LooksLikeLegacyLiveObjectSubMessageBoundaryBytes(*payload, 7)) {
    return false;
  }

  const size_t old_fragment_bytes = payload->size() - old_wire_declared;
  constexpr size_t kMinSuspiciousShortDeclaredTail = 128;
  if (old_fragment_bytes < kMinSuspiciousShortDeclaredTail) {
    return false;
  }

  // In the short-declared zlib stream shape, the apparent tiny tails can be a
  // false positive: EE still needs the legacy BOOL stream for creature
  // equipment/active-property reads. Most hook-era captures leave six or more
  // CNW fragment bytes, but live HG packets such as the Town Greeter A/P/U
  // bundle validate with a four-byte tail after promoting three apparent tail
  // bytes back into the read buffer. Keep the shorter candidate gated by the
  // full record/cursor simulation below instead of enforcing a fixed floor.
  constexpr size_t kMinCandidateFragmentTail = 4;
  constexpr size_t kMaxCandidateFragmentTail = 96;
  const size_t max_tail = std::min(
      kMaxCandidateFragmentTail,
      old_fragment_bytes - 1);
  LiveObjectShortDeclaredExpansionCandidate best;
  bool have_best = false;
  for (size_t tail = kMinCandidateFragmentTail; tail <= max_tail; ++tail) {
    LiveObjectShortDeclaredExpansionCandidate candidate;
    if (!EvaluateLiveObjectShortDeclaredExpansionCandidate(
            *payload,
            old_wire_declared,
            tail,
            &candidate)) {
      continue;
    }
    if (!have_best ||
        candidate.score < best.score ||
        (candidate.score == best.score &&
         candidate.records_after_old_declared > best.records_after_old_declared)) {
      best = candidate;
      have_best = true;
    }
  }

  if (!have_best || best.new_declared <= old_wire_declared) {
    return false;
  }

  WriteU32Le(payload->data() + 3, best.new_declared);
  const uint64_t observation = ++runtime->live_object_short_declared_expand_count;
  LogFormat(
      L"%s live-object short-declared layout expanded #%llu: declared=%u->%u payload=%zu fragments=%zu->%zu records=%u after_old=%u cuts_old=%d bit_cursor=%zu/%zu known_bits=%u unknown_bits=%u score=%zu old_tail=[%s] new_tail=[%s]",
      context != nullptr ? context : L"server->client",
      static_cast<unsigned long long>(observation),
      old_wire_declared,
      best.new_declared,
      payload->size(),
      old_fragment_bytes,
      best.fragment_bytes,
      best.records,
      best.records_after_old_declared,
      best.cuts_old_record ? 1 : 0,
      best.estimated_bit_cursor,
      best.fragment_bits,
      best.known_bit_records,
      best.unknown_bit_records,
      best.score,
      FormatLimitedBytes(
          payload->data() + old_wire_declared,
          std::min<size_t>(old_fragment_bytes, 48),
          48).c_str(),
      FormatLimitedBytes(
          payload->data() + best.new_declared,
          std::min<size_t>(best.fragment_bytes, 48),
          48).c_str());
  return true;
}

bool NormalizeLegacyLiveObjectPrefixedFragmentsPayloadIfNeeded(
    BridgeRuntime* runtime,
    std::vector<unsigned char>* payload,
    const wchar_t* context) {
  if (runtime == nullptr || payload == nullptr ||
      payload->size() < 8 ||
      !IsHighLevelGameplayEnvelope((*payload)[0]) ||
      (*payload)[1] != 5 ||
      (*payload)[2] != 1 ||
      payload->size() > kMaxReasonableReassembledGameplayPayload) {
    return false;
  }

  const uint32_t old_wire_declared = ReadU32Le(payload->data() + 3);
  if (old_wire_declared >= 7 && old_wire_declared <= payload->size()) {
    return ExpandLegacyLiveObjectShortDeclaredPayloadIfNeeded(
        runtime,
        payload,
        old_wire_declared,
        context);
  }
  if (old_wire_declared == 0) {
    return false;
  }

  constexpr size_t kLegacyPrefixedFragmentBytes = 4;
  constexpr size_t kLiveBytesOffsetAfterPrefixedFragments = 7;
  size_t live_bytes_offset = kLiveBytesOffsetAfterPrefixedFragments;
  size_t first_record_end = 0;
  bool salvaged_partial_leadin = false;

  // Some 1.69 live-object frames use P 5/1 followed by a small CNW fragment
  // byte prefix and then the read buffer. EE expects P 5/1, a declared
  // read-buffer end, the read buffer, and fragment bytes at the tail.
  if (!LooksLikeLegacyLiveObjectSubMessageBoundaryBytes(*payload, live_bytes_offset)) {
    if (!FindSalvageableLegacyLiveObjectBoundaryAfterPrefixedFragments(
            *payload,
            &live_bytes_offset,
            &first_record_end) ||
        live_bytes_offset <= kLiveBytesOffsetAfterPrefixedFragments) {
      return false;
    }
    salvaged_partial_leadin = true;
  } else {
    first_record_end = FindNextLegacyLiveObjectSubMessageBoundaryAfter(
        *payload,
        live_bytes_offset);
    if (first_record_end > payload->size()) {
      first_record_end = payload->size();
    }
  }

  const size_t dropped_leadin_bytes =
      live_bytes_offset - kLiveBytesOffsetAfterPrefixedFragments;
  const size_t live_bytes_size = payload->size() - live_bytes_offset;
  const uint32_t new_declared = static_cast<uint32_t>(7 + live_bytes_size);
  const size_t new_payload_size = static_cast<size_t>(new_declared) + kLegacyPrefixedFragmentBytes;
  if (new_declared > kMaxReasonableReassembledGameplayPayload ||
      new_payload_size > kMaxReasonableReassembledGameplayPayload) {
    return false;
  }

  std::vector<unsigned char> rewritten;
  rewritten.reserve(new_payload_size);
  rewritten.insert(rewritten.end(), payload->begin(), payload->begin() + 3);
  rewritten.resize(7);
  WriteU32Le(rewritten.data() + 3, new_declared);
  rewritten.insert(
      rewritten.end(),
      payload->begin() + static_cast<std::ptrdiff_t>(live_bytes_offset),
      payload->end());
  rewritten.insert(rewritten.end(), payload->begin() + 3, payload->begin() + 7);

  const uint64_t observation = ++runtime->live_object_prefixed_fragment_normalize_count;
  if (salvaged_partial_leadin) {
    ++runtime->live_object_prefixed_fragment_salvage_count;
    runtime->live_object_prefixed_fragment_salvage_byte_count += dropped_leadin_bytes;
  }
  LogFormat(
      L"%s live-object prefixed-fragment layout normalized #%llu: wire_declared=0x%08X/%u declared=%u payload=%zu->%zu prefixed_fragments=[%s] live_offset=%zu dropped=%zu salvaged=%d first_record_end=%zu first_live=[%s]",
      context != nullptr ? context : L"server->client",
      static_cast<unsigned long long>(observation),
      old_wire_declared,
      old_wire_declared,
      new_declared,
      payload->size(),
      rewritten.size(),
      FormatLimitedBytes(payload->data() + 3, kLegacyPrefixedFragmentBytes, 16).c_str(),
      live_bytes_offset,
      dropped_leadin_bytes,
      salvaged_partial_leadin ? 1 : 0,
      first_record_end,
      FormatLimitedBytes(
          payload->data() + live_bytes_offset,
          std::min<size_t>(live_bytes_size, 48),
          48).c_str());

  *payload = std::move(rewritten);
  return true;
}

bool NormalizeLiveObjectPrefixedFragmentsIfPossible(
    BridgeRuntime* runtime,
    std::vector<unsigned char>* packet,
    const wchar_t* context) {
  if (runtime == nullptr || packet == nullptr ||
      packet->size() <= kLegacyGameplayPayloadOffset || packet->front() != 'M') {
    return false;
  }

  GameplayPayloadWindow window;
  if (!ExtractGameplayPayloadWindow(*packet, &window)) {
    return false;
  }
  std::vector<unsigned char> rewritten_payload = window.payload;
  const size_t old_payload_length = rewritten_payload.size();
  const uint16_t old_crc = ReadU16Be(packet->data() + 1);
  if (!NormalizeLegacyLiveObjectPrefixedFragmentsPayloadIfNeeded(
          runtime,
          &rewritten_payload,
          context)) {
    return false;
  }

  bool packetized_length_updated = false;
  bool crc_updated = false;
  if (!ReplaceGameplayPayloadWindow(
          packet,
          window,
          rewritten_payload,
          &packetized_length_updated,
          &crc_updated)) {
    return false;
  }
  const uint16_t new_crc = packet->size() >= 3 ? ReadU16Be(packet->data() + 1) : 0;
  LogFormat(
      L"%s live-object prefixed-fragment packet repaired: old_payload=%zu new_payload=%zu trailing_preserved=%zu pkt_len_updated=%d crc_updated=%d crc=0x%04X->0x%04X",
      context != nullptr ? context : L"server->client",
      old_payload_length,
      rewritten_payload.size(),
      window.trailing.size(),
      packetized_length_updated ? 1 : 0,
      crc_updated ? 1 : 0,
      old_crc,
      new_crc);
  return true;
}

bool RewriteLiveCreaturePFeatureGatesPayloadIfPossible(
    BridgeRuntime* runtime,
    std::vector<unsigned char>* payload,
    LiveCreaturePFeatureRewriteResult* result) {
  if (result != nullptr) {
    *result = LiveCreaturePFeatureRewriteResult{};
  }
  if (runtime == nullptr || payload == nullptr ||
      payload->size() < 7 ||
      !IsHighLevelGameplayEnvelope((*payload)[0]) ||
      (*payload)[1] != 5 ||
      (*payload)[2] != 1) {
    return false;
  }

  uint32_t declared = 0;
  uint32_t wire_declared = 0;
  if (!TryResolveLiveObjectPayloadDeclaredLength(*payload, &declared, &wire_declared)) {
    ++runtime->live_object_creature_p_feature_rewrite_skipped_count;
    if (runtime->live_object_creature_p_feature_rewrite_skipped_count <= 40 ||
        runtime->options.packet_dump) {
      LogFormat(
          L"server->client live creature-P feature rewrite skipped: incomplete-or-invalid declared=%u payload-len=%zu",
          wire_declared,
          payload->size());
    }
    return false;
  }

  const size_t declared_live_end = declared >= 7 ? static_cast<size_t>(declared - 7) : 0;
  if (declared_live_end > payload->size() - 7) {
    return false;
  }

  std::vector<unsigned char> combined(
      payload->begin() + 7,
      payload->end());
  LiveCreaturePFeatureRewriteResult local;
  local.envelope = (*payload)[0];
  local.old_declared = wire_declared;

  std::vector<unsigned char> live_bytes;
  live_bytes.reserve(declared_live_end + 64);
  size_t copied_until = 0;
  size_t fragment_start = declared_live_end;
  std::vector<unsigned char> fragment_bytes(
      combined.begin() + static_cast<std::ptrdiff_t>(declared_live_end),
      combined.end());
  std::vector<unsigned char> fragment_bits;
  bool fragment_bits_reliable = DecodeCnwFragmentBits(fragment_bytes, &fragment_bits);
  bool fragment_bits_changed = false;
  size_t bit_cursor = 3;
  bool rewritten_any = false;
  bool pending_creature_p_tail_repair = false;
  std::vector<unsigned char> pending_creature_p_original_bits;
  size_t pending_creature_p_original_tail_start = 0;
  size_t pending_creature_p_rewritten_tail_start = 0;
  size_t pending_creature_p_offset = 0;
  uint32_t pending_creature_p_inserted_bits = 0;
  uint32_t pending_creature_p_name_bits = 0;

  const auto log_fragment_cursor_loss = [&](
      const wchar_t* reason,
      size_t record_offset,
      size_t record_end) {
    if (!runtime->options.packet_dump) {
      return;
    }
    const size_t safe_end = std::min(record_end, combined.size());
    const size_t available =
        record_offset < safe_end ? safe_end - record_offset : 0;
    const wchar_t opcode =
        record_offset < combined.size() &&
                combined[record_offset] >= 0x20 &&
                combined[record_offset] <= 0x7E
            ? static_cast<wchar_t>(combined[record_offset])
            : L'.';
    const unsigned int marker =
        record_offset + 1 < combined.size()
            ? static_cast<unsigned int>(combined[record_offset + 1])
            : 0x100u;
    LogFormat(
        L"server->client live creature-P fragment cursor unreliable: reason=%s offset=%zu end=%zu opcode='%c'/0x%02X marker=0x%02X bit_cursor=%zu bits=%zu fragments=[%s] raw=[%s]",
        reason != nullptr ? reason : L"<unknown>",
        record_offset,
        record_end,
        opcode,
        record_offset < combined.size()
            ? static_cast<unsigned int>(combined[record_offset])
            : 0x100u,
        marker,
        bit_cursor,
        fragment_bits.size(),
        fragment_bytes.empty()
            ? L"<empty>"
            : FormatLimitedBytes(
                  fragment_bytes.data(),
                  fragment_bytes.size(),
                  std::min<size_t>(fragment_bytes.size(), 128)).c_str(),
        available != 0
            ? FormatLimitedBytes(
                  combined.data() + record_offset,
                  available,
                  std::min<size_t>(available, 192)).c_str()
            : L"<empty>");
  };
  const auto mark_fragment_cursor_unreliable = [&](
      const wchar_t* reason,
      size_t record_offset,
      size_t record_end) {
    if (fragment_bits_reliable) {
      log_fragment_cursor_loss(reason, record_offset, record_end);
    }
    fragment_bits_reliable = false;
  };
  const auto clear_pending_creature_p_tail_repair = [&]() {
    pending_creature_p_tail_repair = false;
    pending_creature_p_original_bits.clear();
    pending_creature_p_original_tail_start = 0;
    pending_creature_p_rewritten_tail_start = 0;
    pending_creature_p_offset = 0;
    pending_creature_p_inserted_bits = 0;
    pending_creature_p_name_bits = 0;
  };
  const auto try_repair_pending_creature_p_tail_for_record = [&](
      size_t record_offset,
      size_t record_end) -> bool {
    if (!pending_creature_p_tail_repair ||
        !fragment_bits_reliable ||
        bit_cursor != pending_creature_p_rewritten_tail_start ||
        pending_creature_p_rewritten_tail_start > fragment_bits.size() ||
        pending_creature_p_original_tail_start >
            pending_creature_p_original_bits.size()) {
      if (runtime->options.packet_dump && pending_creature_p_tail_repair) {
        LogFormat(
            L"server->client live creature-P fragment tail repair guard rejected: p_offset=%zu record_offset=%zu record_end=%zu bit_cursor=%zu rewritten_tail=%zu current_bits=%zu original_tail=%zu original_bits=%zu reliable=%d",
            pending_creature_p_offset,
            record_offset,
            record_end,
            bit_cursor,
            pending_creature_p_rewritten_tail_start,
            fragment_bits.size(),
            pending_creature_p_original_tail_start,
            pending_creature_p_original_bits.size(),
            fragment_bits_reliable ? 1 : 0);
      }
      return false;
    }

    std::vector<size_t> candidate_tail_starts;
    const auto add_candidate_tail_start = [&](size_t tail_start) {
      if (tail_start > pending_creature_p_original_bits.size()) {
        return;
      }
      for (size_t existing : candidate_tail_starts) {
        if (existing == tail_start) {
          return;
        }
      }
      candidate_tail_starts.push_back(tail_start);
    };
    add_candidate_tail_start(pending_creature_p_original_tail_start);
    if (pending_creature_p_name_bits != 0) {
      const size_t name_bits =
          static_cast<size_t>(pending_creature_p_name_bits);
      if (pending_creature_p_original_tail_start >= name_bits) {
        add_candidate_tail_start(
            pending_creature_p_original_tail_start - name_bits);
      }
      add_candidate_tail_start(
          pending_creature_p_original_tail_start + name_bits);
    }

    std::wstring candidate_start_summary;
    for (size_t i = 0; i < candidate_tail_starts.size(); ++i) {
      wchar_t text[64]{};
      swprintf_s(
          text,
          L"%s%zu",
          i == 0 ? L"" : L",",
          candidate_tail_starts[i]);
      candidate_start_summary += text;
    }

    std::vector<unsigned char> accepted_candidate_bits;
    std::vector<unsigned char> rejected_candidate_bits;
    size_t accepted_tail_start = pending_creature_p_original_tail_start;
    size_t rejected_tail_start = pending_creature_p_original_tail_start;
    size_t accepted_trial_bit_cursor = bit_cursor;
    std::wstring creature_advance_failure;
    bool advanced = false;
    if (!IsLegacyLiveReadBufferOnlySubMessage(
            combined,
            record_offset,
            record_end)) {
      for (size_t candidate_tail_start : candidate_tail_starts) {
        std::vector<unsigned char> candidate_bits = fragment_bits;
        candidate_bits.resize(pending_creature_p_rewritten_tail_start);
        candidate_bits.insert(
            candidate_bits.end(),
            pending_creature_p_original_bits.begin() +
                static_cast<std::ptrdiff_t>(candidate_tail_start),
            pending_creature_p_original_bits.end());

        size_t trial_bit_cursor = bit_cursor;
        std::wstring candidate_failure;
        const bool candidate_advanced =
            AdvanceLegacyLiveDeleteRecordBitCursorForEe(
                combined,
                record_offset,
                record_end,
                candidate_bits,
                &trial_bit_cursor) ||
            AdvanceKnownLegacyLiveCreatureBitCursor(
                combined,
                record_offset,
                record_end,
                candidate_bits,
                &trial_bit_cursor,
                &candidate_failure) ||
            AdvanceLegacyLiveAddRecordBitCursor(
                combined,
                candidate_bits,
                record_offset,
                record_end,
                &trial_bit_cursor) ||
            AdvanceRewrittenLiveUpdateRecordBitCursor(
                combined,
                record_offset,
                record_end,
                &trial_bit_cursor);
        if (candidate_advanced) {
          accepted_candidate_bits = std::move(candidate_bits);
          accepted_tail_start = candidate_tail_start;
          accepted_trial_bit_cursor = trial_bit_cursor;
          advanced = true;
          break;
        }
        rejected_candidate_bits = std::move(candidate_bits);
        rejected_tail_start = candidate_tail_start;
        creature_advance_failure = std::move(candidate_failure);
      }
    } else {
      creature_advance_failure = L"read-buffer-only";
    }
    if (!advanced) {
      if (runtime->options.packet_dump) {
        const size_t before_slice =
            bit_cursor >= 8 ? bit_cursor - 8 : 0;
        LogFormat(
            L"server->client live creature-P fragment tail repair candidate rejected: p_offset=%zu record_offset=%zu record_end=%zu reason=%s original_tail=%zu rejected_tail=%zu rewritten_tail=%zu inserted_bits=%u name_bits=%u candidates=[%s] bit_cursor=%zu current_bits=%zu candidate_bits=%zu original_slice=[%s] current_slice=[%s] candidate_slice=[%s] raw=[%s]",
            pending_creature_p_offset,
            record_offset,
            record_end,
            creature_advance_failure.empty()
                ? L"<none>"
                : creature_advance_failure.c_str(),
            pending_creature_p_original_tail_start,
            rejected_tail_start,
            pending_creature_p_rewritten_tail_start,
            pending_creature_p_inserted_bits,
            pending_creature_p_name_bits,
            candidate_start_summary.empty()
                ? L"<none>"
                : candidate_start_summary.c_str(),
            bit_cursor,
            fragment_bits.size(),
            rejected_candidate_bits.size(),
            FormatCnwBitSlice(
                pending_creature_p_original_bits,
                pending_creature_p_original_tail_start >= 8
                    ? pending_creature_p_original_tail_start - 8
                    : 0,
                80).c_str(),
            FormatCnwBitSlice(fragment_bits, before_slice, 80).c_str(),
            FormatCnwBitSlice(
                rejected_candidate_bits.empty() ? fragment_bits : rejected_candidate_bits,
                before_slice,
                80).c_str(),
            record_end > record_offset && record_offset < combined.size()
                ? FormatLimitedBytes(
                      combined.data() + record_offset,
                      std::min(record_end, combined.size()) - record_offset,
                      160).c_str()
                : L"<empty>");
      }
      return false;
    }

    if (runtime->options.packet_dump) {
      const size_t before_slice =
          bit_cursor >= 8 ? bit_cursor - 8 : 0;
      const long long tail_delta =
          static_cast<long long>(accepted_tail_start) -
          static_cast<long long>(pending_creature_p_original_tail_start);
      LogFormat(
          L"server->client live creature-P fragment tail repaired: p_offset=%zu record_offset=%zu record_end=%zu original_tail=%zu accepted_tail=%zu tail_delta=%lld rewritten_tail=%zu inserted_bits=%u name_bits=%u candidates=[%s] bit_cursor=%zu->%zu before=[%s] after=[%s]",
          pending_creature_p_offset,
          record_offset,
          record_end,
          pending_creature_p_original_tail_start,
          accepted_tail_start,
          tail_delta,
          pending_creature_p_rewritten_tail_start,
          pending_creature_p_inserted_bits,
          pending_creature_p_name_bits,
          candidate_start_summary.empty()
              ? L"<none>"
              : candidate_start_summary.c_str(),
          bit_cursor,
          accepted_trial_bit_cursor,
          FormatCnwBitSlice(fragment_bits, before_slice, 80).c_str(),
          FormatCnwBitSlice(accepted_candidate_bits, before_slice, 80).c_str());
    }

    fragment_bits = std::move(accepted_candidate_bits);
    bit_cursor = accepted_trial_bit_cursor;
    fragment_bits_changed = true;
    clear_pending_creature_p_tail_repair();
    return true;
  };
  if (!fragment_bits_reliable && runtime->options.packet_dump) {
    log_fragment_cursor_loss(L"fragment-decode", 0, declared_live_end);
  }

  for (size_t offset = 0; offset + 10 <= declared_live_end;) {
    if (!LooksLikeLegacyLiveObjectSubMessageBoundaryBytes(combined, offset)) {
      ++offset;
      continue;
    }

    ++local.records_examined;
    const bool is_gui_inventory_add =
        combined[offset] == 'G' &&
        offset + 3 <= declared_live_end &&
        (combined[offset + 1] == 'I' || combined[offset + 1] == 'i') &&
        combined[offset + 2] == 'A';
    const bool is_gui_repository_add =
        combined[offset] == 'G' &&
        offset + 3 <= declared_live_end &&
        (combined[offset + 1] == 'R' || combined[offset + 1] == 'r') &&
        combined[offset + 2] == 'A';
    if (is_gui_inventory_add || is_gui_repository_add) {
      std::vector<unsigned char> rewritten_record;
      size_t old_record_end = offset;
      uint32_t inserted = 0;
      uint32_t active_property_bits = 0;
      std::wstring detail;
      std::vector<unsigned char> record_fragment_bits_snapshot;
      size_t record_bit_cursor_snapshot = bit_cursor;
      if (fragment_bits_reliable) {
        record_fragment_bits_snapshot = fragment_bits;
      }

      if (fragment_bits_reliable &&
          (is_gui_inventory_add
               ? RewriteLegacyGuiInventoryAddFeatureGateRecord(
                     *runtime,
                     combined,
                     offset,
                     declared_live_end,
                     &fragment_bits,
                     &bit_cursor,
                     &rewritten_record,
                     &old_record_end,
                     &inserted,
                     &active_property_bits,
                     &detail)
               : RewriteLegacyGuiRepositoryAddFeatureGateRecord(
                     *runtime,
                     combined,
                     offset,
                     declared_live_end,
                     &fragment_bits,
                     &bit_cursor,
                     &rewritten_record,
                     &old_record_end,
                     &inserted,
                     &active_property_bits,
                     &detail)) &&
          old_record_end > offset &&
          old_record_end <= combined.size()) {
        if (offset < copied_until) {
          offset = old_record_end;
          continue;
        }
        if (offset > copied_until) {
          const size_t copy_end = std::min(offset, declared_live_end);
          if (copy_end > copied_until) {
            live_bytes.insert(
                live_bytes.end(),
                combined.begin() + static_cast<std::ptrdiff_t>(copied_until),
                combined.begin() + static_cast<std::ptrdiff_t>(copy_end));
          }
        }
        live_bytes.insert(live_bytes.end(), rewritten_record.begin(), rewritten_record.end());
        copied_until = old_record_end;
        rewritten_any = true;
        ++local.records_rewritten;
        local.bytes_inserted += inserted;
        ++local.equipment_items_seen;
        ++local.equipment_item_appearances_seen;
        local.active_property_bits_inserted += active_property_bits;
        if (active_property_bits != 0) {
          fragment_bits_changed = true;
        }
        if (!detail.empty() && local.details.size() < 1800) {
          if (!local.details.empty()) {
            local.details += L"; ";
          }
          local.details += detail;
        }
        offset = old_record_end;
        continue;
      }

      if (fragment_bits_reliable) {
        const size_t restored_fragment_count = record_fragment_bits_snapshot.size();
        fragment_bits = std::move(record_fragment_bits_snapshot);
        bit_cursor = record_bit_cursor_snapshot;
        LegacyGuiInventoryAddShape shape;
        const bool shape_ok = TryGetLegacyLiveGuiItemCreateRecordShape(
                combined,
                offset,
                declared_live_end,
                runtime,
                &shape);
        if (shape_ok &&
            !AdvanceLegacyActiveItemPropertiesBitCursorForEe(
                combined,
                shape.active_offset,
                shape.record_end,
                shape.base_item_id,
                fragment_bits,
                &bit_cursor,
                false)) {
          mark_fragment_cursor_unreliable(
              is_gui_inventory_add
                  ? L"gui-inventory-A-active-bits"
                  : L"gui-repository-A-active-bits",
              offset,
              shape.record_end);
        }
        if (runtime->options.packet_dump) {
          const size_t next =
              FindNextLegacyLiveObjectSubMessageBoundaryAfter(
                  combined,
                  offset,
                  declared_live_end,
                  runtime);
          const size_t probe_end =
              shape_ok ? shape.record_end : (next > offset ? next : declared_live_end);
          LogFormat(
              L"server->client live GUI item-create rewrite skipped: offset=%zu kind=%c%c%c shape=%d record_end=%zu active=%zu base=%u model=%d bit_cursor=%zu fragments=%zu next=%zu reason=%s prefix=[%s]",
              offset,
              static_cast<wchar_t>(combined[offset]),
              static_cast<wchar_t>(offset + 1 < combined.size() ? combined[offset + 1] : 0),
              static_cast<wchar_t>(offset + 2 < combined.size() ? combined[offset + 2] : 0),
              shape_ok ? 1 : 0,
              shape_ok ? shape.record_end : 0,
              shape_ok ? shape.active_offset : 0,
              shape_ok ? shape.base_item_id : 0,
              shape_ok ? shape.model_type : -1,
              record_bit_cursor_snapshot,
              restored_fragment_count,
              next,
              !detail.empty()
                  ? detail.c_str()
                  : (shape_ok ? L"rewrite-failed-after-shape" : L"shape-parse-failed"),
              offset < combined.size()
                  ? FormatLimitedBytes(
                        combined.data() + offset,
                        std::min<size_t>(
                            std::min<size_t>(probe_end, combined.size()) - offset,
                            192),
                        192).c_str()
                  : L"<empty>");
        }
      }
      const size_t next =
          FindNextLegacyLiveObjectSubMessageBoundaryAfter(
              combined,
              offset,
              declared_live_end,
              runtime);
      offset = next > offset ? std::min(next, declared_live_end) : offset + 1;
      continue;
    }

    if (combined[offset] != 'P' || combined[offset + 1] != 5) {
      const size_t next =
          FindNextLegacyLiveObjectSubMessageBoundaryAfter(
              combined,
              offset,
              declared_live_end,
              runtime);
      const size_t record_end = next > offset ? std::min(next, declared_live_end) : offset + 1;
      if (fragment_bits_reliable) {
        const unsigned char opcode = combined[offset];
        if (opcode == 'I') {
          size_t inventory_fragment_bits = 0;
          if (TryGetLegacyLiveInventoryFragmentBitCount(
                  combined,
                  offset,
                  record_end,
                  &inventory_fragment_bits) &&
              inventory_fragment_bits <= fragment_bits.size() &&
              bit_cursor <= fragment_bits.size() - inventory_fragment_bits) {
            bit_cursor += inventory_fragment_bits;
          } else {
            mark_fragment_cursor_unreliable(
                L"inventory-fragment-bits",
                offset,
                record_end);
          }
        } else if (opcode == 'A' &&
                   offset + 1 < combined.size() &&
                   (combined[offset + 1] == 9 || combined[offset + 1] == 10)) {
          std::wstring skip_reason;
          if (ShouldSkipLegacyLiveShortAddRecordBytes(
                  runtime,
                  combined,
                  offset,
                  record_end,
                  &skip_reason)) {
            if (!AdvanceLegacyLiveShortAddRecordBitCursor(
                    combined,
                    fragment_bits,
                    offset,
                    record_end,
                    &bit_cursor)) {
              mark_fragment_cursor_unreliable(
                  L"short-add-skip-fragment-bits",
                  offset,
                  record_end);
            }
          } else if (!AdvanceLegacyLiveAddRecordBitCursor(
                         combined,
                         fragment_bits,
                         offset,
                         record_end,
                         &bit_cursor)) {
            mark_fragment_cursor_unreliable(
                L"known-record-bit-advance",
                offset,
                record_end);
          }
        } else if (TryGetLegacyLiveDeleteFragmentBitCount(
                       combined,
                       offset,
                       record_end,
                       nullptr)) {
          if (!AdvanceLegacyLiveDeleteRecordBitCursorForEe(
                  combined,
                  offset,
                  record_end,
                  fragment_bits,
                  &bit_cursor)) {
            mark_fragment_cursor_unreliable(
                L"delete-fragment-bits",
                offset,
                record_end);
          }
        } else if (!IsLegacyLiveReadBufferOnlySubMessage(combined, offset, record_end)) {
          const size_t bit_cursor_before_probe = bit_cursor;
          size_t trial_bit_cursor = bit_cursor;
          if (AdvanceKnownLegacyLiveCreatureBitCursor(
                  combined,
                  offset,
                  record_end,
                  fragment_bits,
                  &trial_bit_cursor) ||
              AdvanceLegacyLiveAddRecordBitCursor(
                  combined,
                  fragment_bits,
                  offset,
                  record_end,
                  &trial_bit_cursor) ||
              AdvanceRewrittenLiveUpdateRecordBitCursor(
                  combined,
                  offset,
                  record_end,
                  &trial_bit_cursor)) {
            bit_cursor = trial_bit_cursor;
            clear_pending_creature_p_tail_repair();
          } else {
            bit_cursor = bit_cursor_before_probe;
            if (!try_repair_pending_creature_p_tail_for_record(offset, record_end)) {
              mark_fragment_cursor_unreliable(
                  L"known-record-bit-advance",
                  offset,
                  record_end);
            }
          }
        }
      }
      offset = next > offset ? std::min(next, declared_live_end) : offset + 1;
      continue;
    }

    std::vector<unsigned char> rewritten_record;
    size_t old_record_end = offset;
    uint32_t promoted = 0;
    uint32_t inserted = 0;
    uint32_t removed = 0;
    uint32_t equipment_items = 0;
    uint32_t equipment_appearances = 0;
    uint32_t active_property_bits = 0;
    uint32_t name_mode_bits = 0;
    std::wstring detail;
    std::vector<unsigned char> record_fragment_bits_snapshot;
    size_t record_bit_cursor_snapshot = bit_cursor;
    if (fragment_bits_reliable) {
      record_fragment_bits_snapshot = fragment_bits;
    }
    if (!RewriteLegacyCreaturePFeatureGateRecord(
            *runtime,
            combined,
            offset,
            declared_live_end,
            fragment_bits_reliable ? &fragment_bits : nullptr,
            fragment_bits_reliable ? &bit_cursor : nullptr,
            &rewritten_record,
            &old_record_end,
            &promoted,
            &inserted,
            &removed,
            &equipment_items,
            &equipment_appearances,
            &active_property_bits,
            &name_mode_bits,
            &detail) ||
        old_record_end <= offset ||
        old_record_end > combined.size()) {
      if (fragment_bits_reliable) {
        fragment_bits = std::move(record_fragment_bits_snapshot);
        bit_cursor = record_bit_cursor_snapshot;
        if (!AdvanceKnownLegacyLiveCreatureBitCursor(
                combined,
                offset,
                std::min(
                    FindNextLegacyLiveObjectSubMessageBoundaryAfter(
                        combined,
                        offset,
                        declared_live_end,
                        runtime),
                    declared_live_end),
                fragment_bits,
                &bit_cursor)) {
          mark_fragment_cursor_unreliable(
              L"creature-p-fallback-bit-advance",
              offset,
              std::min(
                  FindNextLegacyLiveObjectSubMessageBoundaryAfter(
                      combined,
                      offset,
                      declared_live_end,
                      runtime),
                  declared_live_end));
        }
      }
      const size_t next =
          FindNextLegacyLiveObjectSubMessageBoundaryAfter(
              combined,
              offset,
              declared_live_end,
              runtime);
      offset = next > offset ? std::min(next, declared_live_end) : offset + 1;
      continue;
    }

    if (offset < copied_until) {
      offset = old_record_end;
      continue;
    }
    if (offset > copied_until) {
      const size_t copy_end = std::min(offset, declared_live_end);
      if (copy_end > copied_until) {
        live_bytes.insert(
            live_bytes.end(),
            combined.begin() + static_cast<std::ptrdiff_t>(copied_until),
            combined.begin() + static_cast<std::ptrdiff_t>(copy_end));
      }
    }
    live_bytes.insert(live_bytes.end(), rewritten_record.begin(), rewritten_record.end());
    copied_until = old_record_end;
    if (old_record_end > fragment_start) {
      fragment_start = old_record_end;
    }
    rewritten_any = true;
    ++local.records_rewritten;
    if (promoted != 0) {
      ++local.records_promoted;
      local.bytes_promoted += promoted;
    }
    local.bytes_inserted += inserted;
    local.bytes_removed += removed;
    local.equipment_items_seen += equipment_items;
    local.equipment_item_appearances_seen += equipment_appearances;
    local.active_property_bits_inserted += active_property_bits;
    local.name_mode_bits_rewritten += name_mode_bits;
    if (active_property_bits != 0 || name_mode_bits != 0 || promoted != 0) {
      fragment_bits_changed = true;
    }
    clear_pending_creature_p_tail_repair();
    if (fragment_bits_reliable &&
        active_property_bits != 0 &&
        promoted == 0 &&
        bit_cursor >= active_property_bits &&
        record_bit_cursor_snapshot <= record_fragment_bits_snapshot.size()) {
      const size_t original_tail_start =
          bit_cursor - static_cast<size_t>(active_property_bits);
      if (original_tail_start <= record_fragment_bits_snapshot.size()) {
        pending_creature_p_tail_repair = true;
        pending_creature_p_original_bits = record_fragment_bits_snapshot;
        pending_creature_p_original_tail_start = original_tail_start;
        pending_creature_p_rewritten_tail_start = bit_cursor;
        pending_creature_p_offset = offset;
        pending_creature_p_inserted_bits = active_property_bits;
        pending_creature_p_name_bits = name_mode_bits;
        if (runtime->options.packet_dump) {
          const size_t original_slice =
              original_tail_start >= 8 ? original_tail_start - 8 : 0;
          const size_t rewritten_slice =
              bit_cursor >= 8 ? bit_cursor - 8 : 0;
          LogFormat(
              L"server->client live creature-P fragment tail repair pending: p_offset=%zu original_tail=%zu rewritten_tail=%zu inserted_bits=%u name_bits=%u original_bits=%zu rewritten_bits=%zu original_slice=[%s] rewritten_slice=[%s]",
              offset,
              pending_creature_p_original_tail_start,
              pending_creature_p_rewritten_tail_start,
              pending_creature_p_inserted_bits,
              pending_creature_p_name_bits,
              pending_creature_p_original_bits.size(),
              fragment_bits.size(),
              FormatCnwBitSlice(
                  pending_creature_p_original_bits,
                  original_slice,
                  80).c_str(),
              FormatCnwBitSlice(
                  fragment_bits,
                  rewritten_slice,
                  80).c_str());
        }
      }
    }
    if (!detail.empty() && local.details.size() < 1800) {
      if (!local.details.empty()) {
        local.details += L"; ";
      }
      local.details += detail;
    }

    offset = old_record_end;
  }

  if (!rewritten_any) {
    return false;
  }
  if (copied_until < declared_live_end) {
    live_bytes.insert(
        live_bytes.end(),
        combined.begin() + static_cast<std::ptrdiff_t>(copied_until),
        combined.begin() + static_cast<std::ptrdiff_t>(declared_live_end));
  }

  const uint32_t new_declared = static_cast<uint32_t>(7 + live_bytes.size());
  std::vector<unsigned char> rewritten_fragment_bytes;
  if (fragment_bits_reliable && fragment_start == declared_live_end) {
    size_t final_bit_cursor = 3;
    std::wstring final_cursor_failure;
    if (TryValidateEeRewrittenLiveObjectFragmentCursor(
            runtime,
            live_bytes,
            fragment_bits,
            &final_bit_cursor,
            &final_cursor_failure)) {
      if (final_bit_cursor >= 3 && final_bit_cursor < fragment_bits.size()) {
        const size_t trimmed = fragment_bits.size() - final_bit_cursor;
        fragment_bits.resize(final_bit_cursor);
        fragment_bits_changed = true;
        bit_cursor = final_bit_cursor;
        local.fragment_bits_trimmed += static_cast<uint32_t>(
            std::min<size_t>(trimmed, std::numeric_limits<uint32_t>::max()));
      } else {
        bit_cursor = final_bit_cursor;
      }
    } else if (runtime->options.packet_dump) {
      LogFormat(
          L"server->client live creature-P final fragment trim skipped: old_declared=%u new_declared=%u live=%zu bits=%zu current_bit=%zu reason=%s",
          wire_declared,
          new_declared,
          live_bytes.size(),
          fragment_bits.size(),
          bit_cursor,
          final_cursor_failure.empty() ? L"<none>" : final_cursor_failure.c_str());
    }
  }
  if (fragment_bits_changed) {
    if (fragment_start != declared_live_end || !fragment_bits_reliable) {
      ++runtime->live_object_creature_p_feature_rewrite_skipped_count;
      LogFormat(
          L"server->client live creature-P feature rewrite refused: fragment bit insertion with promoted tail old_declared=%u new_declared=%u fragment_start=%zu declared_live_end=%zu reliable=%d",
          wire_declared,
          new_declared,
          fragment_start,
          declared_live_end,
          fragment_bits_reliable ? 1 : 0);
      return false;
    }
    RefreshCnwFragmentFinalBitHeader(&fragment_bits);
    PackCnwMsbBits(fragment_bits, &rewritten_fragment_bytes);
    if (rewritten_fragment_bytes.empty()) {
      rewritten_fragment_bytes.push_back(0);
    }
  } else {
    rewritten_fragment_bytes.insert(
        rewritten_fragment_bytes.end(),
        combined.begin() + static_cast<std::ptrdiff_t>(fragment_start),
        combined.end());
  }

  const size_t new_payload_size = static_cast<size_t>(new_declared) +
      rewritten_fragment_bytes.size();
  if (new_declared > kMaxReasonableReassembledGameplayPayload ||
      new_payload_size > kMaxReasonableReassembledGameplayPayload) {
    ++runtime->live_object_creature_p_feature_rewrite_skipped_count;
    LogFormat(
        L"server->client live creature-P feature rewrite refused: old_declared=%u new_declared=%u live=%zu fragments=%zu",
        wire_declared,
        new_declared,
        live_bytes.size(),
        combined.size() - fragment_start);
    return false;
  }

  std::vector<unsigned char> rewritten;
  rewritten.reserve(new_payload_size);
  rewritten.insert(rewritten.end(), payload->begin(), payload->begin() + 7);
  rewritten.insert(rewritten.end(), live_bytes.begin(), live_bytes.end());
  rewritten.insert(
      rewritten.end(),
      rewritten_fragment_bytes.begin(),
      rewritten_fragment_bytes.end());
  WriteU32Le(rewritten.data() + 3, new_declared);
  *payload = std::move(rewritten);

  local.new_declared = new_declared;
  local.old_fragment_bytes = static_cast<uint32_t>(combined.size() - declared_live_end);
  local.new_fragment_bytes = static_cast<uint32_t>(rewritten_fragment_bytes.size());
  ++runtime->live_object_creature_p_feature_rewrite_count;
  runtime->live_object_creature_p_feature_records_rewritten_count += local.records_rewritten;
  runtime->live_object_creature_p_feature_promoted_byte_count += local.bytes_promoted;
  runtime->live_object_creature_p_feature_inserted_byte_count += local.bytes_inserted;
  if (result != nullptr) {
    *result = std::move(local);
  }
  return true;
}

