bool RewriteLiveObjectUpdatesPayloadIfPossible(
    BridgeRuntime* runtime,
    std::vector<unsigned char>* payload,
    LiveObjectUpdateRewriteResult* result) {
  if (result != nullptr) {
    *result = LiveObjectUpdateRewriteResult{};
  }
  if (runtime == nullptr || payload == nullptr || !runtime->options.rewrite_live_object_updates ||
      payload->size() < 7 || !IsHighLevelGameplayEnvelope((*payload)[0]) ||
      (*payload)[1] != 5 || (*payload)[2] != 1) {
    return false;
  }

  uint32_t declared = 0;
  uint32_t wire_declared = 0;
  if (!TryResolveLiveObjectPayloadDeclaredLength(*payload, &declared, &wire_declared)) {
    ++runtime->live_object_update_rewrite_skipped_count;
    if (runtime->live_object_update_rewrite_skipped_count <= 40 || runtime->options.packet_dump) {
      LogFormat(
          L"server->client live-object update rewrite skipped: incomplete-or-invalid declared=%u payload-len=%zu",
          wire_declared,
          payload->size());
    }
    return false;
  }

  std::vector<unsigned char> live_bytes(
      payload->begin() + 7,
      payload->begin() + static_cast<std::ptrdiff_t>(declared));
  std::vector<unsigned char> fragment_bytes(
      payload->begin() + static_cast<std::ptrdiff_t>(declared),
      payload->end());
  LiveObjectUpdateRewriteResult local;
  local.envelope = (*payload)[0];
  local.old_declared = wire_declared;
  if (!RewriteLegacyLiveObjectUpdateRecords(runtime, &live_bytes, &fragment_bytes, &local)) {
    if (!local.diagnostics.empty()) {
      ++runtime->live_object_creature_alignment_diagnostic_count;
      if (runtime->live_object_creature_alignment_diagnostic_count <= 80 ||
          runtime->options.packet_dump) {
        LogFormat(
            L"server->client live-object creature alignment diagnostics without rewrite #%llu: envelope=0x%02X declared=%u payload-len=%zu fragments=%u diagnostics=[%s]",
            static_cast<unsigned long long>(
                runtime->live_object_creature_alignment_diagnostic_count),
            local.envelope,
            local.old_declared,
            payload->size(),
            local.old_fragment_bytes,
            local.diagnostics.c_str());
      }
    }
    return false;
  }

  const uint32_t new_declared = static_cast<uint32_t>(7 + live_bytes.size());
  const size_t new_payload_size = new_declared + fragment_bytes.size();
  if (new_declared > kMaxReasonableReassembledGameplayPayload ||
      new_payload_size > kMaxReasonableReassembledGameplayPayload) {
    return false;
  }
  local.new_declared = new_declared;

  std::vector<unsigned char> rewritten;
  rewritten.reserve(new_payload_size);
  rewritten.insert(rewritten.end(), payload->begin(), payload->begin() + 7);
  rewritten.insert(rewritten.end(), live_bytes.begin(), live_bytes.end());
  rewritten.insert(rewritten.end(), fragment_bytes.begin(), fragment_bytes.end());
  WriteU32Le(rewritten.data() + 3, new_declared);
  *payload = std::move(rewritten);

  ++runtime->live_object_update_rewrite_count;
  runtime->live_object_update_mask_translate_count += local.masks_translated;
  runtime->live_object_update_tail_strip_count += local.scalar_tails_removed;
  runtime->live_object_update_bits_insert_count += local.bits_inserted;
  runtime->live_object_update_door_extra_bit_insert_count += local.door_extra_bits_inserted;
  runtime->live_object_update_name_mode_bit_insert_count += local.name_mode_bits_inserted;
  runtime->live_object_update_creature_tail_padding_count += local.creature_tail_records_padded;
  runtime->live_object_update_creature_tail_padding_byte_count += local.creature_tail_bytes_inserted;
  if (result != nullptr) {
    *result = std::move(local);
  }
  return true;
}

