bool RewriteCoalescedLiveObjectPayloadsIfPossible(
    BridgeRuntime* runtime,
    std::vector<unsigned char>* packet) {
  if (runtime == nullptr || packet == nullptr ||
      packet->size() <= kLegacyGameplayPayloadOffset || packet->front() != 'M') {
    return false;
  }

  const bool any_live_rewrite_enabled =
      runtime->options.rewrite_live_object_updates ||
      runtime->options.rewrite_live_object_visual_transform_masks ||
      runtime->options.rewrite_live_object_material_shader_params ||
      runtime->options.rewrite_live_object_add_visual_transforms ||
      runtime->options.rewrite_live_object_add_records ||
      runtime->options.rewrite_live_object_inventory_feature23_categories ||
      runtime->options.rewrite_live_object_item_appearances;
  if (!any_live_rewrite_enabled) {
    return false;
  }

  GameplayWrapperView first_view;
  size_t first_frame_length = 0;
  if (!TryParseGameplayFrameSpanAt(*packet, 0, &first_view, &first_frame_length) ||
      first_frame_length >= packet->size()) {
    return false;
  }

  const uint16_t old_crc = ReadU16Be(packet->data() + 1);
  size_t cursor = first_frame_length;
  bool changed = false;
  bool all_lengths_updated = true;
  bool all_inner_crcs_updated = true;
  while (cursor < packet->size()) {
    PacketizedMessageSpan frame_view;
    if (!TryParsePacketizedMessageSpanAt(*packet, cursor, &frame_view)) {
      ++runtime->live_object_coalesced_scan_stop_count;
      if (runtime->options.packet_dump ||
          runtime->live_object_coalesced_scan_stop_count <= 24) {
        LogFormat(
            L"server->client coalesced live-object scan stopped #%llu: offset=%zu remaining=%zu first_seq=%u first_payload=%zu prefix=[%s]",
            static_cast<unsigned long long>(
                runtime->live_object_coalesced_scan_stop_count),
            cursor,
            packet->size() - cursor,
            first_view.sequence,
            static_cast<size_t>(first_view.payload_length),
            FormatLimitedBytes(packet->data() + cursor, packet->size() - cursor, 96).c_str());
      }
      break;
    }

    const size_t old_frame_length = frame_view.record_length;
    if (old_frame_length == 0) {
      break;
    }

    const size_t payload_offset = cursor + kLegacyGameplayPayloadOffset;
    if (!frame_view.has_payload ||
        frame_view.payload_length < 7 ||
        payload_offset + frame_view.payload_length > packet->size() ||
        !frame_view.has_high_envelope ||
        frame_view.high_major != 5 ||
        frame_view.high_minor != 1) {
      cursor += old_frame_length;
      continue;
    }

    ++runtime->live_object_coalesced_candidate_count;
    std::vector<unsigned char> rewritten_payload(
        packet->begin() + static_cast<std::ptrdiff_t>(payload_offset),
        packet->begin() + static_cast<std::ptrdiff_t>(
            payload_offset + frame_view.payload_length));
    const size_t old_payload_length = rewritten_payload.size();
    const uint32_t old_declared =
        rewritten_payload.size() >= 7 ? ReadU32Le(rewritten_payload.data() + 3) : 0;

    LiveVisualTransformRewriteResult visual_transform_result;
    LiveMaterialShaderRewriteResult material_shader_result;
    LiveObjectUpdateRewriteResult live_update_result;
    LiveAddVisualTransformRewriteResult add_visual_transform_result;
    LiveAddRecordRewriteResult add_record_result;
    LiveInventoryFeature23RewriteResult inventory_feature23_result;
    LiveItemAppearanceRewriteResult item_appearance_result;
    LiveCreaturePFeatureRewriteResult creature_p_feature_result;
    const bool live_layout_normalized =
        NormalizeLegacyLiveObjectPrefixedFragmentsPayloadIfNeeded(
            runtime,
            &rewritten_payload,
            L"server->client coalesced");
    const bool creature_p_feature_rewritten =
        RewriteLiveCreaturePFeatureGatesPayloadIfPossible(
            runtime,
            &rewritten_payload,
            &creature_p_feature_result);
    const bool visual_transform_rewritten =
        RewriteLiveObjectVisualTransformMasksPayloadIfPossible(
            runtime,
            &rewritten_payload,
            &visual_transform_result);
    const bool material_shader_rewritten =
        RewriteLiveObjectMaterialShaderParamsPayloadIfPossible(
            runtime,
            &rewritten_payload,
            &material_shader_result);
    const bool live_updates_rewritten =
        RewriteLiveObjectUpdatesPayloadIfPossible(
            runtime,
            &rewritten_payload,
            &live_update_result);
    const bool add_visual_transforms_rewritten =
        RewriteLiveObjectAddVisualTransformsPayloadIfPossible(
            runtime,
            &rewritten_payload,
            &add_visual_transform_result);
    const bool add_records_rewritten =
        RewriteLiveObjectAddRecordsPayloadIfPossible(
            runtime,
            &rewritten_payload,
            &add_record_result);
    const bool inventory_feature23_rewritten =
        RewriteLiveObjectInventoryFeature23PayloadIfPossible(
            runtime,
            &rewritten_payload,
            &inventory_feature23_result);
    const bool item_appearances_rewritten =
        RewriteLiveObjectItemAppearancesPayloadIfPossible(
            runtime,
            &rewritten_payload,
            &item_appearance_result);
    if (!live_layout_normalized &&
        !creature_p_feature_rewritten &&
        !visual_transform_rewritten &&
        !material_shader_rewritten &&
        !live_updates_rewritten &&
        !add_visual_transforms_rewritten &&
        !add_records_rewritten &&
        !inventory_feature23_rewritten &&
        !item_appearances_rewritten) {
      cursor += old_frame_length;
      continue;
    }

    if (rewritten_payload.empty() ||
        rewritten_payload.size() > kMaxReasonableReassembledGameplayPayload ||
        rewritten_payload.size() > UINT32_MAX) {
      LogFormat(
          L"server->client coalesced live-object rewrite refused: frame_offset=%zu payload_offset=%zu old_payload=%zu new_payload=%zu declared=%u prefix=[%s]",
          cursor,
          payload_offset,
          old_payload_length,
          rewritten_payload.size(),
          old_declared,
          FormatLimitedBytes(
              packet->data() + payload_offset,
              frame_view.payload_length,
              120).c_str());
      cursor += old_frame_length;
      continue;
    }

    packet->erase(
        packet->begin() + static_cast<std::ptrdiff_t>(payload_offset),
        packet->begin() + static_cast<std::ptrdiff_t>(
            payload_offset + frame_view.payload_length));
    packet->insert(
        packet->begin() + static_cast<std::ptrdiff_t>(payload_offset),
        rewritten_payload.begin(),
        rewritten_payload.end());

    const size_t new_frame_length = kLegacyGameplayPayloadOffset + rewritten_payload.size();
    const bool length_updated = UpdatePacketizedMessagePayloadLengthAt(
        packet,
        cursor,
        static_cast<uint32_t>(rewritten_payload.size()));
    const bool record_has_crc = (*packet)[cursor] == 'M';
    const bool inner_crc_updated =
        record_has_crc ? EncodeNetLayerFrameCrcAt(packet, cursor, new_frame_length) : true;
    all_lengths_updated = all_lengths_updated && length_updated;
    all_inner_crcs_updated = all_inner_crcs_updated && inner_crc_updated;

    ++runtime->live_object_coalesced_rewrite_count;
    changed = true;
    const uint32_t new_declared =
        rewritten_payload.size() >= 7 ? ReadU32Le(rewritten_payload.data() + 3) : 0;
    LogFormat(
        L"server->client coalesced live-object rewritten #%llu/%llu: frame_offset=%zu payload_offset=%zu flags=0x%02X pkt_seq=%u declared=%u->%u payload=%zu->%zu frame=%zu->%zu packet=%zu layout=%d creature_p=%d visual=%d material=%d updates=%d add_visual=%d add_records=%d inventory23=%d item_appearance=%d len_updated=%d inner_crc_present=%d inner_crc_updated=%d old_crc=0x%04X creature_p_details=[%s] update_details=[%s] add_details=[%s]",
        static_cast<unsigned long long>(runtime->live_object_coalesced_rewrite_count),
        static_cast<unsigned long long>(runtime->live_object_coalesced_candidate_count),
        cursor,
        payload_offset,
        static_cast<unsigned int>(frame_view.flags),
        frame_view.packetized_sequence,
        old_declared,
        new_declared,
        old_payload_length,
        rewritten_payload.size(),
        old_frame_length,
        new_frame_length,
        packet->size(),
        live_layout_normalized ? 1 : 0,
        creature_p_feature_rewritten ? 1 : 0,
        visual_transform_rewritten ? 1 : 0,
        material_shader_rewritten ? 1 : 0,
        live_updates_rewritten ? 1 : 0,
        add_visual_transforms_rewritten ? 1 : 0,
        add_records_rewritten ? 1 : 0,
        inventory_feature23_rewritten ? 1 : 0,
        item_appearances_rewritten ? 1 : 0,
        length_updated ? 1 : 0,
        record_has_crc ? 1 : 0,
        inner_crc_updated ? 1 : 0,
        old_crc,
        creature_p_feature_rewritten && !creature_p_feature_result.details.empty()
            ? creature_p_feature_result.details.c_str()
            : L"<none>",
        live_updates_rewritten && !live_update_result.details.empty()
            ? live_update_result.details.c_str()
            : L"<none>",
        add_records_rewritten && !add_record_result.details.empty()
            ? add_record_result.details.c_str()
            : L"<none>");
    if (live_updates_rewritten && !live_update_result.diagnostics.empty()) {
      LogFormat(
          L"server->client coalesced live-object update diagnostics #%llu/%llu: %s",
          static_cast<unsigned long long>(runtime->live_object_coalesced_rewrite_count),
          static_cast<unsigned long long>(runtime->live_object_coalesced_candidate_count),
          live_update_result.diagnostics.c_str());
    }
    cursor += new_frame_length;
  }

  if (!changed) {
    return false;
  }

  const bool crc_updated = EncodeNetLayerFrameCrc(packet);
  const uint16_t new_crc = packet->size() >= 3 ? ReadU16Be(packet->data() + 1) : 0;
  ++runtime->live_object_coalesced_packet_repair_count;
  LogFormat(
      L"server->client coalesced live-object packet repaired #%llu: packet=%zu lengths_updated=%d inner_crcs_updated=%d crc_updated=%d crc=0x%04X->0x%04X",
      static_cast<unsigned long long>(runtime->live_object_coalesced_packet_repair_count),
      packet->size(),
      all_lengths_updated ? 1 : 0,
      all_inner_crcs_updated ? 1 : 0,
      crc_updated ? 1 : 0,
      old_crc,
      new_crc);
  return true;
}

bool RewriteModuleHakListPayloadIfPossible(
    BridgeRuntime* runtime,
    std::vector<unsigned char>* payload,
    ModuleHakRewriteResult* result) {
  if (result != nullptr) {
    *result = ModuleHakRewriteResult{};
  }
  if (runtime == nullptr || payload == nullptr || !runtime->options.rewrite_module_hak_list || payload->empty()) {
    return false;
  }

  ModuleInfoPacketView view;
  if (!TryParseModuleInfoPacket(payload->data(), payload->size(), &view)) {
    return false;
  }

  LegacyHakBlockCandidate hak_block;
  const bool have_hak_block = TryFindLegacyModuleHakBlock(payload->data(), payload->size(), view, &hak_block);

  if (!have_hak_block) {
    if (runtime->options.packet_dump) {
      LogFormat(
          L"server->client LoadModule hak-list rewrite skipped: no legacy hak block found module='%s' payload-len=%zu envelope=0x%02X",
          AsciiPreviewToWide(view.module_name).c_str(),
          payload->size(),
          static_cast<unsigned int>((*payload)[0]));
    }
    return false;
  }

  if (hak_block.skipped_bytes == 0 ||
      hak_block.skipped_bytes >= view.declared ||
      hak_block.offset + hak_block.skipped_bytes > view.declared) {
    LogFormat(
        L"server->client LoadModule hak-list rewrite refused: declared=%u skip=%u offset=%zu envelope=0x%02X",
        view.declared,
        hak_block.skipped_bytes,
        hak_block.offset,
        static_cast<unsigned int>((*payload)[0]));
    return false;
  }

  ++runtime->module_hak_block_candidate_count;
  uint32_t new_declared = view.declared - hak_block.skipped_bytes;
  const size_t erase_begin = hak_block.offset;
  const size_t erase_end = erase_begin + hak_block.skipped_bytes;
  if (erase_end > payload->size()) {
    return false;
  }

  if (result != nullptr) {
    result->envelope = (*payload)[0];
    result->offset = hak_block.offset;
    result->hak_count = hak_block.hak_count;
    result->removed_bytes = hak_block.skipped_bytes;
    result->old_declared = view.declared;
    result->new_declared = new_declared;
    result->resource_count = hak_block.resource_count_peek;
    result->haks = hak_block.haks;
    result->module_resref = hak_block.module_resref;
    result->old_payload_length = payload->size();
  }

  payload->erase(
      payload->begin() + static_cast<std::ptrdiff_t>(erase_begin),
      payload->begin() + static_cast<std::ptrdiff_t>(erase_end));
  WriteU32Le(payload->data() + 3, new_declared);

  if (runtime->module_hak_block_rewrite_count < 4 || runtime->options.packet_dump) {
    LogFormat(
        L"server->client LoadModule resource table after hak-strip: %s",
        FormatLoadModuleResourceNameTableSummary(*payload, erase_begin).c_str());
  }

  // EE's CNWCModule::LoadModule consumes the initial area-name table, then a
  // shared read-buffer byte and BOOL tail. Diamond keeps a larger resource-name
  // block after those area names; trim that legacy tail before stock EE walks
  // into it as the post-table fields.
  LoadModuleResourceNameTableRewrite table_rewrite;
  const bool table_rewritten =
      TryRewriteLoadModuleResourceNameTableTail(payload, erase_begin, &table_rewrite);
  if ((runtime->module_hak_block_rewrite_count < 4 || runtime->options.packet_dump) && table_rewritten) {
    LogFormat(
        L"server->client LoadModule area-name table trimmed: count=%u->%u declared=%u->%u removed=%u zero_len_repairs=%u zero_len_terminal=%d fragments=%u->%u",
        table_rewrite.old_count,
        table_rewrite.new_count,
        table_rewrite.old_declared,
        table_rewrite.new_declared,
        table_rewrite.tail_removed,
        table_rewrite.zero_length_name_repairs,
        table_rewrite.zero_length_name_terminator ? 1 : 0,
        table_rewrite.old_fragment_bytes,
        table_rewrite.new_fragment_bytes);
  }

  uint32_t ee_tail_bits_inserted = 0;
  const uint32_t final_declared = ReadU32Le(payload->data() + 3);
  const uint32_t fragment_bytes =
      payload->size() > final_declared ? static_cast<uint32_t>(payload->size() - final_declared) : 0;
  if (result != nullptr) {
    result->legacy_tail_removed = table_rewritten ? table_rewrite.tail_removed : 0;
    result->ee_tail_bits_inserted = ee_tail_bits_inserted;
    result->old_fragment_bytes = table_rewritten ? table_rewrite.old_fragment_bytes : fragment_bytes;
    result->new_fragment_bytes = table_rewritten ? table_rewrite.new_fragment_bytes : fragment_bytes;
    result->new_declared = final_declared;
    result->resource_name_count = table_rewritten ? table_rewrite.new_count : hak_block.resource_count_peek;
    result->resource_name_zero_length_repairs =
        table_rewritten ? table_rewrite.zero_length_name_repairs : 0;
    result->resource_name_table_rewritten = table_rewritten;
    result->resource_name_zero_length_terminator =
        table_rewritten ? table_rewrite.zero_length_name_terminator : false;
    result->synthetic_tail_byte = table_rewritten ? table_rewrite.tail_byte : 0;
    result->new_payload_length = payload->size();
  }
  ++runtime->module_hak_block_rewrite_count;
  return true;
}

void LogModuleRewriteResult(
    const wchar_t* label,
    unsigned long long sequence,
    const ModuleHakRewriteResult& result,
    size_t frame_length = 0,
    bool packetized_length_updated = false,
    bool crc_updated = false,
    uint16_t old_crc = 0,
    uint16_t new_crc = 0) {
  const wchar_t* tag = label != nullptr ? label : L"server->client module-info rewrite";
  LogFormat(
      L"%s #%llu: mode=legacy-loadmodule-hak-strip envelope=0x%02X offset=%zu count=%u removed=%u legacy_tail_removed=%u table=%u->%u table_rewritten=%d zero_len_repairs=%u zero_len_terminal=%d synthetic_tail=0x%02X ee_tail_bits=%u fragments=%u->%u declared=%u->%u payload=%zu->%zu resource_count=%u module_resref='%s' haks=[%s] frame_len=%zu pkt_len_updated=%d crc_updated=%d crc=0x%04X->0x%04X",
      tag,
      sequence,
      result.envelope,
      result.offset,
      result.hak_count,
      result.removed_bytes,
      result.legacy_tail_removed,
      result.resource_count,
      result.resource_name_count,
      result.resource_name_table_rewritten ? 1 : 0,
      result.resource_name_zero_length_repairs,
      result.resource_name_zero_length_terminator ? 1 : 0,
      static_cast<unsigned int>(result.synthetic_tail_byte),
      result.ee_tail_bits_inserted,
      result.old_fragment_bytes,
      result.new_fragment_bytes,
      result.old_declared,
      result.new_declared,
      result.old_payload_length,
      result.new_payload_length,
      result.resource_count,
      AsciiPreviewToWide(result.module_resref).c_str(),
      JoinAsciiListPreview(result.haks).c_str(),
      frame_length,
      packetized_length_updated ? 1 : 0,
      crc_updated ? 1 : 0,
      old_crc,
      new_crc);
}

bool RewriteServerStatusModuleResourcesIfPossible(BridgeRuntime* runtime, std::vector<unsigned char>* packet) {
  if (runtime == nullptr || packet == nullptr ||
      !runtime->options.enable_nwsync_advertisement ||
      packet->size() <= kLegacyGameplayPayloadOffset ||
      packet->front() != 'M') {
    return false;
  }

  GameplayWrapperView view;
  if (!TryParseGameplayWrapper(packet->data(), packet->size(), &view) || view.payload_length < 3) {
    return false;
  }
  const unsigned char* old_payload = packet->data() + kLegacyGameplayPayloadOffset;
  if (!IsHighLevelGameplayEnvelope(old_payload[0]) || old_payload[1] != 1 || old_payload[2] != 3) {
    return false;
  }
  std::vector<unsigned char> trailing_payload;
  if (view.trailing_payload_length != 0) {
    const size_t trailing_offset = kLegacyGameplayPayloadOffset + view.payload_length;
    trailing_payload.assign(
        packet->begin() + static_cast<std::ptrdiff_t>(trailing_offset),
        packet->end());
  }

  std::string status_module_name = runtime->latest_bnxr_module_name;
  if (status_module_name.empty()) {
    std::string parsed_status_name;
    if (TryReadHighLevelCnwLeadingString(old_payload, view.payload_length, &parsed_status_name) &&
        !parsed_status_name.empty()) {
      status_module_name = parsed_status_name;
    }
  }

  std::wstring failure_reason;
  std::vector<unsigned char> rewritten_payload;
  if (!BuildEeServerStatusModuleResourcesPayload(
          runtime,
          old_payload[0],
          status_module_name,
          &rewritten_payload,
          &failure_reason)) {
    LogFormat(
        L"server->client ServerStatus_ModuleRunning module-resources rewrite skipped: reason=%s old_payload=%zu available=%zu trailing=%zu status_module='%s' bnxr_module='%s' module_resources_name='' hash='%s' url='%s' hak_count=%zu haks=[%s]",
        failure_reason.empty() ? L"<unknown>" : failure_reason.c_str(),
        view.payload_length,
        view.available_payload_length,
        view.trailing_payload_length,
        AsciiPreviewToWide(status_module_name).c_str(),
        AsciiPreviewToWide(runtime->latest_bnxr_module_name).c_str(),
        AsciiPreviewToWide(runtime->options.nwsync_repository_hash).c_str(),
        AsciiPreviewToWide(runtime->options.nwsync_url).c_str(),
        kHgModuleHakOrderTopFirst.size(),
        HgModuleHakOrderPreview().c_str());
    return false;
  }

  const uint16_t old_crc = ReadU16Be(packet->data() + 1);
  packet->resize(kLegacyGameplayPayloadOffset);
  packet->insert(packet->end(), rewritten_payload.begin(), rewritten_payload.end());
  packet->insert(packet->end(), trailing_payload.begin(), trailing_payload.end());
  const bool packetized_length_updated = UpdateWindowPacketizedPayloadLength(
      packet,
      static_cast<uint32_t>(rewritten_payload.size()));
  const bool crc_updated = EncodeNetLayerFrameCrc(packet);
  const uint16_t new_crc = packet->size() >= 3 ? ReadU16Be(packet->data() + 1) : 0;
  ++runtime->server_status_module_resources_rewrite_count;
  LogFormat(
      L"server->client ServerStatus_ModuleRunning module-resources rewritten #%llu: mode=ee-nwsync old_payload=%zu new_payload=%zu available=%zu trailing_preserved=%zu status_module='%s' bnxr_module='%s' module_resources_name='' root='%s' url='%s' manifests=%zu hak_count=%zu haks=[%s] pkt_len_updated=%d crc_updated=%d crc=0x%04X->0x%04X",
      static_cast<unsigned long long>(runtime->server_status_module_resources_rewrite_count),
      view.payload_length,
      rewritten_payload.size(),
      view.available_payload_length,
      trailing_payload.size(),
      AsciiPreviewToWide(status_module_name).c_str(),
      AsciiPreviewToWide(runtime->latest_bnxr_module_name).c_str(),
      AsciiPreviewToWide(runtime->options.nwsync_repository_hash).c_str(),
      AsciiPreviewToWide(runtime->options.nwsync_url).c_str(),
      runtime->options.nwsync_manifests.size(),
      kHgModuleHakOrderTopFirst.size(),
      HgModuleHakOrderPreview().c_str(),
      packetized_length_updated ? 1 : 0,
      crc_updated ? 1 : 0,
      old_crc,
      new_crc);
  return true;
}

bool RewriteModuleHakListIfPossible(BridgeRuntime* runtime, std::vector<unsigned char>* packet) {
  if (runtime == nullptr || packet == nullptr || !runtime->options.rewrite_module_hak_list ||
      packet->size() <= kLegacyGameplayPayloadOffset || packet->front() != 'M') {
    return false;
  }

  GameplayPayloadWindow window;
  if (!ExtractGameplayPayloadWindow(*packet, &window)) {
    return false;
  }
  const uint16_t old_crc = ReadU16Be(packet->data() + 1);
  std::vector<unsigned char> payload = window.payload;
  ModuleHakRewriteResult result;
  if (!RewriteModuleHakListPayloadIfPossible(runtime, &payload, &result)) {
    return false;
  }

  bool packetized_length_updated = false;
  bool crc_updated = false;
  if (!ReplaceGameplayPayloadWindow(
          packet,
          window,
          payload,
          &packetized_length_updated,
          &crc_updated)) {
    return false;
  }
  const uint16_t new_crc = packet->size() >= 3 ? ReadU16Be(packet->data() + 1) : 0;

  LogModuleRewriteResult(
      L"server->client module-info frame rewritten",
      static_cast<unsigned long long>(runtime->module_hak_block_rewrite_count),
      result,
      packet->size(),
      packetized_length_updated,
      crc_updated,
      old_crc,
      new_crc);
  return true;
}

